\title{Discovering the Unequal Importance of Coded Bits in the Decoding of Polar Codes}

\author{Hossam Hassan\thanks{H. Hassan is with the Department of Electrical Engineering, Faculty of Engineering, Alexandria University, Alexandria, Egypt (email: \href{mailto:h.m.hassan@alexu.edu.eg}{h.m.hassan@alexu.edu.eg}).},
