Since the ideal semantics relies on the labels included in our annotated commands, we can only show relative security (the counterpart of \autoref{lem:faslh-ideal-rs}) if the annotations have been computed correctly, \IE a secret value can never be labeled as public.
While this is the case for the initial annotated program obtained by our IFC analysis, we need a property that is preserved during execution, and thus cannot reference the analysis directly.
%
We therefore define a well-labeledness judgment
$\wlacom{\annotated{\cexpr{c}}}{\PubVars_1}{\PubArrs_1}{\mathpc}{\PubVars_2}{\PubArrs_2}$
of an annotated command $\annotated{\cexpr{c}}$ with respect to an initial
labeling $(\PubVars_1, \PubArrs_1)$ and $\mathpc$ label
and a final labeling $(\PubVars_2, \PubArrs_2)$ with the derivation rules given
in \autoref{fig:well-labeled}.
%
The rules largely match the behavior of
$\flowtrack{\cdot}{\PubVars}{\PubArrs}{\mathpc}$, except instead of saving
computed labels, we only make sure that they don't contradict the already annotated ones.

The most interesting case is that of loops (\textsc{WL\_While}).
%
Instead of doing another fixpoint iteration,
we confirm that the annotated labeling is indeed a fixpoint by using it for both
the initial and final labeling for the loop body.

Like in the ideal semantics, in \textsc{WL\_Seq}
we use $\pcofacom{\ell}{\annotated{\cexpr{c_1}}}$
to determine the correct program counter label after executing the first part of a sequence.
%
However, this would create problems for the preservation result below
if we had branch annotations at arbitrary locations, so we prohibit branch annotations in nonsensical locations 
using the predicate $\branchfree{\annotated{\cexpr{c}}}$.

Note that well-labeledness does not require labels to match \emph{precisely}, instead,
they may overapproximate.
Specifically, the initial labeling can be made more precise and the final labeling less precise while preserving well-labeledness.

\begin{lemma}[IFC analysis produces well-labeled programs]
  \label{lem:static-tracking-well-labeled}
  \[ \flowtrack{{\cexpr{c}}}{\PubVars}{\PubArrs}{\mathpc} = (\annotated{\cexpr{c}}, \PubVars', \PubArrs') \implies \wlacom{\annotated{\cexpr{c}}}{\PubVars}{\PubArrs}{\mathpc}{\PubVars'}{\PubArrs'}\]
\end{lemma}
\begin{proof}[Proof sketch]
  By induction on $\cexpr{c}$; most cases follow easily from the definition of well-labeledness.
  The loop case follows by a nested induction on the number of public variables and arrays, with two base cases: If there are no public variables or arrays left or if the set of public variables and arrays does not shrink in one iteration, then a fixpoint has been reached; in both cases, well-labeledness of the loop body in the fixpoint labeling follows by the outer induction hypothesis.
\end{proof}

\begin{lemma}[$\idealstep{}{}{}{}$ preserves well-labeledness]
  \label{lem:fs-ideal-preserves-wl}
  \begin{align*}
    & \wlacom{\annotated{\cexpr{c}}}{\PubVars}{\PubArrs}{\mathpc}{\PubVars''}{\PubArrs''} & \Rightarrow \\
    & \idealstep{{\fsidealstate{\annotated{\cexpr{c}}}{\rho}{\mu}{b}{\mathpc}{\PubVars}{\PubArrs}}}{\Obss}{\Dirs}{\fsidealstate{\annotated{\cexpr{c'}}}{\rho}{\mu}{b}{\mathpc'}{\PubVars'}{\PubArrs'}} & \Rightarrow \\
    & \qquad \wlacom{\annotated{\cexpr{c'}}}{\PubVars}{\PubArrs}{\mathpc'}{\PubVars''}{\PubArrs''} 
  \end{align*}
\end{lemma}
\begin{proof}[Proof sketch]
  By induction on the annotated command.
  The loop case relies on the fact that well-labeledness is preserved when making the initial labeling more precise, as the labeling when reaching the loop is generally more precise than the loop's fixed-point labeling.
The sequence case is similar.
\end{proof}

\subsection{Key Theorems}

We have already shown that \FsFlexvSLH is correct w.r.t. the ideal semantics (\autoref{lem:bcc-fs}), so it remains to show the relative security of the ideal semantics.
%
One difference compared to \autoref{lem:faslh-ideal-rs} is that we compare the
ideal semantics on annotated commands to the nonspeculative semantics of
unannotated commands, so in \eqref{eq:fsfvslh-flowtrack-eq} we assume that the
annotated command was generated using the IFC analysis on the source program
using the same initial labeling used for the ideal semantics.

\begin{lemma}[$\idealmultiarrow{}{}$ ensures relative security]
  \label{lem:fs-fsvslh-ideal-rs}
%
\setcounter{equation}{0}
\begin{align}
 &  \flowtrack{\cexpr{c}}{\PubVars}{\PubArrs}{\BoolTrue} = (\annotated{\cexpr{c}}, \PubVars', \PubArrs') \wedge
  \ScalarState_1 \sim_{\PubVars} \ScalarState_2 \wedge
  \ArrayState_1 \sim_{\PubArrs} \ArrayState_2
 &\Rightarrow
 \label{eq:fsfvslh-flowtrack-eq}
\\
 &\seqstate{\cexpr{c}}{\ScalarState_1}{\ArrayState_1}
  \approx
  \seqstate{\cexpr{c}}{\ScalarState_2}{\ArrayState_2}
 %% &( \forall \Obss_1 \Obss_2.
 %%   \\
 %%   &\quad
 %%    \seqmultis{\seqstate{\cexpr{c}}{\ScalarState_1}{\ArrayState_1}}{\Obss_1}{\cdot}
 %%    \Rightarrow
 %%    \seqmultis{\seqstate{\cexpr{c}}{\ScalarState_2}{\ArrayState_2}}{\Obss_2}{\cdot}
 %%    \Rightarrow
 %%    \Obss_1 \lessgtr \Obss_2
 %%  )
 &\Rightarrow
\\
 &\fsidealstate{\annotated{\cexpr{c}}}{\ScalarState_1}{\ArrayState_1}{\BoolFalse}{\BoolTrue}{\PubVars}{\PubArrs}
 \approx_i
 \fsidealstate{\annotated{\cexpr{c}}}{\ScalarState_2}{\ArrayState_2}{\BoolFalse}{\BoolTrue}{\PubVars}{\PubArrs}
%%  &\idealmulti
%%   {\specstate{\cexpr{c}}{\ScalarState_1}{\ArrayState_1}{\BoolFalse}}
%%   {\Obss_1}{\Dirs}
%%   {\cdot}
%%  &\Rightarrow
%% \\
%%  &\idealmulti
%%   {\specstate{\cexpr{c}}{\ScalarState_2}{\ArrayState_2}{\BoolFalse}}
%%   {\Obss_2}{\Dirs}
%%   {\cdot}
%%  &\Rightarrow
%% \\
%%  &\Obss_1 = \Obss_2
\end{align}
\end{lemma}
\begin{proof}[Proof sketch]
  We apply \autoref{lem:static-tracking-well-labeled} to obtain well-labeledness of $\annotated{\cexpr{c}}$.
%
  The rest of the proof is analogous to \autoref{lem:faslh-ideal-rs}, since we
  can prove counterparts to \autoref{lem:faslh-ideal-noninterference} and
  \autoref{lem:gilles-lemma} using well-labeledness instead of typing, and since
  well-labeledness is preserved by the ideal semantics
  (\autoref{lem:fs-ideal-preserves-wl}).
\end{proof}

We compose Lemmas \ref{lem:bcc-fs} and \ref{lem:fs-fsvslh-ideal-rs} to prove the relative security of \FsFlexvSLH.
While \autoref{lem:fs-fsvslh-ideal-rs} requires the annotated command to be the result of the IFC analysis, this analysis always succeeds, so we obtain relative security \emph{for all programs}.

\newtheorem*{thm:fsfvslh-rs}{\autoref{thm:fvslh-rs}}
\begin{thm:fsfvslh-rs}[Relative security of \FsFlexvSLH for all programs]
\begin{align*}
 &\cvar{b} \notin \UsedVars{\cexpr{c}} \wedge
  \lookup{\ScalarState_1}{\cvar{b}} = 0 \wedge
  \lookup{\ScalarState_2}{\cvar{b}} = 0
 &\Rightarrow
\\
 &(\forall \cvar{a}. | \cvar{a} |_{\ArrayState_1} > 0) \wedge
  (\forall \cvar{a}. | \cvar{a} |_{\ArrayState_2} > 0)
 &\Rightarrow
\\
 &
  \ScalarState_1 \sim_{\PubVars} \ScalarState_2 \wedge
  \ArrayState_1 \sim_{\PubArrs} \ArrayState_2
 &
  \Rightarrow
\\
 &
 \seqstate{\cexpr{c}}{\ScalarState_1}{\ArrayState_1}
 \approx
 \seqstate{\cexpr{c}}{\ScalarState_2}{\ArrayState_2}
 &\Rightarrow
\\
 &\flowtrack{\cexpr{c}}{\PubVars}{\PubArrs}{\BoolTrue} = (\annotated{\cexpr{c}}, \PubArrs', \PubVars') &\Rightarrow \\
 &\specstate{\translFsFlexvSLH{\annotated{\cexpr{c}}}}{\ScalarState_1}{\ArrayState_1}{\BoolFalse}
  \approx_s
  \specstate{\translFsFlexvSLH{\annotated{\cexpr{c}}}}{\ScalarState_2}{\ArrayState_2}{\BoolFalse}
\end{align*}

\end{thm:fsfvslh-rs}

