\subsection{Proof for \cref{thm:theorem_by}} \label{app:ByITFL}
\begin{proof}
We start by proving the IT privacy of \ourscheme.
\subsubsection{IT Privacy}\label{proof:privacy_by}
We first prove the IT privacy against any $\Colluding$ colluding users and the federator according to  \cref{eq:privacy_combine}:
\begin{align}\label{eq:proof_privacy_byitfl}
    & I(\modelupdate_{\honestset}; M_{\mathcal{T}}, M_0\!\mid \!\modelupdate_{\mathcal{T}}, \modelupdate_0, \Dataset_{\mathcal{T}}, \Dataset_0, \model, \aggresult) \nonumber \\
    = & H(\modelupdate_{\honestset}\!\mid \!\modelupdate_{\mathcal{T}}, \modelupdate_0, \Dataset_{\mathcal{T}}, \Dataset_0, \model, \aggresult) \nonumber \\
    & - H(\modelupdate_{\honestset}\!\mid \! M_{\mathcal{T}}, M_0,\modelupdate_{\mathcal{T}}, \modelupdate_0, \Dataset_{\mathcal{T}}, \Dataset_0, \model, \aggresult) \nonumber \\
    = & H(\modelupdate_{\honestset}\!\!\mid\! \!\Dataset_{\mathcal{T}},\! \Dataset_0,\! \model,\! \aggresult) \!- \!H(\modelupdate_{\honestset}\!\!\mid \!\! M_{\mathcal{T}},\! M_0,\! \Dataset_{\mathcal{T}},\! \Dataset_0,\! \model,\! \aggresult),
\end{align}
where the last equation follows because $\modelupdate_\colset$ is a deterministic function of $\Dataset_{\mathcal{T}}$ and $\model$, and $\modelupdate_0$ is a deterministic function of $\Dataset_0$ and $\model$. We then consider the exchanged messages $M_\colset$ observed by the colluding users and $M_0$ observed by the federator in each step. $M_\colset$ includes:
\begin{enumerate}[label=Step \Alph*, wide=0pt, font=\itshape,, leftmargin=*]
    \item [Step A and E:] nothing, since step A only involves local computations and step E is performed by the federator;
    \item [Step B:] shares $\normalmodelupdate_j[i]$ for $i \in \colset, j \in [\TotalUser]$; 
    \item [Step C:] ${\| \normalmodelupdate_j \|}_2^2[i]$ for $i \in \colset, j \in [\TotalUser]$ and sub-shares from the re-randomization when computing ${\| \normalmodelupdate_j \|}_2^2[i]$; and
    \item [Step D:] shares $\sumone[i], \sumtwo[i]$, $(\random \sumone)[i]$, $(\random \sumtwo)[i]$, the random values $\random_i$, and $\random_j[i]$, for $j\!\in\! [\TotalUser]$ and $i \!\in\! \colset$, and sub-shares from the re-randomization step when computing shares of $\sumone, \sumtwo, \random \sumone$ and $\random \sumtwo$.
\end{enumerate}
With regard to $M_0$, we need to consider: 
\begin{enumerate}[label=Step \Alph*, wide=0pt, font=\itshape,, leftmargin=*]
    \item [Step A and B:] nothing, since step A and B only involve computations among the users; and
    \item [Step C, D and E:] shares ${\| \normalmodelupdate_j \|}_2^2[i]$, for $j \in [\TotalUser]$, $(\random \sumone)[i]$ and $(\random \sumtwo)[i]$ received from the users for $i \in [\TotalUser]$, and the reconstruction of ${\| \normalmodelupdate_j \|}_2^2$, $\random \sumone$ and $\random \sumtwo$.
\end{enumerate}

Regarding $M_\colset$, we leverage the privacy guarantees of LCC \cite{yu2019lagrange}, the re-randomization step \cite{gennaro1998simplified}, \cite{asharov2017full} and ITVSS \cite{BGW}. Since each secret-sharing is encoded by a degree $\partition+\Colluding-1$ polynomial, when considering at most $\Colluding$ colluding users, the shares and the sub-shares observed by the colluding users are completely random and independent of $\modelupdate_\honestset, \Dataset_\colset, \Dataset_0, \model$ and $\aggresult$. Since the random values are drawn uniformly and independently from $\mathbb{F}_p$, $\random_i$'s are independent of $\modelupdate_\honestset, M_0, \Dataset_\colset, \Dataset_0, \model$ and $\aggresult$. However, the shares ${\| \normalmodelupdate_j \|}_2^2[i]$, $(\random \sumone)[i]$ and $(\random \sumtwo)[i]$ for $i \in \colset, j \in [\TotalUser]$ are not independent of $M_0$, rather, $M_0$ includes these shares. We denote these shares as $\hat{M}_{\colset}$, thus, we obtain $H(\hat{M}_{\colset}\!\mid\!M_0)=0$. Hence,
\begin{align}
\label{eq:mt}
    H(\modelupdate_{\honestset} \!\! \mid \!\! M_{\mathcal{T}},\! M_0,\! \Dataset_{\mathcal{T}},\! \Dataset_0,\! \model,\! \aggresult) \nonumber & \!\!=\!\! H(\modelupdate_{\honestset}\!\!\mid\!\! \hat{M}_{\colset},\! M_0,\! \Dataset_{\mathcal{T}},\! \Dataset_0,\! \model,\! \aggresult) \nonumber \\
    =& H(\modelupdate_{\honestset} \!\!\mid\!\!  M_0,\! \Dataset_{\mathcal{T}},\! \Dataset_0,\! \model,\! \aggresult),
\end{align}
where the first equality holds because of the independence, and the second equality holds because $H(\hat{M}_{\colset} \mid M_0)=0$. 

As for $M_0$, since the collection of all the shares from user $i \in [\TotalUser]$ is informationally equivalent to the secret itself, we only need to consider the privacy of the reconstructions. Among the reconstructions: \begin{enumerate*}[label=(\emph{\alph*})]
    \item $\| \normalmodelupdate_i \|_2^2$ lies within a certain range for all possible model updates (ideally equivalent to one);
    \item $\sumone$ is completely hidden due to the randomness $\random$; and
    \item no information is leaked beyond $\aggresult=\frac{\sumtwo}{\sumone}$, i.e., $H(\random\sumtwo|\aggresult)=0$.
\end{enumerate*}
We denote all the exchanged messages except $\random\sumtwo$ as $\hat{M}_0$, thus,
\begin{align*}
    H(\modelupdate_{\honestset}\!\!\mid \!\! M_0, \Dataset_{\mathcal{T}}, \Dataset_0, \model, \aggresult)& =H(\modelupdate_{\honestset}\!\!\mid \!\! \hat{M}_0, \random\sumtwo, \Dataset_{\mathcal{T}}, \Dataset_0, \model, \aggresult) \\
    &= H(\modelupdate_{\honestset}\!\!\mid \!\! \Dataset_{\mathcal{T}}, \Dataset_0, \model, \aggresult),
\end{align*}
where the second equation holds since $\hat{M}_0$ is completely random and independent of other terms, and $H(\random\sumtwo|\aggresult)=0$.
By substituting the above into  \cref{eq:proof_privacy_byitfl} we prove  \cref{eq:privacy_combine}, showing that \ourscheme is IT private against $\Colluding$ colluding users and the federator.




\subsubsection{Resilience against Byzantine and Robustness against dropout}\label{proof:byz_by}
Byzantine users may present corrupt updates, and perform the required computations dishonestly. The effect of corrupt updates is mitigated by the robust aggregation rule, i.e. FLTrust~\cite{cao2020fltrust}. Next, we guarantee the correct computation of $\random\sumone[i]$ and $\random\sumtwo[i]$. For dishonest computations, Byzantine users may behave arbitrarily in any step during the computation. Particularly, user $i\in\byzset$ can: 
\begin{enumerate*}[label=(\emph{\alph*})]
    \item incorrectly normalize local model updates $\realnormalmodelupdate_i$ in the normalization step;
    \item distribute invalid secret shares, i.e. secret shares encoded using different encoding polynomials, in the secret sharing step; and,
    \item misbehave when computing $ \| \normalmodelupdate_j \|_2^2 [i]$, $ (\random\sumone)[i] $ and $(\random\sumtwo)[i] $, and send corrupt results to the federator. 
\end{enumerate*} 

Byzantine behavior in the first scenario can be detected and identified in the normalization validation step. For all honest users, the model updates presented and normalized lie within a certain range. Thus, even if malicious users present model updates with the largest squared $l_2$-norm that will be accepted by the normalization validation, it only has limited impact since $\epsilon$ is empirically set to be very small. For the second scenario, the attack can be detected by ITVSS~\cite{BGW}, thus guaranteeing the correctness of the secret sharing scheme. 

With regard to the third scenario, the correctness is ensured by the Reed-Solomon (RS) decoding algorithm~\cite{mceliece1981sharing}. As described in \cref{sub:normalization} and \cref{sub:aggregation}, $ \| \normalmodelupdate_j \|_2^2 [i]$, $ (\random\sumone)[i] $ 
and $ (\random\sumtwo)[i] $ can be viewed as evaluations of the polynomials with degree $2(\partition+\Colluding-1)$, $(\approdegree+1) \cdot (\partition+\Colluding-1)$ and $(\approdegree+2)\cdot (\partition+\Colluding-1)$, respectively. The decoding of $ \| \normalmodelupdate_j \|_2^2$, $\random\sumone$ 
and $\random\sumtwo$ can be treated as the decoding of Reed-Solomon codes with parameters 
\begin{enumerate}
    \item $[\TotalUser, 2(\partition+\Colluding-1)+1, \TotalUser-2(\partition+\Colluding-1)]_p$;
    \item $[\TotalUser, (\approdegree+1)\! \cdot\! (\partition+\Colluding-1)+1, \TotalUser-(\approdegree+1) \!\cdot\! (\partition+\Colluding-1)]_p$;
    \item $[\TotalUser, (\approdegree+2)\!\cdot\! (\partition+\Colluding-1)+1, \TotalUser-(\approdegree+2)\!\cdot\! (\partition+\Colluding-1)]_p$;
\end{enumerate}
respectively. Note that, a $[\TotalUser,\SSthreshold,\TotalUser-\SSthreshold+1]_p$ RS code with $\Dropout$ erasures is able to decode $\lfloor \frac{\TotalUser-\SSthreshold-\Dropout}{2}\rfloor$ errors. By viewing the updates presented by Byzantine users as errors in a RS code and dropout users as erasures, we obtain three requirements on $\TotalUser$ given by the decoding of these three RS codes:
\begin{enumerate}
    \item $\Byzantine \leq \frac{\TotalUser-\left(2(\partition+\Colluding-1)+1\right)-\Dropout}{2}$;
    \item $\Byzantine \leq \frac{\TotalUser-\left((\approdegree+1) \cdot (\partition+\Colluding-1)+1\right)-\Dropout}{2}$;
    \item $\Byzantine \leq \frac{\TotalUser-\left((\approdegree+2)\cdot (\partition+\Colluding-1)+1\right)-\Dropout}{2}$;
\end{enumerate}
Hence, the federator can decode the correct computation results as long as $\TotalUser \geq 2\Byzantine+(\approdegree+2)\cdot (\partition+\Colluding-1)+\Dropout+1$, which is the largest $\TotalUser$ required by these three decodings.




\subsubsection{Complexity}
For each user sharing a single scalar, the computation complexity of encoding in LCC is $O(n\log^2 n\log\log n)$ \cite{yu2019lagrange} and that of ITVSS \cite{BGW} is $O(n^2 \log^2 n)$. Since the re-randomization step \cite{gennaro1998simplified} involves sub-sharing each secret share using ITVSS and a linear combination of the sub-shares, the computation complexity is $O(n^2\log^2 n\log\log n+n^3 \log^2 n)$. The communication cost for the ITVSS is $O(n^2)$, and $O(n^3)$ for re-randomization. With respect to the federator, the computation cost for decoding a single scalar using error-correction decoding takes $O(n\log^2 n\log\log n)$. The remaining proof follows from counting, here omitted for brevity.
\end{proof}

\subsection{Proof for \cref{thm:theorem_loby}} \label{app:LoByITFL}
\begin{proof}
We begin with the proof for IT privacy for \ourschemelo.
\subsubsection{IT Privacy}
For privacy against any $\Colluding$ colluding users and the federator according to \cref{eq:privacy_combine}, we want to prove \cref{eq:proof_privacy_byitfl}. The exchanged messages $M_{\mathcal{T}}$ are:
\begin{enumerate}[label=Step \Alph*, wide=0pt, font=\itshape,, leftmargin=*]
    \item [Initialization Step:] random vectors $ \randomvector_i$'s, shares of random values $\{ \randomvector_j[i] \}$'s for $j \in [\TotalUser]$ and $\{ \random[i] \}$'s, shares of Beaver triple $\{ \gamma[i] \}$'s, $\{ \omega[i] \}$'s, $\{ \kappa[i] \}$'s, for $i\in \colset$;
    \item [Step A and E:] nothing, since step A only involves local computations and step E is performed by the federator;
    \item [Step B:] the broadcasted values $\normalmodelupdate_j-\randomvector_j$ and the shares $\{ \normalmodelupdate_j[i] \}$, for $i \in \colset, j \in [\TotalUser]$; 
    \item [Step C:] shares $\{\| \normalmodelupdate_j \|_2^2[i]\}$ and the messages incurred when consuming Beaver triples to compute $\{\| \normalmodelupdate_j \|_2^2[i]\}$, for $i \in \colset, j \in [\TotalUser]$; and
    \item [Step D:] shares $\{\sumone[i]\}, \{\sumtwo[i]\}$, $\{(\random \sumone)[i]\}$, $\{(\random\sumtwo)[i]\}$, and $\{\random_j[i]\}$ for $j\in [\TotalUser]$ and $i \in \colset$, and the messages incurred when consuming Beaver triples to compute shares of $\sumone, \sumtwo, \random \sumone$ and $\random\sumtwo$.
\end{enumerate}
The exchanged messages $M_0$ include:
\begin{enumerate}[label=Step \Alph*, wide=0pt, font=\itshape,, leftmargin=*]
    \item [Initialization Step:] the MAC keys used for generating the MACs of the secret shares;
    \item [Step A and B:] nothing, since step A and B only involve computations among the users; and
    \item [Step C, D and E:] shares $\{ {\| \normalmodelupdate_j \|}_2^2[i] \}$ for $j \in [\TotalUser]$, $\{ (\random \sumone)[i] \}$ and $\{ (\random\sumtwo)[i] \}$ received from the user $i \in [\TotalUser]$, the reconstruction of ${\| \normalmodelupdate_j \|}_2^2$, $\random \sumone$ and $\random\sumtwo$, and the messages incurred when using Beaver triples to compute multiplications.
\end{enumerate}
Note that, when computing $\{ (sv)[i] \}$, colluding users get $\{s[i]-\gamma[i]\}$, $\{v[i]-\omega[i]\}$, $s-\gamma$ and $v-\omega$, for $i\in \colset$, and the federator gets the values of $\{s[i]-\gamma[i]\}$, $\{v[i]-\omega[i]\}$ for $i \in [\TotalUser]$ and the reconstructed values $s-\gamma$ and $v-\omega$.

We leverage the privacy guarantees of the SecShare scheme, the Beaver triple and the MAC scheme. Regarding the messages $M_\colset$, when the number of colluding users is smaller than the threshold of the secret sharing scheme, i.e. $\Colluding$, 
we have:
\begin{enumerate*}[label=(\emph{\alph*})]
    \item the shares observed by the colluding users are completely random and independent of $\modelupdate_\honestset, \Dataset_\colset, \Dataset_0, \model$ and $\aggresult$, but partially included by $M_0$;
    \item the random vectors $\randomvector$'s are random and independent of $M_0, \modelupdate_\honestset, \Dataset_\colset, \Dataset_0, \model$ and $\aggresult$;%
    \item the broadcasted values $\normalmodelupdate_j-\randomvector_j$'s are random because of one-time padding;
    \item the MACs are also random because of the randomness of $\beta$; and
    \item the messages incurred when consuming Beaver triples for multiplication are either secret shares or protected by one-time padding, thus, independent of $\modelupdate_\honestset, M_0, \Dataset_\colset, \Dataset_0, \model$ and $\aggresult$.
\end{enumerate*}
Thus, we have \cref{eq:mt} when considering the shares $\{ {\| \normalmodelupdate_j \|}_2^2[i] \}$, $\{ (\random \sumone)[i] \}$ and $\{ (\random\sumtwo)[i] \}$ for $j \in [\TotalUser]$ and $i \in \colset$ as $\hat{M}_\colset$.


As for $M_0$, the MAC keys sent from the TTP and the messages broadcasted during multiplication are random values that are independent of $\modelupdate_\honestset, \Dataset_\colset, \Dataset_0, \model$ and $\aggresult$. By following the same reasoning as in \cref{proof:privacy_by}, we conclude the IT privacy proof for \ourschemelo. 

\subsubsection{Resilience against Byzantine and Robustness against dropout}
Byzantine users may present corrupt updates, and perform the required computations dishonestly. Same as in \cref{proof:byz_by}, the effect of corrupt updates is eliminated by the robust aggregation rule. We next guarantee the correct computation of $\random\sumone[i]$ and $\random\sumtwo[i]$. For dishonest computations, Byzantine users $i\in\byzset$ may:
\begin{enumerate*}[label=(\emph{\alph*})]
    \item incorrectly normalize local model updates $\realnormalmodelupdate_i$; 
    \item compute invalid secret shares $\{ \normalmodelupdate_j[i] \}$ for any $j\in[\TotalUser]$; and,
    \item misbehave during the computation of $\{ \| \normalmodelupdate_j \|_2^2 [i]\}$, $\{ (\random\sumone)[i] \}$ 
and $\{ (\random\sumtwo)[i] \}$.
\end{enumerate*}

As stated in \cref{proof:byz_by}, Byzantine attacks in the first scenario can be detected and identified in the normalization validation step. For Byzantine attacks in the remaining scenarios, the MACs are used to enable integrity check, i.e., for each linear operation performed on the secret shares, the users also perform the same computation on the corresponding MACs. 
Since the federator receives all the corresponding MAC keys $(\alpha,\beta)$'s in the initialization phase, integrity check can be performed by the federator to guarantee the correctness of the computation. 
Therefore, the correctness of the computations entirely relies on the integrity check of the IT one-time MAC~\cite{bendlin2011semi}, where we need to consider the forgery probability of the MAC. Forgery probability is the probability that a malicious user guesses the MAC key used for generating the MAC of a specific secret share correctly, such that it can create a valid MAC for the computation result to fool the integrity check. Since in all MAC keys $(\alpha,\beta)$s', $\alpha$ is a uniformly random consistent value and $\beta$'s are chosen independently uniformly at random from the underlying prime field $\mathbb{F}_p$, which are used to protect the value of $\alpha$ when we reusing it in different MACs. The forgery probability for each scalar is the probability of guessing the $\beta$ used for generating the MAC for a specific scalar, that is $1/ \| \mathbb{F}_p \|= 1/p$, i.e. the inverse of the size of the underlying finite field. Since the finite field we choose is very large, i.e. $p \geq 2\TotalUser \dimension^\approdegree q^{2\approdegree+1}+1$, and the malicious users have to guess the $\beta$'s used for all $\dimension$ dimensions to fool the integrity check, the forgery probability is small enough to guarantee the security and correctness of the scheme.

\subsubsection{Complexity}
In the training phase, the computation for each user sharing a scalar is, according to  \cref{eq:sharing}, the addition of a publicly known value and a secret share, thus $O(1)$, and that of one share multiplication is $O(1)$ as well by consuming one Beaver triple, which only involves addition and scaling of the secret shares. For the federator, the computation is to reconstruct the intermediate results during share multiplications and the final results, which is a Lagrange polynomial interpolation problem and costs $O(n\log^2n\log\log n)$ per scalar. The communication cost for secret sharing and computations on secret shares are $O(1)$ for each user and $O(n)$ for the federator per scalar. The rest of the proof follows by counting, and is omitted here for the sake of brevity.
\end{proof}

\subsection{Proof for convergence}\label{proof:convergence}
For the proof of convergence, we need \cref{lem:bounded}.
\begin{lem}\label{lem:bounded}
    At each global iteration $\globalIteration$, the distance between the federator's aggregation of the gradients $\modelupdate^{(\globalIteration)}$ and the gradient $\nabla F(\model^{(\globalIteration)})$ is bounded from above as:
    \[
    \| \modelupdate^{(\globalIteration)} - \nabla F(\model^{(\globalIteration)}) \| \leq
    3\| \modelupdate_0^{(\globalIteration)} - \nabla F(\model^{(\globalIteration)}) \| + 2 \|\nabla F(\model^{(\globalIteration)}) \|.
    \]
\end{lem}

\begin{proof}
We omit the superscript ${(\globalIteration)}$ for ease of notation. 
Recall the definition of  $\aggresult$
\[
\aggresult \define \frac{1}{\sum_{i\in [\TotalUser]}{\discripoly(\langle \normalmodelupdate_0,\normalmodelupdate_i \rangle)}}\sum_{i\in [\TotalUser]}{\discripoly(\langle \normalmodelupdate_0,\normalmodelupdate_i \rangle) \cdot \normalmodelupdate_i}.
\]
Therefore, since \cref{eq:modelupdate},  $\langle \modelupdate,\modelupdate_0 \rangle \geq 0$ always holds.
We can bound $\| \modelupdate - \nabla F(\model) \|$ as
\begin{align*}
\| \modelupdate - \nabla F(\model) \|
    &= \| \modelupdate - \modelupdate_0 + \modelupdate_0 - \nabla F(\model) \| \\
    &\stackrel{(a)}{\leq} \| \modelupdate - \modelupdate_0 \| + \| \modelupdate_0 - \nabla F(\model) \| \\
    &\stackrel{(b)}{\leq} \| \modelupdate + \modelupdate_0 \| + \| \modelupdate_0 - \nabla F(\model) \| \\
    &\stackrel{(c)}{\leq} \| \modelupdate \| + \| \modelupdate_0 \| + \| \modelupdate_0 - \nabla F(\model) \| \\
    &= 2\| \modelupdate_0 \| + \| \modelupdate_0 - \nabla F(\model) \| \\
    &= 2\| \modelupdate_0 - \nabla F(\model) + \nabla F(\model) \| \\
    & ~~~~ + \| \modelupdate_0 - \nabla F(\model) \| \\
    &\stackrel{(d)}{\leq} 3\| \modelupdate_0 - \nabla F(\model) \| + 2 \|\nabla F(\model) \|,
\end{align*}
where (a), (b), and (d) follow from the triangle inequality, and (c) follows since $\langle \modelupdate,\modelupdate_0 \rangle \geq 0$.
\end{proof}

Using \cref{lem:bounded} and the same assumptions as in~\cite[Assumptions 1, 2 and 3]{cao2020fltrust}, the proof of convergence of \ourscheme follows the same steps as the proofs in Appendix A of~\cite{cao2020fltrust}.




