        \hline
        \hline
        & \textbf{Autoreg ML} & \textbf{PID} & \textbf{Nelder-Mead}  \\
        \hline
        RMSE &     $\mathbf{1.15}$ &   $1.20$ &  $3.27$  \\
        \hline
        Optimization time, s &   $1.46$ &  $\mathbf{0.05}$ & $356.80$  \\
