    \section{Constructions of plateaued functions}\label{plateaued functions}
    In this section, we present seven classes of plateaued functions including a class constructed from permutations of the form $x^{3 \cdot 2^{m}}+ax^{2 \cdot 2^{m}+1}+bx^{2^{m}+2}+cx^3$, three classes constructed from the so-called DO permutations, and three classes constructed from permutations of the form $cx+\tr_{m}^{km}(x^s)$. We first recall the explicit computation of the Walsh transform of quadratic functions, as detailed in Lemma \ref{qudratic_sum}.
    \begin{Lem}\cite{hou2007explicit}\label{qudratic_sum}
        Let $A(x)$ and $Q(x)$ be an affine function and a quadratic function over $\F_{2^n}$, respectively. Then for any pair $(a,b) \in \F_{2^n} \times \F_{2^n}^{*}$, quadratic Boolean function $\varphi_{a,b}=\tr_n(bQ(x)+ax)$ can be expressed as 
        \begin{eqnarray*}
            \varphi_{a,b}(x)
            =\tr_n\left(\sum_{i \in I} {a_ix^{2^{i}+1}}+A(x)\right),
        \end{eqnarray*}
        where $I \subset \left\{1,2,\cdots, \lfloor \frac{n}{2} \rfloor\right\}$ and
        \[
            a_i \in 
                \begin{cases}
                    \F_{2^n}^{*} , &\text{if~} i < \frac{n}{2},\\
                    \F_{2^n} \backslash \F_{2^\frac{n}{2}} ,  &\text{if~} i = \frac{n}{2}.
                \end{cases}
        \]
        Assume that $k= \max{I}$, define the associated bilinear mapping of $\varphi_{a,b}$ as 
        \begin{eqnarray*}
            B_{\varphi_{a,b}}(x,y)
            &=&\varphi_{a,b}(x+y)+\varphi_{a,b}(x)+\varphi_{a,b}(y) \\
            &=&\tr_n\left( x\sum_{i \in I}{\left( a_i^{2^k}y^{2^{k+i}}+a_i^{2^{k-i}}y^{2^{k-i}} \right)}^{2^{-k}} \right),
        \end{eqnarray*}
        and its kernel $V_{\varphi_{a,b}}$ is given by
        \begin{eqnarray}\label{gy}
            V_{\varphi_{a,b}}
            &=& \left\{y \in \F_{2^n} \mid B_{\varphi_{a,b}}(x,y)=0 \text{ for}~\forall x \in \F_{2^n} \right\} \nonumber \\
            &=& \left\{ y \in \F_{2^n}~\Big|~\sum_{i \in I}{\left( a_i^{2^k}y^{2^{k+i}}+a_i^{2^{k-i}}y^{2^{k-i}} \right)}=0 \right\}.
        \end{eqnarray}
        Then 	
        \begin{equation}\label{Eq-Quad}
            W_Q(a,b)=
            \begin{cases}
                \pm 2^{\frac{n+d}{2}}, & \text{if~} \varphi_{a,b} \text{~vanishes on~} V_{\varphi_{a,b}}, \\
                0, & \text{otherwise,} 
            \end{cases}
        \end{equation} 
        where $d$ is the dimension of $V_{\varphi_{a,b}}$ over $\F_2$.
    \end{Lem}

    The proofs of plateaued functions constructed by the last two largely rely on the quantity of roots for the polynomial $a^{2^m}x^{2^{2m}}+ax \in \F_{2^n}[x]$. This polynomial, where $a \neq 0$ and $m > 0$, has either $0$ or $2^{\gcd(2m,n)}$ nonzero solutions, as noted by Coulter \cite{coulter1999evaluation}.
    \begin{Lem}\cite{coulter1999evaluation}\label{binoeq}
        Let $n,m$ be positive integers, and $N$ be the number of nonzero solutions to the equation $a^{2^m}x^{2^{2m}}+ax=0 \text{~over~} \F_{2^n}$. For any $a \in \F_{2^n}^{*}$, we have
        \begin{eqnarray*}
            N= 
            \begin{cases}
              2^{d}-1,&\frac{n}{d} \text{~odd},\\
              2^{2 d}-1,&\frac{n}{d} \text{~even~and~} a=\alpha^{t(2^d+1)},\\
              0,&\text{~otherwise},
            \end{cases}
        \end{eqnarray*}
        where $\alpha$ is a primitive element of $\F_{2^n}$ and $d=\gcd(m,n)$.
    \end{Lem}

    \subsection{Constructions from $x^{3 \cdot 2^{m}}+ax^{2 \cdot 2^{m}+1}+bx^{2^{m}+2}+cx^3$}
    In \cite{tu2018new}, a well-known class of quadratic quadrinomials over $\F_{2^{n}}$ in the form 
    \[
         P(x)=x^{3 \cdot 2^{m}}+ax^{2 \cdot 2^{m}+1}+bx^{2^{m}+2}+cx^3
    \]
    was first studied as a permutation, where $m$ is odd. Further work promoted this result \cite{tu2019revisit,gupta2020several,kim2023completely} and revealed its excellent properties in boomerang uniformity \cite{tu2020class}. Here we concentrate on the subclass shown in Lemma \ref{qudpp} and obtain plateaued functions in Theorem \ref{Thm_plateaued}. 
    \begin{Lem}\label{qudpp}
    \cite{tu2018new}
        Let $m$ be an odd positive integer and $n= 2m$, $a, b, c\in \mathbb{F} _{2^{n}}$. Then
        \[
            P(x)=x^{3 \cdot 2^{m}}+ax^{2 \cdot 2^{m}+1}+bx^{2^{m}+2}+cx^3
        \]
        permutes $\mathbb{F}_{2^{n}}$ if one of the following three conditions is satisfied:\\
        (1) $c=1$, $a$ satisfies $\bar{\omega}\bar{a}+a+\omega\neq0$ and $b=\omega(a+1)+1$, where $\omega \in \F_{4} \backslash \F_{2}$;\\
        (2) $c= 1$, $b= a+ 1$ and $a+ \bar{a} + 1 \neq 0$;\\
        (3) $a,b,c \in\mathbb{F}_{2^{m}}$, $A=ab+c$, $B=1+a+b+c \neq 0$ and $C=a^2+b^2+ac+b$ satisfy either $C=0$ and $\tr_m\left(\frac{A}{B^2}\right)=1$, or $C=B^2$ and $\tr_m\left(\frac{A}{B^2}\right)=0$.
    \end{Lem}
    To complete the proof of plateaued functions in this subsection, we shall start with two lemmas to streamline the proof process. 
    Define the parameters $\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4$ as follows:
        \begin{eqnarray}\label{coffdef}
            \begin{cases*}
                \epsilon_1=\gamma+\bar{\gamma}+\gamma c+\bar{\gamma}\bar{c}+\gamma a+\gamma b+\bar{\gamma}\bar{a}+\bar{\gamma}\bar{b},\\
                \epsilon_2=\omega(\bar{\gamma}+\gamma c)+\bar{\omega}(\gamma+\bar{\gamma}\bar{c})+\omega(\gamma a+\bar{\gamma}\bar{b})+\bar{\omega}(\bar{\gamma}\bar{a}+\gamma b),\\
                \epsilon_3=\bar{\omega}(\bar{\gamma}+\gamma c)+\omega(\gamma+\bar{\gamma}\bar{c})+\bar{\omega}(\bar{\gamma}\bar{a}+\gamma b)+\omega(\gamma a+\bar{\gamma}\bar{b}),\\
                \epsilon_4=\bar{\gamma}+\gamma c+\gamma+\bar{\gamma}\bar{c}+\omega(\bar{\gamma}\bar{a}+\gamma b)+\bar{\omega}(\gamma a+\bar{\gamma}\bar{b}).
            \end{cases*}
        \end{eqnarray}
    Lemma \ref{coff} summarizes certain constraints on parameters $\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4$ for each condition stated in Lemma \ref{qudpp}, see \cite{tu2018new} for more details. Lemma \ref{linear} is related to the maximum number of roots of a linearized polynomial.
    \begin{Lem}\label{coff}\cite{tu2018new}
        Let $n= 2m$ with $m$ odd, $\omega \in \F_{2^2} \backslash \F_2$, $\gamma \in \mathbb{F} _{2^{n}}$, and $a, b, c$ be the coefficients stated in Lemma \ref{qudpp}. Parameters $\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4$ defined by Eq. (\ref{coffdef}) adhere to the following constraints:\\
        (\Rm{1}) If Condition (1) of Lemma \ref{qudpp} holds, then $\epsilon_1=\epsilon_2=\epsilon_3$, and thus $\epsilon_2^2+\epsilon_1\epsilon_3=0$;\\
        (\Rm{2}) If Condition (2) or (3) of Lemma \ref{qudpp}  holds, then there is 
        \[
            \tr_m\left( \frac{(\epsilon_2^2+\epsilon_1\epsilon_3)^3}{(\epsilon_1\epsilon_4+\epsilon_2\epsilon_3)^2\epsilon_1^2} \right)=0 
        \]
        holds true when $\epsilon_1=\gamma+\bar{\gamma} \ne 0$ or $\epsilon_1=(1+a+b+c)(\gamma+\bar{\gamma}) \ne 0$, respectively.
    \end{Lem}
    \begin{Lem}\cite{trachtenberg1970cross}\label{linear}
        Let $k$ be an integer with $\gcd(k,n)=1$ and $L$ be a linearized polynomial of the form 
        \[
            L(x) = c_0x+c_1x^{2^k}+c_2x^{2^{2k}}+\cdots + c_dx^{2^{dk}}\in\F_{2^n}[x]
        \]
        of degree $2^{dk}$. Then $L$ has at most $2^d$ zeros in $\F_{2^n}$.  
    \end{Lem}
    \begin{Thm}\label{Thm_plateaued}
        Let $n=2m$ with $m$ odd, $P(x) = x^{3\cdot2^{m}}+ax^{2\cdot2^{m}+1}+bx^{2^{m}+2}+cx^3$, and $f_P$ be the balanced Boolean function parameterized by $P(x^2+x)$, where $a,b,c$ satisfy the conditions in Lemma \ref{qudpp}. Then $f_P$ is $(m+1)$-plateaued if Condition (1) of Lemma \ref{qudpp} holds and $2$-plateaued (semi-bent) if Condition (2) or (3) of Lemma \ref{qudpp} holds.
    \end{Thm}
    \begin{proof}
        According to Lemma \ref{relation} and Proposition \ref{nihopp}, 
        \begin{eqnarray*}
            W_{f_P}(\gamma)
            &=&-\sum_{z \in U_m}\sum_{y \in \F_{2^{m}}}{\chi_m\left( \varphi_1(z) y^3+\varphi_2(z) y \right)}+2^{m},
        \end{eqnarray*}
        where
        \[
            \varphi_1(z)=u z^3+\bar{u}z^{-3}+v z+\bar{v}z^{-1},~
            \varphi_2(z)=z+z^{-1},
        \]
        and 
        \[
            u=\bar{\gamma}+\gamma c,~
            v=\gamma b+\bar{\gamma}\bar{a}.
        \]
        Let $\lambda(t)$ denote the bijection 
        \begin{eqnarray*}
            \lambda : \F_{2^{m}} & \to & U_m \backslash \{1\} \\
            t & \mapsto & \frac{t+\omega}{t+\bar{\omega}}
        \end{eqnarray*}
        where $\omega\in\F_4\backslash\F_2$.
        Then for any $z\in U_m\backslash\{1\}$, there exists a unique element $t\in\F_{2^{m}}$ such that $z=\lambda(t)$. Thus $\varphi_1(z)$ and $\varphi_2(z)$ are respectively simplified to
        \begin{eqnarray*}
            \varphi_1(\lambda(t))&=&u \left( \frac{t+\omega}{t+\omega^2} \right)^3+\bar{u}\left( \frac{t+\omega^2}{t+\omega} \right)^{3}+v \left( \frac{t+\omega}{t+\omega^2} \right)+\bar{v}\left( \frac{t+\omega^2}{t+\omega} \right)\\
            &=&\frac{(u+\bar{u})(t^6+1)+(u \omega+\bar{u} \omega^2)t^2+(u \omega^2+\bar{u}\omega)t^4}{(t^2+t+1)^3}+\frac{(v+\bar{v})t^2+v \omega^2+\bar{v} \omega}{t^2+t+1}\\
            &=&\frac{\varepsilon_1 t^6+\varepsilon_2 t^4+\varepsilon_3 t^2+\varepsilon_4}{(t^2+t+1)^3},
        \end{eqnarray*}
        and 
        \begin{eqnarray*}
            \varphi_2(\lambda(t))=\frac{1}{t^2+t+1},
        \end{eqnarray*}
        where 
        \[
        \begin{cases*}
            \varepsilon_1=u+\bar{u}+v+\bar{v}=\epsilon_1,\\
            \varepsilon_2=(\bar{u}+v)\omega+(u+\bar{v})\omega^2=\epsilon_2+\epsilon_1,\\
            \varepsilon_3=(u+v)\omega+(\bar{u}+\bar{v})\omega^2=\epsilon_3+\epsilon_1,\\
            \varepsilon_4=u+\bar{u}+v \omega^2+\bar{v}\omega=\epsilon_4+\epsilon,
        \end{cases*}
        \]
        and $\epsilon=v+\bar{v}$, $\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4$ are the same as defined in Lemma \ref{coff}. 
        Then we have
        \begin{eqnarray}\label{W}
            W_{f_P}(\gamma)&=&-\sum_{z \in U_m \backslash \{1\}}\sum_{y \in \F_{2^{m}}}{\chi_m\left( \varphi_1(z) y^3+\varphi_2(z) y \right)}-\sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_1y^3)}+2^{m} \nonumber \\
            &=&-\sum_{t \in \F_{2^{m}}}\sum_{y \in \F_{2^{m}}}{\chi_m\left( \varphi_1(\lambda(t)) y^3+\varphi_2(\lambda(t)) y \right)}-\sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_1y^3)}+2^{m}.
        \end{eqnarray}
        Note that $\gcd(3,2^{m}-1)=1$, therefore $y^3$ permutes $\F_{2^{m}}$ and then 
        \[
        \sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_1y^3)}=
        \begin{cases}
            2^{m},& \text{if~} \varepsilon_1=\epsilon_1=0,\\
            0,&\text{otherwise}.
        \end{cases}
        \]
        The subsequent proof process depends on whether $\varepsilon_1$ is equal to $0$ or not. 

        (\Rm{1}) In the case of $\varepsilon_1=0$, (\ref{W}) is equivalent to
        \begin{eqnarray*}
            W_{f_P}(\gamma)&=&-\sum_{t \in \F_{2^{m}}}\sum_{y \in \F_{2^{m}}}{\chi_m\left( \varphi_1(\lambda(t)) y^3+\varphi_2(\lambda(t)) y \right)}~( \varphi_2(\lambda(t))y \to y) \\
            &=&-\sum_{t \in \F_{2^{m}}}\sum_{y \in \F_{2^{m}}}{\chi_m\left((\varepsilon_1 t^6+\varepsilon_2 t^4+\varepsilon_3 t^2+\varepsilon_4)y^3+y\right)} ~( t^2 \to t)\\
            &=&-\sum_{t \in \F_{2^{m}}}\sum_{y \in \F_{2^{m}}}{\chi_m\left((\varepsilon_1 t^3+\varepsilon_2 t^2+\varepsilon_3 t+\varepsilon_4)y^3+y\right)}\\
            &=&-\sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_4y^3+y)}\sum_{t \in \F_{2^{m}}}{\chi_m\left((\varepsilon_2t^2+\varepsilon_3t)y^3\right)}\\
            &=&-\sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_4 y^3 + y)}\sum_{t \in \F_{2^{m}}}{\chi_m\left(\left(\varepsilon_2 y^3+\varepsilon_3^2 y^6\right)t^2\right)}.
        \end{eqnarray*}

        If \textit{Condition (1)} holds, note that $\varepsilon_1=\varepsilon_2=\varepsilon_3=0$ due to $\varepsilon_1=\epsilon_1$ and $\epsilon_1=\epsilon_2=\epsilon_3$. Then for any $y\in \F_{2^{m}}$, we have $\sum_{t \in \F_{2^{m}}}{\chi_m\left(\left(\varepsilon_2 y^3+\varepsilon_3^2 y^6\right)t^2\right)}=2^m$. It is trival that $W_{f_P}(\gamma)=-2^{m}\sum_{y \in \F_{2^{m}}}{\chi_m(y)}=0$ when $\varepsilon_4 = 0$ holds true. And for any $\varepsilon_4 \ne 0$, we obtain
        \begin{eqnarray*}
            W_{f_P}(\gamma)&=&-2^{m}\sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_4y^3+y)}~(y \to \varepsilon_4^{-\frac{1}{3}} y)\\
            &=&-2^{m}\sum_{y \in \F_{2^{m}}}{\chi_m\left(y^3+\varepsilon_4^{-\frac{1}{3}}y\right)}\\
            &=&
            \begin{cases}
                -\left(\frac{2}{m}\right) \chi_m(\theta^3+\theta)2^{\frac{3m+1}{2}} ,&\text{if}~x^{4}+x=\left(\varepsilon_4^{-\frac{1}{3}}+1\right)^2~\text{has a solution}~ \theta\in\F_{2^{m}}, \\
                0,&\text{otherwise},
            \end{cases}
        \end{eqnarray*}
        where the last equality is owing to Lemma \ref{Three_sum}.  

        Let $\gamma=\gamma_1+\gamma_2\omega$ with $\gamma_1,\gamma_2 \in \F_{2^m}$. Then $\gamma \bar{\omega}=\gamma_1\bar{\omega}+\gamma_2$, $\bar{\gamma}\omega=\gamma_1\omega+\gamma_2$. Noting that $\bar{\omega}\bar{a}+a+\omega \ne 0$, we obtain
        \begin{eqnarray*}
            \varepsilon_1 = 0 &\Leftrightarrow& u+\bar{u}+v+\bar{v} = 0\\
            &\Leftrightarrow& \gamma a+\gamma b+\bar{\gamma}\bar{a}+\bar{\gamma}\bar{b}=0\\
            &\Leftrightarrow& \gamma(a+b)+\bar{\gamma}(\bar{a}+\bar{b})=0\\
            &\Leftrightarrow& \gamma \bar{\omega}(a+1)+\bar{\gamma} \omega (\bar{a}+1)=0\\
            &\Leftrightarrow& \gamma_2(a+\bar{a})=\gamma_1+\gamma_1 \bar{\omega} a+\gamma_1 \omega \bar{a}\\
            &\Leftrightarrow& \gamma_2(a+\bar{a})\omega=\gamma_1(\bar{\omega}\bar{a}+a+\omega)\\
            &\Leftrightarrow& \gamma \in R=\left\{\gamma_1+\gamma_2 \omega ~\Big| ~\gamma_2 \in \F_{2^m},\gamma_1=\frac{(a+\bar{a})\omega}{\bar{\omega}\bar{a}+a+\omega}\gamma_2\right\}.
        \end{eqnarray*}
        Then it can be verified that
        \begin{eqnarray*}
            \varepsilon_4 &=& \gamma a+\bar{\gamma}\bar{b}\\
            &=& \gamma a+\bar{\gamma}\left( \bar{\omega} (\bar{a}+1)+1 \right)\\
            &=& \gamma a+\bar{\gamma}\bar{\omega}\bar{a}+\bar{\gamma}\omega\\
            &=& \left( \gamma_1+\gamma_2 \omega \right)a+\left( \gamma_1 \bar{\omega}+\gamma_2 \omega \right)\bar{a}+\gamma_1\omega+\gamma_2\\
            &=& \gamma_2+ \gamma_2 \omega\left( a+\bar{a} \right)+\gamma_1 \omega+\gamma_1 \bar{\omega} \bar{a}+\gamma_1 a\\
            &=& \gamma_2.
        \end{eqnarray*}
        That is to say, for any  triple $(a,b,c)$ satisfying \textit{Condition (1)}, precisely $2^{m}$ distinct values of $\gamma$ such that $\varepsilon_1=0$ hold, and half of these $\gamma$ additionally ensure $\tr_m(\varepsilon_4^{-1/3})=1$, when $\gamma_2$ ranges over $\F_{2^{m}}$. Thus in this case, $W_f(\gamma)\in\{ 0 ,\pm 2^{\frac{3m+1}{2}}\}$.

        If \textit{Condition (2)} or \textit{(3)} holds, then $\varepsilon_1=\gamma+\bar{\gamma} \text{~or~} (\gamma+\bar{\gamma})(1+a+b+c)$ holds accordingly. We claim that $\varepsilon_2 \varepsilon_3 \varepsilon_4=0$ if and only if $\varepsilon_2 =\varepsilon_3 =\varepsilon_4=0$. In fact, the premise $\varepsilon_1=0$ directly ensures $\gamma \in \F_{2^m}$ and further limits  
        \begin{eqnarray*}
            \begin{cases*}
                \varepsilon_2=\gamma(a+\bar{a}+1),\\
                \varepsilon_3=\gamma(a+\bar{a}+1),\\
                \varepsilon_4=\gamma(a+\bar{a}+1),
            \end{cases*}
            \text{~or~}
            \begin{cases*}
                \varepsilon_2=\gamma(a+b+c+1),\\
                \varepsilon_3=\gamma(a+b+c+1),\\
                \varepsilon_4=\gamma(a+b).
            \end{cases*}
        \end{eqnarray*}
        Thus $\varepsilon_2 \varepsilon_3 \varepsilon_4 \ne 0$ holds when $\gamma \in \F_{2^m}^{*}$, and we obtain
        \begin{eqnarray*}
            W_{f_P}(\gamma)&=&-2^{m}\sum_{\{y|\varepsilon_2 y^3+\varepsilon_3^2 y^6=0\}}{\chi_m(\varepsilon_4 y^3+y)}\\
            &=&-2^{m}\left(\chi_m(0)+\chi_m\left(\varepsilon_4\frac{\varepsilon_2}{\varepsilon_3^2}+\left( \frac{\varepsilon_2}{\varepsilon_3^2}\right)^{\frac{1}{3}} \right) \right)\\
            &=&0 \text{~or~} -2^{\frac{2m+2}{2}},
        \end{eqnarray*}
        since 
        \[
        \sum_{t \in \F_{2^{m}}}{\chi_m\left(\left(\varepsilon_2 y^3+\varepsilon_3^2 y^6\right)t^2\right)}
        =
        \begin{cases}
            2^{m},& \text{if~} \varepsilon_2 y^3+\varepsilon_3^2 y^6=0,\\
            0,&\text{otherwise}.
        \end{cases}
        \]
        Moreover, it is evident that when $\gamma=0$, the equation $W_{f_P}(\gamma)=0$ holds true.

        (\Rm{2}) In the case of $\varepsilon_1 \ne 0$, (\ref{W}) becomes 
        \begin{eqnarray}\label{ww}
            W_{f_P}(\gamma)&=&-\sum_{y \in \F_{2^{m}}}{\chi_m(\varepsilon_4 y^3+y)}\sum_{t \in \F_{2^{m}}}{\chi_m\left((\varepsilon_1 t^3+\varepsilon_2 t^2+\varepsilon_3 t)y^3\right)}+2^{m}~( t \to t+\frac{\varepsilon_2}{\varepsilon_1}) \nonumber \\
            &=&-\sum_{y \in \F_{2^{m}}^{*}}{\chi_m\left(\left(\varepsilon_4+\frac{\varepsilon_2\varepsilon_3}{\varepsilon_1}\right)y^3+y\right)}\sum_{t \in \F_{2^{m}}}{\chi_m\left(\left(\varepsilon_1t^3+\left(\frac{\varepsilon_2^2}{\varepsilon_1}+\varepsilon_3\right)t\right)y^3\right)}~( yt \to t) \nonumber \\
            &=&-\sum_{y \in \F_{2^{m}}^{*}}{\chi_m\left(\left(\varepsilon_4+\frac{\varepsilon_2\varepsilon_3}{\varepsilon_1}\right)y^3+y\right)}\sum_{t \in \F_{2^{m}}}{\chi_m\left(\varepsilon_1t^3+\left(\frac{\varepsilon_2^2}{\varepsilon_1}+\varepsilon_3\right)y^2t\right)}~( \varepsilon_1^{\frac{1}{3}}t \to t) \nonumber \\
            &=&-\sum_{y \in \F_{2^{m}}^{*}}{\chi_m\left(\left(\varepsilon_4+\frac{\varepsilon_2\varepsilon_3}{\varepsilon_1}\right)y^3+y\right)}\sum_{t \in \F_{2^{m}}}{\chi_m\left(t^3+\frac{\varepsilon_2^2+\varepsilon_1\varepsilon_3}{\varepsilon_1^{4/3}}y^2t\right)}.
        \end{eqnarray}
        If $\varepsilon_2^2+\varepsilon_1\varepsilon_3 \ne 0$, (\ref{ww}) can continue to do calculations as follows:
        \begin{eqnarray*}
            W_{f_P}(\gamma)&=&-\sum_{y \in \F_{2^{m}}^{*}}{\chi_m\left(\left(\varepsilon_4+\frac{\varepsilon_2\varepsilon_3}{\varepsilon_1}\right)^2y^6+y^2\right)}\sum_{t \in \F_{2^{m}}}{\chi_m\left(t^3+\frac{\varepsilon_2^2+\varepsilon_1\varepsilon_3}{\varepsilon_1^{4/3}}y^2t\right)}\\
            &=&-\chi_m(\theta^3+\theta)\left(\frac{2}{m}\right)2^{\frac{m+1}{2}-1}\sum_{\theta \in \F_{2^{m}}^{*}}{\chi_m\left(U^2V^3(\theta^4+\theta+1)^3+V(\theta^4+\theta+1)\right)}\\
            &=&-\left(\frac{2}{m}\right)2^{\frac{m-1}{2}}\sum_{\theta \in \F_{2^{m}}^{*}}{\psi(\theta)},
        \end{eqnarray*}
        where $\psi(\theta)=\chi_m\left(\Delta(\theta^4+\theta+1)^3+V(\theta^4+\theta+1)+\theta^3+\theta \right)$, $y^2/V=1+\theta+\theta^4$ with 
        \begin{eqnarray*}
            U=\frac{\varepsilon_1\varepsilon_4+\varepsilon_2\varepsilon_3}{\varepsilon_1},~V=\frac{\varepsilon_1^{4/3}}{\varepsilon_2^2+\varepsilon_1\varepsilon_3},~\Delta=U^2V^3.
        \end{eqnarray*}
        Thus, we have
        \begin{eqnarray*}
            \psi(\theta)
            &=&\chi_m\left(\Delta(\theta^8+\theta^2+1)(\theta^4+\theta+1)+V(\theta^4+\theta+1)+\theta^3+\theta \right)\\
            &=&\chi_m\left(\Delta+V+\left(1+V+\Delta+\Delta^{\frac{1}{2}}+V^{\frac{1}{4}}+\Delta^{\frac{1}{4}}+\Delta^{\frac{1}{8}}\right)\theta+\left( 1+\Delta^{\frac{1}{4}}+\Delta^{\frac{1}{2}}+\Delta\right)\theta^3+\Delta\theta^9 \right)\\
            &=&\chi_m\left(\Delta+V \right) \psi^{\prime}(\theta),
        \end{eqnarray*}
        with 
        \[
        \psi^{\prime}(\theta)=\chi_m\left(\left(1+V+\Delta+\Delta^{\frac{1}{2}}+V^{\frac{1}{4}}+\Delta^{\frac{1}{4}}+\Delta^{\frac{1}{8}}\right)\theta+\left( 1+\Delta^{\frac{1}{4}}+\Delta^{\frac{1}{2}}+\Delta\right)\theta^3+\Delta\theta^9 \right),
        \]
        it suffices to compute $\sum_{\theta \in \F_{2^{m}}}{\psi^{\prime}(\theta)}$. Denote the associated bilinear mapping of $\psi^{\prime}$ by 
        \begin{eqnarray*}
            B_{\psi^{\prime}}(x,y)&=&\psi^{\prime}(x+y)+\psi^{\prime}(x)+\psi^{\prime}(y)\\
            &=&\chi_m\left( \left( 1+\Delta^{\frac{1}{4}}+\Delta^{\frac{1}{2}}+\Delta\right) (xy^2+x^2y)+\Delta(xy^8+x^8y) \right)\\
            &=&\chi_m\left(\left(\Delta^8y^{4^3}+\left( 1+\Delta+\Delta^2+\Delta^4\right)^2y^{4^2}+\left( 1+\Delta+\Delta^2+\Delta^4\right)y^4+\Delta y \right)x^8\right)\\
            &=&\chi_m\left( \left(\Delta^8(y^{16}+y^{64})+(1+\Delta^2+\Delta^4)(y^4+y^{16})+\Delta(y+y^4)\right)x^8 \right),
        \end{eqnarray*}
        then by Lemma \ref{linear} the dimension $d$ of the kernel of 
        \begin{eqnarray*}
            L(y)=\Delta^8y^{4^3}+\left( 1+\Delta+\Delta^2+\Delta^4\right)^2y^{4^2}+\left( 1+\Delta+\Delta^2+\Delta^4\right)y^4+\Delta y
        \end{eqnarray*}
        is not greater than 3. Since $\frac{m+d}{2}$ is an integer and $m$ is odd, $d=1~\text{or}~3$.

        Let $Y=y^4+y$, the equation $L(y)=0$ becomes
        \begin{eqnarray*}
             \Delta^8Y^{16}+(1+\Delta^2+\Delta^4)Y^4+\Delta Y =0,
        \end{eqnarray*}
        obviously $y=0$ and $y=1$ are solutions of $L(y)=0$, then we have
        \begin{eqnarray}\label{lasteq}
            && \Delta^8Y^{15}+(1+\Delta^2+\Delta^4)Y^3+\Delta=0~(\Delta Y^3 \to Z) \nonumber\\
            &\Leftrightarrow& \Delta^3Z^5+\frac{1+\Delta^2+\Delta^4}{\Delta}Z+\Delta=0 \nonumber\\
            &\Leftrightarrow& Z^5+\left(1+\frac{1}{\Delta^2}+\frac{1}{\Delta^4}\right)Z+\frac{1}{\Delta^2}=0.
        \end{eqnarray}
        Next, we examine the corresponding Walsh transform values for each condition.

        If \textit{Condition (1)} holds, note that $\varepsilon_2^2+\varepsilon_1\varepsilon_3=\epsilon_2^2+\epsilon_1^2+\epsilon_1\epsilon_3+\epsilon_1^2=\epsilon_2^2+\epsilon_1\epsilon_3=0$, Eq. (\ref{ww}) becomes 
        \begin{eqnarray*}
            W_{f_P}(\gamma)&=&-\sum_{y \in \F_{2^{m}}^{*}}{\chi_m\left(\left(\varepsilon_4+\frac{\varepsilon_2\varepsilon_3}{\varepsilon_1}\right)y^3+y\right)}\sum_{t \in \F_{2^{m}}}{\chi_m\left(t^3\right)}\\
            &=&0,
        \end{eqnarray*}
        where the last equality due to $\sum_{t \in \F_{2^{m}}}{\chi_m\left(t^3\right)}=0$.

        If \textit{Condition (2)} or \textit{(3)} holds, we have $\varepsilon_2^2+\varepsilon_1\varepsilon_3=(\epsilon_2+\epsilon_1)^2+\epsilon_1(\epsilon_3+\epsilon_1)=\epsilon_2^2+\epsilon_1\epsilon_3$ and $(\varepsilon_1\varepsilon_4+\varepsilon_2\varepsilon_3)\varepsilon_1=\epsilon_1\epsilon_4+\epsilon_1\epsilon+\epsilon_2\epsilon_3+\epsilon_1^2+\epsilon_1(\epsilon_2+\epsilon_3)=(\epsilon_1\epsilon_4+\epsilon_2\epsilon_3)\epsilon_1$ since $\epsilon_1(\epsilon_1+\epsilon_2+\epsilon_3+\epsilon)=\epsilon_1\cdot 0$. Combined with Lemma \ref{coff}, we can obtain that
        \begin{eqnarray*}
            \tr_m\left(\frac{1}{\Delta^2}\right)&=&\tr_m\left(\frac{1}{\Delta}\right)\\
            &=&\tr_m\left(\frac{(\varepsilon_2^2+\varepsilon_1\varepsilon_3)^3}{(\varepsilon_1\varepsilon_4+\varepsilon_2\varepsilon_3)^2\varepsilon_1^2}\right)\\
            &=&\tr_m\left(\frac{(\epsilon_2^2+\epsilon_1\epsilon_3)^3}{(\epsilon_1\epsilon_4+\epsilon_2\epsilon_3)^2\epsilon_1^2}\right)\\
            &=&0.
        \end{eqnarray*}
        For Eq. (\ref{lasteq}), there exists an element $\tau$ such that $\frac{1}{\Delta^2}=\tau^2+\tau$, it suffices to consider 
        \begin{eqnarray}\label{le2}
            Z^5+(1+\tau+\tau^4)Z+\tau+\tau^2=0,
        \end{eqnarray}
        and $Z=\tau$ is exactly a solution of Eq. (\ref{le2}), which means the dimension $d$ is greater than $1$, and thus $d = 3$. Moreover, 
        \begin{eqnarray*}
            W_{f_P}(\gamma)=-\chi_m\left(\Delta+V \right)\left(\frac{2}{m}\right)2^{\frac{m-1}{2}}\sum_{\theta \in \F_{2^{m}}^{*}}{\psi(\theta)} \in \{0,\pm 2^{\frac{2m+2}{2}}\}.
        \end{eqnarray*}

        The proof of the theorem is now complete.
    \end{proof}
    \begin{example}
        The permutation $P(x)=x^{3 \cdot 2^m}+x^{2 \cdot 2^m+1}+x^3$ satisfies \textit{Condition (2)} in Lemma \ref{qudpp}, and the Boolean function parameterized by $P(x^2+x)$ is $2$-plateaued (semi-bent) on $\F_{2^{2m}}$ with main cryptographic criteria shown in Table \ref{table3}.
