    \subsection{Constructions from DO permutations}
    Plateaued functions in this subsection are derived from a special case of the Dembowski-Ostrom (DO) polynomial of the form $xL(x)$ with $L(x)$ linearized. For permutation property and other applications of DO polynomial, see \cite{blokhuis2001permutations,patarin1996hidden}.
    \begin{Lem}\label{xL1}\cite{blokhuis2001permutations}
        Let $n,m$ be positive integers, the following linearized polynomials $L(x) \in \F_{2^n}[x]$ yield permutation polynomials of the form $xL(x)$ over $\F_{2^n}$:\\
        (1) $L(x)=x^{2^m}$ with $\frac{n}{\gcd(n,m)}$ odd.\\
        (2) $L(x)=x^{2^m}+ax^{2^{n-m}}$ with $\frac{n}{\gcd(n,m)}$ odd and $a^{\frac{2^n-1}{2^{\gcd(n,m)}-1}} \ne 1$.\\
        (3) $L(x)=x^{2^{2m}}+a^{2^m+1}x^{2^{m}}+ax$ with $n=3m$ and $a^{\frac{2^n-1}{2^{m}-1}} \ne 1$.
    \end{Lem}
    \begin{Thm}\label{ex1}
        Let $n,m$ be positive integers with $\frac{n}{\gcd(n,m)}$ odd. Suppose that  $P(x)=xL(x)$ and $f_P$ is the balanced Boolean function parameterized by $P(x^2+x)$. Then $f_P$ is $\gcd(n,m)$-plateaued on $\F_{2^n}$ if one of the following two conditions is satisfied:\\
        (1) $L(x)=x^{2^m}$; \\
        (2) $L(x)=x^{2^m}+ax^{2^{n-m}}$ with $a^{\frac{2^n-1}{2^{\gcd(n,m)}-1}} \ne 1$.
    \end{Thm}
    \begin{proof}
        Since the proofs under either Condition \textit{(1)} or \textit{(2)} are similar, only the latter is given here. 

        In light of Lemmas \ref{relation} and \ref{binoeq}, 
        \begin{eqnarray*}
            W_{f_P}(\gamma)&=& -\sum_{x \in \F_{2^n}}{\chi_n(\gamma xL(x)+x)} \\
            &=& -\sum_{x \in \F_{2^n}}{\chi_n(\gamma x^{2^m+1}+ \gamma ax^{2^{n-m}+1}+x)} \\
            %&=& \epsilon_n(f,\gamma)2^{\frac{n+d}{2}},
            &=& 
            \begin{cases}
                \pm 2^{\frac{n+d}{2}},& \text{if~} \varphi \text{~vanishes on~} V_{\varphi},\\
                0, & \text{otherwise},
            \end{cases}
        \end{eqnarray*}
        where $\varphi=\tr_n(\gamma xL(x)+x)$, and $d$ is the dimension of 
        \[
            V_{\varphi}=\left\{y \in \F_{2^n} \big| \left( \gamma^{2^{m}}+\left( \gamma a \right)^{2^{2m}} \right)y^{2^{2m}}+\left( \gamma+\left( \gamma a \right)^{2^m} \right)y=0 \right\}.
        \]

        Noting that $\frac{n}{\gcd(n,m)}$ is odd, we now turn to the equation  
        \begin{eqnarray*}
            \left( \gamma^{2^{m}}+\left( \gamma a \right)^{2^{2m}} \right)y^{2^{2m}}+\left( \gamma+\left( \gamma a \right)^{2^m} \right)y=0,
        \end{eqnarray*}
        which has $2^{\gcd(n,m)}$ solutions if $\gamma+(\gamma a)^{2^m} \ne 0$. That is to say $d=\gcd(n,m)$, thus  
        \[
            W_{f_P}(\gamma) \in \left\{ 0,\pm 2^{\frac{n+\gcd(n,m)}{2}} \right\}.
        \]

        This proof has been finished.
    \end{proof}
    \begin{Rem}
        Consistent with the notation in Theorem \ref{ex1}. Let $n$ be any odd integer, and $m$ be a positive integer with $\gcd(n,m)=1$, other conditions remain the same. Then the parameterized Boolean function derived from $P(x^2+x)$ with $P(x)=x^{2^{m}}$ is $1$-plateaued (near-bent) on $\F_{2^n}$.
    \end{Rem}
    \begin{Thm}\label{ex2}
        Let $n=3m$, $P(x)=xL(x)$, and $f_P$ be the balanced Boolean function parameterized by $P(x^2+x)$, where $L(x)=x^{2^{2m}}+a^{2^m+1}x^{2^{m}}+ax$ with $a^{\frac{2^n-1}{2^{m}-1}} \ne 1$. Then $f_P$ is $m$-plateaued on $\F_{2^n}$.
    \end{Thm}
    \begin{proof}
        Similar to the proof process of Theorem \ref{ex1}, we obtain $W_{f_P}(\gamma) \in \{0,\pm 2^{\frac{n+d}{2}}\}$, where $\varphi=\tr_n(\gamma xL(x)+x)$, $b=\gamma^{2^{2m}}+( \gamma a^{2^m+1})^{2^m}$, and $d$ is the dimension of 
        \[
            V_{\varphi}=\left\{y \in \F_{2^n}~\big|~b y^{2^{m}}+b^{2^m}\left(y^{2^m}\right)^{2^{2m}}=0 \right\}.
        \]

        Note that $\gcd(2^m,2^n-1)=1$, hence $y^{2^m}$ permutes $\F_{2^n}$. Then equation $b y^{2^{m}}+b^{2^m}\left(y^{2^m}\right)^{2^{2m}}=0$ and $b y+b^{2^m}y^{2^{2m}}=0$ have the same number of solutions, which equals $2^m$, and thus $d=m$. 

        Now we can conclude that $f_P$ is $m$-plateaued on $\F_{2^n}$.
    \end{proof}
    \begin{example}
        Given a primitive element $\alpha$, all balanced Boolean functions parameterized by $P(x^2+x)$ with permutations $P(x)=xL(x)$ are 2-plateaued (semi-bent) on $\F_{2^6}$, where $L(x)$ equals $x^{2^2}$, $x^{2^2}+\alpha x^{2^{6-4}}$, or $x^{2^{2 \cdot 2}}+\alpha^{2^2+1} x^{2^{2}}+\alpha x$. Table \ref{table4} details their main cryptographic properties consistent with the claims presented in Theorems \ref{ex1} and \ref{ex2}.
