    \subsection{Constructions from permutation of the form $cx+\tr_{m}^{km}(x^s)$}
    Different from permutations with Niho exponents in Section \ref{four-valued}, here we choose the quadratic ones of the form $cx+\tr^{km}_{m}(x^s)$.
    \begin{Lem}\cite{li2018permutation}
        Let $m,k,i$ be positive integers. Then the following polynomials of the form $cx+\tr^{km}_{m}(x^s)$ permute $\F_{2^{km}}$.\\
        (1) $P=cx+\tr^{km}_{m}(x^{2^i(2^{m}+1)})$ where $c \in \F_{2^{2m}} \backslash \F_{2^{m}}$ and $k \equiv 2 \pmod{4}$;\\
        (2) $P=cx+\tr^{km}_{m}(x^{\frac{2^{2m}+2^{m}}{2}})$ where $c \in \F_{2^{m}} \backslash \F_2$ and $k$ odd;\\
        (3) $P=cx+\tr^{km}_{m}(x^{2(2^{im}+1)})$ where $c \in \F_{2^{m}}^{*}$, $c^{\frac{2^{m}-1}{3}} \ne 1$, $m \not \equiv 0 \pmod {3}$, $m$ even and $k$ odd.
    \end{Lem}
    \begin{Lem}\label{symmetry}
        Let $k,m,s$ be positive integers and $\gamma \in \F_{2^{km}}$. The trace functions $\tr_{km}(x)$ and $\tr_{m}^{km}(x)$ satisfy the following equation:
        \[
            \tr_{km}\left(\gamma \tr^{km}_{m}(x^s)\right)=\tr_{km}\left( \tr_{m}^{km}(\gamma) x^{s} \right).
        \]
    \end{Lem}
    \begin{proof}
        It is evident that
        \begin{eqnarray*}
            \tr_{km}\left(\gamma \tr^{km}_{m}(x^s)\right)
            &=& \tr_{km}\left(\gamma \left( x^{s}+x^{s2^m}+\cdots+x^{s2^{m(k-1)}} \right) \right)\\
            &=& \tr_{km}\left( \left( \gamma+\gamma^{\frac{1}{2^m}}+\cdots+\gamma^{\frac{1}{2^{m(k-1)}}} \right) x^{s} \right)\\
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma^{\frac{1}{2^{m(k-1)}}}) x^{s} \right)\\
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma) x^{s} \right).
        \end{eqnarray*}
    \end{proof}
    \begin{Thm}\label{pl2}
        Let $m,k,i$ be positive integers, $c \in \F_{2^{2m}} \backslash \F_{2^{m}}$, and $k \equiv 2 \pmod{4}$. Consider the balanced Boolean function $f_P$ derived from $P(x^2+x)$ with $P(x)=cx+\tr^{km}_{m}(x^{2^i(2^{m}+1)})$. Then $f_P$ is $2m$-plateaued on $\F_{2^{km}}$.
    \end{Thm}
    \begin{proof}
        According to Lemma \ref{symmetry}, we observe the fact that
        \begin{eqnarray*}
            \tr_{km}\left(\gamma \tr^{km}_{m}(x^{2^i(2^{m}+1)})\right)
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma) x^{2^i(2^{m}+1)} \right)\\
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma)^{\frac{1}{2^i}} x^{2^{m}+1} \right).
        \end{eqnarray*}
        Consequently, as established by Lemma \ref{relation}, the Walsh transform of the function $f$ evaluated at arbitrary $\gamma \in \F_{2^{km}}$ simplifies to
        \begin{eqnarray*}
            W_{f_P}(\gamma) &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}(\gamma P(x)+x)} \\
            &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}\left(\gamma \tr^{km}_{m}(x^{2^i(2^{m}+1)})+(\gamma c+1)x \right)}\\
            &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}\left(\tr_{m}^{km}(\gamma)^{\frac{1}{2^i}} x^{2^{m}+1}+(\gamma c+1)x \right)}.
        \end{eqnarray*}

        We claim that $\gamma c+1 \ne 0$ always holds for any $\gamma$ such that $\tr_{m}^{km}(\gamma)=0$. If the claim is not true, then $\gamma=c^{-1} \in \F_{2^{2m}} \backslash \F_{2^{m}}$, which implies $\gamma^{2^{2m}}+\gamma=0$ and $\gamma^{2^{m}}+\gamma \ne 0$. This leads to a contradiction
        \begin{eqnarray*}
            \tr_{m}^{km}(\gamma) &=& \gamma+\gamma^{2^{m}}+\cdots+\gamma^{2^{(k-1)m}}\\
            &=& \gamma+\gamma^{2^{m}} \ne 0.
        \end{eqnarray*}

        Therefore, we can make the conclusion that (\Rm{1}) if $\tr_{m}^{km}(\gamma)=0$, then $W_f(\gamma)=0$; (\Rm{2}) if $\tr_{m}^{km}(\gamma) \ne 0$, the bilinear form of 
        \[
            \tr_{km}\left(\tr_{m}^{km}(\gamma)^{\frac{1}{2^i}} x^{2^{m}+1}+(\gamma c+1)x\right)
        \]
        has a $2m$-dimensional kernel over $\F_{2}$, since $\gcd(2m,km)=2m$. Then we obtain
        \[
        W_{f_P}(\gamma) \in \left\{0,\pm 2^{\frac{km+2m}{2}}\right\}.
        \]

        Complete the proof here.
    \end{proof}
    \begin{Rem}
        Consistent with the notation in Theorem \ref{pl2}. Let $m=1$, and other conditions remain the same. Then parameterized Boolean function derived from $P(x^2+x)$ with $P(x)=cx+\tr_{k}(x^{3})$ is $2$-plateaued (semi-bent) on $\F_{2^k}$.
    \end{Rem}
    \begin{Thm}\label{pl3}
        Let $m,k,i$ be positive integers with $k$ odd, $c \in \F_{2^{m}} \backslash \F_{2}$. Consider the balanced Boolean function $f_P$ derived from $P(x^2+x)$ with $P(x)=cx+\tr^{km}_{m}(x^{\frac{2^{2m}+2^{m}}{2}})$. Then $f_P$ is $m$-plateaued on $\F_{2^{km}}$.
    \end{Thm}
    \begin{proof}
        Note that 
        \begin{eqnarray*}
            \tr_{km}\left(\gamma \tr^{km}_{m}(x^{\frac{2^{2m}+2^{m}}{2}})\right)
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma) x^{\frac{2^{m}(2^{m}+1)}{2}} \right)\\
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma)^{\frac{2}{2^{m}}} x^{2^{m}+1} \right),
        \end{eqnarray*}
        then we need to compute 
        \begin{eqnarray*}
            W_{f_P}(\gamma) &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}(\gamma P(x)+x)} \\
            &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}\left(\gamma \tr^{km}_{m}(x^{\frac{2^{2m}+2^{m}}{2}})+(\gamma c+1)x \right)}\\
            &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}\left(\tr_{m}^{km}(\gamma)^{\frac{2}{2^{m}}} x^{2^{m}+1}+(\gamma c+1)x \right)},
        \end{eqnarray*}
        divide it into two cases that $\gamma$ satisfies (\Rm{1}) $\tr_{m}^{km}(\gamma)=0$ or (\Rm{2}) $\tr_{m}^{km}(\gamma) \ne 0$.

        (\Rm{1}) In the case of $\tr_{m}^{km}(\gamma)=0$, it can be proved that $\gamma c+1 \ne 0$. Otherwise $\gamma =c^{-1} \in \F_{2^{m}} \backslash \F_{2}$, and then
        \begin{eqnarray*}
            \tr_{m}^{km}(\gamma) &=& \gamma+\gamma^{2^{m}}+\cdots+\gamma^{2^{(k-1)m}}\\
            &=& \underbrace{\gamma+\gamma+\cdots+\gamma}_{k \text{~times~with~} k \text{~odd}} \\
            &=& \gamma ~\ne~ 0,
        \end{eqnarray*}
        which contradicts the assumption. Thus we get
        \begin{eqnarray*}
            W_{f_P}(\gamma)=-\sum_{x \in \F_{2^{km}}}{\chi_{km}\left((\gamma c+1)x \right)}=0.
        \end{eqnarray*}

        (\Rm{2}) Consider the case of $\tr_{m}^{km}(\gamma) \ne 0$, then according to Lemma \ref{binoeq}, the bilinear form of 
        \[
            \tr_{km}\left(\tr_{m}^{km}(\gamma)^{\frac{2}{2^{m}}} x^{2^{m}+1}+(\gamma c+1)x\right)
        \]
        has a $m$-dimensional kernel over $\F_{2}$, since $\gcd(km,2m)=m$ and $\frac{km}{\gcd(km,m)}$ is odd, which implies 
        \[
            W_{f_P}(\gamma) \in \left\{ 0,\pm 2^{\frac{km+m}{2}}\right\}.
        \]

        The proof can be completed here. 
    \end{proof}
    \begin{Rem}
        Consistent with the notation in Theorem \ref{pl3}. Let $m=2$ and other conditions remain the same. Then parameterized Boolean function derived from $P(x^2+x)$ with $P(x)=cx+\tr_{2}^{2k}(x^{10})$ is $2$-plateaued (semi-bent) on $\F_{2^{2k}}$.
    \end{Rem}
    \begin{Thm}\label{pl4}
        Let $m,k,i$ be positive integers, where $k$ is odd, $m$ is even, and $m \not \equiv 0 \pmod{3}$. Consider the balanced Boolean function $f_P$ derived from $P(x^2+x)$ with $P(x)=cx+\tr^{km}_{m}(x^{2(2^{im}+1)})$, where $c \in \F_{2^{m}}^{*}$ such that $c^{\frac{2^{m}-1}{3}} \ne 1$. Then $f_P$ is $m\gcd(i,k)$-plateaued on $\F_{2^{km}}$.
    \end{Thm}
    \begin{proof}
        We claim that
        \begin{eqnarray*}
            \tr_{km}\left(\gamma \tr^{km}_{m}(x^{2(2^{im}+1)})\right)
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma) x^{2(2^{im}+1)} \right)\\
            &=& \tr_{km}\left( \tr_{m}^{km}(\gamma)^{\frac{1}{2}} x^{2^{im}+1} \right),
        \end{eqnarray*}
        and then it suffices to compute
        \begin{eqnarray*}
            W_{f_P}(\gamma) &=& -\sum_{x \in \F_{2^{km}}}{\chi_{km}\left(\tr_{m}^{km}(\gamma)^{\frac{1}{2}} x^{2^{im}+1}+(\gamma c+1)x \right)}.
        \end{eqnarray*}

         The proof process for the remaining part is similar to the previous theorem and is omitted here.
    \end{proof}
    \begin{Rem}
        Consistent with the notation in Theorem \ref{pl4}. Let $m=2$, $i$ be a positive integer with $\gcd(i,k)=1$, and other conditions remain the same. Then parameterized Boolean function derived from $P(x^2+x)$ with $P(x)=cx+\tr_{2}^{2k}(x^{2^{2i+1}+2})$ is $2$-plateaued (semi-bent) on $\F_{2^{2k}}$.
    \end{Rem}


    \section{Conclusions and further work}\label{conclusion}
    In this paper, the parametric construction approach was employed to construct few-valued spectrum Boolean functions from $2$-to-$1$ mappings of the form $P(x^2+x)$ where $P$ represents sparse permutation polynomials. By carefully selecting permutations with low degrees or Niho exponents, we constructed a new class of four-valued spectrum functions and seven plateaued functions, including four semi-bent subclasses and a near-bent subclass. 

    Our analysis demonstrates that the computability afforded by quadratic or Niho exponents enables the effective determination of Walsh spectra, directly revealing the nonlinear properties of constructed Boolean functions through their underlying algebraic structures. It is expected to obtain more valuable results by considering permutations and $2$-to-$1$ mappings with other specific properties, e.g., Dillon exponents.


