\begin{theorem}
    \cm is NP-hard.
\end{theorem}
\begin{proof}
    We will reduce from the \textsc{Max Cut} problem, which is NP-hard~\cite{Karp72}. Let \(G=(V, E)\) be a \textsc{Max Cut} instance with \(V = [n]\). From \(G\), we will construct a \cm instance \(S \subseteq \mathcal{S}_{N}\) consisting of permutations of length \(N := 3n+2\). On a high level, our construction will work as follows. We will first construct many copies of two special permutations that will force every median of \(S\) to take on a very specific structure. All permutations of this structure will naturally encode cuts of the vertex set \(V\). Then for each edge \(e\) in \(G\), we will construct permutations that reward choosing a median that ``cuts'' \(e\). Thus, we will end up with a set of permutations whose overall median will encode the maximum cut of \(G\). Details follow.

    To describe our construction, it will be convenient to define the following two strings, both of length \((n+1)\):
    \begin{align*}
        X_1 &:= (n+1)\circ(n+2)\circ \cdots \circ (2n+1), \\
        X_2 &:= (2n+2)\circ(2n+3)\circ \cdots \circ (3n+2).
    \end{align*}
    Next, we define the two special permutations \(\pi^L, \pi^R \in \mathcal{S}_{N}\) alluded to earlier:
    \begin{align*}
        \pi^L &:= 1\circ 2 \circ \cdots \circ (n-1) \circ n \circ X_1 \circ X_2, \\
        \pi^R &:= X_1 \circ n \circ (n-1) \circ \cdots \circ 2 \circ 1 \circ X_2.
    \end{align*}
We make the observation that every median of the set \(\{\pi^{L}, \pi^R\}\) naturally encodes a cut of the vertex set \(V\).
\begin{defi}
    For a nonnegative integer \(r \leq n\), let \(A = \{a_1, a_2, \ldots , a_r\}\) and \(B=\{b_1, b_2, \ldots , b_{n-r}\}\) be sets such that \(A \sqcup B = [n]\), \(a_1 < a_2 < \cdots  < a_r\) and \(b_1 > b_2 > \cdots > b_{n-r}\). Define \(\pi^{A, B} \in \mathcal{S}_{N}\) as:
    \[\pi^{A, B} := a_1 \circ a_2 \circ \cdots \circ a_r \circ X_1 \circ b_1 \circ b_2 \circ \cdots \circ b_{n-r} \circ X_2.\]
    Furthermore, define \(\mathcal{S}_{N}^{*} \subseteq \mathcal{S}_{N}\) as:
    \[\mathcal{S}_{N}^{*}:= \{\pi \in \mathcal{S}_N: \pi = \pi^{A, B} \textnormal{ for some pair of sets \(A, B\) with \(A \sqcup B = [n]\)} \}.\]
\end{defi}
Clearly, permutations in \(\mathcal{S}_N^*\) naturally encode cuts of \([n]\). We will first show that every permutation in \(\mathcal{S}_N^*\) has the same sum of Ulam distances to \(\pi^L\) and \(\pi^R\).
\begin{lemma}
\label{lemma:legal-cost}
    For every \(\pi \in \mathcal{S}_N^*\), \(d_U(\pi, \pi^L) + d_U(\pi, \pi^R) = n\).
\end{lemma}
\begin{proof}
\renewcommand\qedsymbol{\(\lrcorner\)}
    Fix some \(\pi \in \mathcal{S}_N^*\). Then \(\pi = \pi^{A, B}\) for some sets \(A, B\) with \(A\sqcup B = [n]\). Let \(|A| = r\) and \(|B| = n-r\) for some nonnegative integer \(r\leq n\). Clearly, \(\LCS(\pi, \pi^L)\geq r + 2(n+1)\), since one can form a common subsequence of \(\pi\) and \(\pi^L\) by deleting the symbols in \(B\) from both. Furthermore, no LCS of \(\pi\) and \(\pi^L\) can contain a symbol from \(B\) since otherwise, the LCS would not contain any symbol from \(X_1\) and would have a length that is at most \(2n+1\). Therefore, \(\LCS(\pi, \pi^L) = r + 2(n+1)\) and \(d_U(\pi, \pi^L) = n-r\). By a similar argument, \(d_U(\pi, \pi^R) = r\). So, \(d_U(\pi, \pi^L) + d_U(\pi, \pi^R) = n\).
\end{proof}
Next, we show that any permutation that is not in \(\mathcal{S}_N^*\) has strictly larger sum of Ulam distances to \(\pi^L\) and \(\pi^R\).
\begin{restatable}{lemma}{tedious}
\label{lemma:suboptimality}
    Let \(\pi \notin \mathcal{S}_N^*\). Then \(d_U(\pi, \pi^L) + d_U(\pi, \pi^R) \geq n+1\). 
\end{restatable}
The proof of Lemma~\ref{lemma:suboptimality} involves somewhat tedious casework and has been deferred to Appendix~\ref{sec:suboptimality}.

% \begin{figure}
%     \centering
