%     \caption{Edge gadgets \(\pi_e^1\) and \(\pi_e^2\) for the edge \(e=\{i, j\}\) with \(i<j\). The strings \(X_1\) and \(X_2\) are so long that they appear in every LCS. If the edge \(e\) is not cut by the partition \((A, B)\), then exactly one of \(i\) or \(j\) appears in one of the LCS while neither appears in the other.}
%     \label{fig:edge-gadget-2}
% \end{figure}

The final pieces in our construction are the ``edge gadgets'', which we now define. For each edge \(e = \{i, j\} \in E\), where \(i < j\), define the following two strings:
\begin{align*}
    \pi_e^1 &= j\circ i\circ X_1 \circ X_2 \circ 1 \circ 2 \circ \cdots \circ (i-1) \circ (i+1) \circ \cdots \circ (j-1) \circ (j+1) \circ \cdots \circ n, \\
    \pi_e^2 &=  X_1 \circ i\circ j\circ X_2 \circ 1 \circ 2 \circ \cdots \circ (i-1) \circ (i+1) \circ \cdots \circ (j-1) \circ (j+1) \circ \cdots \circ n.
\end{align*}
The role of the edge gadgets associated with an edge \(e\) is to reward choosing partitions of the vertices that cut \(e\). This is formalized in the following lemma.
\begin{lemma}
\label{lemma:edge-gadget}
    Let \(\pi\in \mathcal{S}^*_N\) such that \(\pi = \pi^{A, B}\) with \(A \sqcup B =[n]\) and \(e\in E\). Then we have the following:
    \[d_U(\pi_e^1, \pi ) +d_U(\pi_e^2, \pi)=\begin{cases}
        2n-2, & \text{if \(e\) is cut by the partition \((A, B)\),}\\
        2n-1, & \text{otherwise.}
    \end{cases}\]
\end{lemma}
\begin{proof}
\renewcommand\qedsymbol{\(\lrcorner\)}
    Suppose \(e\) is cut by the partition \((A, B)\) and let \(\{k\}=A\cap e\). We must have \(\LCS(\pi_e^1, \pi) \geq 2n+3\) since the string \(k \circ X_1 \circ X_2\) is a common subsequence of \(\pi_e^1\) and \(\pi\).
    Furthermore, no LCS of \(\pi_e^1\) and \(\pi\) can contain any symbol in \([n]\setminus\{k\}\) since otherwise, the LCS would not contain any symbol from one of \(X_1\) and \(X_2\), and consequently, would have a length of at most \(2n+1\). Therefore, \(\LCS(\pi_e^1, \pi) = 2n+3\) and \(d_U(\pi_e^1, \pi)=n-1\). By essentially the same argument, we also have \(d_U(\pi_e^2, \pi )=n-1\) and therefore, \(d_U(\pi_e^1, \pi ) +d_U(\pi_e^2, \pi)=2n-2\).

    If \(e\) is not cut by the partition \((A, B)\), then assume that \(e=\{i, j\} \subseteq A\). The case where \(e\subseteq B\) is similar. First, note that \(\LCS(\pi_e^1, \pi) \geq 2n+3\) since the string \(i \circ X_1 \circ X_2\) is a common subsequence of \(\pi_e^1\) and \(\pi\). Furthermore, \(\LCS(\pi_e^1, \pi) \leq 2n+3\) because of the following two reasons:
    \begin{itemize}
        \item No LCS of \(\pi_e^1\) and \(\pi\) can contain both \(i\) and \(j\) since their relative order is different in \(\pi_e^1\) and \(\pi\).
        \item No LCS of \(\pi_e^1\) and \(\pi\) can contain any symbol in \([n]\setminus\{i, j\}\) since otherwise, the LCS would not contain any symbol from one of \(X_1\) and \(X_2\), and consequently, would have a length of at most \(2n+1\).
    \end{itemize}
    Therefore, \(\LCS(\pi_e^1, \pi) = 2n+3\) and \(d_U(\pi_e^1, \pi)=n-1\).
    Next we claim that \(\LCS(\pi_e^2, \pi) \leq 2n+2\). Let \(\rho\) be any LCS of \(\pi_e^2\) and \(\pi\). We make the following observations.
    \begin{itemize}
        \item If \(\rho\) contains any symbol from \(A\), then \(\rho\) cannot contain any symbol from \(X_1\) forcing \(|\rho|\leq 2n+1\).
        \item If \(\rho\) contains any symbol from \(B\), then \(\rho\) cannot contain any symbol from \(X_2\), once again forcing \(|\rho|\leq 2n+1\). This is because \(B\) contains neither \(i\) nor \(j\).
    \end{itemize}
    Therefore, the symbols of \(\rho\) must come from \(X_1\) or \(X_2\) and so, \(|\rho| \leq |X_1| +|X_2| =2n+2\). Furthermore, \(X_1\circ X_2\) is a common subsequence of \(\pi_e^2\) and \(\pi\). Therefore, \(\LCS(\pi_e^1, \pi) = 2n+2\) and \(d_U(\pi_e^1, \pi)=n\). Putting everything together, we have \(d_U(\pi_e^1, \pi ) +d_U(\pi_e^2, \pi)=2n-1\).
\end{proof}
Now let \(S_E=\{\pi_e^1 : e\in E\} \cup \{\pi_e^2 : e\in E\}\) and \(S_{\text{aux}}\) be the set consisting of \(t:=|E|(2n-1)\) copies of \(\pi^L\) and \(\pi^R\). Our final \cm instance will be the multiset
\[S:= S_E \cup S_{\text{aux}}.\]
We now show that  \(G\) has a cut of size at least \(k\) if and only if the median of \(S\) has cost at most \(k'\), where \(k'= |E|(2n-1) - k +tn\). For the completeness case, assume there exist sets \(A, B\) with \(A\sqcup B =n\) such that the partition \((A, B)\) cuts at least \(k\) edges in \(G\). Denote by \(E(A, B)\) the set of all edges cut by the partition \((A, B)\). Now consider the permutation \(\pi^{A, B} \in \mathcal{S}_n\) and note that:

\begin{small}
\begin{align*}
    \sum_{\pi\in S} d_U(\pi^{A, B}, \pi) & = \sum_{\pi\in S_E}d_U(\pi^{A, B}, \pi) + \sum_{\pi\in S_{\text{aux}}} d_U(\pi^{A, B}, \pi)\\
    & = \left(\sum_{e\in E}(d_U(\pi^{A, B}, \pi_e^1)+d_U(\pi^{A, B}, \pi_e^2))\right) + t(d_U(\pi^{A, B}, \pi^L)+d_U(\pi^{A, B}, \pi^R))\\
    &=\left(\sum_{e\in E(A, B)}(d_U(\pi^{A, B}, \pi_e^1)+d_U(\pi^{A, B}, \pi_e^2)) + \sum_{e\notin E(A, B)}(d_U(\pi^{A, B}, \pi_e^1)+d_U(\pi^{A, B}, \pi_e^2))\right) + tn\\
    & =\left(|E(A, B)|(2n-2)+ (|E|-|E(A, B)|)(2n-1)\right) + tn\\
    & = |E|(2n-1) - |E(A, B)| +tn\\
    & \leq |E|(2n-1) - k +tn.
\end{align*}
\end{small}

For the soundness case, assume that there exists \(\pi^* \in \mathcal{S}_N\) whose median cost to \(S\) is at most \(k'\). We can further assume that \(\pi^*\in \mathcal{S}^*_N\) since otherwise, every \(\tilde{\pi}\in \mathcal{S}^*_N\) will have a median cost that is at most that of \(\pi^*\). Indeed, assume that \(\pi^*\notin \mathcal{S}^*_N\) and fix any \(\tilde{\pi}\in \mathcal{S}^*_N\). We have:
\begin{align*}
    \sum_{\pi\in S}d_U(\pi^*, \pi) &=\sum_{\pi\in S_{\text{aux}}}d_U(\pi^*, \pi) +\sum_{\pi\in S_E}d_U(\pi^*, \pi)\\
    &\geq t(n+1) + 0\\
    &= tn +t\\
    &=tn + |E|(2n-1)\\
    &\geq tn +\sum_{\pi\in S_{E}}d_U(\tilde{\pi}, \pi)\\
    & = \sum_{\pi\in S_{\text{aux}}}d_U(\tilde\pi, \pi) +\sum_{\pi\in S_E}d_U(\tilde\pi, \pi)= \sum_{\pi\in S}d_U(\tilde\pi, \pi).
\end{align*}
Thus, the assumption that \(\pi^*\in \mathcal{S}^*_N\) is without loss of generality. Then, we have \(\pi^*=\pi^{A, B}\) for sets \(A, B\) with \(A\sqcup B =[n]\). We claim that the partition \((A, B)\) cuts at least \(k\) edges in \(G\). Indeed, since \(\sum_{\pi\in S_{\text{aux}}}d_U(\pi^*, \pi)=tn\), we have \(\sum_{\pi\in S_{E}}d_U(\pi^*, \pi) \leq k' - tn = |E|(2n-1)-k = k(2n-2)+(|E|-k)(2n-1)\). Then, by Lemma~\ref{lemma:edge-gadget} the partition \((A, B)\) cuts at least \(k\) edges.
\end{proof}

\begin{remark}
    Although our NP-hardness reduction produces multisets instead of sets, it is not to hard to turn them into sets by appending a unique permutation to each permutation without affecting the structure of the solution. See Appendix~\ref{sec:from-multisets-to-sets} for details. 
\end{remark}

