    \centering
    \renewcommand{\arraystretch}{1.4} % Adjust row spacing

    \begin{tabular}{|p{0.927\textwidth}|}
        \hline
        \dc \\
        \hline
    \end{tabular}

    \begin{tabular}{|p{0.15\textwidth}|p{0.75\textwidth}|}
        \hline
        \textbf{Input:} & A set \(S\subseteq \mathcal{S}_L\) of permutations such that \(|S|=n\) and an integer \(\tau\).\\
        \hline
        \textbf{Question:} & Is there a permutation \(\pi^*\in S\) such that \(\max_{\pi\in S}d_U(\pi, \pi^*)\leq \tau\)?  \\
