\section*{\textbf{Supplementary Material}}
\vspace{-2mm}
The supplementary material is structured as follows:

\Cref{app:proposition_sec} presents a proposition that provides special cases of the generalized Householder product for specific choices of keys and betas and characterizes the spectrum of the product of two generalized Householders.

\Cref{app:expressivity} characterizes the expressivity of DeltaProduct. 
\begin{itemize}
        \item \ref{app:expressivity:group_word_rproblems} demonstrates how DeltaProduct can solve any group word problem in a single layer when $n_h$ is sufficiently high, or alternatively using up to 4 layers when $n_h$ is limited.
        \item \ref{app:regular} shows how DeltaProduct can recognize any regular language in a finite number of layers using the Krohn-Rhodes decomposition.
        \item \ref{app:rwkv_7_regular} details the expressivity of a linear RNN with products of RWKV-7 state-transition matrices.
        \item \ref{app:dihedral} demonstrates how DeltaNet can solve any dihedral group in 2 layers using a specific construction.
        \item \ref{app:stabilityvsexpressivity} discusses the tradeoff between expressivity and stability in linear RNNs.
\end{itemize}


\Cref{app:experiments} provides comprehensive details on our experiments and additional results.

We provide the code for our experiments at \url{https://github.com/automl/DeltaProduct}

\textbf{Notation.} Mathematical objects are typically styled as follows.
Matrices: uppercase letters (e.g., $\mA, \mH, \mM$).
Vectors: lowercase letters (e.g., $\vk, \vv, \vx$).
Standard sets: $\R$ for reals, $\C$ for complexes, $\N$ for naturals. Common symbols and operations are denoted as follows.
$\mI$: Identity matrix.
$\top$: Transpose operator (e.g., $\vk^\top$).
$\|\vv\|$ or $\|\vv\|_2$: Euclidean norm of a vector $\vv$.
$\|\mA\|$: the operator norm for a matrix $\mA$.
$|\cdot|$: Absolute value for real scalars, or modulus for complex numbers.
$\odot$: Element-wise (Hadamard) product.
$\spec(\mA), \rho(\mA)$: Spectrum (set of eigenvalues) and spectral radius of matrix $\mA$.
$\text{tr}(\mA), \det(\mA)$: Trace and determinant of matrix $\mA$.
$\kron_{ij}$: Kronecker delta (1 if $i=j$, 0 otherwise). $\ve_i \in \{0,1\}^n$ is the $i$-th element of the canonical basis of $\R^n$.
\vspace{-3mm}
\section{Spectral Properties and Simplifications of Householder Product Matrices}\label{app:proposition_sec}
\vspace{-2mm}
The following proposition characterizes conditions under which the product structure simplifies and the spectrum is real, contrasting with the general case which allows for complex spectra. It provides illustrative special cases for the more general Proposition 1 in~\citet{grazzi-iclr25a}.
\begin{proposition}\label{proposition:householder}
Let $\mA \in \R^{n \times n}$ be a matrix defined as the product of $n_h \ge 1$ generalized Householder transformations:
$ \mA = \prod_{j=1}^{n_h} \mH_j$
where each $\mH_j = \mI - \beta_j \vk_j \vk_j^\top$, with $\vk_j \in \R^n$ being a unit vector ($\norm{\vk_j}_2 = 1$) and $\beta_j \in [0, 2]$. Let $\spec(\mA) \subset \C$ denote the spectrum (set of eigenvalues) of $\mA$. Then, all eigenvalues $\lambda \in \spec(\mA)$ satisfy $\abs{\lambda} \le 1$ and the following hold.
\vspace{-2mm}
\begin{enumerate}[leftmargin=2em]
    \item \textbf{(Identical Direction Vector)} Let $\vk \in\mathbb{R}^n$ be nonzero and  $\vk_j = \vk / \norm{\vk}$ for all $j=1..m$. Then
        $\prod_{j=1}^m 
        \bigl(\mI - \beta_j\, \vk\vk^\top \bigr)
        =
        \mI
        -
        \beta^*\,
        \vk\vk^\top$
    for some real scalar $\beta^*$ depending on $\{\beta\}_{j=1}^m$. The product collapses to a single effective transformation of the same form. Consequently, if $\mA$ is formed using only a single direction vector $\vk_1$, it is symmetric and its spectrum is real.

    \item \textbf{(Orthogonal Vectors)} If the direction vectors $\{\vk_j\}_{j=1}^{n_h}$ form an orthonormal set (i.e., $\vk_j^\top \vk_l = \kron_{jl}$; this requires $n_h \le n$), then the factors $\mH_j$ commute, and the product simplifies to $\mA = \mI - \sum_{j=1}^{n_h} \beta_j \vk_j \vk_j^\top$. This matrix $\mA$ is symmetric, and its spectrum is purely real: $\spec(\mA) = \{1 - \beta_1, \dots, 1 - \beta_{n_h}\} \cup \{1 \text{ (multiplicity } n-n_h) \}$. When $\beta_j=2$ for all $j \in \{1, ..., n_h\}$ then $\mA$ is known as a block reflector~\citep{schreiber1988block}.


    \item \textbf{(Complex Spectrum via Non-orthogonal Directions)} For $n_h = 2$, $\mA$ has complex eigenvalues if two consecutive direction vectors, e.g.\@ $\vk_1, \vk_2$ satisfy $0 < |\vk_1^\top \vk_2| < 1$ and their coefficients $\beta_1, \beta_2$ exceed a threshold $\beta^*(\theta) < 2$ dependent on the angle $\theta$ between them. 
    Conversely, if $0 \le \beta_1\le 1$ or $0 \le \beta_2\le 1$, these eigenvalues from the 2D span are guaranteed to be real. %
\end{enumerate}
\vspace{-2mm}

\end{proposition}
\begin{proof}\textbf{Identical Direction Vector}
If $m=1$, then the statement is trivially satisfied with $\beta^* = \beta_1$.
Suppose the statement is true for $m \geq 1$, i.e., $\prod_{j=1}^m (\mI - \beta_j\, \vk\vk^\top) = \mI - \beta^{(m)}\,\vk\vk^\top.$
Multiplying by $(\mI - \beta_{m+1}\,\vk\vk^\top)$ produces $(\mI - \beta^{(m)}\,\vk\vk^\top)(\mI - \beta_{m+1}\,\vk\vk^\top) = \mI - \bigl[\beta^{(m)} + \beta_{m+1} - \beta^{(m)}\beta_{m+1}\bigr] \,\vk\vk^\top.$
Hence, by induction, the product of any number of such factors remains of the form 
\(\mI - \beta^* \vk\vk^\top\).
Since the resulting matrix $\mA = \mI - \beta^* \vk\vk^\top$ (where $\vk = \vk_1$) is symmetric, its eigenvalues are real. 

\textbf{Orthogonal Vectors}
Assume $\{\vk_j\}_{j=1}^{n_h}$ is an orthonormal set ($\vk_j^\top \vk_l = \kron_{jl}$, $n_h \le n$). Let $\mP_j = \vk_j \vk_j^\top$. Then $\mP_j \mP_l = \kron_{jl} \mP_j$. The factors $\mH_j = \mI - \beta_j \mP_j$ commute because $\mP_j \mP_l = \bm{0}$ for $j \neq l$. The product simplifies via induction to $\mA = \mI - \sum_{j=1}^{n_h} \beta_j \mP_j$. This matrix is symmetric. Its eigenvalues are $(1 - \beta_l)$ for $l=1, \dots, n_h$ (eigenvector $\vk_l$) and $1$ with multiplicity $n-n_h$ (subspace orthogonal to all $\vk_j$). The spectrum is real.

\textbf{Complex Spectrum via Non-orthogonal Directions and Real Subcase}
\begin{figure}
    \centering
    \vspace{-2mm}
    \includegraphics[width=1.0\linewidth, trim={3 0 4 0}, clip=true]{figures/visualization_complex_eigenvalue_regions.pdf}
    \vspace{-6mm}
    \caption{Visualization of complex eigenvalues of $(\mI - \beta_1\vk_1\vk_1^\top)(\mI - \beta_2\vk_2\vk_2^\top)$ with $\cos \theta = \vk_1^\top\vk_2$. Complex region in red, real in white.}
    \label{fig:complex_eigvals}
\end{figure}
Let $\vk_1,\vk_2$ span a 2D subspace $S \subset \R^n$ with $\cos\theta = \vk_1^\top\vk_2$ such that $0 < |\cos\theta| < 1$. The product $\mA = \mH_2\mH_1$ acts as the identity on $S^\perp$ (preserving $n-2$ eigenvalues at 1) and non-trivially on $S$. The restriction $\mA_S$ of $\mA$ to $S$ has trace $\text{tr}(\mA_S) = 2 - \beta_1 - \beta_2 + \beta_1\beta_2\cos^2\theta$ and determinant $\det(\mA_S) = (1-\beta_1)(1-\beta_2)$. The discriminant of its characteristic equation is $D = [\text{tr}(\mA_S)]^2 - 4\det(\mA_S)$. Complex eigenvalues arise if $D < 0$. This occurs when $(2 - \beta_1 - \beta_2 + \beta_1\beta_2\cos^2\theta)^2 < 4(1 - \beta_1)(1 - \beta_2)$, a condition which can be met if $\beta_1,\beta_2$ are sufficiently large (e.g., $>\beta^*(\theta)$ for some $\beta^*(\theta) < 2$).

Conversely, we show that if $0 \le \beta_1, \beta_2 \le 1$, then $D \ge 0$.
Expanding the expression of the discriminant, we get $D = (2- \beta_1 - \beta_2)^2 + 2(2 - \beta_1 - \beta_2)\beta_1\beta_2 \cos^2\theta + \beta_1^2\beta_2^2 \cos^4\theta.$
When $0 \le \beta_1, \beta_2 \le 1$, each term in this sum is non-negative, hence $D \ge 0$. This ensures that the eigenvalues from the 2D span $S$ are real when $0 \le \beta_1, \beta_2 \le 1$. 
Furthermore, real eigenvalues from $S$ are also guaranteed if one coefficient is in the range $[0,1]$ while the other is in $(1,2]$.
Specifically, if one $\beta_i \le 1$ (i.e., $\beta_i \in [0,1]$) and the other $\beta_j > 1$ (i.e., $\beta_j \in (1,2]$ for $i \neq j$), then their product $(1-\beta_i)(1-\beta_j) \le 0$, which means $\det(\mA_S) = (1-\beta_1)(1-\beta_2) \le 0$.
If $\det(\mA_S) = 0$ (which occurs if the coefficient $\beta_i=1$), then the discriminant $D = [\text{tr}(\mA_S)]^2 \ge 0$.
If $\det(\mA_S) < 0$ (which occurs if $\beta_i \in [0,1)$ and $\beta_j \in (1,2]$), then the term $-4\det(\mA_S)$ is strictly positive.
Consequently, $D = [\text{tr}(\mA_S)]^2 - 4\det(\mA_S)$ must be positive, as it is the sum of a non-negative term $[\text{tr}(\mA_S)]^2$ and a positive term.
Thus, in both these subcases, $D \ge 0$ and the eigenvalues are real.
This analysis confirms that complex eigenvalues can arise if and only if both $\beta_1 > 1$ and $\beta_2 > 1$, which enables rotations within the 2D subspace. Conversely, when $\beta_1 \le 1$ or $\beta_2 \le 1$, real eigenvalues restrict the transformations in that subspace to scaling or reflection. This clear distinction in behavior, dictated by the $\beta$ values and $\theta$, is illustrated in~\Cref{fig:complex_eigvals}.
\end{proof}
\section{Expressivity of DeltaProduct}\label{app:expressivity}
In this section, we characterize the expressivity of (Gated) DeltaProduct in solving group word problems and recognizing regular languages, in support of \Cref{sec:expressivity}. The results hold in finite precision (since our constructions require a finite number of values), and take inspiration from \citet[Appendix D]{peng2025rwkv7gooseexpressivedynamic} and \citep{grazzi-iclr25a}.
We begin by stating and discussing our key assumptions in \Cref{app:assumptions}. We then present our main results for group word problems in \Cref{app:expressivity:group_word_rproblems}, followed by our findings for regular languages in \Cref{app:regular}. In \Cref{app:dihedral}, we examine a result specific to dihedral groups. Finally, we explore the fundamental tradeoff between expressivity and stability of the recurrence in \Cref{app:stabilityvsexpressivity}.

\subsection{Assumptions}\label{app:assumptions}
We consider a {\color{red}(Gated)} DeltaProduct model where each layer is structured as 
\begin{gather*}
\mH_i = \mA(\vx_i) \mH_{i-1} + \mB(\vx_i),\qquad
\hat{\vy}_i = \mathrm{dec}(\mH_i, \vx_i)\qquad
\text{where } i \in {1, \dots, t} \\
\mA(\vx_i) = {\color{red}g_i}\prod_{j=1}^{n_h} \Bigl(\mI - \beta_{i,j}\,\vk_{i,j}\vk_{i,j}^\top\Bigr), \quad
\mB(\vx_i) = \sum_{j=1}^{n_h} \Bigl(\prod_{k=j+1}^{n_h} \bigl(\mI - \beta_{i,k}\,\vk_{i,k}\vk_{i,k}^\top\bigr)\Bigr)\,\beta_{i,j}\,\vk_{i,j}\vv_{i,j}^\top,
\end{gather*}
where $g_i$ is only present in the gated variant and there is only one head per layer. If $H$ heads are considered, head $i$ will run the recurrence $\mH^j_i = \mA^j(\vx_i) \mH_{i-1} + \mB^j(\vx_i)$, (with different learnable parameters from all other heads) and all the states will be passed to the decoder to get the output as $\hat \vy_i = \mathrm{dec}((\mH_i^1, \dots,\mH_i^H), \vx_i)$.  

\textbf{Each layer receives the outputs of all previous layers.} We assume that the output of all layers is passed as input to all following layers: this can be achieved by using the residual connections (which would be inside $\mathrm{dec}$) and by placing the output of different layers onto separate subspaces.

\textbf{Task-dependent initial state.} We assume that the initial state $\mH_0$ can be set appropriately depending on the task and is of rank at most $n_h$. 


 \textbf{Arbitrary decoder and state transition functions.}  We also assume that for every $i,j$, $g_i \in [0,1]$, $\beta_{i,j} \in [0,2], \vk_{i,j} \in \R^d$, $\norm{\vk_{i,j}} =1$ and $\vv_{i,j} \in \R^d$ are arbitrary continuous functions of $\vx_i$. The function $\mathrm{dec}$ can also be arbitrary (continuous).
 Since in all our setups the possible values of $\vx_i$ and $\mH_i$ are finite, this implies that the functions $\mathrm{dec}$, $\mA, \mB$ can model an arbitrary function of their discrete domain of interest, with the only restriction coming from the structural assumption of the output spaces of $\mA$ (product of $n_h$ Householders) and $\mB$ (rank $n_h$). This assumption can always be fulfilled in practice if $\mathrm{dec}$ is a sufficiently wide MLP (see the next section for practical concerns) and, in the case of $\mA,\mB$, which do not contain MLPs, by setting the dimension of $\vx_i$ sufficiently large, which can be achieved by adjusting the embedding layer or the dimensionality of the output of $\mathrm{dec}$.



\subsubsection{Practical Considerations}

 \textbf{Beginning of sequence token.} Alternatively, the assumption on $\mH_0$ can be replaced by using a beginning of sequence token $x_1 = \$$ and setting $\mH_0 = 0$, as done in practice, so that $\mH_1 = \mB(\$)$ is a learnable matrix of rank at most $n_h$ which acts as the $\mH_0$ in our constructions. 

 \textbf{Decoder implementation.} In our implementation, $\mathrm{dec}$ is the same as in Gated DeltaNet:
\begin{gather*}
    \mathrm{dec}((\mH^1_t,\dots \mH_t^H),\vx_t) = \mathrm{MLP}(\mathrm{RMSnorm}(\vx_t + \vo_t)), \\ \quad \vo_t = \sum_{j=1}^H\mW^j_o\mathrm{RMSnorm}( (\mH^j_t)^\top 
    \vq^j_t), \quad \vq^j_t = \psi(\mW^j_q \vx_t)/||\psi(\mW^j_q \vx_t)||
\end{gather*}
where $\mW^j_o, \mW^j_q$ are two learned matrices, $\psi = \mathrm{SiLU}$, $\mathrm{RMSnorm}(\vx) = 
\va \odot \vx/\sqrt{\epsilon + d^{-1}\sum_{i=1}^d x_i}$ corresponds (when $\epsilon=0$) to a projection onto an axis aligned ellipse where $\va \in \R^d$ is learnable and determines the lengths of the axis and $\epsilon>0$ is a small value set to avoid numerical errors.
Meanwhile, $\mathrm{MLP}$ is a two layer MLP. This structure can be limiting. For instance, when $\mH_t^j \in \R^{d}$, then  $b_t = (\mH^j_t)^\top \vq_t \in \R$ and if $b_t >> \epsilon$, then $|\mathrm{RMSNorm}(b_t) | \approx 1$, which means that $\mathrm{RMSNorm}(b_t) \approx \pm 1$ (binary), which would restrict the flow of information. Indeed, for all our constructions to work, we would need $|\epsilon| \approx |b_t|$ (which can happen in practice), so that the $\mathrm{RMSnorm}$ can retain the magnitude information and we could set $\vq_t = \vb/\norm{\vb}$ with $\vb = (2b, 2b^2,\dots, 2b^d)$ with $b = a/c$ where $a$ and $c$ are respectively the maximum and minimum absolute value of the values that each element of $\mH^j_t$ can take (always a finite set in our constructions) excluding $0$. When these conditions are met, we are guaranteed that $\mH^j_t \mapsto \mathrm{RMSnorm}((\mH^j_t)^\top\vq_t)$ is injective so that the MLP can model any continuous function of $\mH_t^j$ even after the bottleneck caused by the scalar product with $\vq_t$ and the RMSnorm. When the state is one-hot, i.e.\@ $\mH_t = \ve_i \in \{0,1\}^d$ (i-th element of the canonical basis), an alternative to the above construction is to replicate the recurrence onto $d$ heads, where the $j$-th head has $\mW^j_o = \vq^j_t = \ve_j$, so that, assuming that in the RMSnorm  $\va = (\sqrt{d},\dots,\sqrt{d})^\top$ and $\epsilon = 0$, we get $\vo_t = \mH_t = \ve_i$. This is the strategy used in \citet[Appendix D]{peng2025rwkv7gooseexpressivedynamic}. However, for some problems using the one-hot encoding states $\ve_1,\dots\ve_n$ is not very efficient. For instance, to solve the $S_n$ word problem one would need $n!$-dimensional one-hot vectors as states, while in our \Cref{th:groups} we use $n$-dimensional vectors. Moreover, learning multiple identical heads is redundant and indeed we observe that in our synthetic experiments, the model is learning to use only one head to solve the tasks (see~\Cref{sec:state-tracking}).
\vspace{-2mm}
\subsection{Group Word Problems}\label{app:expressivity:group_word_rproblems}
\vspace{-2mm}
The next theorem establishes that DeltaProduct can solve the word problem for the symmetric group $S_n$, which implies that it can also solve any group word problem, since for every group $G$ there exist $n$ such that $G$ is isomorphic to a subgroup of $S_n$.


\begin{theorem}[Restatement of \Cref{th:groups}]\label{th:groups_restated} For any $n \in \N$ there exists a DeltaProduct model with one of the following configurations that can solve the word problem of the symmetric group $S_n$: (i) one layer with $n_h =n{-}1$ \citep[Theorem 3]{grazzi-iclr25a} (ii) 3 layers with $n_h{>}1$ (iii) 4 layers with $n_h{=}1$.
The construction for (ii) and (iii) requires that the MLP at the second last layer computes a lookup-table of size $2m \times (n!)^{2m}$, function of the last $2m$ input tokens and the position modulo $2m$ with $m = \ceil{(n{-}1)/n_h}$.
\end{theorem}

\begin{proof}
One way to solve the group word problem for the symmetric group $S_n$ is to map each element of the group $g \in S_n$ to the corresponding permutation matrix $\mP_g \in \{0,1\}^n$ and then for each input sequence $x_1,\dots, x_t$ with $x_i \in S_n$ compute each element of the output sequence $y_1,\dots, y_t$ as
\begin{equation*}
    y_i = x_{i} \cdot x_{i-1} \cdots x_1 = \phi(\mP_{x_i}\cdots\mP_{x_1}\vu_0 ), \quad \vu_0 = (1,\dots, n)^\top,
\end{equation*}
where $\phi$ is a surjective map from vectors in $\{1,\dots, n\}^n$ to the $n!$ elements of $S_n$, which we consider integers for simplicity, i.e.\@ $x_i, y_i \in \{1,\dots, n!\}$.

\textbf{(i).} Since a permutation of $n$ elements is a series of at most $n-1$ swaps of $2$ elements, if $n_h = n-1$, then we can solve the problem with a  1-layer DeltaProduct by setting $\mH_0 = \vu_0$, $\mathrm{dec}(\mH_i, x_i) =\phi(\mH_i)$, $\mB(x_i) = 0$ ($\vv_{i,j} = 0$),  $\mA(x_i) = \mP_{x_i}$. The latter is achieved by setting for the $j$-th element in the product $\prod_{j=1}^{n_h}(I - \beta_{i,j} \vk_{i,j}\vk_{i,j}^\top$), either $\beta_{i,j} = 2$ and $\vk_{i,j} = (\ve_k -\ve_p)/\sqrt{2}$ with $\ve_i$ being the $i$-th element of the canonical basis of $\R^n$ (swap element at index $k$ with the one at index $p$), or $\beta_{i,j} = 0$ (identity).

\textbf{(ii) and (iii).} If $n_h < n-1$, then the state transition matrix is not sufficiently expressive to represent all permutations of $n$ elements.  However, we can use additional layers to overcome this issue as follows. We divide the input sequence into blocks of $m$ elements: we factorize the position $i \in \{1,\dots t\}$ into $ i = lm + \tilde i$ where $l \geq 0$ is the index of the previous block and $\tilde{i} \in \{1,\dots, m\}$ is the position within the current  block (index $l+1$). First, consider the case when $l \geq 1$. Let $\tilde\mP_l = \mP_{x_{(l-1)m+m}} \dots \mP_{x_{(l-1)m + 1}}$ be the product of the permutations of the previous block. Since $\tilde \mP_l$ is a permutation matrix of $n$ elements, we can factor it into $\tilde\mP_l = \mG_{l,m} \cdots \mG_{l,1}$ where we recall that $m =\ceil{(n-1)/n_h}$ and each of $\mG_{l,1}, \dots, \mG_{l,m}$ is a product of $n_h$ generalized householder matrices and thus can be a state-transition matrix of our model. We fix one factorization for each possible permutation matrix and we set $\tilde\mP_0 = \mG_{0,m}\cdots \mG_{0,1}$, with $\mG_{0,i} = I$ to handle the case when $l=0$.

If the input $\vx_i$ of the last layer contains enough information  about previous tokens, we can set $\mH_0 = \vu_0$, $\mB(\vx_i) = 0$ and the recurrence and decoder of the last layer as
\begin{equation*}
    \mH_i =\mA(\vx_i)\mH_{i-1} = \mG_{l,\tilde i} \mH_{i-1}, \quad \mathrm{dec}(\mH_i, \vx_i) = \phi\Big(\underbrace{\mP_{x_i}\cdots \mP_{x_{lm + 1}}}_{\text{current block}}  \underbrace{\mG_{l, m}\cdots \mG_{l,\tilde{i} + 1}}_{\text{previous block}} \mH_i\Big).
\end{equation*} 
Note that $\mH_i$ contains the product of the input permutations only up to token $x_{(l-1)m}$ and has computed only partially pervious block of permutations $\tilde \mP_l$.
Hence, the decoder completes the computation by applying two additional components: (1) the remaining transformations $\mG_{l,\tilde{i}+1}$ through $\mG_{l,m}$ needed to complete the previous block's contribution, and (2) the actual permutations from the current partial block $\mP_{x_{lm + 1}}$ through $\mP_{x_i}$.
We can check that this ends up computing the correct output $y_i$ by substituting the expression for $\mH_i$ and unrolling the recurrence as follows.
\begin{align*}
     \mathrm{dec}(\mH_i, \vx_i) &= \phi(\mP_{x_{lm + \tilde{i}}}\cdots \mP_{x_{lm + 1}} \mG_{l, m}\cdots \mG_{l,1} \mG_{l-1, m}\cdots \mG_{l-1,1} \dots  \mG_{0,m} \dots \mG_{0,1} \mH_0). \\
    &= \phi(\mP_{x_{lm + \tilde{i}}}\cdots \mP_{x_{lm + 1}} \tilde\mP_l \tilde \mP_{l-1} \dots \tilde \mP_{0} \vu_0). \\ 
    &= \phi(\mP_{x_{lm + \tilde{i}}}\cdots \mP_{x_{lm + 1}} \mP_{x_{(l-1)m +m}}\cdots \mP_{x_{(l-1)m + 1}} \dots \mP_{x_{m}}\cdots \mP_{x_{1}} \tilde \mP_{0} \vu_0). \\ 
    &= \phi(\mP_{x_{i}}\cdots \mP_{x_{1}}\vu_0) = y_i,  
\end{align*}
 Note that to compute $\mA(\vx_i) = \mG_{l,\tilde i}$ and $\mathrm{dec}(\mH_i, \vx_i)$, $\vx_i$ should contain $\tilde{i} = i \bmod m$ and the last $m + \tilde{i}$ (in general the last $2m$) tokens. Hence, the layers before the last one are dedicated to compute at each time-step $i$ a lookup table for the possible values of  $(i \bmod 2m, x_i, \dots, x_{i-2m+1})$ whose output will be included in the input of the last layer $\vx_i$. The first layers (two layers if $n_h=1$, one if $n_h>1$) can provide $i \bmod 2m$ by using \Cref{lm:countmodm} with $d=2m$. Finally, the second to last layer can output any function of the last $2m$ tokens and the position modulo $2m$  through \Cref{lm:lastmtokens} with $d=2m$ and $\va_t = x_t$, by using $i \bmod 2m$ from the first layer(s).

 \end{proof}







\begin{lemma}\label{lm:countmodm}
The following DeltaProduct configurations can count modulo $d \in \N$. (i) 2 layers each with one head and $n_h = 1$ \cite[Theorem 6]{grazzi-iclr25a}. (ii) 1 layer  with one head and $n_h\geq2$.
\end{lemma}
\begin{proof}
For (i), we can use the same construction as in \cite[Theorem 6]{grazzi-iclr25a}, where the first layer does counting modulo 2 and the second layer computes addition modulo $d$. In this case, since we just want to count modulo $d$ we can ignore input tokens and add $1$ modulo $d$ at each time-step.
For (ii), note that if $n_h > 2$, we can set, for any time-step $t$, $\mB(\vx_t) = 0$ and the state transition matrix $\mA(\vx_t)$ equal to a 2D rotation with an angle of $2\pi/d$ by appropriately setting two keys, say $\vk_{t,1}, \vk_{t,2}$, setting $\beta_{t,1},\beta_{t,2} = 2$  (while for the other Householders we set $\beta_{i,j} = 0$). Then, we can count modulo $d$ by setting $\mH_0$ in the span of $\vk_{t,1},\vk_{1,2}$ and   $\mathrm{dec}$ appropriately to map the $d$ values that $\mH_t$ can take to the correspondent element in $\{1,\dots, d\}$.
\end{proof}

\begin{lemma}\label{lm:lastmtokens}
A DeltaProduct layer with $n_h=1$, receiving in its input at time-step $t$ the tuple $(t \bmod d, a_t)$ ($t \geq 1$) where $a_t \in D \subset \R$ with $D$ being a discrete set of values, can implement any function of $(t\bmod d, a_{t-d+1}, \dots, a_{t})$, where for simplicity we set $a_i = a \notin D$ for $i \in \{2-d,\dots, 0\}$.
\end{lemma}
\begin{proof}
Let $\tilde t = t \bmod d + 1$ and $\sigma: D \to \{0, \dots, |D| \}$ bijective and $\sigma(\va) = 0$. Set $\mH_0 = 0 \in \R^d$ and the recurrence update as
\begin{equation*}
    \mH_t = (I - \ve_{\tilde t} \ve_{\tilde t}^\top)\mH_{t-1} + \ve_{\tilde t} a_t,
\end{equation*}
where $\ve_i$ is the $i$-th element of the canonical basis of $\R^d$.
This can be implemented by setting $\beta_{t,1} = 1$, $\vk_{t,1} = \ve_{\tilde{t}}$, $\vv_{t,1} = a_t$ and $\beta_{t,j},\vk_{t,j}, \vv_{t,j} = 0$ for $j > 1$.
 With this choice, $\mH_t$ contains $a_{t-d+1},\dots, a_t$. The result follows since $\mathrm{dec}$ can be an arbitrary continuous function of both $\mH_t$ and $\vx_t$ and the latter contains $t \bmod d$. 
\end{proof}

Finally, the next results concern finite subgroups of the orthogonal and special orthogonal groups.
\begin{theorem}\label{th:suborth} Let $G$ be a group isomorphic either to a subgroup of $\mathrm{O}(n)$, or to a subgroup of $\mathrm{SO}(n+1)$ if $n$ is even, then if $n_h=n$, there exist DeltaProduct model that solves the group word problem for $G$. 
\end{theorem}
\begin{proof}
From the isomorphism we can map each element $g \in G$ to an orthogonal matrix $\mG_g$. For the word problem for $G$, each element of the input sequence belongs to $G$:  $x_i \in G$ for every $i$. 

If $\mG_g \in \mathrm{O}(n)$, then, since $n_h = n$ and every orthogonal $n \times n$ matrix can be written as the product of at most $n$ Householder matrices, we can set $\mH_0 = I \in \R^{n \times n}$ and $\mA(x_t) = \mG_{x_t}$, $\mB(x_t) = 0$ and $\mathrm{dec}(\mH_t, x_t) = \phi(\mH_t)$ with $\phi: \mathrm{O}(n) \to G$ bijective (which exists due to the isomorphism). The Householder product structure enables $\mA(x_t)$ to represent general orthogonal matrices $\mG_{x_t}$, including rotations.

If instead $\mG_g \in \mathrm{SO}(n+1)$, since $n$ is even in this case then we can still write $\mG_g$ as a product of an even number (at most $n$ since $n+1$ is odd) of Householder matrices of dimension $n+1 \times n+1$. This is because the determinant of $\mG_g$ is $+1$, which is only possible if it is a product of an even number of Householder matrices. Thus, we can set $\mA(x_t) = \mG_{x_t} \in \R^{n+1 \times n +1}$, $\mB(x_t) = 0$. 
Now if we let $\bar\mG = \mG_{x_t}\mG_{x_{t-1}}\cdots \mG_{x_1}$ and set $\mH_0 = \mathrm{diag}(1,\dots, 1, 0) \in \R^{(n+1) \times (n+1)}$ (we are only allowed a rank n matrix), then $\mH_t = \bar \mG \mH_0$ will have all the first $n$ columns equal to $\bar\mG$ and the last set to zero. However, the last column can be found as a function of the others since it must be the unique unit vector orthogonal to all other columns of $\bar\mG$ and for which $\operatorname{det}(\bar\mG)=+1$. Therefore, there exists a bijective functon from states to elements of the group, which can be implemented in $\mathrm{dec}$.
\end{proof}
\vspace{-2mm}
\subsection{Regular Languages}\label{app:regular}
\vspace{-2mm}
This section details how Gated DeltaProduct networks can recognize any regular language in a finite number of layers. The core idea is to show that Gated DeltaProduct can simulate any Finite State Automaton (FSA), since FSAs are the computational models that define regular languages. The proof proceeds in two main steps: First, we leverage the Krohn-Rhodes theorem, a fundamental result in automata theory, which states that any FSA can be decomposed into a cascade of simpler FSAs known as permutation-reset automata. These simpler automata only perform two types of operations: permuting their states or resetting all states to a single state. Second, we demonstrate in Lemma~\ref{lm:permreset} that Gated DeltaProduct is well-equipped to simulate these permutation-reset automata. The ``DeltaProduct'' mechanism, using products of Householder transformations, naturally handles permutations, while the ``Gated'' aspect allows for the reset operations by nullifying the previous state's influence and setting a new one. By simulating these building blocks and cascading them, Gated DeltaProduct can thus simulate any FSA and, consequently, recognize any regular language.


\begin{definition}[Finite state automaton (FSA)] A finite state automaton (FSA) is a tuple $(\Sigma, Q, q_0, \delta, F )$, where $\Sigma$ is a finite set called alphabet, $Q$ is the finite set of states, $q_0 \in Q$ is the initial state, for every $w \in \Sigma$, $\delta_w: Q \to Q$ is a state transition function and $F \subset Q$ is the set of accepting states. 
\end{definition}

\begin{definition}[Permutation-reset automaton]
An FSA is permutation-reset if for every $w \in \Sigma$, $\delta_w$ is either bijective or constant.
\end{definition}
\begin{definition}[Regular language]
A regular language is a set of sequences $L$ such that there exists an FSA that accepts it, i.e.\@ such that $L \subset \Sigma^*$, where $\Sigma^*$ is the set of sequences with elements in $\Sigma$, and that for every word $\vw = w_1w_2\dots w_t \in\Sigma^*$
\begin{equation}\label{eq:reglanrec}
    \delta_\vw(q_0) := \delta_{w_t} \circ \delta_{w_{t-1}} \circ \cdots\circ \delta_{w_{1}}(q_0) \in F \iff \vw \in L.
\end{equation}    
\end{definition}

Notably, the computation of any FSA can be also done using only matrix and vector multiplications. Indeed, if we let $Q =\{1,\dots, n\}$ (for simplicity), then we can map each state $q$ to the one hot vector $\ve_q$  (element of the canonical basis of $\R^n$) and each transition $\delta_w$ to the matrix $ \mM_w \in \{0,1\}^{n\times n}$ with element at row $q$ and column $q'$ being 1 if and only if $\delta(q') = q$. This way, by setting $\vr \in \{0,1\}^n$ such that $r_q = 1$ if $q \in F$ and $r_q = 0$ otherwise, we have that for every word $\vw = w_1w_2\dots w_n \in\Sigma^*$
\begin{equation}\label{eq:fsadecomp}
    \vr^\top \mM_{w_t} \mM_{w_{t-1}} \cdots \mM_{w_1} \ve_{q_0} = 1 \iff \vw \in L.
\end{equation} 
We observe that if $\delta_w$ is bijective and changes $k$ states, then the corresponding $\mM_w$ is a permutation matrix that can be written as a product of $k-1$ Householder matrices, each corresponding to a swap of two elements. Moreover, if $\delta_w$ is a reset (constant), i.e.\@ if $\delta_w(q) = \bar{q}$ for every $q \in Q$, then $\mM_w \ve_q = \ve_{\bar q}$. As we will see, constant transitions can be modeled by setting the gate to zero. We are now ready to state our main result.



\begin{theorem}[Restatement of \Cref{th:regular}]
For any regular language $L$ and any $n_h \in \N$, there exists a Gated DeltaProduct model with a finite number of layers that recognizes the language, i.e., for every word $\vw \in \Sigma^*$ outputs $1$ if $\vw \in L$ and $0$ otherwise.
\end{theorem}
\begin{proof}
Using the landmark theorem by \citet{krohn1965algebraic} we can decompose the FSA corresponding to the regular language $L$ into a cascade of permutation-reset FSA. We can use a group of at most 4 consecutive layers to represent each automaton in the cascade via \Cref{lm:permreset}. Then, we can combine the different FSA in the cascade in a feedforward manner using the same construction as the one in the proof of \cite[Theorem 3]{grazzi-iclr25a}, where the input of each FSA is the output concatenated with the input of the previous FSA in the cascade. %
\end{proof}

\begin{lemma}\label{lm:permreset}
For any permutation-reset FSA with $|Q| = n$ and $|\Sigma| = s$, where each bijective state-transition function $\delta_w$ changes at most $k$ states, there exists a Gated DeltaProduct model with the following configuration that can implement it, i.e.,\@ for any word $\vw= w_1,\dots,w_t \in \Sigma$ in input, it can output the corresponding sequence of states $q_1,\dots,q_t$ of the FSA.
(i) one layer with $n_h =k-1$. (ii) 3 layers with $n_h>1$. (iii) 4 layers with $n_h=1$.
The construction for (ii) and (iii) requires that the MLP at the second last layer computes a lookup-table of size $2m \times s^{2m}$, function of the last $2m$ input tokens and the position modulo $2m$ with $m = \ceil{(k-1)/n_h}$.
\end{lemma}
\begin{proof}
We use the matrix vector multiply construction to implement the FSA. For every time-step $i$ we set $x_i = w_i$ as the input to the model. The proof follows a path similar to the one of \Cref{th:groups_restated} (where more details are provided), where in addition to modeling permutations, the state-transition matrix uses the gate to model constant transitions.

\textbf{(i).} Set $\mH_0 = \ve_{q_0}$. When $\delta_{w_i}$ is bijective, by assumption it changes at most $k$ states. Thus, by setting $n_h = k-1$ we can represent the corresponding $\mM_{w_i}$ matrix using $\mA(w_i)$ with gate $g_i = 1$ (product of $k-1$ generalized Householder matrices), and thus we set $\mB(w_i) = 0$. If instead $\delta_{w_i}$ is constant, i.e., $\delta_i(q) = \bar{q}$ and $\mM_w \ve_q = \ve_{\bar q}$ for every $q \in Q$, then we can set the gate $g_i = 0$ so that $\mA(w_i) = 0$  and $\mB(w_i) = \vk_i = \ve_{\bar{q}}$. Finally, we set $\mathrm{dec}(\mH_i, x_i) = \mH_i^\top(1,\dots, n)^\top $ to retrieve the correct state at step $i$ (for simplicity $Q = \{1,\dots, n\}$). 

\textbf{(ii) and (iii).} If $n_h < k-1$, then the state transition matrix is not sufficiently expressive to represent all permutations of $k$ elements. However, we can use additional layers to overcome this issue.

We factorize the position $i \in \{1,\dots t\}$ into $ i = lm + \tilde i$ for integers $l \geq 0$ and $\tilde i \in \{1,\dots, m\}$.
First, consider the case when $l \geq 1$. The product $\tilde\mM_l = \mM_{w_{(l-1)m+1}} \dots \mM_{w_{(l-1)m + m}}$ is either a permutation matrix of $k$ elements or, if for some $i$ $\delta_{w_i}$ is constant, then there exist $\bar{q}$ such that $\tilde \mM_l \ve_q =\bar q$ for every $q \in Q$. Therefore, we  factor $\tilde \mM_l$ into $\tilde\mM_l = \mG_{l,m} \cdots \mG_{l,1}$ where each of $\mG_{l,1}, \dots, \mG_{l,m}$ is either a product of $n_h$ generalized householder matrices or $\mG_{l,i} \ve_q = \ve_{\bar q}$ for every $q \in Q$, which can be modeled setting the gate to zero as in point (i). We fix one factorization for each possible permutation matrix. In the last layer and with enough information in its input $\vx_i$ about past tokens, we can thus set $\mH_0 = \ve_0$ and
\begin{equation*}
    \mH_i = \mG_{l,\tilde i} \mH_{i-1}, \quad \mathrm{dec}(\mH_i, \vx_i) = (\mM_{lm + \tilde{i}}\cdots \mM_{lm + 1} \mG_{l, m}\cdots \mG_{l,\tilde{i} + 1} \mH_i)^\top(1,\dots, n)^\top
\end{equation*}
The case when $l=0$ is handled by setting $\tilde\mM_0 = \mG_{0,m}\cdots \mG_{0,1}$ with $\mG_{0,i} = I$. Note that both  $\mM_{l,\tilde i}$ and $\mathrm{dec}(\mH_t, \vx_t)$ are functions of $\tilde{i} = i \bmod m$ and the last $m + \tilde{i}$ (in general the last $2m$) tokens. Hence, the layers before the last are dedicated to output at each time-step $i$ a lookup table for the possible values of  $(i \bmod 2m, w_i, \dots, w_{i-2m+1})$. The first layers (2 if $n_h=1$, 1 if $n_h>1$) can provide $i \bmod 2m$ by using \Cref{lm:countmodm} with $d=2m$. Finally, the second last layer can output any function of the last $2m$ tokens and the position modulo $2m$  through \Cref{lm:lastmtokens} with $d=2m$ and $a_t = w_t$, by using $i \bmod 2m$ from the first layer(s).
\end{proof}

\subsection{Regular language recognition through products of RWKV-7 matrices}\label{app:rwkv_7_regular}

To enhance the expressivity at the cost of stability, we can replace the product of Householder matrices of DeltaProduct with a product of RWKV-7 matrices, i.e.\@ for each layer set 
\begin{equation}\label{eq:rwkvproduct}
\mA(\vx_i) = \prod_{j=1}^{n_h} (\mathrm{diag}(\vw_{i,j}) -c\vk_{i,j}(\vk_{i,j}\odot \va_{i,j})),
\end{equation}
where $\vw_{i,j}$, $\va_{i,j}$, $\vk_{i,j}$ are computed from $\vx_i$ such that $\va_{i,j},\vw_{i,j} \in [0,1]^n$, $||\vk_{i,j}|| =1$ and $c \in \{1,2\}$.
Even without using gates, the resulting model will be capable of recognizing regular languages effectively as the following theorem shows.

\begin{theorem}\label{th:rwkv7deltaprod_app} For any \textbf{regular language} recognized by a finite-state automaton (FSA) with $n \in \N$ states, there exists a linear RNN using products of RWKV-7 matrices as state-transition matrices (as in (\ref{eq:rwkvproduct}) with $c=2$) with one of the following configurations that can recognize it: (i) one layer with $n_h =n$ (ii) 3 layers with $n_h>1$ (iii) 4 layers with $n_h = 1$ \citep[Theorem 3]{peng2025rwkv7gooseexpressivedynamic}.
The construction for (ii) and (iii) requires that the MLP at the second last layer computes a lookup-table of size $2m \times (n!)^{2m}$, function of the last $2m$ input tokens and the position modulo $2m$ with $m = \ceil{n/n_h}$.
\end{theorem}
\begin{proof}
The computation of an FSA with $n$ states can be done using matrix-vector multiplications as shown in (\ref{eq:reglanrec}), where the $n \times n$ state transition matrices $\mM_{w_t}$ have elements in $\{0,1\}$ and a single one in each column.
\citet[Lemma 3]{peng2025rwkv7gooseexpressivedynamic} prove that any of those matrices can be expressed as products of $n$ matrices, each of which is either a swap (identity with two columns swapped), copy (identity with one row copied onto another), or the identity matrix and  can be modeled by a single RWKV-7 matrix. The proof for (ii) and (iii) follows similarly to~\Cref{th:groups} but now tackling all state transition matrices, while \Cref{th:groups} could handle only permutations since a generalized Householders matrix cannot be a copy matrix.
\end{proof}

\vspace{-2mm}
\subsection{Dihedral Groups}\label{app:dihedral}
\vspace{-2mm}
In \citet[Theorem 6]{grazzi-iclr25a} it is shown that  with 2 layers and the extended eigenvalue range, DeltaNet can compute addition modulo $m$, which corresponds to solving the group word problem for the cyclic group $\mathbb{Z}_m$, for any $m \in \N$.
We extend this result and prove that, under identical assumptions, DeltaNet (DeltaProduct with $n_h=1$) can solve the group word problem for the dihedral group $D_m$, for any $m \in \N$. The dihedral group $D_m$ represents the symmetries (both rotations and reflections) of a regular $m$-sided polygon. As a notable example, $D_3$ is isomorphic to the symmetric group $S_3$. 

The linear RNN construction used in this result can be implemented using a 2-layer DeltaNet Model with two heads in the first layer.  In the first layer, the linear RNN will compute parity for rotations and reflections separately, i.e.\@ it will record if the number of past rotations (reflections) is even or odd. 
The recurrent state of the second layer will have $2m$ possible values (same as the order of $D_m$) and each will be decoded differently based on the parity of reflections. 
The parity of rotations, combined with the group element, determines which reflection matrix to use as the state transition matrix of the second layer.


\begin{theorem}[Dihedral group word problems with reflections]\label{thm:dihedral} For any $m\in N$, consider the group word problem of the dihedral group $D_m$. There exist DeltaProduct models with the following configurations that can solve it.  (ii) Two layers with $n_h = 1$ and at least two heads in the first layer and one in the second layer. (ii) One layer with $n_h\geq2$.
\end{theorem}
\begin{proof}
The elements of the dihedral group $D_m$ can be divided into $m$ rotations $\mathcal{R} =\{r_0, \dots, r_{m-1}\}$ and $m$ reflections $\mathcal{S} =\{s_0, \dots, s_{m-1}\}$. The identity is $r_0$. To be able to solve the corresponding word problem, we would like to map sequences of group elements $x_1,\dots, x_t$ with $x_i \in \mathcal{R}\cup\mathcal{S}$ into sequences $y_1,\dots, y_t$ with $y_i = x_1 \cdot x_2 \cdots x_i$ and $\cdot$ is the group operation, that for dihedral groups is defined as
\begin{equation}\label{eq:groupop}
    r_i \cdot r_j=r_{i+j \bmod m}, \quad r_i \cdot s_j=s_{i+j \bmod m}, \quad s_i \cdot r_j=s_{i-j \bmod m}, \quad s_i \cdot s_j=r_{i-j \bmod m}.
\end{equation}
Note that a product of two rotations is commutative, while the product of two reflections or a reflection with a rotation is not. Indeed for $m \geq 3$ $D_m$, is not an abelian group. 

\textbf{(ii)} The constructions of the two layers of DeltaProduct with $n_h=1$ builds upon the one for the cyclic group $Z_m$ outlined in \citep[Theorem 6]{grazzi-iclr25a}. The first layer is constructed to output parity separately for rotations and reflections. In particular, using the following diagonal recurrence which indicates in the first (second) coordinate whether the number of rotations (reflections) is even (0) or odd (1). 
\begin{gather*}
\vh^{(1)}_{0} = 0, \quad  \vh_{t}^{(1)} = \va(x_t) \odot \vh^{(1)}_{t-1} + \vb(x_t), \quad \vy^{(1)}_t = \mathrm{dec}^{(1)}(\vh_{t}, x_t) = (x_t, h_{t,1}, h_{t,2}). \\
\va(x_i)_1 = \begin{cases}
-1 & \text{if } x_i \in \mathcal{R}    \\
1 & \text{if } x_i \in \mathcal{S}
\end{cases} \quad \va(x_i)_2 = \begin{cases}
-1 & \text{if } x_i \in \mathcal{S}    \\
1 & \text{if } x_i \in \mathcal{R}
\end{cases} \\
\vb(x_i)_1 = \begin{cases}
1 & \text{if } x_i \in \mathcal{R}    \\
0 & \text{if } x_i \in \mathcal{S}
\end{cases} \quad \vb(x_i)_2 = \begin{cases}
1 & \text{if } x_i \in \mathcal{S}    \\
0 & \text{if } x_i \in \mathcal{R}
\end{cases} \\
\end{gather*} 
This recurrence can be implemented also by DeltaProduct with $n_h=1$ using 2 heads each with scalar hidden states: one for the rotations and the other for the reflections.
For the second layer, we have instead the following constructions, which selects the appropriate reflection based on the parity of the rotations and uses the parity of the reflections for $\mathrm{dec}$.
\begin{gather*}
    \vh^{(2)}_{0} = (1,0)^\top, \quad  \vh^{(2)}_t = \mA^{(2)}(\vy^{(1)}_t) \vh^{(2)}_{t-1}, \quad \vy^{(2)}_t = \mathrm{dec}^{(2)}(\vh_t^{(2)}, \vy^{(1)}_t)  \\
    \mA^{(2)}(\vy) = \mH(\theta(y_1, y_2)) = \left[\begin{array}{cc}
\cos \theta(y_1, y_2) &  \sin \theta(y_1, y_2) \\
\sin \theta(y_1, y_2, ) & -\cos \theta(y_1, y_2)
\end{array}\right] \\
    \mathrm{dec}^{(2)}(\vh, \vy) = \begin{cases} 
    r_{i^*} & \text{if } y_3 = 0 \\
    s_{m-i^*} & \text{if } y_3 = 1
    \end{cases}, \quad 
    i^* = \argmax_{i \in \{0, \dots, m-1\}} \max (\vc_i^\top \vh, \vd_i^\top \vh) \quad 
\end{gather*}
where $\vy = (y_1, y_2, y_3)^\top \in \mathcal{R}\cup\mathcal{S} \times \{0,1\} \times \{0,1\}$,  $\mH(\alpha)$ is the $2 \times 2$ reflection matrix that reflects all vectors by a line having an angle of $\alpha/2$ with the line passing from the origin and the vector $(1,0)^\top$ and $\theta:  \mathcal{R}\cup\mathcal{S} \times \{0,1\} \to \R$ determines the angle of the reflection and is defined for all $i \in \{0,\dots, m-1\}$ as
\begin{align*}
    \theta(r_i, 1) &= \frac{(1 - 2i)\pi}{m}, \quad
    \theta(r_i, 0) = \frac{(1+2i) \pi}{m}, \quad  %
    \quad \theta(s_j, 1) = \frac{ - 2i\pi}{m}, \quad
    \theta(s_i, 0) = \frac{(2+2j) \pi}{m}. %
\end{align*} 
Moreover, $\mathcal{C} = \{\vc_0,\dots, \vc_{m-1}\}$ and $\mathcal{D} = \{\vd_0,\dots, \vd_{m-1}\}$ are two sets of states and are defined as
\begin{gather*}
\vd_0 = \vh_0^{(2)} =  (1,0)^\top, \quad \vc_0 = \mH(\pi/m)\vd_0, \\ \vd_i = \mR(2i\pi/m) \vd_0, \quad \vc_i = \mR(-2i\pi/m)\vc_0 \quad    \text{for all } i \in \{0,\dots,  m-1\},
\end{gather*}
where $\mR(\beta)$ is a rotation matrix with angle $\beta \in \R$.  

Let $\alpha,\gamma \in \R$, the following are standard identities of products of 2D rotations and reflections.
\begin{align*}
\begin{aligned}
\mR(\alpha) \mR(\gamma) & =\mR(\alpha + \gamma), \quad 
 &&\mH(\alpha)\mH(\gamma)  =\mR(\alpha- \gamma), \\
\mR(\alpha) \mH(\gamma) & =\mH\left(\alpha+ \gamma\right) 
&&\mH(\gamma) \mR(\alpha)  =\mH\left(\gamma-\alpha\right).
\end{aligned}
\end{align*}
From our choice of $\vd_0 = (1,0)^\top$ and $\vc_0$, for any $\alpha \in \R$ we have 
\begin{align*}
    \mR(\alpha)\vd_0 &=\mH(\alpha)d_0, \quad \text{and}  \\
    \mR(\alpha)\vc_0&=\mR(\alpha)\mH(\pi/m)\vd_0 = \mR(\alpha)\mR(\pi/m)\vd_0 = \mR(\alpha + \pi/m \pm \pi/m)d_0 \\
    &=\mH(\alpha + 2 \pi/m) \mH(\pi/m)\vd_0 = \mH(\alpha + 2 \pi/m) \vc_0.
\end{align*}
Moreover, from our choice of $\theta$, $\vd_i$ and $\vc_i$, using the identities above and the the fact that $\mR$ is a periodic function with period $2\pi$ we have that
\begin{align*}
     \vd_i &= \mR(2i\pi/m)\vd_0 
     = \mR(2i\pi/m)\mH(\pi/m)\vc_0 
     = \mH(\theta(r_i,0))\vc_0 \\  
\vc_i &= \mR(-2i\pi/m)\vc_0 
     = \mR(-2i\pi/m)\mH(\pi/m)\vd_0 
      = \mH(\theta(r_i,1))\vd_0 \\
     \vd_{m-i} &= \mR(-2i\pi/m)\vd_0 
     = \mH(-2i\pi/m)\vd_0 = \mH(\theta(s_{i}, 1))\vd_0 \\  
\vc_{m-i} &= \mR(+2i\pi/m)\vc_0 
     = \mH((2 +2i)\pi/m)\vc_0 = \mH(\theta(s_{i}, 0))\vc_0
\end{align*}
for every $i \in \{0,\dots, m-1\}$. 
Therefore, we can write 
\begin{equation}\label{eq:dtoc}
\begin{aligned}
     \mH(\theta(r_j,1))\vd_i 
     &= \mR( \theta(r_j,1) - \theta(r_i,0))\vc_0 
     = \mR(-2(i+j)\pi/m)\vc_0 = \vc_{i+j \bmod m}, \\
     \mH(\theta(r_j,0))\vc_i &= \mR( \theta(r_j,0) - \theta(r_i,1))\vd_0   = \mR(2(i+j)\pi/m)\vd_0 = \vd_{i+j \bmod m}, \\
     \mH(\theta(s_j,1))\vd_i 
     &= \mR( \theta(s_j,1) - \theta(s_{m-i},1))\vd_0 
     = \mR(-2(i+j)\pi/m)\vd_0 = \vd_{-i-j \bmod m}, \\
     \mH(\theta(s_j,0))\vc_i &= \mR( \theta(s_j,0) - \theta(s_{m-i},0))\vc_0   = \mR((2+ 2(i+j))\pi/m)\vc_0 = \vc_{-i-j \bmod m}, \\
\end{aligned}    
\end{equation}
for every $i,j \in \{0,\dots, m-1\}$.
We proceed to verify that the output of the second layer is computed correctly: satisfying the product rule for the dihedral group in (\ref{eq:groupop}), i.e.,\@ we want to verify that
\begin{equation}\label{eq:correctupdate}
    y^{(2)}_t = \begin{cases}
     r_{i + j \bmod m} & \text{if } y^{(2)}_{t-1} = r_i, x_t = r_j   \\
     s_{i + j \bmod m} & \text{if } y^{(2)}_{t-1} = r_i, x_t = s_j   \\
     s_{i - j \bmod m} & \text{if } y^{(2)}_{t-1} = s_i, x_t = r_j   \\
     r_{i - j \bmod m} & \text{if } y^{(2)}_{t-1} = s_i, x_t = s_j   \\
    \end{cases}
\end{equation}
Where we set $y^{(2)}_0 = r_0$. First note that  when $y^{(2)}_t \in \mathcal{S}$, then $y^{(1)}_{t,3} = 1$ and when $y^{(2)}_t \in \mathcal{R}$, then $y^{(1)}_{t,3} = 0$.
We consider two cases.

\textbf{Case 1.} If $y^{(2)}_{t-1} = r_i$ and hence $y^{(1)}_{t-1,3}= 0 $, then using (\ref{eq:dtoc}) we obtain
\begin{align*}
\vh^{(2)}_{t} = \mA^{(2)}(\vy^{(1)})\vh^{(2)}_{t-1} =
\begin{cases}
     \mH(\theta(r_j,1))\vd_i  = \vc_{i+j \bmod m} & \text{if } x_t = r_j, y^{(1)}_{t,2} = 1 \\
     \mH(\theta(r_j,0))\vc_i  = \vd_{i+j \bmod m} & \text{if } x_t = r_j, y^{(1)}_{t,2} = 0 \\
     \mH(\theta(s_j,1))\vd_i  = \vd_{-i-j \bmod m}& \text{if } x_t = s_j, y^{(1)}_{t,2} = 1 \\
     \mH(\theta(s_j,0))\vc_i  = \vc_{-i-j \bmod m} & \text{if } x_t = s_j, y^{(1)}_{t,2} = 0
    \end{cases}
\end{align*}
This, together with the definition of $\mathrm{dec}^{(2)}$ implies that
\begin{align}\label{eq:update_part_1}
y^{(2)}_{t} = \mathrm{dec}^{(2)}(\vh^{(2)}_{t}, \vy^{(1)}_{t}) =
\begin{cases}
      r_{i+j \bmod m} & \text{if } x_t = r_j, y^{(1)}_{t,3} = 0 \\
      s_{i+j \bmod m} & \text{if } x_t = s_j, y^{(1)}_{t,3} = 1
    \end{cases}
\end{align}
\textbf{Case 2.} If instead $y^{(2)}_{t-1} = s_i$ and hence $y^{(1)}_{t-1,3}= 1$, then using (\ref{eq:dtoc}) we obtain
\begin{align*}
\vh^{(2)}_{t} = \mA^{(2)}(\vy^{(1)})\vh^{(2)}_{t-1} =
\begin{cases}
     \mH(\theta(r_j,1))\vd_{m-i}  = \vc_{j-i \bmod m} & \text{if } x_t = r_j, y^{(1)}_{t,2} = 1 \\
     \mH(\theta(r_j,0))\vc_{m-i}  = \vd_{j-i \bmod m} & \text{if } x_t = r_j, y^{(1)}_{t,2} = 0 \\
     \mH(\theta(s_j,1))\vd_{m-i}  = \vd_{i-j \bmod m}& \text{if } x_t = s_j, y^{(1)}_{t,2} = 1 \\
     \mH(\theta(s_j,0))\vc_{m-i}  = \vc_{i-j \bmod m} & \text{if } x_t = s_j, y^{(1)}_{t,2} = 0
    \end{cases}
\end{align*}
This, together with the definition of $\mathrm{dec}^{(2)}$ implies that
\begin{align}\label{eq:update_part_2}
y^{(2)}_{t} = \mathrm{dec}^{(2)}(\vh^{(2)}_{t}, \vy^{(1)}_{t}) =
\begin{cases}
      s_{i-j \bmod m} & \text{if } x_t = r_j, y^{(1)}_{t,3} = 1 \\
     r_{i-j \bmod m} & \text{if } x_t = s_j, y^{(1)}_{t,3} = 0
    \end{cases}.
\end{align}
Note that (\ref{eq:update_part_1}) and (\ref{eq:update_part_2}) imply (\ref{eq:correctupdate}).
Setting the output of the linear RNN equal to the output of the second layer concludes the proof.

\textbf{(ii)} 
It follows from \Cref{th:suborth} since $D_m$ is a finite subgroup of $\mathrm{O}(2)$, the group of 2D orthogonal transformations: rotations and reflections.
\end{proof}

\subsection{Stability vs. Expressivity of Linear RNNs}\label{app:stabilityvsexpressivity}
In this section, we discuss the tradeoff between expressivity and stability of a linear RNN recurrence
$
    \mH_i = \mA_i \mH_{i-1} + \mB_i
$, where $\mA_i = \mA(\vx_i)$, $\mB_i = \mB(\vx_i)$.
We say that such a recurrence is stable if 
\begin{equation}\label{eq:stable}
      \exists M \in [0,\infty) \text{ such that } \norm{\prod_{j=1}^{i}\mA_j} < M \quad \forall i \in \N,   
\end{equation}
where $\norm{\cdot}$ is the spectral norm.
This property is true if and only if $\rho(\prod_{j=1}^i \mA_j) \leq 1$ where $\rho(\mM)$ is the spectral radius of $\mM$, i.e. the maximum modulus of its eigenvalues. When this property is not satisfied, the norm of the state will diverge exponentially fast to infinity. An effective way to satisfy (\ref{eq:stable}) with $M=1$ is to enforce $\norm{\mA_i} \leq 1$ for every $i$, since the norm of the product is less than or equal to the product of the norms (due to the submultiplicativity property). 
However, this restriction excludes some boolean matrices which are useful for recognizing regular languages. Indeed, in the construction shown in (\ref{eq:reglanrec}), all matrices involved are $n \times n$ with entries taking values in $\{0,1\}$ and having only a single one in each column. This class of matrices $\mathcal{B}$ satisfies (\ref{eq:stable}) with $M = \sqrt{n}$ because it is closed under matrix multiplication, i.e.\@ $\forall \mB, \mB' \in \mathcal{B}$, we have $\mB\mB' \in \mathcal{B}$, and $\max_{\mB \in \mathcal{B}} \norm{\mB} = \sqrt{n}$, which is achieved by matrices with ones only in one row. In particular, all matrices in $\mathcal{B}$ that are not permutations have spectral norm greater than one and therefore cannot be expressed if we enforce $\norm{\mA_i} \leq 1$.

The (Gated) DeltaProduct state transition matrix $\mA_i = \prod_{l=1}^{n_h} g_l(I - \beta_l \vk_l \vk_l^\top)$ satisfies $\norm{\mA_i} \leq 1$ since $g_l \in [0,1]$, $\beta_l \in [0,2]$, and $\norm{\vk_l} = 1$. Thus, from the matrices in $\mathcal{B}$, it can represent only permutations of up to $n_h + 1$ elements.
Instead, the state-transition matrix of RWKV-7, $\mA_i = \mathrm{diag}(w_i) - c \vk_i(\vk_i \odot \va_i)^\top$ with $c=2$, can represent not only the identity and permutations of two elements, but also any copy matrix, which is obtained by copying one column of the identity onto another and has spectral norm equal to $\sqrt{2}$. 
However, as we show in the next theorem, even with the less expressive $c=1$ setup that is used in practice, the RWKV-7 recurrence is not stable unless $\va_i$ is the same for every $i$, which is the case studied in \citet[Theorem 1]{peng2025rwkv7gooseexpressivedynamic}. Having different $\va_i$ values is key to modeling the copy matrix, since this requires a value different from that of a permutation matrix.
\begin{theorem}
Consider the RWKV-7 state transition matrix $\mA_i = \mathrm{diag}(w_i) - c \vk_i(\vk_i \odot \va_i)^\top$ with $c = 1$ (as set in practice), $w_i = (1,\dots,1)^\top \in \R^n$, $\va_i \in [0,1]^n$, $\vk_i \in \mathbb{R}^n$ with $\|\vk_i\| = 1$, and $n \geq 2$. 
There exists an infinite set $\mathcal{M}$ of matrix pairs such that for every $(\mA, \mA') \in \mathcal{M}$, we have $\rho(\mA\mA') > 1.2$, where $\rho$ denotes the spectral radius. Thus, if we set 
\begin{equation*}
    \mA_i = \begin{cases}
        \mA & \text{if } i \bmod 2 = 0 \\
        \mA' & \text{if } i \bmod 2 = 1
    \end{cases}, \quad \text{which implies} \quad \lim_{i \to \infty} \left\|\prod_{j=1}^{i}\mA_j\right\| = \infty.
\end{equation*}
\end{theorem}
\begin{proof}
We demonstrate this by construction for $n = 2$; the generalization to $n \geq 2$ is straightforward.

Let $\theta = \pi/3$,
$\va = (0, 1)^\top$, $\va' = (1, 0)^\top$.
$\vk = (\cos\theta, \sin\theta)^\top = [1/2, \sqrt{3}/2]^\top$.
$\vk' = (\sin\theta, \cos\theta)^\top = (\sqrt{3}/2, 1/2)^\top$.
Note that $\|\vk\| = \|\vk'\| = 1$.
We construct $\mA$ and $\mA'$ as
\begin{align*}
\mA &= I - \vk(\vk \odot \va)^\top =  I - \begin{pmatrix} \sqrt{3}/2 \\ 1/2 \end{pmatrix} [0 \quad 1/2] = \begin{pmatrix} 1 & -\sqrt{3}/4 \\ 0 & 3/4 \end{pmatrix} \\
\mA' &= I - \vk'(\vk' \odot \va')^\top = I - \begin{pmatrix} 1/2 \\ \sqrt{3}/2 \end{pmatrix} [1/2 \quad 0] = \begin{pmatrix} 3/4 & 0 \\ -\sqrt{3}/4 & 1 \end{pmatrix} 
\end{align*} 

Now, consider the product matrix
\[ \mM = \mA\mA' = \begin{pmatrix} 1 & -\sqrt{3}/4 \\ 0 & 3/4 \end{pmatrix} \begin{pmatrix} 3/4 & 0 \\ -\sqrt{3}/4 & 1 \end{pmatrix} = \begin{pmatrix} 15/16 & -\sqrt{3}/4 \\ -3\sqrt{3}/16 & 3/4 \end{pmatrix} \]

To find the spectral radius $\rho(M)$, we examine its eigenvalues. The characteristic equation is $\lambda^2 - \operatorname{Tr}(\mM)\lambda + \det(\mM) = 0$, with
$\operatorname{Tr}(\mM) = 27/16$ and
$\det(\mM) = 9/16$.
Hence, the characteristic equation is $16\lambda^2 - 27\lambda + 9 = 0$.
Thus, the eigenvalues are $\lambda_1 = \frac{27 + \sqrt{153}}{32}$ and $\lambda_2 = \frac{27 - \sqrt{153}}{32} $ and
the spectral radius is $\rho(\mM) = \max\{|\lambda_1|,|\lambda_2|\} =\lambda_1 \approx 1.23$. Also, since the spectral radius is a continuous function of the matrix entries, which are a continuous function of $\theta$, then this means that there is an infinite set of matrices, namely $\mathcal{M}$, obtained by varying $\theta$ around $\pi/3$ whose product has spectral radius greater than $1.2$.

From our construction of $\mA_i$, we have $\prod_{j=1}^{2i} \mA_j = \mM^i$. By the definition of the spectral norm and spectral radius, $\norm{\mM^i} \geq \norm{\lambda_1^i \vx} = |\lambda|^i = \rho(\mM)^i$, where $\vx$ is the eigenvector associated with the dominant eigenvalue $\lambda_1$. The result follows since $\lim_{i \to \infty} \rho(\mM)^i = \infty$.
\end{proof}


