\section{Preliminaries} \label{sec:prelim}
\subparagraph{Graphs.}
In this paper, all graphs of main interest are simple, that is, without self loops or parallel edges. Let $G$ be a graph.
We denote by $V(G)$ the vertex set of $G$ and by $E(G)$ the edge set of $G$.
When the vertex set of $G$ is $V$, we say that the graph $G$ is \emph{on} $V$.
%As $G$ is \emph{simple}, each edge of $G$ is a subset of $V(G)$ with exactly two members that are adjacent to each other in $G$.
The \emph{complete graph} on $V$, denoted by $K(V)$, is a graph on $V$ where every vertex is adjacent to all other vertices.
A complete graph $K(V)$ is a $K_n$ if $|V| = n$.
%The \emph{complete bipartite graph} on a pair of vertex sets $(X, Y)$, denoted by $K(X, Y)$, is a graph on %$X \cup Y$ where two vertices are adjacent to each other if and only if one of them is in $X$ and the other %is in $Y$. 
%A complete bipartite graph $K(X, Y)$ is a $K_{m, n}$ if $|X| = m$ and $|Y| = n$.

A graph $H$ is a \emph{subgraph} of a graph $G$ if $V(H) \subseteq V(G)$ and $E(H) \subseteq E(G)$.
The subgraph of $G$ induced by $U \subseteq V(G)$ is denoted by $G[U]$: its  vertex set is $U$ and its edge set is $\{\{u, v\} \in E(G) \mid u, v \in U\}$. 
A vertex set $C \subseteq V(G)$ is a \emph{clique} of $G$ if $G[C]$ is a complete graph.
For each $v \in V(G)$, $N_G(v)$ denotes the set of neighbors of $v$ in $G$: $N_G(v) = \{u \in V(G) \mid \{u, v\} \in E(G)\}$.
The \emph{degree} of $v$ in $G$ is $|N_G(v)|$.
For $U \subseteq V(G)$, the {\em open neighborhood of $U$ in $G$}, denoted by $N_G(U)$, is the set of vertices adjacent to some vertex in $U$ but not belonging to $U$ itself: $N_G(U) = (\bigcup_{v \in U} N_G(v)) \setminus U$. 
For an edge set $E \subseteq E(G)$ we denote by $V(E)$ the set of vertices of $G$ incident to some edge in $E$.

We say that a vertex set $C \subseteq V(G)$ is {\em connected in} $G$ if, for every $u, v \in C$, there is a walk of $G[C]$ starting with $u$ and ending with $v$, where a \emph{walk} of $G$ is a sequence of vertices in which every vertex except for the last is adjacent to the next vertex in the sequence.
It is a {\em connected component} or simply a {\em component} of $G$ if it is connected and is inclusion-wise maximal subject to connectivity.
For each vertex set $S$ of $G$, we denote by $\CC_G(S)$ the set of components of $G[V(G) \setminus S]$.
When $G$ is clear from the context we may drop the subscript and write $\CC(S)$ for $\CC_G(S)$.
A vertex set $S \subseteq V(G)$ is a {\em separator} of $G$ if $|\CC_G(S)| \geq 2$.
We usually assume that $G$ is connected and therefore $\emptyset$ is not a separator of $G$.
A component $C \in \CC_G(S)$ is a \emph{full component} associated with $S$ if $N_G(C) = S$.
A graph $G$ is \emph{biconnected} (\emph{triconnected}) if every separator of $G$ is of cardinality two (three) or greater. 
A graph is a \emph{cycle} if it is connected and every vertex is adjacent to exactly two vertices. 
A graph is a \emph{tree} if it is connected and does not contain a cycle as a subgraph.
%A tree is a \emph{star} if all but one of its vertices are of degree one.
%A vertex $v$ of a star is a \emph{root} of the star if all the vertices of the star except for $v$ are of %degree one.
A tree is a \emph{path} if it has exactly two vertices of degree one or its vertex set is a singleton.
Those two vertices of degree one are called the \emph{ends} of the path.
If $p$ is a path with ends $a$ and $b$, we say that $p$ is \emph{between} $a$ and $b$.
When we speak of cycles or paths of $G$, we mean subgraphs of $G$ that are cycles or paths. 
Let $p$ be a cycle or path of $G$.
A \emph{chord} of $p$ in $G$ is an edge $\{u, v \}$ of $G$ with $u, v \in V(p)$ that is not an edge of $p$. 
A cycle or path of $G$ is \emph{chordless} if it does not have any chord in $G$.

\subparagraph{Tree decompositions.}
A {\em tree-decomposition} of $G$ is a pair $(T, \calX)$ where $T$ is a tree and $\calX$ is a family $\{X_i\}_{i \in V(T)}$ of vertex sets of $G$, indexed by the nodes of $T$, such that the following three conditions are satisfied. 
We call each $X_i$ the {\em bag} at node $i$.   
\begin{enumerate}
  \item $\bigcup_{i \in V(T)} X_i = V(G)$.
  \item For each edge $\{u, v\} \in E(G)$, there is some $i \in V(T)$ such that $u, v \in X_i$.
  \item For each $v \in V(G)$, the set of nodes $I_v = \{i \in V(T) \mid v \in
  X_i\} \subseteq V(T)$ is connected in $T$.
\end{enumerate}
The {\em width} of this tree-decomposition is $\max_{i \in V(T)} |X_i| - 1$.
The {\em treewidth} of $G$, denoted by $\tw(G)$ is the smallest $k$ such that there is a tree-decomposition of $G$ of width $k$.

\subparagraph{Minimal separators and potential maximal cliques.}
Let $G$ be a graph and $S$ a separator of $G$. 
For distinct vertices $a, b \in V(G)$, $S$ is an {\em $a$-$b$ separator} if there is no path between $a$ and $b$ in $G[V(G) \setminus S]$; it is a {\em minimal $a$-$b$ separator} if it is an $a$-$b$ separator and no proper subset of $S$ is an $a$-$b$ separator.
A separator is a {\em minimal separator} if it is a minimal $a$-$b$ separator for some $a, b \in V(G)$. 
%We denote by $\Delta(G)$ the set of all minimal separators of $G$ and by $\Delta_k(G)$ the set of all %minimal separators of $G$ of cardinality at most $k$.
A necessary and sufficient condition for a separator $S$ of $G$ to be minimal is that $\CC_G(S)$ has at least two members that are full components associated with $S$.
We say that a connected vertex set $C$ of $G$ is \emph{minimally separated} if $N_G(C)$ is a minimal separator.

Graph $H$ is {\em chordal} if every cycle of $H$ with four or more vertices has a chord in $H$.
$H$ is a {\em triangulation of graph $G$} if it is chordal, $V(G) = V(H)$, and $E(G) \subseteq E(H)$. 
A triangulation $H$ of $G$ is {\em minimal} if there is no triangulation $H'$ of $G$ such that $E(H')$ is a proper subset of $E(H)$.
%It is known (see \cite{heggernes2006minimal} for example) that
%if $H$ is a minimal triangulation of $G$ then every minimal separator of $H$
%is a minimal separator of $G$. In fact, the set of minimal separators of $H$
%is a maximal set of pairwise non-crossing minimal separators of $G$, where
%two separators $S$ and $R$ \emph{cross each other} if at least two components
%of $G \setminus S$ intersects $R$.

A vertex set $X$ of $G$ is a \emph{potential maximal clique} (PMC for short) of $G$ if there is some minimal triangulation $H$ of $G$ such that $X$ is a maximal clique of $H$.
We denote by $\Pi(G)$ the set of all PMCs of $G$.
%and by $\Pi_k(G)$ the set of all PMCs of $G$ of cardinality at most $k$.
The following characterization of PMCs, which we heavily rely on, is due to Bouchitt\'{e} and Todinca~\cite{bouchitte2002listing}.
\begin{lemma}[Bouchitt\'{e} and Todinca~\cite{bouchitte2002listing}]\label{lem:BT-lemma}
  A vertex set $X$ of graph $G$ is a PMC of $G$ if and only if all of the following conditions hold.
  \begin{enumerate}
  \item There is no full component associated with $X$.
  \item Every $C \in \CC_G(X)$ is minimally separated.
  \item For every $u, v \in X$, either $\{u, v\} \in E(G)$ or there is some $C \in \CC_G(X)$ such that $u, v \in N_G(C)$.
  \end{enumerate}
\end{lemma}

They also show that PMCs are extremely useful for computing the treewidth.
\begin{theorem}
[Bouchitt\'{e} and Todinca \cite{bouchitte2001treewidth}]
\label{thm:bt-dp}
    Given a graph $G$ of $n$ vertices and $\Pi(G)$, the treewidth of $G$ can be computed in time $|\Pi(G)|n^{O(1)}$.
\end{theorem}
