\begin{proposition}
  \label{prop:compo_in_region}  
  Let $G$ be a triconnected plane graph and  let $X \subseteq V(G)$ be such that $L_G[X]$ is a biconnected plane graph.  Then, each $C \in \CC_G(X)$ is contained in some region of $L_G[X]$.
  Moreover, each region of $L_G[X]$ contains at most one component in $\CC_G(X)$.
\end{proposition} 
\begin{proof}
Since no edge of $G$ crosses any edge of $L_G$, each edge of $G[V(G) \setminus X]$ has
its ends in the same region of $L_G[X]$. Therefore, for each $C \in \CC_G(X)$,
all the vertex of $C$ lie in the same region of $L_G[X]$. 
For the second statement, suppose a region $r$ of $L_G[X]$ contains more than
one component in $\CC_G(X)$. 
Then, there is some $x \in X$ on the boundary of
$r$ that is adjacent to vertices from more than one component in $\CC_G(X)$ contained in $r$.
Let $e_1$, $e_2$, \ldots, $e_m$ be the edges incident to $x$ lying in $r$, arranged in the
clockwise ordering, and let $v_i$, $i \in \{1, \ldots, m\}$,
be the other end of edge $e_i$. Since $r$ is a region of $L_G[X]$, none of $v_i$, 
$i \in \{1, \ldots, m\}$, belongs to $X$. Therefore, for some $i$, $1 \leq i < m$,
$v_i$ and $v_{i + 1}$ belong to distinct components in $\CC_G(X)$. 
But the face of $G$ to which $x$, $v_i$, and $v_{i + 1}$ are incident is not incident
to a vertex in $X$ other than $x$, since, if it did, the cycle bounding $r$ would have a chord
in $L_G[X]$ that separates $r$, a contradiction. Therefore, there is a path of $G[V(G) \setminus X]$
between $v_i$ and $v_{i+1}$ around this face, also a contradiction.
We conclude that $r$ contains at most one component in $\CC_G[X]$.
\end{proof}

We use this framework to formulate the fundamental observation on minimal separators of triconnected plane graphs, which is conventionally stated in terms of nooses~\cite{bouchitte2003chordal}.
\begin{proposition}
\label{prop:min-sep-of-triconn}
Let $G$ be a triconnected plane graph.
A vertex set $S$ of $G$ is a minimal separator of $G$ if and only if $L_G[S]$ is a cycle and 
neither of the two regions of $L_G[S]$ is empty.
%\todo{we need a one line argument or a ref for this proposition, esp. on how uniqueness/triconnectivity is used here}
\end{proposition}
\begin{proof}
Let $S$ be a minimal separator of $G$ and let $C_1, C_2 \in \CC_G(S)$ be distinct such that
$N_G(C_i) = S$ for $i \in \{1, 2\}$. To separate $C_1$ from $C_2$, $L_G[S]$ must contain a cycle
$\gamma$ that separates this components. Since $S$ is a minimal separator, we indeed have
$V(\gamma) = S$ and $L_G[S]$ is a biconnected plane graph.
Due to Proposition~\ref{prop:compo_in_region},
there are regions $r_1$ and $r_2$ of $L_G[S]$ such that $C_i$ is the unique component in 
$\CC_G(X)$ that is contained in $r_i$, for $i \in \{1, 2\}$.
Since $S$ is a minimal separator separating $C_1$ from $C_2$, every vertex in $S$ is incident
to both regions $r_1$ and $r_2$ and therefore the cycles of $L_G[S]$ bounding these two regions
are identical to each other and to $L_G[S]$. Therefore, $L_G[S]$ is a cycle.

For the converse, suppose $L_G[S]$ is a cycle and neither of the two regions $r_1$ and $r_2$ 
of $L_G[S]$ is empty. Let $C_i$ be the set of vertices of $G$ contained in $r_i$ for $i \in \{1, 2\}$.
Due to Proposition~\ref{prop:compo_in_region},
both $C_1$ and $C_2$ belongs to $\CC_G(S)$.
We claim that $N_G(C_1) = S$. This is trivial if $|S| = 3$ 
since $G$ is triconnected. So suppose $|S| \geq 4$. Let $s \in S$ be arbitrary and
let $s_1$ and $s_2$ be the vertices on the cycle $L_G[S]$ adjacent to $s$.
If there is no edge of $G$ between $s$ and vertices in $C_1$ then $s_1$ and
$s_2$ belong to the same face of $G$ and therefore there is an edge of $L_G$ between
$s_1$ and $s_2$. Since $s_1, s_2 \in S$ this edge belongs to $L_G[S]$ contradicting
the assumption that $L_G[S]$ is a cycle. This shows that $N_G(C_1) = S$.
As we similarly have $N_G(C_2) = S$, $S$ is a minimal separator of $G$.
\end{proof}
\begin{remark}
It follows from this proposition that every minimal separator of a triconnected planar graph has exactly two full components associated with it.
\end{remark}
\begin{corollary}
\label{cor:minsep4}
   Let $G$ be a triconnected plane graph.
A vertex set $S$ of $G$ with $|S| \geq 4$ is a minimal separator of $G$ if and only if
$L_G[S]$ is a cycle. 
\end{corollary}

\begin{proof}
    Suppose $|S| \geq 4$ and $L_G[S]$ is a cycle. 
    Then, neither of the two regions of $L_G[S]$ is empty, since if one of the two regions $r$ is empty, $r$ is contained in a face $f$ of $G$ and the definition of $L_G[S]$ implies that $L_G[S]$ is a complete graph, not a cycle.
    Therefore, the ``if'' part of Proposition~\ref{prop:min-sep-of-triconn} applies and 
    $S$ is a minimal separator of $G$.
    The other direction is an immediate consequence of the ``only if'' part of Proposition~\ref{prop:min-sep-of-triconn}.
\end{proof}

The following fact is essential in our treatment of PMCs of triconnected plane graphs.
\begin{proposition}
\label{prop:pmc-planar}
    For every PMC $X$ of a triconnected plane graph $G$, $L_G[X]$ is a biconnected plane graph.
    Moreover, every region of $L_G[X]$ is bounded by a chordless cycle of $L_G$.
\end{proposition}
\begin{proof}
Let $X$ be a PMC of $G$.
We first show that $L_G[X]$ is biconnected. 
Consider an arbitrary vertex $x \in X$ in the PMC.
We show that $L_G[X \setminus \{x\}]$ is connected.
Let $y$ and $z$ be any two members of $X \setminus \{x\}$.
Due to the third condition for PMCs, either $y$ is adjacent to $z$ in $G$ or there is some $C \in \CC_G(X)$ such that $y, z \in N_G(C)$.
In the former case, $y$ is adjacent to $z$ in $L_G[X]$. 
In the latter case, $S = N_G(C)$ is a minimal separator of $G$ and, therefore, $L_G[S]$ is a cycle.
It follows that there is a subpath of the cycle $L_G[S]$ between $y$ and $z$ that does not contain $x$.
Therefore, $L_G[X \setminus \{x\}]$ is connected for every $x \in X$ and hence $L_G[X]$ is biconnected.

To show that $L_G[X]$ is a plane graph, suppose that it is not the case. 
Due to Proposition~\ref{prop:plane-latch-subgraph},  there is a face $f$ of $G$ such that $|V(f) \cap X| \geq 4$.
    Let $x_1$, $x_2$, $x_3$, and $x_4$ be arbitrary four vertices in $V(f)$, listed in the order around $f$. 
    If $x_1$ is not adjacent to $x_3$ in $G$, there is some $C \in \CC_G(X)$ such that $x_1, x_3 \in N_G(C)$. 
    In either case, there is a path $p_1$ of $G$ between $x_1$ and $x_3$ that intersects $X$ only at $x_1$ and $x_3$.
    Similarly, there is a path $p_2$ of $G$ between $x_2$ and $x_4$ that intersects $X$ only at $x_2$ and $x_4$.
    Since the Jordan curve obtained from $p_1$ by adding a curve in $f$ separates $x_2$ and $x_4$, $p_1$ and $p_2$ must intersect at a vertex of $G$.
    Therefore, there is some component $C \in \CC_G(X)$ such that $x_i \in N_G(C)$ for every $i \in \{1, 2, 3, 4\}$.
    But $S = N_G(C)$ cannot be a minimal separator, since $|S \cap V(f)| \geq 4$ and therefore $L_G[S]$ is not a cycle. 
    This contradicts the assumption that $X$ is a PMC. Therefore, $L_G[X]$ is a plane graph.

    Let $r$ be an arbitrary region of $L_G[X]$. 
    If $r$ is non-empty and $C$ is the set of vertices lying in $r$, then $C \in \CC_G(X)$ 
    due to Proposition~\ref{prop:compo_in_region} and hence $S = N_G(C)$ is a minimal separator of $G$ since
    $X$ is a PMC of $G$.
    Due to Proposition~\ref{prop:min-sep-of-triconn}, $L_G[S]$ is a cycle and bounds $r$.
    Suppose, on the other hand, that $r$ is empty. Then the cycle bounding $r$ has exactly three vertices 
    because otherwise $G$ has a face $f$ such that $|V(f) \cap X| \geq 4$ and $L_G[X]$ would not be a plane graph
    due to Proposition~\ref{prop:plane-latch-subgraph}. This cycle, having exactly three vertices, is trivially chordless.
    %\todo{I didn't get this last sentence}
\end{proof}

\section{Characterizing PMCs in triconnected planar graphs}
\label{sec:charact}

In this section, we characterize PMCs of a triconnected plane graph
in terms of graphs we call steerings.

\begin{definition}
\label{def:steering}
Let $\gamma$ be a cycle. A subset $R$ of $V(\gamma)$ is a \emph{slot} of
$\gamma$ if $R$ is a singleton or an edge of $\gamma$. A \emph{socket} of $\gamma$
is an unordered pair $\{R_1, R_2\}$ of slots such that $R_1 \cup R_2$
is not a slot.
A vertex $s$ of $\gamma$ is a \emph{hinge} of a socket $\{R_1, R_2\}$
if $R_1 \cup R_2$ is a subset of $N_{\gamma}(s) \cup \{s\}$.

A graph $H$ is a \emph{steering}, if there is a bipartition $(S, P)$ of
$V(H)$ such that $H[S]$ is a cycle, 
$N_H(P)$ is neither empty nor a slot of $H[S]$, 
and if $|P| \geq 2$ then the following conditions hold.
\begin{enumerate}
    \item $H[P]$ is a path. Let $u_1$ and $u_2$ be the two ends of $H[P]$.
    \item The unordered pair $\{N_H(u_1) \cap S, N_H(u_2) \cap S\}$ is a socket of $H[S]$.
    \item $N_H(P \setminus \{u_1, u_2\}) \cap S$ is either empty
    or a singleton $\{s\}$ where $s$ is a hinge of the socket $\{N_H(u_1) \cap S, N_H(u_2) \cap S\}$.
\end{enumerate}
We call $H$ an \emph{$(S, P)$-steering} in this situation.
\end{definition}
\begin{remark}
It is important to note that the bipartition $(S, P)$ of $V(H)$ such that
$H$ is an $(S, P)$-steering may not be unique in general.
Also note that there is at most one hinge of a socket if $|S| \geq 5$
and at most two if $|S| = 4$.
\end{remark}

