\begin{proposition}
\label{prop:subset-enough}
Let $X$ be a PMC of a triconnected plane graph $G$.
If $L_G[X']$ is a steering for some $X' \subseteq X$, then
$X = X'$ and hence $L_G[X]$ is a steering.
\end{proposition}
\begin{proof}
    If $L_G[X']$ is a steering, $X'$ is a PMC of $G$
    due to Lemma~\ref{lem:steering-is-PMC}.
    Since no proper subset of a PMC is a PMC (Lemma~\ref{lem:pmc_subset}), 
    we have $X = X'$.
\end{proof}

\begin{lemma}
    \label{lem:all-triang}
    Let $X$ be a PMC of a triconnected plane graph $G$ and suppose
    that, for every $C \in \CC_G(X)$, $|N_G(C)| = 3$.
    Then, $L_G[X]$ is a $K_4$.
\end{lemma}
\begin{proof}
Recall that, due to Proposition~\ref{prop:pmc-planar}, $L_G[X]$ is a
biconnected plane graph. Recall also that every $C \in \CC_G(X)$
is contained in a region of $L_G[X]$ bounded by a cycle whose vertex set
is $N_G(C)$.
    Let $\gamma$ be a cycle that bounds a region $r$ of $L_G[X]$ and
    let $S = V(\gamma)$. If $r$ is empty then $|S| = 3$ since
    otherwise $L_G[X]$ would not be planar (Proposition~\ref{prop:plane-latch-subgraph}). 
    Otherwise $r$ contains
    some $C \in \CC_G(X)$ and we also have $|S| = 3$ due to the assumption.
    Let $x \in X \setminus S$ and $s \in S$ be arbitrary.
    We show that $x$ is adjacent to $s$ in $L_G[X]$.
    If $x$ is adjacent to $s$ in $G$ then we are done.
    Otherwise, due to the third condition for PMCs, 
    there is some $C \in \CC_G(X)$ such that
    $x, s \in N_G(C)$. Since the region of $L_G[X]$ containing $C$
    is bounded by a triangle on $N_G(C)$, $x$ is adjacent to
    $s$ in $L_G[X]$.
    Therefore, $x$ is adjacent in $L_G[X]$ to every $s \in S$
    and hence $L_G[S \cup \{x\}]$ is a $K_4$.
    As $L_G[S \cup \{x\}]$ is an $(S, \{x\})$-steering, we have 
    $X = S \cup \{x\}$ due to Proposition~\ref{prop:subset-enough}
    and hence $L_G[X]$ is a $K_4$.
\end{proof}

\begin{definition}
Let $G$ be a triconnected plane graph and let
$S$ be a minimal separator of $G$. 
An \emph{arch} of $S$ is a subset $P$ of $V(G) \setminus S$
such that $L_G[P]$ is connected and 
$N_{L_G}(P) \cap S$ is neither empty nor a slot of the cycle $L_G[S]$.
\end{definition}

\begin{lemma}
\label{lem:min-arch2steering}
Let $S$ be a minimal separator of a triconnected plane graph
$G$ with $|S| \geq 4$.
Suppose $S$ has an arch and let $P$ be 
an inclusion-wise minimal arch of $S$. 
Then, $L_G[P \cup S]$ is an $(S, P)$-steering.
\end{lemma}
\begin{proof}
Let $H = L_G[P \cup S]$.
We verify the conditions for $H$ being an $(S, P)$-steering in Definition~\ref{def:steering}.
The first condition that $N_H(P)$ is neither empty nor a slot of $H[S]$ is
satisfied because $N_H(P) = N_{L_G}(P) \cap S$, $H[S] = L_G[S]$, and
$P$ is an arch of $S$.
If $|P| \geq 2$, $H$ must satisfy the following additional conditions.
\begin{enumerate}
    \item $H[P]$ is a path. Let $u_1$ and $u_2$ be the two ends of $H[P]$.
    \item The unordered pair $\{R_1, R_2\}$, where $R_1 = N_H(u_1) \cap S$ and $R_2 = N_H(u_2) \cap S$, is a socket of $H[S]$.
    \item $N_H(P \setminus \{u_1, u_2\}) \cap S$ is either empty
    or a singleton $\{s\}$ where $s$ is a hinge of the socket $\{R_1, R_2\}$.
\end{enumerate}
Since $P$ is an arch of $L_G[S]$, there are distinct $w_1, w_2 \in N_{L_G}(P) \cap S$ 
that are not adjacent to each other in $L_G[S]$. Let $u_i \in P$ be adjacent in $L_G$ to $w_i$,
for $i \in \{1, 2\}$, with $u_1$ and $u_2$ not necessarily distinct. 
Let $p$ be a path of $L_G[P]$ between $u_1$
and $u_2$. Then, $V(p)$ is an arch of $L_G[S]$ and, since $P$ is an inclusion-wise minimal arch, 
$L_G[P]$ is the path $p$ with ends $u_1$ and $u_2$. If $u_1 = u_2$ then $P$ is a singleton
and $H$ is an $(S, P)$-steering. So, suppose $u_1 \neq u_2$ and hence $|P| \geq 2$.
Then Condition 1 holds.
For Condition 2, first observe that $R_i = N_H(u_i) \cap S =
N_{L_G}(u_i) \cap S$ is a slot of $H[S] = L_G[S]$,
for $i \in \{1, 2\}$. This is because, if $R_1$ is not a slot of $L_G[S]$, say,
then $\{u_1\}$ would be an arch of $S$, contradicting the minimality of $P$.
Since $P$ is an arch of $S$, $N_{L_G}(P) \cap S$ is not a slot of $L_G[S]$ and
hence contains two vertices $y_1$ and $y_2$ not adjacent to each other on $L_G[S]$.
Unless $y_1$ belongs to one of $R_1$ and $R_2$ and $y_2$ belongs to the other,
either $N_{L_G}(P \setminus \{u_1\})$ or $N_{G_L}(P \setminus \{u_2\})$ contains both
$y_1$ and $y_2$ and hence there is a proper subset of $P$ that is 
an arch of $S$, contradicting the minimality of $P$. 
Therefore, $R_1 \cup R_2$ is not a slot of $L_G[S]$ and hence $\{R_1, R_2\}$ is a socket of $L_G[S]$.

To show that Condition 3 holds, suppose that 
$N_H(P \setminus \{u_1, u_2\}) \cap S$ has a member $s$ that is not a hinge
of the socket $\{R_1, R_2\}$. Then, not both of 
$R_1 \cup \{s\}$ and $R_2 \cup \{s\}$ are slots of $L_G[S]$. Therefore, 
either $P \setminus \{u_1\}$ or $P \setminus \{u_2\}$ would be an arch of $S$,
contradicting the minimality of $P$. It follows that every member
of $N_{L_G}(P \setminus \{u_1, u_2\}) \cap S$ is a hinge of the socket $\{R_1, R_2\}$.
Even though there can be two hinges $s_1$ and $s_2$ of the socket when
$|S| = 4$, $N_{L_G}(P \setminus \{u_1, u_2\}) \cap S$ cannot contain both of them,
since if they did then $P \setminus \{u_1, u_2\}$ would be an arch of $S$, a contradiction. 
Therefore, Condition 3 holds.
\end{proof}

\begin{lemma}
    \label{lem:pmc-has-arch}
    Let $X$ be a PMC of a triconnected plane graph $G$ and
    let $S \subset X$ be a minimal separator of $G$. 
    Then, there is an arch $P$ of $S$ such that $P \subseteq X \setminus S$.  
\end{lemma}
\begin{proof}
Since a PMC does not have a full component associated with it, $X \setminus S$ is non-empty.
Note also that $X \setminus S$ is contained in one of the two regions
of $L_G[S]$, since any minimal separator of $G$ that is a subset of
a PMC of $G$ does not separate the PMC.
Call this region~$r_0$.

For each edge $e$ of the cycle $L_G[S]$, we define a path $p_e$ of $L_G[X]$ as follows.
Consider paths of $L_G[X]$ between the ends of $e$ with all internal vertices belonging to
$X \setminus S$ and choose such a path $p_e$ that maximizes the area in $r_0$ bounded
by the cycle formed by $p_e$ with $e$. As a special case, if the only such path
is a path consisting only of $e$, we let $p_e$ be this single-edge path.
Since $X \setminus S$ is not empty and $L_G[X]$ is biconnected
(Proposition~\ref{prop:pmc-planar}), there is some edge $e$
of $L_G[S]$ such that $p_e$ is not a single-edge path.
Let $\gamma$ be the closed walk obtained by concatenating the paths $p_e$ for all edges $e$ of the cycle $L_G[S]$.

We observe that $\gamma$ cannot be a cycle bounding a region of $L_G[X]$, 
since if it was then it must be chordless due to Proposition~\ref{prop:pmc-planar}, while
an edge $e$ of $L_G[S]$ such that $p_e$ is not a single edge path is a chord of $\gamma$, a contradiction.

Since $\gamma$ is not a cycle bounding a region of $L_G[X]$, 
either a vertex $v$ repeats on $\gamma$ or $\gamma$ is a cycle but has a chord in the face $r_1$ 
of $\gamma$ that is entirely contained in $r_0$.
If a vertex $v$ repeats on $\gamma$ then there are two edges $e, e'$ of $L_G[S]$
such that $v$ is an internal vertex of both $p_e$ and $p_{e'}$.
We claim that if $\gamma$ is a cycle and has a chord $\{x, y\}$ in $L_G$ that
lies in $r_1$ then either (1) $x$ and $y$ are internal vertices of $p_e$ and $p_{e'}$, respectively,
for some distinct edges $e, e'$ of $L_G[S]$ or (2) one of $x$ and $y$, say $x$, belongs to $S$ and
the other, $y$, is an internal vertex of $p_e$ for some edge $e$ of $L_G[X]$ such that
$x \not\in V(e)$.
This is because an edge $\{x, y\}$ with $x, y \in S$ is an edge of $L_G[S]$ and cannot lie in $r_1$
and an edge $\{x, y\}$ with $x, y \in V(p_e)$ for some edge $e$ of $L_G[S]$ cannot lie in $r_1$
because of the choice of $p_e$ to maximize the area in $r_0$ bounded by $p_e$ and $e$.

In case (1), as well as when a vertex $v$ repeats on $\gamma$, we let
$P = (V(p_e) \cup V(p_{e'})) \setminus ((V(e) \cup V(e'))$, where $e$ and $e'$ are edges of $L_G[S]$
specified above in the respective cases. 
In case (2), we let $P = V(p_e) \setminus V(e)$. In either case, $P$ is an arch of $S$ 
since it is connected and we have $|N_{L_G}(P) \cap S| \geq 3$.
\end{proof}

The following is our main theorem in this section.
\begin{theorem}
\label{thm:PMC-is-steering}
    A vertex set $X$ of  a triconnected plane graph $G$ is a PMC if and only if
    $L_G[X]$ is a steering.
\end{theorem}
\begin{proof}
Lemma~\ref{lem:steering-is-PMC} shows that if $L_G[X]$ is a steering then $X$ is a PMC.
We prove the other direction. Let $X$ be a PMC of $G$.

If $|N_G(C)| = 3$ for
every $C \in \CC_G(X)$, $L_G[X]$ is a $K_4$ due to Lemma~\ref{lem:all-triang} and 
hence is an $(X \setminus \{x\}, \{x\})$-steering for every $x \in X$.

Suppose there is some $C \in \CC_G(X)$ with $|S| \geq 4$ where $S = N_G(C)$.
Due to Lemma~\ref{lem:pmc-has-arch}, there is an arch of $S$ that is a subset of
$X \setminus S$. Let $P$ be an inclusion-wise minimal arch of $S$ that is a subset of $X \setminus S$.
Due to Lemma~\ref{lem:min-arch2steering}, $L_G[S \cup P]$ is a steering and hence $S \cup P$
is a PMC of $G$, due to Lemma~\ref{lem:steering-is-PMC}. 
Due to Proposition~\ref{prop:subset-enough}, $X = S \cup P$ and hence
$L_G[X]$ is a steering.
\end{proof}

\section{Polynomial delay generation of PMCs of a triconnected planar graph}
\label{sec:poly_delay}
Let $J$ be some combinatorial structure of size $n$ and let $\calS(J)$
be the set of some combinatorial objects defined on $J$. We say an algorithm
\emph{generates $\calS(J)$ with polynomial delay} if it outputs each member
of $\calS(J)$ exactly once and the time between two consecutive events is
$n^{O(1)}$, where an event is the initiation of the algorithm, an output,
or the termination of the algorithm.

The basic approach for generating $\Pi(G)$ for a given triconnected plane graph $G$
is as follows.
PMCs $X$ such that $|N_G(C)| = 3$ for every $C \in \CC_G(X)$ can be trivially
generated with polynomial delay, since $L_G[X]$ is a $K_4$ for each such $X$
due to Lemma~\ref{lem:all-triang}.
So, we concentrate on generating $\Pi'(G)$ consisting of members $X$ of $\Pi(G)$
such that $\CC_G(X)$ contains a component $C$ with $|S| \geq 4$ where $S = N_G(C)$.

We need an algorithm to generate minimal separators of $G$.
Although a polynomial delay algorithm for this task is known for general graphs~\cite{berry2000generating}, we use an algorithm specialized for triconnected plane graphs for a technical reason to become clear below.

We need the following result due to Uno and Satoh \cite{uno2014efficient}. 
\begin{lemma}
[Uno and Satoh \cite{uno2014efficient}]
 \label{lem:chordless}
    Given a graph $G$, all chordless cycles of $G$ can be generated
    with polynomial delay. 
    Given a graph $G$ and two vertices $s, t \in V(G)$, 
    all chordless paths of $G$ between $s$ and $t$ can be
    generated with polynomial delay.  
\end{lemma}

\begin{lemma}
    \label{lem:minsep-polydelay}
    Given a triconnected plane graph $G$, all minimal separators of $G$
    can be generated with polynomial delay. Moreover, for each $v \in V(G)$,
    all minimal separators of $G$ that do not contain $v$ can be generated with polynomial delay.
\end{lemma}
\begin{proof}
    Given $G$, we generate all chordless cycles of $L_G$ with polynomial delay,
    using the algorithm of Uno and Satoh. These chordless cycles are in one-to-one correspondence
    with minimal separators of $G$
    due to Proposition~\ref{prop:min-sep-of-triconn}.
    For the second part, we generate all chordless cycles of $G[V(G) \setminus \{v\}]$.
    Since a chordless cycle of $G[V(G) \setminus \{v\}]$ is a chordless cycle of $G$, we have the result.
\end{proof}
\begin{remark}
    It is not clear if the algorithm \cite{berry2000generating} for generating minimal separators of a general graph can be adapted to support the second part of the lemma, which is used in the proof of Theorem~\ref{thm:poly-delay-pmcs}. We also note that the chordless path part of Lemma~\ref{lem:chordless} is used in
    the proof of Lemma~\ref{lem:gen-for-compo}.
\end{remark}

A natural approach to generate $\Pi'(G)$ is to generate all minimal separators and, for each $S$ output with $|S| \geq 4$, generate PMCs that contain $S$ based on the proof of Theorem~\ref{thm:PMC-is-steering}, which shows that
$X \supset S$ is a PMC if and only if $L_G[X]$ is an $(S, P)$-steering, where $P = X \setminus S$.
To implement this approach, 
we need to deal with the problem of suppressing duplicate
outputs of a single element without introducing super-polynomial delay.
We use the following technique due to 
Bergougnoux, Kant\'e and Wasa \cite{bergougnoux2019disjunctive} to address this problem.

Let $G$ be a graph on $n$ vertices.
We consider the general task of generating some structures defined on $G$.
Let $\calS(G)$ denote the set of those structures to be generated. 
Suppose $N$ subsets $\calS_1(G)$, \ldots, $\calS_N(G)$ of $\calS(G)$ are defined.
Let $I = \{i \mid 1 \leq i \leq N\}$. 
Suppose that the following conditions are satisfied.
\begin{enumerate}
    \item \label{item:union}
    $\calS(G) = \bigcup_{i \in I} \calS_i(G)$.
    \item $N = n^{O(1)}$.
    \item For each $s \in \calS(G)$ and $i \in I$, it can be decided whether $s \in \calS_i(G)$ in
        time $n^{O(1)}$.
    \item For each $i \in I$, there is an algorithm $\gen_i$ 
    that generates $\calS_i(G)$ with polynomial delay.
\end{enumerate}
Under these assumptions, Algorithm~\ref{alg:poly-delay-gen} generates $\calS(G)$ with
polynomial delay. The idea of this algorithm is as follows.
For each $s \in \calS(G)$, let us say that $i \in I$ \emph{owns} $s$ if $i$ is the largest
$j$ such that $s \in \calS_j(G)$.
We let $\gen_i$, where $i$ owns $s$, be responsible for the output of $s$ and suppress the output of $s$
from $\gen_j$ for other $j$. The executions of $\gen_i$ for
$i \in I$ are scheduled in such a way that at most a polynomial number of outputs are suppressed before
an unsuppressed output occurs.
\begin{algorithm}
\caption{Generation of $\calS(G)$, using sub-generators $\gen_i$ for $\calS_i(G)$, $i \in I$}
\Comment{We say \emph{emit} $s$ to mean that this algorithm outputs $s$, in order to distinguish this action from the output events of the sub-generators}\label{alg:poly-delay-gen}
\LineComment{We say that an output of a sub-generator is \emph{suppressed} if it is not emitted}
\begin{algorithmic}[1]
\Ensure Generate all members of $\calS(G)$
\For {each $i \in I$}
 \State Initiate $\gen_i$ and immediately suspend it
\EndFor
\State $i^* \gets 1$
\Repeat
 \State $\mathop{ascending} \gets \mathop{true}$
 \While {$\mathop{ascending}$}
   \State Execute $\gen_{i^*}$ up to the next event
       \label{line:while_top}
   \If {the event is the termination event}
     \State $\mathop{ascending} \gets \mathop{false}$
   \Else \Comment{the event is an output event}
     \State Let $s$ be the object to be output
       \If {$s \in \calS_i(G)$ for some $i > i^*$}
          \Comment{the output of $s$ is suppressed}
       \State $i^* \gets $ the smallest $j > i^*$
         such that $\gen_j$ has not been terminated
         \label{line:suppress}
         \State 
         \Comment{such $j$ exists, see the proof}
       \Else   
       \State Emit $s$ 
       \State $\mathop{ascending} \gets \mathop{false}$
       \EndIf
   \EndIf
 \EndWhile 
 \If {there is some $j$ such that $\gen_j$ has not been terminated}
   \State $i^* \gets$ the smallest $j$ such that $\gen_j$ has not been terminated
    \label{line:down}
 \EndIf
 \Until {$\gen_i$ has been terminated for every $i \in I$}
\end{algorithmic}
\end{algorithm}


\begin{lemma}
    \label{lem:poly-delay}
    \cref{alg:poly-delay-gen} generates $\calS(G)$ with polynomial delay,
    if all of the four conditions above are satisfied.

\end{lemma}
\begin{proof}
Let us say that $i \in I$ \emph{owns} $s \in \calS(G)$ if $s \in \calS_i(G)$ but
$s \not\in \calS_{i'}(G)$ for every $i' > i$. We also say that $\gen_i$ is the owner of
if $i$ owns $s$. Note that the set of
members of $\calS(G)$ owned by $i$ is the set of those generated by $\gen_i$ without
being suppressed in Algorithm~\ref{alg:poly-delay-gen}.

We first prove the claim given as a comment in the algorithm:
when an output of $\gen_i$ is suppressed at Line~\ref{line:suppress}, there
is some $j > i$ such that $\gen_{j}$ has not been terminated.
Let $\calS_i'(G)$ denote the set of members of $\calS_i(G)$ that are not owned by $i$.
At each point in the algorithm execution, let $\epsilon_i$ denote the
number of elements of $\calS_i'(G)$   that have been emitted and $\sigma_i$ the
number of elements of $\calS_i'(G)$ whose output by $\gen_i$ has been suppressed.
We claim that the invariant $\epsilon_i \leq \sigma_i$
holds at line~\ref{line:while_top}, the beginning of the while loop, for every $i \in I$. 
This certainly holds at the start of the algorithm. Before a member $s$ of $\calS_i'(G)$ 
is emitted for the first time, a suppression of the output of some member $s'$ of $\calS_i'(G)$ 
by $\gen_i$ must occur, in order for the owner of $s$ to obtain the control.
Unless $\sigma_i = |\calS_i'(G)|$, $\gen_i$ has not been terminated and the control
transfers to $\sigma_j$ for some $j \leq i$ after the emission of $s$.
Thus, every increment of $\epsilon_i$ is preceded by an increment of $\sigma_i$
and therefore the invariant holds. Therefore, at line~\ref{line:suppress},
$\sigma_{i^*} > \epsilon_{i^*}$ holds and the owner of some $s \in \calS_{i^*}'(G)$ has not been
terminated. This proves the claim maid in the comment at at line~\ref{line:suppress}.

Thus, every step of the algorithm is well-defined and hence it terminates after executing
$\gen_i$ for every $i \in I$ to termination. Due to Condition~\ref{item:union},
every member of $\calS(G)$ is owned by some $i \in I$ and hence is emitted exactly once, 
when it is output by its owner.

The delay in this algorithm is polynomial time, 
since each while iteration runs in polynomial time, 
each while iteration ends with an emission or the termination event of a sub-generator, and 
there are only $N = n^{O(1)}$ termination events. 
\end{proof}

We now turn to the application of this technique to our goal.
\begin{definition}
    Let $G$ be a triconnected plane graph and $C$ a minimally separated component of $G$
    with $|S| \geq 4$ where $S = N_G(C)$.
    Recall that there are exactly two full components associated with $S$ and 
    let $C'$ be the full component distinct from $C$.
    A \emph{port} of $S$ in $C'$ is a vertex $u \in C'$ such that
    $N_{L_G}(u) \cap S$ is a slot of $L_G[S]$. For a socket $\{R_1, R_2\}$ of $L_G[S]$,
    a \emph{port pair on $\{R_1, R_2\}$} in $C'$ is an unordered pair $\{u_1, u_2\}$ of ports of $S$ in $C'$
    such that $N_{L_G}(u_i) \cap S = R_i$ for $i \in \{1, 2\}$.
\end{definition}
\begin{lemma}
    \label{lem:steering-socket}   
Let $G$ be a triconnected plane graph and $C$ a minimally separated component of $G$
with $|S| \geq 4$, where $S = N_G(C)$. Let $C'$ be the other full component of $S$.
Let $P$ be an arbitrary subset of  $C'$ with $|P| \geq 2$ 
and let $X = S \cup P$.
Then, $L_G[X]$ is an $(S, P)$-steering if and only if
there is a socket $\{R_1, R_2\}$ of $L_G[S]$ and a port pair
$\{u_1, u_2\}$ in $C'$ on this socket such that either 
$L_G[P]$ is a chordless path of $A(C, u_1, u_2)$ between $u_1$ and $u_2$, where 
$A(C, u_1, u_2)$ is the subgraph of $L_G$ induced by
the vertex set $(C' \setminus N_{L_G}(S)) \cup \{u_1, u_2\}$,
or there is a hinge $s$ of the socket $\{R_1, R_2\}$ and 
$L_G[P]$ is a chordless path of $B(C, u_1, u_2, s)$ between $u_1$ and $u_2$,
where $B(C, u_1, u_2, s)$ is the subgraph of $L_G$ induced by
the vertex set $(C' \setminus N_{L_G}(S \setminus \{s\})) \cup \{u_1, u_2\}$.
\end{lemma}
\begin{proof}
Suppose $L_G[X]$ is an $(S, P)$-steering. 
Let $H = L_G[X]$.
Due to Definition~\ref{def:steering}, $H[P] = L_G[P]$ is a path.
Let $u_1$ and $u_2$ be the two ends of this path and
let $R_i = N_{L_G}(u_i) \cap S$ for $i \in \{1, 2\}$.
Since $\{R_1, R_2\}$ is a socket of the cycle $L_G[S]$, 
$R_i$ is a slot of $L_G[S]$ for $i \in \{1, 2\}$ and, moreover,
$R_1 \cup R_2$ is not a slot of $L_G[S]$.
Furthermore, $N_{L_G}(P \setminus \{u_1, u_2\}) \cap S$ is either empty or a singleton 
$\{s\}$ where $s$ is a hinge of the socket $\{R_1, R_2\}$.
Suppose the former is the case. Then, $L_G[P]$ is a path in $A(C, u_1, u_2)$
since no internal vertex of it is adjacent in $L_G$ to any vertex in $S$.
It is a chordless path, since if it had a chord in $A(C, u_1, u_2)$, then the graph $L_G[P]$ would contain
that chord and $L_G[P]$ would not be a path.
Now suppose the latter, that $N_{L_G}(P \setminus \{u_1, u_2\}) \cap S$ is a singleton
$\{s\}$ where $s$ is a hinge of the socket $\{R_1, R_2\}$.
Then, $L_G[P]$ is a path in $B(C, u_1, u_2, s)$
since no internal vertex of it is adjacent in $L_G$ to any vertex in $S \setminus \{s\}$.

For the other direction, suppose that there is a socket $\{R_1, R_2\}$ of $L_G[S]$
and a port pair $\{u_1, u_2\}$ on this socket 
such that either (1) $L_G[P]$ is a chordless path of $A(C, u_1, u_2)$ between $u_1$ and $u_2$ or
(2) there is a hinge $s$ of the socket $\{R_1, R_2\}$ and $L_G[P]$ is a chordless path of 
$B(C, u_1, u_2, s)$ between $u_1$ and $u_2$. 
If (1) is the case, then $N_{L_G}(P \setminus \{u_1, u_2\}) \cap S$ is empty.
If, on the other hand, (2) is the case, 
then $N_{L_G}(P \setminus \{u_1, u_2\}) \cap S$ is either empty or a singleton~$\{s\}$.
In either case, $L_G[S \cup P]$ is an $(S, P)$-steering.
\end{proof}

For a minimally separated component $C$ of a triconnected plane graph $G$ with $|S| \geq 4$ 
where $S = N_G(C)$,
let $\Pi(G, C)$ denote the set of PMCs $X$ such that $C \in \CC_G(X)$.

\begin{proposition}
\label{prop:pi-g-c-nonempty}
    Let $G$ and $C$ be as above. Then, $\Pi(G, C) \neq \emptyset$.
\end{proposition}
\begin{proof}
Let $S = N_G(C)$ and let $C'$ be the other full component of $S$.
Let $H$ be an arbitrary minimal triangulation of $G$ in which $S$ is a clique.
Let $X$ be an arbitrary maximal clique of $H[S \cup C']$ that contains $S$.
Since $S$ is a separator of $H$, $X$ is a maximal clique of $H$.
Since no maximal clique of a chordal graph is a minimal separator, $X$ is a proper
superset of $S$ and belongs to $\Pi(G, C)$.
\end{proof}

\begin{lemma}
    \label{lem:gen-for-compo}
    Given a triconnected plane graph $G$ and a minimally separated component $C$ of $G$ with 
    $|S| \geq 4$ where $S = N_G(C)$, 
    $\Pi(G, C)$ can be generated with polynomial delay.
\end{lemma}
\begin{proof}
Due to the proof of Theorem~\ref{thm:PMC-is-steering}, $X \subseteq V(G)$ belongs
to $\Pi(G, C)$ if and only if $L_G[X]$ is an $(S, P)$-steering where $P = X \setminus S$.
Based on Lemma~\ref{lem:steering-socket}, $\Pi(G, C)$ can be generated as follows.
First assume that $|S| \geq 5$.
Let $C'$ be the other full component of $S = N_G(C)$. For every socket $\{R_1, R_2\}$ 
of $L_G[S]$ and every port pair $\{u_1, u_2\}$ on $\{R_1, R_2\}$ in $C'$, 
do the following. If the socket does not have a hinge, then 
generate all chordless paths of $A(C, u_1, u_2)$ between $u_1$ and $u_2$,
where $A(C, u_1, u_2)$ is as defined in Lemma~\ref{lem:steering-socket};
if the socket has a hinge $s$
then generate all chordless paths of $B(C, u_1, u_2, s)$ between $u_1$ and $u_2$,
where $B(C, u_1, u_2, s)$ is as defined in Lemma~\ref{lem:steering-socket}.
For each path $p$ generated, output $S \cup V(p)$. 
Note that, in the latter case, the hinge $s$ of the socket is unique since $|S| \geq 5$
and hence PMCs in $\Pi(G, C)$ are generated without duplication.

If $|S| = 4$, a socket may have two hinges. We apply the technique of Theorem~\ref{thm:poly-delay-pmcs} to
deal with this situation. Let $S = \{s_1, s_2, s_3, s_4\}$ and suppose these vertices appear on $L_G[S]$
in this clockwise order. For each $i \in \{1, 2, 3, 4\}$, 
let $\{R_{i, 1}, R_{i, 2}\}$ denote the socket of $L_G[S]$ of which $s_i$ is a hinge.
Observe that such a socket is unique for fixed $i$.
Let $\Pi_i(G, C)$ be the set of PMCs $X \in \Pi(G, C)$ such that
$L_G[X \setminus S]$ is a path of $L_G$ between $u_1$ and $u_2$, where $\{u_1, u_2\}$ is a port pair
on the socket $\{R_{i,1}, R_{i, 2}\}$.
It is straightforwardly confirmed below that the four subsets $\Pi_i(G, C)$, $i \in \{1, 2, 3, 4\}$, 
of $\Pi(G, C)$ satisfy
the four conditions for Algorithm~\ref{alg:poly-delay-gen} to be applicable. Let $n = V(G)$.
\begin{enumerate}
    \item 
    $\Pi(G, C) = \bigcup_{i \in \{1, 2, 3, 4\}} \Pi_i(G, C)$.
    \item $4 = n^{O(1)}$.
    \item For each $X \in \Pi(G, C)$ and $i \in \{1, 2, 3, 4\}$, it can be decided whether 
    $X \in \Pi_i(G, C)$ in time $n^{O(1)}$.
    \item For each $i \in \{1, 2, 3, 4\}$, there is an algorithm 
    that generates $\Pi_i(G, C)$ with polynomial delay.
\end{enumerate}
Therefore, Algorithm~\ref{alg:poly-delay-gen} applied to this situation generates $\Pi(G, C)$
with polynomial delay.
\end{proof}

The following is the main result of this section.
\begin{theorem}
\label{thm:poly-delay-pmcs}
Given a triconnected plane graph $G$, 
$\Pi(G)$ can be generated with polynomial delay.
\end{theorem}
\begin{proof}
It suffices to show that $\Pi'(G)$, the set of PMCs $X$ of $G$ such that $|N_G(C)| \geq 4$
for some $C \in \CC_G(X)$,
can be generated with polynomial delay. Let $n = |V(G)|$.
    For each $v \in G$, let $\Pi_v(G)$ denote the
    union of $\Pi(G, C)$ over all minimally separated components $C$ of
    $G$ such that $v \in C$ and $|N_G(C)| \geq 4$.
    We have $\Pi'(G) = \bigcup_{v \in V(G)} \Pi_v(G)$ and $|V(G)| = n = n^{O(1)}$.
    Given $X \in \Pi(G)$, it is straightforward to test if $X \in \Pi_v(G)$
    in polynomial time, for a fixed~$v$.
    For each $v$, $\Pi_v(G)$ can be
    generated with polynomial delay: we generate all minimal separators 
    $S$ such that $v \not\in S$ by the second part of Lemma~\ref{lem:minsep-polydelay}
    and, for each $S$ generated such that $|S| \geq 4$, generate
    $\Pi(G, C)$ for the full component $C$ of $S$ such that $v \in C$. 
    The delay in this algorithm is polynomial, since minimal separators are generated with polynomial delay and,
    for each minimal separator generated, at least one PMC is generated due to
    Proposition~\ref{prop:pi-g-c-nonempty}.

    Therefore, applying Lemma~\ref{lem:poly-delay}, we can generate $\Pi(G)$
    with polynomial delay.
\end{proof}

\section{Computing the planar treewidth}
An algorithm for generating PMCs immediately leads to a treewidth algorithm
because of Theorem~\ref{thm:bt-dp} due to Bouchitt{\'e} and Todinca~\cite{bouchitte2001treewidth}.
%\begin{lemma}[\cite{bouchitte2001treewidth}]\label{lem:bt}
%    Given a graph $G$ on $n$ vertices and $\Pi(G)$, $\tw(G)$ can be computed in time $|\Pi(G)| n^{O(1)}$.
%\end{lemma}
\begin{theorem}
Given a planar graph $G$, $\tw(G)$ can be computed in time $|\Pi(G)| n^{O(1)}$.
\end{theorem}
\begin{proof}
We first prove the case where $G$ is triconnected. We compute a planar embedding of $G$ in time $O(n)$.
Then we apply our generation algorithm to compute $\Pi(G)$ in time $|\Pi(G)| n^{O(1)}$.
Finally, we apply Theorem~\ref{thm:bt-dp} to obtain $\tw(G)$ in time $|\Pi(G)| n^{O(1)}$.

For a general planar graph $G$, let $s(G)$ denote the number of minimal separators of cardinality at most two.
We prove the theorem by induction on $s(G)$. The base case $s(G) = 0$, where $G$ is triconnected, is already proved.
Suppose $s(G) > 0$ and let $S$ be an arbitrary minimal separator of $G$ with $|S| \leq 2$.
Let $C_1$, \ldots, $C_m$ be
the components of $G[V(G) \setminus S]$ and let $G_i = G[C_i \cup N_G(C_i)] \cup K(N_G(C_i))$, for $i = 1, \ldots, m$, be the
graph obtained from $G[C_i \cup N_G(C_i)]$, the subgraph of $G$ induced by the closed neighborhood of $C_i$,
by filling the open neighborhood of $C_i$ into a clique. Then $S$ is a \emph{safe separator} of $G$
in the sense of \cite{bodlaender2006safe} and therefore we have $\tw(G) = \max\{|S|, \max_{i \in \{1, \ldots, m\}} \tw(G_i)\}$.
By the induction hypothesis, we can compute $\tw(G_i)$ for each $i$ in time $|\Pi(G_i)| n^{O(1)}$.
We have $\sum_i |\Pi(G_i)| \leq |\Pi(G)|$, since every PMC of $G_i$ is a PMC of $G \cup K(S)$ and
hence is a PMC of $G$ and, moreover, there is no PMC that is common to $G_i$ and $G_j$ for $i \neq j$.
Therefore, 
%$\sum_i |\Pi(G_i)| \leq |\Pi(G)|$ as desired and 
we can compute $\tw(G)$ in time $|\Pi(G)| n^{O(1)}$.
\end{proof}

