\subsection{Notations} %%\label{sec:notation}
For any vector \(\vx\), \(\|\vx\|_p\) denotes its \(\ell_p\)-norm. The symbols \(\vx^\top\) and \(\vx^\ast\) represent the transpose and conjugate transpose of \(\vx\), respectively. For a matrix \(\ma\), \(\|\ma\|\), \(\|\ma\|_*\), and \(\|\ma\|_F\) denote its spectral norm, nuclear norm, and Frobenius norm, respectively, while \(\|\ma\|_{2 \to 2p} := \sup_{\|\vx\|=1} \|\ma \vx\|_{2p}\). The notations \(\ma^\top\), \(\ma^\ast\), and \(\overline{\ma}\) stand for the transpose, conjugate transpose, and entrywise conjugate of \(\ma\), respectively. We write \(\operatorname{Re}(\cdot)\) and \(\operatorname{Im}(\cdot)\) for the real and imaginary parts of a complex number or matrix (applied entrywise). For \(\mathbb{H} \in \{\mathbb{R}, \mathbb{C}\}\), \(\mathbb{S}_{\mathbb{H}}^{d-1} := \{\vx \in \mathbb{H}^d : \norm{\vx} = 1\}\) denotes the unit sphere. A vector \(\va \in \mathbb{H}^d\) is called a standard Gaussian random vector if
\begin{equation} \label{def:gauss}
\va \sim \begin{cases}
\mathcal{N}(\mathbf{0}, \mi_d), & \text{if } \mathbb{H} = \mathbb{R}, \\
\mathcal{N}(\mathbf{0}, \mi_d/2) + \i\, \mathcal{N}(\mathbf{0}, \mi_d/2), & \text{if } \mathbb{H} = \mathbb{C},
\end{cases}
\end{equation}
where \(\mathcal{N}(\mathbf{0}, \Sigma)\) denotes a Gaussian distribution with mean zero and covariance \(\Sigma\). A matrix \(\ma \in \mathbb{H}^{m \times d}\) is a standard Gaussian random matrix if its rows are independent standard Gaussian vectors. We use the notation \(f(m,n) = O(g(m,n))\) or \(f(m,n) \lesssim g(m,n)\) to mean there exists a constant \(c > 0\) such that \(f(m,n) \leq c\, g(m,n)\), and \(f(m,n) \gtrsim g(m,n)\) to mean \(f(m,n) \geq c\, g(m,n)\) for some \(c > 0\). Finally, \([m] := \{1, 2, \ldots, m\}\) for any positive integer \(m\).





\subsection{Organization}
The remainder of this paper is organized as follows: Section~\ref{sec:preliminaries} introduces equivalent characterizations of the optimal Lipschitz constants \(L_{\Psi_\ma}^{\ell_p}\) and \(U_{\Psi_\ma}^{\ell_p}\), along with orthogonality conditions as preliminaries. In Section~\ref{sec:p = 2}, we focus on the condition number with respect to the \(\ell_2\) norm, establishing optimal uniform lower bounds, concentration results for random matrices, and showing that the harmonic frame attains the optimal lower bound when \(\mathbb{H} = \mathbb{R}\). Section~\ref{sec:p = 1} presents analogous results for the \(\ell_1\) norm. Finally, Section~\ref{sec:discussion} provides a discussion and outlook. Technical lemmas and detailed proofs are collected in the supplementary materials.



\section{Characterizing the Lipschitz constants: Equivalent forms and orthogonal conditions}\label{sec:preliminaries}
In this section, we first present alternative expressions for \(L_{\Psi_\ma}^{\ell_p}\) and \(U_{\Psi_\ma}^{\ell_p}\), and then investigate the conditions under which the  lower Lipschitz bound is attained at orthogonal vectors. These results aim to simplify the characterization of \(L_{\Psi_\ma}^{\ell_p}\) and \(U_{\Psi_\ma}^{\ell_p}\), thereby facilitating the computation.



\subsection{Others expressions for \texorpdfstring{$L_{\Psi}^{\ell_p}$ and $U_{\Psi}^{\ell_p}$.}{} } 
The following theorem extends \cite[Theorem 4.5]{balan2015invertibility} from the real case to the complex case.

\begin{theorem}\label{th:equivalent}
	For any matrix $\ma = (\va_1,\cdots,\va_m)^\hh \in \H^{m\times d}$ and each $p\ge 1$, one has
	 \begin{align*}
		L_{\Psi_\ma}^{\ell_p} = \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}\in\R}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p} \quad \mbox{and} \quad U_{\Psi_\ma}^{\ell_p} =  \norms{\ma}_{2\rightarrow 2p}^2.
\end{align*}
%	and	
%	 \begin{align*}
%		U_{\Psi_\ma}^{\ell_p} = \sup_{\norm{\vu}=1} \xkh{\sum_{j=1}^m \abs{\va_j^\hh\vu}^{2p}}^{\frac 1p} = \norms{\ma}_{2\rightarrow 2p}^2.
%	\end{align*}
\end{theorem}
\begin{proof}
	For any $\vx, \vy \in \H^d$ with $\disth{\vx, \vy}\ne 0$, let $\theta_0 = \argmin{\theta\in\R} \norm{\vx-\e^{\i\theta}\vy}$.
It is easy to verify that $\nj{\vx, \e^{\i\theta_0} \vy} \in \R $ and
\[  \maxm{\theta\in\R} \ucnorm{\vx-\e^{\i\theta}\vy}=\ucnorm{\vx+\e^{\i\theta_0}\vy}. \] 
Define $\vu = \vx-\e^{\i\theta_0}\vy, \vv = \vx+\e^{\i\theta_0}\vy$.  Then $0<\norm{\vu} \le \norm{\vv}$ and $\disth{\vx, \vy}=\norm{\vu} \norm{\vv}$.  Moreover,
\[\nj{\vu, \vv} = \norm{\vx}^2 - \norm{\vy}^2 + 2 \image{\nj{\vx, \e^{\i\theta_0} \vy}} \cdot \i = \norm{\vx}^2 - \norm{\vy}^2 \in \R .
\]
A straightforward calculation yields
\begin{equation} \label{eq:reuvxy}
\ucabs{\va_j^\hh \vx}^2 - \ucabs{\va_j^\hh \vy}^2=\real{\vu^\hh\va_j \va_j^\hh\vv}.
\end{equation}
Therefore,  by the definition of \(L_{\Psi_\ma}^{\ell_p}\) in \eqref{def:l and u}, we have
\[
L^{\ell_p}_{\Psi_\ma} \ge   \inf_{\substack{\vu,\vv\in\H^d, \nj{\vu,\vv}\in\R\\  \vu,\vv \ne 0}} \frac{\xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p}}{\norm{\vu}\norm{\vv}} = \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}\in\R}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p}. 
\]
Conversely, for any $\vu,\vv\in\H^d$ with  $ \nj{\vu,\vv}\in\R$ and $\norm{\vu}=\norm{\vv}=1$, let $\vx=(\vv+\vu)/2$ and $\vy=(\vv-\vu)/2$. Then $\disth{\vx, \vy}=1$, and using \eqref{eq:reuvxy} gives
\[
\inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}\in\R}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p}\ge  \inf_{\substack{\vx,\vy\in\H^d\\ \disth{\vx, \vy}\ne 0}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_p}{\disth{\vx, \vy}} =L^{\ell_p}_{\Psi_\ma}.
\]
Combining the above inequalities, we conclude
\begin{align*}
	L_{\Psi_\ma}^{\ell_p}  = \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}\in\R}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p}. 
\end{align*}
Similarly, the upper Lipschitz constant \(U_{\Psi_\ma}^{\ell_p}\) satisfies
\begin{align*}
	U_{\Psi_\ma}^{\ell_p} = \sup_{\substack{\vu,\vv\in\H^d,  \nj{\vu,\vv}\in\R \\ \vu,\vv \neq 0}} \frac{\xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p}}{\norm{\vu}\norm{\vv}} = \sup_{\norm{\vu}=1} \xkh{\sum_{j=1}^m \abs{\va_j^\hh\vu}^{2p}}^{\frac 1p},
\end{align*}
where the last equality follows from the Cauchy–Schwarz inequality.  
\end{proof}


\begin{remark}
By the definition of \(L_{\Psi_\ma}^{\ell_p}\) in \eqref{def:l and u}, a matrix \(\ma \in \mathbb{H}^{m \times d}\) has the phase retrieval property if and only if \(L_{\Psi_\ma}^{\ell_p} > 0\). In particular, for \(p=2\), Theorem \ref{th:equivalent} implies that \(\ma\) has phase retrieval if and only if there exists a constant \(c_0 > 0\) such that
\begin{equation} \label{eq:uniel2}
\sum_{j=1}^m \left| \operatorname{Re}(\vu^\ast \va_j \va_j^\ast \vv) \right|^2 \geq c_0 \|\vu\|_2^2 \|\vv\|_2^2
\end{equation}
holds for all \(\vu, \vv \in \mathbb{H}^d\) with \(\langle \vu, \vv \rangle \in \mathbb{R}\). Previous work \cite{balan2015stability} established that \(\ma\) has the phase retrieval property if and only if there exists \(c_0 > 0\) such that for all \(\vx, \vy \in \mathbb{H}^d\),
\[
\|\Psi_{\ma}(\vx) - \Psi_{\ma}(\vy)\|_2^2 \geq c_0 \left( \|\vx - \vy\|_2^2 \|\vx + \vy\|_2^2 - 4\, \operatorname{Im}^2 \langle \vx, \vy \rangle \right).
\]
Compared to this, the condition in \eqref{eq:uniel2} is more straightforward and convenient to verify.


\end{remark}

According to Theorem \ref{th:equivalent}, a straightforward conclusion is that the minimal lower Lipschitz bound in \eqref{def:l and u} is attained when \(\vx\) and \(\vy\) are orthogonal, as stated below.


\begin{corollary}\label{th:ortho:1}
	For any matrix $\ma = (\va_1,\cdots,\va_m)^\hh \in \H^{m\times d}$ and each $p \ge 1$, the lower Lipschitz constant $L^{\ell_p}_{\Psi_\ma}$ satisfies 
	\begin{align*}
			L^{\ell_p}_{\Psi_\ma} = \inf_{\substack{\vx,\vy\in\H^d, \nj{\vx,\vy}=0\\ \norm{\vx} \le 1,\norm{\vy} = 1}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_p}{\disth{\vx, \vy}}.
		\end{align*}
\end{corollary}
\begin{proof}
For any \(\vu, \vv \in \mathbb{H}^d\) with \(\langle \vu, \vv \rangle \in \mathbb{R}\) and \(\|\vu\| = \|\vv\| = 1\), define \(\vx = (\vv + \vu)/2\) and \(\vy = (\vv - \vu)/2\). It is straightforward to verify that \(\langle \vx, \vy \rangle = 0\) and  $\disth{\vx, \vy}=1\ne 0$. Note that
\[
\operatorname{Re}(\vu^\ast \va_j \va_j^\ast \vv) = |\va_j^\ast \vx|^2 - |\va_j^\ast \vy|^2.
\]
Therefore,
\[
 L^{\ell_p}_{\Psi_\ma}= \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}\in\R}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p}  \ge  \inf_{\substack{\vx,\vy\in\H^d ,  \nj{\vx,\vy}=0 \\ \disth{\vx, \vy} \neq 0}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_p}{\disth{\vx, \vy}} ,
\]
where the equality on the left follows from Theorem \ref{th:equivalent}. Clearly,
\[
 \inf_{\substack{\vx,\vy\in\H^d ,  \nj{\vx,\vy}=0 \\ \disth{\vx, \vy} \neq 0}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_p}{\disth{\vx, \vy}} \ge  \inf_{\substack{\vx,\vy\in\H^d\\ \disth{\vx, \vy}\ne 0}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_p}{\disth{\vx, \vy}} = L^{\ell_p}_{\Psi_\ma},
\]
where the last equality is by definition of \(L_{\Psi_\ma}^{\ell_p}\). Combining these inequalities, we conclude that
\[
L_{\Psi_\ma}^{\ell_p} =  \inf_{\substack{\vx,\vy\in\H^d ,  \nj{\vx,\vy}=0 \\ \disth{\vx, \vy} \neq 0}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_p}{\disth{\vx, \vy}}.
\]
\end{proof}

\begin{remark}
A similar result has been established for the nonlinear map $\Phi$ in \cite[Theorem 1.1]{alharbi2024locality}, where the minimal lower Lipschitz bound of $\Phi$ occurs at orthogonal vectors.
\end{remark}



\subsection{Orthogonal conditions}
Recall from Theorem \ref{th:equivalent} that the lower Lipschitz bound is given by
\[
L_{\Psi_\ma}^{\ell_p} = \inf_{\substack{\|\vu\|_2 = \|\vv\|_2 = 1 \\ \langle \vu, \vv \rangle \in \mathbb{R}}} \left( \sum_{j=1}^m \left| \operatorname{Re}(\vu^\ast \va_j \va_j^\ast \vv) \right|^p \right)^{\frac{1}{p}}.
\]
To further simplify the computation, it is natural to ask under what conditions the infimum is attained when \(\vu\) and \(\vv\) are orthogonal. The next lemma provides a sufficient condition for this to hold in the case \(p=2\).


\begin{lemma}\label{le:ortho:2:p=2}
	Let $\ma = (\va_1,\cdots,\va_m)^\hh \in \H^{m\times d}$. If $\sum_{j=1}^{m} \ucabs{\va_j^\hh \vx}^4 = \sum_{j=1}^{m} \ucabs{\va_j^\hh \vy}^4 $ holds for all $\vx, \vy \in\H^d$ with $\norm{\vx} = \norm{\vy} = 1$ and  $\nj{\vx, \vy}=0$, then 
	\begin{align*}
		L_{\Psi_\ma}^{\ell_2} = \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv} = 0}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^2}^{\frac 12}. 
	\end{align*}
\end{lemma}
\begin{proof}
To prove the result, it suffices to show that if the condition
 $\sum_{j=1}^{m} \ucabs{\va_j^\hh \vx}^4 = \sum_{j=1}^{m} \ucabs{\va_j^\hh \vy}^4 $ holds for all $\vx, \vy \in\H^d$ with $\norm{\vx} = \norm{\vy} = 1$ and $\nj{\vx, \vy}=0$, then 
	\begin{equation} \label{eq:normorth}
		L_{\Psi_\ma}^{\ell_2} =  \inf_{\substack{\vx,\vy\in\H^d ,  \nj{\vx,\vy}=0 \\ \norm{\vx}=\norm{\vy}=1}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_2}{\disth{\vx, \vy}}.
	\end{equation}
Indeed, for any such $\vx, \vy \in\H^d$, define
\[
\vu = \frac{\vx - \vy}{\sqrt{2}}, \quad \vv = \frac{\vx + \vy}{\sqrt{2}}.
\]
Then $\norm{\vu}=\norm{\vv}=1$, $ \nj{\vu,\vv}=0$, and  $\disth{\vx, \vy}=2$.  Note that $\ucabs{\va_j^\hh \vx}^2 - \ucabs{\va_j^\hh \vy}^2=2\ucreal{\vu^\hh\va_j \va_j^\hh\vv} $. Therefore, 
\begin{equation} \label{eq:gexorthy}
 \inf_{\substack{\vx,\vy\in\H^d ,  \nj{\vx,\vy}=0 \\ \norm{\vx}=\norm{\vy}=1}} \frac{\ucnorms{\abs{\ma\vx}^2-\abs{\ma\vy}^2}_2}{\disth{\vx, \vy}} \ge \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv} = 0}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^2}^{\frac 12} \ge 	L_{\Psi_\ma}^{\ell_2},
\end{equation}
where the last inequality follows from Theorem \ref{th:equivalent}. Combining \eqref{eq:normorth} and \eqref{eq:gexorthy}, we conclude that
\[
L_{\Psi_\ma}^{\ell_2} = \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv} = 0}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^2}^{\frac 12}. 
\]

Next, we prove \eqref{eq:normorth}.  For any $\vx,\vy \in \H^d$ with $\nj{\vx,\vy}=0$ and $\norm{\vx}=\norm{\vy}=1$, define  $\vx^t = \sqrt{t}\,\vx$ and consider the function
 \begin{equation*}
	g(t) := \frac{\ucnorm{\ucabs{\ma\vxt}-\ucabs{\ma\vy}}^2}{\mbox{dist}_{\H}^2\xkh{\vxt, \vy}}.
\end{equation*}
We claim that 
\begin{equation} \label{cla:g1}
\min_{t \ge 0} g(t) = g(1).
\end{equation}
The equation \eqref{eq:normorth} then follows by combining \eqref{cla:g1} with Corollary \ref{th:ortho:1}.  
To prove the claim \eqref{cla:g1},  observing  that since \(\langle \vx^t, \vy \rangle = 0\), we have
\[ 
\disth{\vxt, \vy}=\ucnorm{\vxt-\vy} \ucnorm{\vxt+\vy}=t+1.
\]
For convenience, set $\alpha_j = \ucabs{\va_j^\hh \vx}^2$, $\gamma_j = \ucabs{\va_j^\hh \vy}^2$. Then
 \begin{equation*}
	g(t) = \frac{\sum_{j=1}^{m} \xkh{\alpha_j t - \gamma_j}^2}{(t+1)^2} .
\end{equation*}
It is straightforward to compute the derivative:
\[
g'(t) = \frac{2 \sumjm (\alpha_j t - \gamma_j)(\alpha_j + \gamma_j)}{(t+1)^3}.
\]
Recall the  assumption $\sum_{j=1}^{m} \ucabs{\va_j^\hh \vx}^4 = \sum_{j=1}^{m} \ucabs{\va_j^\hh \vy}^4 $, which implies 
\[
\sumjm \alpha_j^2 = \sumjm \gamma_j^2.
\] 
Evaluating the derivative at \(t=1\) gives 
\[
g'(1) = \frac{2 \sum_{j=1}^m (\alpha_j - \gamma_j)(\alpha_j + \gamma_j)}{2^3} = \frac{2 \sum_{j=1}^m (\alpha_j^2 - \gamma_j^2)}{8} = 0.
\]
Since the numerator of \(g'(t)\) is linear in \(t\) and all \(\alpha_j, \gamma_j \geq 0\), it follows that \(g(t)\) attains its minimum at \(t=1\). This completes the proof.
\end{proof}


Lemma \ref{le:ortho:2:p=2} requires the condition
\[
\sum_{j=1}^m |\va_j^\ast \vx|^4 = \sum_{j=1}^m |\va_j^\ast \vy|^4
\]
to hold for all \(\vx, \vy \in \mathbb{H}^d\) with \(\|\vx\|_2 = \|\vy\|_2 = 1\) and \(\langle \vx, \vy \rangle = 0\). A sufficient condition for this is that \(\{\va_j\}_{j=1}^m\) forms a tight \(p\)-frame with \(p=4\). Here, we focus on \(p\)-frames in finite-dimensional Hilbert spaces; for a broader treatment of \(p\)-frame theory in Banach spaces, see \cite{casazza2005frame, christensen2003p}.




\begin{definition}\label{def:frame}
	Let $H$ be a finite dimensional Hilbert space and let $1\le p < \infty$. A collection of vectors $\{\va_j\}_{j\in J}$ in $H$ is called a $p$-frame of $H$ with $p$-frame bounds $B \ge A > 0$ if
	 \begin{equation*}
		A \norms{\vx} \le \Big(\sum_{j\in J} \ucabs{\nj{\vx, \va_j}}^p\Big)^{1/p} \le B \norms{\vx} \qquad \mbox{for all} \quad \vx \in H.
	\end{equation*}
If $A = B$, then $\{\va_j\}_{j\in J}$ is called   a tight $p$-frame. 
\end{definition}

It is worth noting that the harmonic frame \(\mem\), defined in \eqref{def:mem}, satisfies $\sum_{j=1}^{m} \lvert\va_j^\hh \vu\rvert^4 = 3m/8$ for all \(\vu \in \mathbb{R}^2\) with \(\norm{\vu} = 1\) (see Section \ref{pf:em:l2}), and is therefore a tight 4-frame. Random frame constructions play a fundamental role in phase retrieval within finite-dimensional Hilbert spaces \cite{alharbi2023stable}. Statistical analysis shows that vectors sampled uniformly at random from the unit sphere in such spaces are highly likely to form an approximate tight frame when the sample size is sufficiently large \cite{vershynin2018}.
 Recent studies on phase retrieval stability have highlighted the advantages of employing \(p\)-norms and their extensions to Banach lattices, with explicit applications discussed in \cite{alaifari2017phase, christ2022examples, freeman2023discretizing}.


Building on Lemma \ref{le:ortho:2:p=2}, one might hope for a similar result to hold when \(p = 1\). However, the following lemma demonstrates that, even for the harmonic frame \(\mem \in \mathbb{R}^{m \times 2}\), the minimal lower Lipschitz bound does not necessarily occur at orthogonal vectors \(\vu\) and \(\vv\).




\begin{lemma}\label{le:ortho:l - em:p=1} 
	Let $m \ge 3$. For $\mem = (\va_1,\cdots,\va_m)^\T \in \R^{m\times 2}$ defined in \eqref{def:mem}, one has: \begin{equation}\label{eq:ortho:1}
		\inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv} = 0}} \sum_{j=1}^m \ucabs{\vu^\T\va_j \va_j^\T\vv} = \left\{\begin{aligned}
			&\frac{1}{2\tan \frac{\pi}{2 m}}, \quad \mbox{if}\ m\ \mbox{is odd},\\
			&\ \frac{1}{ \tan \frac{\pi}{m}}, \ \ \quad \mbox{if}\ m\ \mbox{is even},
		\end{aligned}\right.
	\end{equation}
	and \begin{equation}\label{eq:ortho:2}
		\inf_{\norm{\vu}=\norm{\vv}=1} \sum_{j=1}^m \ucabs{\vu^\T\va_j \va_j^\T\vv} = \left\{\begin{aligned}
			&\frac{\cos \frac{\pi}{2 m}}{2\tan \frac{\pi}{2 m}}, \quad \mbox{if}\ m\ \mbox{is odd},\\
			&\ \frac{1}{ \tan \frac{\pi}{m}},             \ \ \quad \mbox{if}\ m\ \mbox{is even}.
		\end{aligned}\right.
	\end{equation}
\end{lemma}
\begin{proof}
	See Section \ref{pf:ortho:l - em:p=1}. 
\end{proof}







