\section{The Condition number under \texorpdfstring{\( \ell_2 \)}{l2} norm}\label{sec:p = 2}
In this section, we first establish universal lower bounds on the condition number \(\betatwo_{\Psi_\ma}\) for all \(\ma \in \mathbb{H}^{m \times d}\). We then demonstrate the tightness or asymptotic tightness of these bounds by computing the condition numbers for the harmonic frame \(\mem \in \mathbb{R}^{m \times 2}\) and for Gaussian random matrices \(\ma \in \mathbb{H}^{m \times d}\).





\begin{theorem}\label{le:opt:number:2}
	For any matrix $\ma \in \H^{m\times d}$, one has 
	\begin{align*}
		\betatwo_{\Psi_\ma} \ge \betatwobar := \left\{\begin{aligned}
			&\sqrt{3},\quad \mbox{if } \H = \R, \\
			&\,\ 2,       \quad\; \mbox{if } \H = \C.
		\end{aligned}\right. 
	\end{align*}
\end{theorem}
\begin{proof}
	See Section \ref{pf:opt:number:2}. 
\end{proof}

It is noteworthy that, to prove Theorem \ref{le:opt:number:2}, we only need to consider the case where \( d = 2 \). In fact, letting $\mb = (\vb_1,\cdots,\vb_m)^\T\in\H^{m\times 2}$ be the the matrix composed of the first two columns of $\ma\in\hmd$, one can easily check that \begin{align*}
	L^{\ell_p}_{\Psi_\ma} = \inf_{\substack{\nj{\vu,\vv}\in\R \\ \norm{\vu}=\norm{\vv}=1}} \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\va_j \va_j^\hh\vv}}^p}^{\frac 1p} \le \inf_{\substack{\nj{\vu,\vv}\in\R, \vu,\vv\in\H^2 \\ \norm{\vu}=\norm{\vv}=1}}  \xkh{\sum_{j=1}^m \abs{\real{\vu^\hh\vb_j \vb_j^\hh\vv}}^p}^{\frac 1p}
\end{align*}
and\begin{align*}
	U^{\ell_p}_{\Psi_\ma} = \sup_{\norm{\vu}=1} \xkh{\sum_{j=1}^m \abs{\va_j^\hh\vu}^{2p}}^{\frac 1p} \ge \sup_{\vu\in\H^2, \norm{\vu}=1} \xkh{\sum_{j=1}^m \abs{\vb_j^\hh\vu}^{2p}}^{\frac 1p}.
\end{align*}
As a result, one has 
\begin{equation} \label{eq:betaAB}
	\betalp_{\Psi_\ma} = \frac{U^{\ell_p}_{\Psi_\ma}}{L^{\ell_p}_{\Psi_\ma}} \ge \frac{U^{\ell_p}_{\Psi_\mb}}{L^{\ell_p}_{\Psi_\mb}}  = \betalp_{\Psi_\mb}. %|_{d=2}
\end{equation}


The following theorem establishes that the universal lower bound given in Theorem \ref{le:opt:number:2} for \(\mathbb{H} = \mathbb{R}\) is tight. To begin, recall the harmonic frame consisting of \(m\) equidistant points on the upper semicircle, defined as
\renewcommand{\arraystretch}{1.5}
\begin{align} \label{eq:harmf}
\mem := \begin{pmatrix}
1 & \cos\left(\frac{\pi}{m}\right) & \cdots & \cos\left(\frac{(m-1)\pi}{m}\right) \\
0 & \sin\left(\frac{\pi}{m}\right) & \cdots & \sin\left(\frac{(m-1)\pi}{m}\right)
\end{pmatrix}^\top \in \mathbb{R}^{m \times 2}.
\end{align}
\renewcommand{\arraystretch}{1}


\begin{theorem}\label{le:em:l2}
	For any $m \ge 3$, let $\mem$ be defined as in \eqref{eq:harmf}. Then
	\begin{equation*}
		\betatwo_{\Psi_\mem} = \sqrt{3}. 
	\end{equation*}
\end{theorem}
\begin{proof}
	See Section \ref{pf:em:l2}. 
\end{proof}


Next, we estimate the  condition number for a standard Gaussian random matrix, which shows that the universal lower bound given in Theorem \ref{le:opt:number:2} is asymptotic optimal for the real case.

%
