%		\betatwobar \le \betatwo_{\Psi_\ma} \le \betatwobar + \delta
%	\end{equation}
%	provided that $m\ge C_0 \delta^{-4} d^2$. Here, $c_0,C_0>0$ are some universal constants. 
%\end{lemma}
