\subsection{Proof of Theorem \ref{le:opt:number:2}} \label{pf:opt:number:2} 
According to \eqref{eq:betaAB}, without loss of generality, we assume  \( d = 2 \), i.e. $\ma = (\va_1,\va_2,\cdots,\va_m)^\hh\in \H^{m\times 2}$. We write
\begin{align}\label{eq:ai}
	\va_i = t_i \begin{pmatrix}
		\cos \varphi_i \cos \alpha_i\\
		\sin \varphi_i \cos \beta_i
	\end{pmatrix} + t_i\cdot \i \cdot \begin{pmatrix}
	\cos \varphi_i \sin \alpha_i\\
	\sin \varphi_i \sin \beta_i
	\end{pmatrix}
\end{align}
where $t_i = \norm{\va_i}\ge 0$, $(\varphi_i,\alpha_i,\beta_i)\in I^\H$ and 
\begin{align}\label{eq:ih}
	I^\H := \left\{\begin{aligned}
		&[0, \pi]\times \dkh{0}\times \dkh{0},       & \mbox{if } \H = \R, \\
		&[0, \pi]\times [0, 2\pi]\times [0, 2\pi],   & \mbox{if } \H = \C.
	\end{aligned}\right. 
\end{align}
Applying Theorem \ref{th:equivalent}, one has
 \begin{align}\label{eq:ulp}
	U^{\ell_2}_{\Psi_\ma} = \sup_{\norm{\vu}=1} \xkh{\sum_{j=1}^m \abs{\va_j^\hh\vu}^{4}}^{\frac 12} 
\end{align} and
 \begin{eqnarray}\label{eq:llp}
	L^{\ell_2}_{\Psi_\ma} &= &  \inf_{\norm{\vu}=\norm{\vv}=1} \xkh{\sumim \abs{\real{\vu^\hh\va_i \va_i^\hh\vv}}^2}^{1/2}   \notag \\
	&\le & \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}=0}} \xkh{\sumim \abs{\real{\vu^\hh\va_i \va_i^\hh\vv}}^2}^{1/2} =: M_\ma.
\end{eqnarray}
Similar to \eqref{eq:ai}, we also parameterize $\vu, \vv$ as
 \begin{align} \label{eq:uv}
	\vu = \begin{pmatrix}
		\cos \theta \cos \alpha\\
		\sin \theta \cos \beta
	\end{pmatrix} + \i \cdot \begin{pmatrix}
		\cos \theta \sin \alpha\\
		\sin \theta \sin \beta
	\end{pmatrix}\ \ \mbox{and}\ \ \vv = \begin{pmatrix}
		\sin \theta \cos \alpha\\
		-\cos \theta \cos \beta
	\end{pmatrix} + \i \cdot \begin{pmatrix}
		\sin \theta \sin \alpha\\
		-\cos \theta \sin \beta
	\end{pmatrix},
\end{align}
where $(\theta,\alpha,\beta)\in I^\H$. A straightforward calculation reveals that 
\[
\abs{\va_i^\hh \vu}^2 = \frac 12 t_i^2 + \frac 12 t_i^2\xkh{\cos 2\varphi_i \cos 2\theta + \sin 2\varphi_i \sin 2\theta \cos\xkh{\alpha-\beta-\alpha_i+\beta_i}}
\]
and 
\begin{equation} \label{eq:Reuv}
\real{\vu^\hh\va_i\va_i^\hh\vv} = \frac 12 t_i^2 \xkh{\cos 2\varphi_i \sin 2\theta - \sin 2\varphi_i \cos 2\theta \cos\xkh{\alpha-\beta-\alpha_i+\beta_i}}.
\end{equation}
To prove the results, it suffices to show 
 \begin{align} \label{eq:upplow}
	(U_{\Psi_\ma}^{\ell_2})^2 \ge \left\{\begin{aligned}
		&\frac{3}{8}\sumim t_i^4, \  \mbox{if } \H = \R, \\
		&\frac{1}{3}\sumim t_i^4, \  \mbox{if } \H = \C,
	\end{aligned}\right. \quad \mbox{and}\quad (M_\ma)^2 \le \left\{\begin{aligned}
		&\; \frac{1}{8}\ \sumim t_i^4, \  \mbox{if } \H = \R, \\
		&\frac{1}{12}\sumim t_i^4,     \  \mbox{if } \H = \C.
	\end{aligned}\right.  
\end{align}
We first estimate $(U_{\Psi_\ma}^{\ell_2})^2$.  It follows from \eqref{eq:ulp} that 
 \[(U_{\Psi_\ma}^{\ell_2})^2 = \maxm{(\vu, \vv)\in\X^\H} \sum_{i=1}^{m} \abs{\va_i^\hh\vu}^4 = \maxm{(\theta, \alpha, \beta)\in I^\H} f(\theta,\alpha,\beta) \]
where \[f(\theta,\alpha,\beta) := \frac 14 \sum_{i=1}^{m} t_i^4\xkh{1+\cos 2\varphi_i\cos 2\theta + \sin 2\varphi_i\sin 2\theta\cos(\alpha-\beta-\alpha_i+\beta_i)}^2. \]
Consider the following two cases:

{\bf Case 1: $\H = \R$.} For this case, \( \alpha = \beta = 0 \) and \( \alpha_i = \beta_i = 0 \) for $i = 1,\cdots,m$, so \( f(\theta,0,0) \) can be simplified to 
\[f(\theta,0,0) = \frac 14 \sum_{i=1}^{m} t_i^4\xkh{1 + \cos(2\varphi_i-2\theta)}^2 = \frac 18 \sum_{i=1}^{m} t_i^4\xkh{3 + 4\cos(2\theta-2\varphi_i)+\cos(4\theta-4\varphi_i)}.\]
Through a straightforward calculation, we obtain 
\begin{eqnarray*}
	\maxm{\theta\in [0,\pi]} f(\theta,0,0) \ge \frac 1\pi \int_0^\pi f(\theta,0,0) \dd \theta \overset{\text{(i)}}{=} \frac 1\pi \int_0^\pi \frac 38 \sum_{i=1}^{m} t_i^4 \dd \theta = \frac 38 \sum_{i=1}^{m} t_i^4. 
\end{eqnarray*} 
Here, (i) comes from the fact that
\begin{align*}
	& \int_0^\pi \sum_{i=1}^{m} t_i^4 \xkh{4\cos(2\theta-2\varphi_i)+\cos(4\theta-4\varphi_i)} \dd \theta = 0 
\end{align*}
since $\cos(2\theta-2\varphi_i)$ and $\cos(4\theta-4\varphi_i)$ are periodic function  in \( \theta \) with period $\pi$. 

{\bf Case 2: $\H = \C$.} Note that \(\cos(\alpha-\beta-\alpha_i+\beta_i) = \cos(\alpha-\beta)\cos(\alpha_i-\beta_i) + \sin(\alpha-\beta)\sin(\alpha_i-\beta_i)\).  Taking $x = \cos2\theta, y = \sin 2\theta \cos(\alpha-\beta), z = \sin 2\theta \sin(\alpha-\beta), a_i = \cos2\varphi_i, b_i = \sin2\varphi_i \cos(\alpha_i-\beta_i), c_i = \sin2\varphi_i \sin(\alpha_i-\beta_i)$, then  one can rewrite \( f(\theta,\alpha,\beta) \) as 
\[f(\theta,\alpha,\beta) = \frac 14\sumim t_i^4 \xkh{1+(a_i\cdot x + b_i\cdot y + c_i\cdot z)}^2:= h(x,y,z).
\]
It is easy to see that $x^2 + y^2 + z^2 = 1$ and $a_i^2 + b_i^2 + z_i^2 = 1$ for each $i$. Denote \(\SSS^2 = \dkh{(x, y, z)^\T \in \R^3:x^2 + y^2 + z^2 = 1}\).  Since $h(x,y,z)$ is nonnegative in \(\SSS^2\), we see that \begin{align*}
	\maxm{(x,y,z)\in\SSS^2} h(x,y,z) \ge \frac{1}{4\pi} \iint_{\SSS^2} h(x,y,z)\dd S = \frac{1}{16\pi} \sumim t_i^4 \iint_{\SSS^2} \xkh{1+(a_i\cdot x + b_i\cdot y + c_i\cdot z)}^2 \dd S. 
\end{align*}
The Poisson formula in surface integrals implies  that 
\[\iint_{\SSS^2} \xkh{1+(a_i\cdot x + b_i\cdot y + c_i\cdot z)}^2 \dd S = 2\pi\int_{-1}^{1}\xkh{1+u}^2\dd u = \frac{16\pi}{3}.\]
As a result, we immediately have 
\[\maxm{(\theta,\alpha,\beta)\in I^\H}f(\theta,\alpha,\beta) \ge \frac 13 \sumim t_i^4.\]
This gives the lower bounds of  $(U_{\Psi_\ma}^{\ell_2})^2$ in \eqref{eq:upplow}.


Next, we turn to estimate the upper bound of $M_\ma$ in \eqref{eq:upplow}. According to \eqref{eq:Reuv}, one has
\((M_\ma)^2 = \min_{(\theta,\alpha,\beta)\in I^\H} g(\theta, \alpha, \beta)\) where
\begin{equation*}
	g(\theta, \alpha, \beta) :=  \frac 14 \sum_{i=1}^{m} t_i^4 \xkh{\cos 2\varphi_i\sin 2\theta - \sin 2\varphi_i\cos 2\theta\cos(\alpha-\beta-\alpha_i+\beta_i)}^2.
\end{equation*}
Using the same arguments to that of \( (U_{\Psi_\ma}^{\ell_2})^2 \), we have
\[\minm{\theta\in [0,\pi]} g(\theta,0,0) = \minm{\theta\in [0,\pi]} \frac 14 \sum_{i=1}^{m} t_i^4\xkh{\sin(2\theta - 2\varphi_i)}^2\le \frac 1{4\pi} \int_0^\pi \sum_{i=1}^{m} t_i^4\xkh{\sin(2\theta - 2\varphi_i)}^2  \dd \theta = \frac 18 \sum_{i=1}^{m} t_i^4\]
for \(\H = \R\), and 
\[\minm{(\theta, \alpha, \beta)\in I^\C} g(\theta, \alpha, \beta) \le \frac{1}{16\pi} \cdot 2\pi\int_{-1}^{1} u^2\dd u \sum_{i=1}^{m} t_i^4 = \frac{1}{12} \sum_{i=1}^{m} t_i^4\]
for \(\H = \C\). This completes the proof.


\subsection{Proof of Theorem \ref{le:em:l2}}\label{pf:em:l2}
Let $\vu = (\cos \theta \; \sin \theta)^\T$ and $\vv = (\cos \varphi \; \sin \varphi)^\T$ with \(0 \le \theta, \varphi \le 2\pi\). Denote $\mem = (\va_1,\va_2,\cdots,\va_m)^\T\in \R^{m\times 2}$. Recalling the definition of $\mem$ in \eqref{eq:harmf}, we have \renewcommand{\arraystretch}{1.5} \begin{align*}
	\mem\vu = \begin{pmatrix}
		1\cdot \cos \theta + 0\cdot \sin \theta \\
		\cos \frac{\pi}{m}\cdot \cos \theta + \sin \frac{\pi}{m}\cdot \sin \theta \\
		\cdots \\
		\cos \frac{(m-1)\pi}{m}\cdot \cos \theta + \sin \frac{(m-1)\pi}{m}\cdot \sin \theta
	\end{pmatrix} = \begin{pmatrix}
		\cos \xkh{0-\theta} \\
		\cos \xkh{\frac{\pi}{m}-\theta} \\
		\cdots \\
		\cos \xkh{\frac{(m-1)\pi}{m}-\theta} 
	\end{pmatrix}.
\end{align*}
It gives
\begin{align*}
 \sumjm \ucabs{\va_j^\T \vu}^4 = \sum_{j=1}^m \cos^4 \xkh{\frac{j\pi}{m}-\theta} = \sum_{j=1}^m \zkh{\frac 38 + \frac{\cos \xkh{\frac{2j\pi}{m}-2\theta}}{2} + \frac{\cos \xkh{\frac{4j\pi}{m}-4\theta}}{8}}.
\end{align*}
Applying the Lagrange's trigonometric identities that
\begin{equation} \label{eq:Lind} 
\sum_{j=1}^k \cos(j \theta)=\frac{\sin\xkh{\frac{2k+1}{2}\theta}}{2\sin\xkh{\frac{\theta}{2}}}-\frac12 \qquad \mbox{and} \qquad \sum_{j=1}^k \sin(j \theta)=\frac{\sin\xkh{\frac{k+1}{2}\theta} \sin\xkh{\frac{k\theta}{2}}}{\sin\xkh{\frac{\theta}{2}}},
\end{equation}
one can check that 
 \begin{equation} \label{eq:cos24}
 \sum_{j=1}^m  \cos \xkh{\frac{2j\pi}{m}-2\theta}=0, \qquad \sum_{j=1}^m  \cos \xkh{\frac{4j\pi}{m}-4\theta}=0.
 \end{equation}
Therefore, the upper Lipschitz constant of $\mem$ is 
\begin{align*}
	U_\mem^{\ell_2} = \maxm{\theta\in[0,2\pi]} \xkh{\sumjm \ucabs{\va_j^\T \vu}^4}^{1/2} = \sqrt{\frac{3m}{8}}
\end{align*}
Similarly, we have
\begin{align*}
	\mem\vv = \begin{pmatrix}
		\cos \xkh{0-\varphi} \ 
		\cos \xkh{\frac{\pi}{m}-\varphi} \ 
		\cdots \ 
		\cos \xkh{\frac{(m-1)\pi}{m}-\varphi} 
	\end{pmatrix}^\T.
\end{align*}\renewcommand{\arraystretch}{1}
This gives
\begin{align*}
\sumjm \ucabs{\va_j^\T \vu}^2\ucabs{\va_j^\T \vv}^2 =& \sum_{j=1}^m \cos^2 \xkh{\frac{j\pi}{m}-\theta} \cos^2 \xkh{\frac{j\pi}{m}-\varphi} \\
	\overset{\text{(i)}}{=} & \frac m4 + \frac 14 \sum_{j=1}^m \cos \xkh{\frac{2j\pi}{m}-2\theta}\cos \xkh{\frac{2j\pi}{m}-2\varphi} \\
	=& \frac m4 + \frac 18 \sum_{j=1}^m \zkh{\cos (2\theta-2\varphi)+ \cos \xkh{\frac{4j\pi}{m}-2\theta-2\varphi}} \\
	=& \frac m4 + \frac m8 \cos (2\theta-2\varphi). 
\end{align*}
where  (i) comes from trigonometric identities together with \eqref{eq:cos24}. 
As a result, $L_\mem^{\ell_2}$ can be calculated as follows 
\begin{align*}
	L_\mem^{\ell_2} = \minm{\theta,\varphi\in[0,2\pi]} \xkh{\sumjm \ucabs{\va_j^\T \vu}^2\ucabs{\va_j^\T \vv}^2}^{1/2} = \sqrt{\frac{m}{8}},
\end{align*}
where the last equality holds if and only if $\abs{2\theta-2\varphi}=\pi$, namely, $\vu \perp \vv$. 
Combining the lower and upper Lipschitz constants, we arrive at the conclusion that 
\begin{align*}
	\betatwo_{\mem} = U_\mem^{\ell_2}/L_\mem^{\ell_2} = \sqrt{3}.
\end{align*}


\subsection{Proof of Theorem \ref{le:concent:p=2}}\label{pf:concent:p=2} 
Based on Lemma \ref{le:u:p=2}, with probability at least \(1 - 2\exp(-d/2)\), it holds
\begin{equation*}
	\norms{\ma}_{2\rightarrow 4} \le  (3m)^{1/4} + 2\sqrt{d}.
	\end{equation*}
Therefore, for any fixed $0<\delta_1 \le 1$, one has
 \begin{equation} \label{eq:gauup}
	 \frac{1}{\sqrt{m}} U_{\Psi_\ma}^{\ell_2}= \frac{1}{\sqrt{m}} \norms{\ma}_{2\rightarrow 4}^2 \le \sqrt{3} + \delta_1,
	 \end{equation}
provided that \(m \ge C_0 \delta_1^{-4} d^2\) for some  constant \( C_0 > 0 \).   For the lower Lipschitz constant, recall that 
\[
\frac 1m (L_{\Psi_\ma}^{\ell_2})^2 = \inf_{\norm{\vu} = \norm{\vv} = 1} \frac 1m \sum_{j=1}^{m} \abs{\vu^\T \va_j\va_j^\T \vv}^2. 
\]
Since $\va_1,\ldots,\va_m \in \R^d $ are i.i.d. Gaussian random vectors,  Lemma \ref{le:l:p=2} yields that 
\begin{equation*} \label{eq:dellow}
\inf_{\norm{\vu} = \norm{\vv} = 1} \frac 1m \sum_{j=1}^{m} \abs{\vu^\T \va_j\va_j^\T \vv}^2 \ge  \inf_{\norm{\vu} = \norm{\vv} = 1}  \xkh{\norm{\vu}^2 \norm{\vv}^2+ 2\abs{\nj{\vu,\vv}}^2 - \delta_1} \ge 1-\delta_1
\end{equation*}
with probability at least $1 - c' \exp\xkh{-c'' \delta_1^2 m} - O(m^{-d})$ when $m\ge C_0  \delta_1 ^{-2} d \log d$.  Here,  $c', c'' > 0$ are universal constants. 
Thus, when $0<\delta_1  \le 1$, it holds
\begin{equation} \label{eq:gaulow}
\frac 1 {\sqrt m} L_{\Psi_\ma}^{\ell_2} \ge 1 - \delta_1.
\end{equation}
Combining \eqref{eq:gauup} and \eqref{eq:gaulow}, we obtain that for any fixed $0<\delta_1<0.4$, when \(m \ge C_0 \delta_1^{-4} d^2\), it holds 
 \begin{align*}
	\frac{U_{\Psi_\ma}^{\ell_2}}{L_{\Psi_\ma}^{\ell_2}} \le  \sqrt{3}+10\delta_1 
	\end{align*}
with probability at least $1 - c_1 \exp\xkh{-c_0 d} - O(m^{-d})$. Here, $c_1, c_0>0$ are universal constants. Taking $\delta=10 \delta_1$, we arrive at the conclusion.



