\section{The condition number under \texorpdfstring{\( \ell_1 \)}{l1} norm} \label{sec:p = 1}
In this section, we study the condition number of \(\Psi\) with respect to the \(\ell_1\) norm. The following theorem establishes a universal lower bound for \(\beta^{\ell_1}_{\Psi_\ma}\).


\begin{theorem}\label{le:opt:number:l1}
	For any matrix $\ma \in \H^{m\times d}$, one has 
	\begin{align*}
		\betaone_{\Psi_\ma} \ge \betaonebar := \left\{\begin{aligned}
			&\pitwo,  \   &  \mbox{if } \ \H = \R, \\
			&\, 2,    \   &  \mbox{if } \ \H = \C.
		\end{aligned}\right. 
	\end{align*}
\end{theorem}
\begin{proof}
	See Section \ref{pf:opt:number:1}. 
\end{proof}

In the real case where \(\mathbb{H} = \mathbb{R}\), a more refined analysis allows for a slight improvement of the universal lower bound presented in Theorem \ref{le:opt:number:l1}.



\begin{theorem}\label{le:subopt:number:l1}
	Let \(d \ge 2\), \(m \ge 3\) and let \(\ma = (\va_1,\va_2,\cdots,\va_m)^\T \in \R^{m\times d}\). Then one has \begin{equation*}
		\betaone_{\Psi_\ma} \ge m \tan\pimtwo. 
	\end{equation*}
\end{theorem}
\begin{proof}
	See Section \ref{pf:subopt:number:l1}. 
\end{proof}

The following theorem characterizes the condition number \(\betaone_{\mem}\) of the harmonic frame \(\mem \in \mathbb{R}^{m \times 2}\) and demonstrates that the bound \(\pitwo\) given in Lemma \ref{le:opt:number:l1} is nearly optimal.


\begin{theorem}\label{le:em:l1}
	For \(d \ge 2\), \(m \ge 3\) and the harmonic frame \( \mem \) defined in \eqref{def:mem}, we have that \begin{equation*}
		\betaone_{\mem} = \left\{\begin{aligned}
			& m \frac{\tan \pimtwo}{\cos \pimtwo},   \quad \mbox{if}\ m\ \mbox{is odd},\\
			& \frac m2 \tan \frac{\pi}{m},           \quad \mbox{if}\ m\ \mbox{is even}.
		\end{aligned}\right.
	\end{equation*}
\end{theorem}
\begin{proof}
	See Section \ref{pf:em:l1}. 
\end{proof}


As before, the following theorem demonstrates that the universal lower bounds established in Theorem \ref{le:opt:number:l1} are asymptotically tight for both the real and complex cases.





\begin{theorem}\label{le:concent:p=1} 
	Assume that $\ma=(\va_1,\cdots,\va_m)^\T\in\hmd$ is a standard Gaussian matrix with $\H=\R$ or $\C$. For any $ 0 < \delta < 0.4 $, with probability at least $1 - 4 \exp(-c_0 d)$, one has \begin{equation}
		\betaonebar \le \betaone_{\Psi_\ma} \le \betaonebar + \delta,
	\end{equation}
	provided that $m\ge C_0\log (1/\delta) \delta^{-2} d$. Here, $c_0,C_0>0$ are some universal constants. 
\end{theorem}
\begin{proof}
	See Section \ref{pf:concent:p=1}. 
\end{proof}

\subsection{Proof of Theorem \ref{le:opt:number:l1}} \label{pf:opt:number:1} 
The proof is similar to that of Theorem \ref{le:opt:number:2}, so we only give a brief description. Without loss of generality, we only need to consider the case where  \( d = 2 \), i.e. $\ma = (\va_1,\va_2,\cdots,\va_m)^\hh\in \H^{m\times 2}$.  According to Theorem \ref{th:equivalent}, one has 
\begin{equation}\label{eq:u:l1} 
	U_{\Psi_\ma}^{\ell_1} = \sup_{\norm{\vu}=1} \norms{\ma\vu}_{2}^2 = \norm{\ma}^2 \ge \frac 12 \normf{\ma}^2
\end{equation}
and
 \begin{eqnarray}\label{eq:llpl1}
	L^{\ell_1}_{\Psi_\ma} =  \inf_{\norm{\vu}=\norm{\vv}=1} \sumim \abs{\real{\vu^\hh\va_i \va_i^\hh\vv}} \le  \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}=0}} \sumim \abs{\real{\vu^\hh\va_i \va_i^\hh\vv}}.
\end{eqnarray}
Using the same notations as in  \eqref{eq:ai} and \eqref{eq:uv}, one has $\normf{\ma}^2=\sumim t_i^2$ and 
\begin{equation}\label{eq:ax ay}
		\real{\vu^\hh\va_i\va_i^\hh\vv} = \frac 12 t_i^2 \xkh{\cos 2\varphi_i \sin 2\theta - \sin 2\varphi_i \cos 2\theta \cos\xkh{\alpha-\beta-\alpha_i+\beta_i}},
\end{equation}
where $(\theta,\alpha,\beta)\in I^\H$ and  $(\varphi_i,\alpha_i,\beta_i)\in I^\H$ for all $i=1,\ldots,m$. Here, $I^\H$ is defined in \eqref{eq:ih}. Putting \eqref{eq:ax ay} into \eqref{eq:llpl1}, we obtain that 
 \begin{equation}\label{eq:m:l1}
	L^{\ell_1}_{\Psi_\ma} \le  \minm{(\theta,\alpha,\beta)\in I^\H} f(\theta, \alpha, \beta)
\end{equation}
where \[f(\theta, \alpha, \beta) := \frac 12 \sum_{i=1}^{m} t_i^2 \abs{\cos 2\varphi_i \sin 2\theta - \sin 2\varphi_i \cos 2\theta \cos\xkh{\alpha-\beta-\alpha_i+\beta_i}}.
\]


For the real case where $\H=\R$,  \( \alpha = \beta = 0 \) and \( \alpha_i = \beta_i = 0 \) for $i = 1,\cdots,m$. Furthermore, one has
\begin{align*}
	\minm{\theta\in [0,2\pi]} f(\theta,0,0) \le \frac{1}{\pi} \int_{0}^{\pi} f(\theta,0,0)\dd\theta = \sumim \frac{t_i^2}{2\pi} \int_{\varphi_i}^{\varphi_i + \pi} \abs{\sin(2\theta - 2\varphi_i)} \dd\theta \\
	\overset{\text(i)}{=} \sumim \frac{t_i^2}{\pi} \int_{\varphi_i}^{\varphi_i + \pitwo} \sin(2\theta - 2\varphi_i) \dd\theta = \frac{1}{\pi} \sum_{i=1}^{m} t_i^2,
\end{align*}
where (i) comes from the fact that  \(\abs{\sin(2\theta - 2\varphi_i)}\) is a periodic function in \(\theta\) with period \(\pitwo\). 

For the complex case where $\H=\C$, the  Poisson formula in surface integrals reveals that 
\[\minm{(\theta, \alpha, \beta)\in I^\C} f(\theta, \alpha, \beta) \le \frac{1}{8\pi} \cdot 2\pi\int_{-1}^{1} \abs{u}\dd u \sum_{i=1}^{m} t_i^2 = \frac{1}{4} \sum_{i=1}^{m} t_i^2.
\]
Putting everything together, we obtain the conclusion 
\begin{align*}
	\betaone_{\Psi_\ma} \ge \frac{U^{\ell_1}_\ma}{L^{\ell_1}_{\Psi_\ma}} \ge \betaonebar.
\end{align*}



\subsection{Proof of Theorem \ref{le:subopt:number:l1}} \label{pf:subopt:number:l1}
Our analysis primarily relies on the following lemma. While \cite[Lemma 3.6]{xiayu2024stability} establishes a lower bound for \(\max_{\theta \in [0,\pi]} \sum_{i=1}^m t_i^2 \left| \sin(\theta - \varphi_i) \right|\), this paper requires an upper bound for \(\min_{\theta \in [0,\pi]} \sum_{i=1}^m t_i^2 \left| \sin(\theta - \varphi_i) \right|\). It is worth noting that the proof of the next lemma is considerably more involved.


\begin{lemma}\label{lemma:sub:tan}
	For any $\varphi_1, \varphi_2, \cdots, \varphi_{m+1} \in \R$ satisfying $0 \le \varphi_1 \le \varphi_2 \le \cdots \le \varphi_m \le \varphi_{m+1} = \pi$, and for all $t_1, t_2, \cdots, t_{m} \in \R$, we have
	 \begin{equation}
		\minm{\theta \in [0,\pi]} \sum_{i = 1}^m t_i^2\abs{\sin\xkh{\theta-\varphi_i}} \le \frac{1}{m\cdot \tan \frac{\pi}{2 m}} \sum_{i = 1}^m t_i^2.
	\end{equation}
\end{lemma}


With Lemma \ref{lemma:sub:tan} in place, we can give a proof of Theorem \ref{le:subopt:number:l1}.


\begin{proof}[Proof of Theorem \ref{le:subopt:number:l1}]
According to \eqref{eq:betaAB}, we only need to consider the case where  \( d = 2 \).  
Similar to \eqref{eq:u:l1} and \eqref{eq:llpl1}, we may assume $\va_i=t_i(\cos\varphi_i,\sin\varphi_i)^\T$ with $t_i=\norm{\va_i}$ and $0\le \varphi_i \le \pi$ for all $i=1,\ldots,m$, and then have that 
\[
U_{\Psi_\ma}^{\ell_1}  \ge \frac12 \sum_{i = 1}^m t_i^2
\]
and 
\[
L^{\ell_1}_{\Psi_\ma}  \le  \inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}=0}} \sumim \abs{\vu^\hh\va_i \va_i^\hh\vv}.
\]
% Note that the condition number $\betaone_{\Psi_\ma}$ is invariant if we switch $\va_i$ to $-\va_i$. Thus, we 
Denote $\vu=(\cos\theta,\sin\theta)^\T$ and $\vv=(\sin\theta,-\cos\theta)^\T$ with $0\le \theta\le \pi$. Then 
\begin{eqnarray*}
\inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}=0}} \sumim \abs{\vu^\hh\va_i \va_i^\hh\vv} =  \minm{\theta\in [0,\pi]} \frac 12 \sum_{i=1}^{m} t_i^2 \abs{\sin(2\theta-2\varphi_i)} =  \minm{\theta\in [0,\pitwo]} \frac 12 \sum_{i=1}^{m} t_i^2 \abs{\sin(2\theta-2\varphi_i)} ,  
\end{eqnarray*}
where the last equality comes from the fact that $\abs{\sin(2\theta-2\varphi_i)}$ has a period of $\pi/2$ for $\theta$ and $\varphi_i$. 
Therefore, apply Lemma \ref{lemma:sub:tan} to obtain that   
\begin{eqnarray*}
	\inf_{\substack{\norm{\vu}=\norm{\vv}=1 \\ \nj{\vu,\vv}=0}} \sumim \abs{\vu^\hh\va_i \va_i^\hh\vv} \le  \frac{1}{2 m\cdot \tan \frac{\pi}{2 m}} \sum_{i = 1}^m t_i^2.  
\end{eqnarray*}  
Combining the above two bounds, we conclude
 \[\betaone_{\Psi_\ma} \ge \frac{U_\ma^{\ell_1}}{L^{\ell_1}_{\Psi_\ma} }  \ge m\tan \frac{\pi}{2 m}.\]
\end{proof}




Finally, we give the proof of Lemma \ref{lemma:sub:tan}.


\begin{proof}[Proof of Lemma \ref{lemma:sub:tan}]
	For the sake of simplicity, we take $g(\theta) := \sumim t_i^2 \abs{\sin\xkh{\theta-\varphi_i}}$.  For each $1\le k\le m$, when $\theta\in\zkh{\varphi_k,\varphi_{k+1}}$, it holds
	\[
	g(\theta) =\sum_i^k t_i^2 \sin\xkh{\theta-\varphi_i} - \sum_{i = k+1}^m t_i^2 \sin\xkh{\theta-\varphi_i} :=g_k(\theta) .
	\]
	For each $1\le k\le m$, there exists $\theta_k\in\zkh{0,\pi}$ and $\rk \ge 0$ such that 
		 \begin{equation}
		g_k(\theta)  = r_k \sin\xkh{\theta-\theta_k}.
	\end{equation}
%	\begin{align*}
%		\cos\theta_k &= \frac{1}{\rk}\cdot\xkh{\sum_i^k t_i^2 \cos\varphi_i - \sum_{i = k+1}^m t_i^2 \cos\varphi_i}, \\
%		\sin\theta_k &= \frac{1}{\rk}\cdot\xkh{\sum_i^k t_i^2 \sin\varphi_i - \sum_{i = k+1}^m t_i^2 \sin\varphi_i}, \\
%		\rk^2 \quad &= \xkh{\sum_i^k t_i^2 \cos\varphi_i - \sum_{i = k+1}^m t_i^2 \cos\varphi_i}^2 + \xkh{\sum_i^k t_i^2 \sin\varphi_i - \sum_{i = k+1}^m t_i^2 \sin\varphi_i}^2.
%	\end{align*}
%	The introduction of the functions $\dkh{g_k}$ aims to eliminate the absolute value $\abs{\sin\xkh{\theta-\varphi_k}}$ in $g(\theta)$. 
	Therefore, one has 
	\begin{align*}
		\int_{\phik}^{\phikk} g(\theta) \dd \theta &= \int_{\phik}^{\phikk} \rk\sin\xkh{\theta - \thetak} \dd \theta \\
		&= \rk\cdot\xkh{\cos\xkh{\phik-\thetak}-\cos\xkh{\phikk-\thetak}}\\
		&= 2\cdot \rk\cdot \sin\xkh{\frac{\phik+\phikk}{2}-\thetak} \sin\xkh{\frac{\phikk-\phik}{2}} \\
		&= 2 \gk\xkh{\frac{\phik+\phikk}{2}} \sin\xkh{\frac{\phikk-\phik}{2}} 
	\end{align*}
	due to $\phik \le \frac{\phik+\phikk}{2} \le \phikk$. We claim that the following holds: 
	\begin{equation}\label{claim:g middle}
		\gk\xkh{\frac{\phik+\phikk}{2}} \cos\xkh{\frac{\phikk-\phik}{2}} \ge \minm{\theta\in\zeropi} g(\theta)
	\end{equation}
	for each $k = 1,\cdots,m$.  We next divide the proof into two cases. 
	\begin{itemize}
		\item For all \(1 \le k \le m\), it holds \(\frac{\varphi_{k+1}-\varphi_k}{2} < \frac{\pi}{2}\). Then we have 
		\begin{align*}
			\sumim t_i^2 &= \frac 12 \int_0^\pi g(\theta) \dd\theta = \frac 12 \sumkm \int_{\phik}^{\phikk} g(\theta) \dd\theta \\
			&= \sumkm \gk\xkh{\frac{\phik+\phikk}{2}} \cos\xkh{\frac{\phikk-\phik}{2}} \tan\xkh{\frac{\phikk-\phik}{2}} \\
			&\ge \minm{\theta\in\zeropi} g(\theta) \cdot \sumkm \tan\xkh{\frac{\phikk-\phik}{2}} \\
			&\stackrel{\mbox{(i)}}{\ge} \minm{\theta\in\zeropi} g(\theta) \cdot m \cdot \tan\xkh{\sumim\frac{\phikk-\phik}{2m}} = \minm{\theta\in\zeropi} g(\theta) \cdot m \tan \frac{\pi}{2m} ,
		\end{align*}
		where (i) comes from Jensen's inequality due to the fact that \(\tan x\) is a convex function on \([0, \frac{\pi}{2})\).  We arrive at the conclusion for this case.

		\item There exists a \(k \) such that \(\frac{\varphi_{k+1}-\varphi_k}{2} = \frac{\pi}{2}\), i.e., \(\varphi_{k+1}-\varphi_k = \pi\).  For this case, we have \(\varphi_j = 0\) for all $j \le k$ and \(\varphi_j = \pi \)  for all $j \ge k+1$.
Thus, one can conclude that \begin{equation*}
			\minm{\theta \in [0,\pi]} g(\theta) = \minm{\theta \in [0,\pi]} \sum_{i = 1}^m t_i^2 \abs{\sin\xkh{\theta}} = 0.
		\end{equation*}
This implies the conclusion of Lemma \ref{lemma:sub:tan} holds trivially  for \(m\ge 2\).
	\end{itemize}


	Finally, it remains to prove the claim \eqref{claim:g middle}. For any fixed $k\in\dkh{1,\cdots,m}$,  note that $g(\theta) = \gk (\theta) = \rk \sin\xkh{\theta-\thetak} \ne 0$ when $\theta\in\xkh{\phik,\phikk}$. Therefore, \(g\xkh{\theta}\) is either monotonic on the interval $\zkh{\phik,\phikk}$, or it first increases and then decreases on $\zkh{\phik,\phikk}$. For convenience, we define $\alpha_k=\phik-\thetak$ and $\alpha_{k+1}=\phikk-\thetak$.  Observe that when $\theta\in\zkh{\varphi_k,\varphi_{k+1}}$, it holds $g_k(\theta)=\rk\sin\xkh{\theta-\thetak}=g(\theta) \ge 0$. It means that 
 $0\le \alphak\le\alphakk\le\pi$.  Our proof then divides into the following three cases:

	{\bf Case 1: $g(\theta)$ is monotonically increasing on $\zkh{\phik,\phikk}$.} For this case, one has $0\le \alphak\le\alphakk\le\frac{\pi}{2}$. Therefore,  
	 \begin{align*}
		\minm{\theta\in\zeropi} g(\theta) &\le \minm{\theta\in\zkh{\phik,\phikk}} g(\theta) = \rk \sin\xkh{\alphak} 
		= \rk \sin\xkh{\frac{\alphakk+\alphak}{2} - \frac{\alphakk-\alphak}{2}} \\
		&= \rk \xkh{\sin \frac{\alphakk+\alphak}{2} \cos \frac{\alphakk-\alphak}{2} - \cos \frac{\alphakk+\alphak}{2} \sin \frac{\alphakk-\alphak}{2}}\\
		&\le \rk \sin \frac{\alphakk+\alphak}{2} \cos \frac{\alphakk-\alphak}{2} = \gk \xkh{\frac{\alphakk+\alphak}{2}} \cos \frac{\alphakk-\alphak}{2}
	\end{align*}
	where the last inequality holds due to $\rk\ge 0$ and the fact that 
	\begin{equation*}\label{ineq:case 1}
		\cos\frac{\alphakk+\alphak}{2} \sin\frac{\alphakk+\alphak}{2}\ge 0.
	\end{equation*}


	{\bf Case 2: $g(\theta)$ is monotonically decreasing on $\zkh{\phik,\phikk}$.} This implies that $\frac{\pi}{2}\le \alphak\le\alphakk\le\pi$ and \begin{equation*}
		\cos\frac{\alphakk+\alphak}{2} \sin\frac{\alphakk+\alphak}{2}\le 0.
	\end{equation*}
	Therefore, we obtain that \begin{align*}
		\minm{\theta\in\zeropi} g(\theta) &\le \minm{\theta\in\zkh{\phik,\phikk}} g(\theta) = \rk \sin\xkh{\alphakk} 
		= \rk \sin\xkh{\frac{\alphakk+\alphak}{2} + \frac{\alphakk-\alphak}{2}} \\
		&= \rk \xkh{\sin \frac{\alphakk+\alphak}{2} \cos \frac{\alphakk-\alphak}{2} + \cos \frac{\alphakk+\alphak}{2} \sin \frac{\alphakk-\alphak}{2}}\\
		&\le \rk \sin \frac{\alphakk+\alphak}{2} \cos \frac{\alphakk-\alphak}{2} = \gk \xkh{\frac{\alphakk+\alphak}{2}} \cos \frac{\alphakk-\alphak}{2}.
	\end{align*}

	{\bf Case 3: $g(\theta)$ is increasing first and then decreasing on $\zkh{\phik,\phikk}$.} If the minimum value on $\zkh{\phik,\phikk}$ is attained at \(\phik\), one can see that  \(\frac{\pi}{2}-\alphak \ge \alphakk-\frac{\pi}{2}\); it implies that $\cos\frac{\alphakk+\alphak}{2} \sin\frac{\alphakk+\alphak}{2}\ge 0$, and the remaining proof details are similar to those of Case 1. Otherwise,  if the minimum value on this interval is attained at \(\phikk\), it indicates \(\frac{\pi}{2}-\alphak \le \alphakk-\frac{\pi}{2}\) and $\cos\frac{\alphakk+\alphak}{2} \sin\frac{\alphakk+\alphak}{2}\le 0$, and the remaining proof is then similar to Case 2.

	This completes the proof. % of claim \eqref{claim:g middle}.
\end{proof}



\subsection{Proof of Theorem \ref{le:em:l1}} \label{pf:em:l1}
For the harmonic frame \( \mem \) defined in \eqref{def:mem}, one can check that  \(\mem^\T\mem = \frac m2 \mi\). Denote \(\mem = (\va_1, \va_2, \cdots, \va_m)^T \in \R^{m\times 2}\). Then the upper Lipschitz constant 
\[U_\mem^{\ell_1} = \sup_{\norm{\vu}=1} \norms{\ma\vu}_{2}^2 = \norm{\mem} = \frac m2. \] 
On the other hand, Lemma \ref{le:ortho:l - em:p=1} reveals that \begin{equation*}
	L_\mem^{\ell_1} = \inf_{\norm{\vu}=\norm{\vv}=1} \sum_{j=1}^m \ucabs{\vu^\T\va_j \va_j^\T\vv} = \left\{\begin{aligned}
		&\frac{\cos \frac{\pi}{2 m}}{2\tan \frac{\pi}{2 m}},   \quad \mbox{if}\ m\ \mbox{is odd},\\
		&\ \frac{1}{ \tan \frac{\pi}{m}},                  \ \ \quad \mbox{if}\ m\ \mbox{is even}.
	\end{aligned}\right.
\end{equation*}
As a result, we obtain the conclusion  that 
\begin{equation*}
	\betaone_{\mem} = \frac{U_\mem^{\ell_1}}{L_\mem^{\ell_1}} = \left\{\begin{aligned}
		& m \frac{\tan \pimtwo}{\cos \pimtwo},   \quad \mbox{if}\ m\ \mbox{is odd},\\
		& \frac m2 \tan \frac{\pi}{m},           \quad \mbox{if}\ m\ \mbox{is even}.
	\end{aligned}\right.
\end{equation*}



\subsection{Proof of Theorem \ref{le:concent:p=1}} \label{pf:concent:p=1}
Given the extensive research on the concentration properties of Gaussian matrices, we directly present several essential lemmas.


\begin{lemma} \cite{candes2013phaselift, fourcart2013} \label{le:u:p=1}
	Assume that $\ma\in\H^d$ is a standard Gaussian matrix with $\H=\R$ or $\C$. Then for any $ 0 < \delta < 1 $, with probability at least $1-2\exp(-c_2 d)$, one has \begin{equation}
		(1-\delta)\norm{\vu}^2 \le \frac 1m \norm{\ma\vu}^2 \le (1+\delta)\norm{\vu}^2
	\end{equation}
	simultaneously for all $\vu\in\H^d$ provided that $m\gtrsim\delta^{-2} d$. Here, $c_2 > 0$ is a universal constant. 
\end{lemma}

\begin{lemma}\label{le:l-concent:p=1}
	Assume that $\ma\in\H^d$ is a standard Gaussian matrix with $\H=\R$ or $\C$, and $m\gtrsim\log(1/\delta) \delta^{-2} d$. Then for any $ 0 < \delta < 0.5 $, with probability exceeding $1-4\exp(-c_3 d)$ for some universal constant $c_3>0$, one has \begin{equation}
		\frac 1m \sum_{j=1}^{m} \abs{\real{\vu^\hh\va_j\va_j^\hh \vv}} \ge \E\abs{\real{\vu^\hh\va_1\va_1^\hh \vv}} - \delta 
	\end{equation}
 for all $\vu,\vv\in\SSS_\H^{d-1}$. 
\end{lemma}
\begin{proof}
The proof is similar to that in \cite[Appendix B.1]{xiayu2024stability} and is therefore omitted.
\end{proof}


With the above two lemmas in hand, we are now ready to prove Lemma \ref{le:concent:p=1}.


\begin{proof}[Proof of Lemma \ref{le:concent:p=1}]
According to Lemma \ref{le:u:p=1}, for any $ 0 < \delta < 1$, it holds with probability at least $1-2\exp(-c_2 d)$ that 
 \[\frac 1m U_{\Psi_\ma}^{\ell_1} = \sup_{\norm{\vu}=1} \frac1m\norms{\ma\vu}_{2}^2 \le 1 + \delta,
 \]
 provided $m\ge C_0\log(1/\delta) \delta^{-2} d$ for some  universal constant  $C_0>0$.  Lemma \ref{le:l-concent:p=1} reveals that when $m\ge C_0\log(1/\delta) \delta^{-2} d$, with probability exceeding $1-4\exp(-c_0 d)$, 
\[\frac 1m L_\ma^{\ell_1} = \inf_{\norm{\vu}=\norm{\vv}=1} \frac 1m \sum_{j=1}^{m} \abs{\real{\vu^\hh\va_j\va_j^\hh \vv}} \ge \inf_{\norm{\vu}=\norm{\vv}=1} \E\abs{\real{\vu^\hh\va_1\va_1^\hh \vv}} - \delta.
\]
Here, $c_3>0$ is a universal constant. Combining the two bounds together with Lemma \ref{le:l-e:p=1}, we obtain that for any $0<\delta<0.2$,  with probability exceeding $1-6\exp(-c_0 d)$, it holds
 \begin{align*}
	\betaone_{\Psi_\ma}=\frac{U_\ma^{\ell_1}}{L_\ma^{\ell_1}} \le \left\{\begin{aligned}
		&\frac \pi2+5\delta,   \quad \mbox{if }\ \H = \R, \\
		& \hspace{0.15em}2\, + 5\delta,     \quad \mbox{if }\ \H = \C,
	\end{aligned}\right. 
\end{align*}
where the inequality follows from the fact that $\frac{1+\delta}{t-\delta}\le\frac 1t +10\delta$ for any $t > 0.5$ and $0<\delta<0.2$, and  $c_0>0$ is a  universal constant. Finally, noting that the lower Lipchitz bound is given in Lemma \ref{le:opt:number:l1}, we complete the proof.
\end{proof}




