\begin{lemma}\label{le:l-e:p=1}
	For a standard Gaussian random vector \(\va\in\H^d\) defined as \eqref{def:gauss}, one has 
	\begin{align*}
		\inf_{\substack{\vu, \vv\in\SSS_{\H}^{d-1} \\ \nj{\vu,\vv}\in\R}}\E\abs{\real{\vu^\hh\va\va^\hh\vv}} = \left\{\begin{aligned}
			&\frac 2\pi,  & \mbox{if }\; \H = \R, \\
			&\frac 12,    & \mbox{if }\; \H = \C.
		\end{aligned}\right. 
	\end{align*}
\end{lemma}
\begin{proof}
Note that $\E\abs{\real{\vu^\hh\va\va^\hh\vv}}$ is unchanged if we multiply $\vu$ or $\vv$ by $-1$. Therefore, without loss of generality we can assume that \(\nj{\vu,\vv}\ge 0\).
	Due to the rotational invariance of the Gaussian random vector, we assume that  \(\vx=\zkh{1,0,\cdots,0}^\T\) and \(\vx=\zkh{\cos\theta,\sin\theta,0,\cdots,0}^\T\), where \(\cos\theta=\nj{\vu,\vv}\) and \(\theta\in[0,\pi/2]\). Next, we divide the proof into two cases.

	{\bf Case 1: $\H = \R$.} A direct calculation gives (see, e.g. \cite[Lemma 4.7]{xiayu2024stability})
\[
\E\abs{\vu^\hh\va\va^\hh\vv}  =\frac 2\pi(\sin\theta+(\frac \pi2-\theta)\cos\theta):=p(\theta).
\]
One can check that $p(\theta)$ is a decreasing function over $\theta\in[0,\pi/2]$. Thus, 
\[
\inf_{ \vu, \vv \in\SSS_{\R}^{d-1}} \E\abs{\vu^\hh\va\va^\hh\vv} = \frac 2\pi .
\]

	{\bf Case 2: $\H = \C$.} Denote the first two entries of $\va$ as $\frac a\sqrttwo$ and $\frac b\sqrttwo$. Here, $a = a_1+a_2\i$ and $b = b_1+b_2\i$, so one has $a_1,a_2,b_1,b_2\sim\mathcal{N} (0,1)$. Then, we have
	\begin{align*}
		h(\theta)&:=\E\abs{\real{\vu^\hh\va\va^\hh\vv}} = \frac 12\E \abs{\real{a(\bar{a}\cos \theta+\bar{b}\sin\theta)}} \\
		&= \frac 12\E\xkh{\abs{\xkh{a_1^2 + a_2^2}\cos\theta + \xkh{a_1b_1 + a_2b_2}\sin\theta}} \\
		&= \frac 12\int_{-\infty}^{\infty}\int_{-\infty}^{\infty}\int_{-\infty}^{\infty}\int_{-\infty}^{\infty} \frac{1}{4\pi^2} f_1(a_1,a_2,b_1,b_2,\theta) \e^{-(a_1^2+a_2^2+b_1^2+b_2^2)/2}\dd a_1\dd a_2\dd b_1\dd b_2
	\end{align*}
	where \[f_1(a_1,a_2,b_1,b_2,\theta) = \abs{\xkh{a_1^2 + a_2^2}\cos\theta + \xkh{a_1b_1 + a_2b_2}\sin\theta}.\]
	We claim that
	 \begin{equation} \label{cla:htheta}
	h(\theta) = \frac{3+\cos2\theta}4.
	\end{equation}
	The conclusion then holds immediately by noting that 
	 \[h(\theta) \ge h(\frac \pi 2) = \frac 12.\]
It remains to prove the claim \eqref{cla:htheta}. Taking the polar coordinates transformations that $a_1 = \rho\cos\phi_1\cos\phi_2, a_2 = \rho\cos\phi_1\sin\phi_2, b_1 = \rho\sin\phi_1\cos\phi_3$ and $b_2 = \rho\sin\phi_1\sin\phi_3$, where $\rho\in [0,+\infty)$, $\phi_1\in[0,\frac \pi2)$, $\phi_2,\phi_3\in[0,2\pi)$ and $\dd a_1\dd a_2\dd b_1\dd b_2 = \rho^3\cos\phi_1\sin\phi_1 \cdot \dd \rho\dd \phi_1\dd \phi_2\dd \phi_3$,  then $h(\theta)$ can be written as 
	\begin{align*}
		h(\theta) &= \frac{1}{8\pi^2} \int_{0}^{\infty}\int_{0}^{\frac \pi2}\int_{0}^{2\pi}\int_{0}^{2\pi} \rho^5\e^{-\frac{\rho^2}{2}} \cos \phi_1\sin\phi_1 f_2(\phi_1,\phi_2,\phi_3,\theta) \cdot \dd \rho\dd \phi_1\dd \phi_2\dd \phi_3 \\
		&= \frac{1}{\pi^2} \int_{0}^{\frac \pi2}\int_{0}^{2\pi}\int_{0}^{2\pi} \cos \phi_1\sin\phi_1 f_2(\phi_1,\phi_2,\phi_3,\theta) \cdot \dd \phi_1\dd \phi_2\dd \phi_3 \\
		&=  \frac{1}{\pi} \int_{0}^{\frac \pi2}\int_{0}^{2\pi} \cos \phi_1\sin\phi_1 \abs{\cos\theta + \cos 2\phi_1 \cos\theta + \sin 2\phi_1\cos \phi_2 \sin\theta} \cdot \dd \phi_1\dd \phi_2,
	\end{align*}
	where \begin{align*}
		f_2(\phi_1,\phi_2,\phi_3,\theta) = \frac12 \abs{\cos\theta + \cos 2\phi_1 \cos\theta + \sin 2\phi_1\cos(\phi_2-\phi_3)\sin\theta},
	\end{align*}
	and the last equality comes from the fact that $f_2(\phi_1,\phi_2,\phi_3,\theta)$ is a periodic function with a period of $2\pi$ for $\phi_3$. Setting $x = \cos2\phi_1, y = \sin 2\phi_1\cos\phi_2, z = \sin 2\phi_1\sin \phi_2$ and denoting 
	$\vx = \xkh{x,y,z}^\T \in\SSS^2$, $\ve = \xkh{\cos\theta,\sin\theta,0}^\T \in\SSS^2$ with $\SSS^2 = \dkh{(x, y, z)^\T \in \R^3:x^2 + y^2 + z^2 = 1}$, one has
	\begin{align} 
		h(\theta) &= \frac{1}{4\pi} \iint_{\SSS^2}\abs{\cos\theta + x\cos\theta + y\sin\theta}\dd S= \frac{1}{4\pi} \iint_{\SSS^2}\abs{\cos\theta + \nj{\vx,\ve}}\dd S \notag \\
		&= \frac{1}{4\pi} \iint_{\SSS^2}\abs{\cos\theta + \nj{\mpm\vx,\ve}}\dd S= \frac{1}{4\pi} \iint_{\SSS^2}\abs{\cos\theta + x}\dd S, \label{eq:hds}
	\end{align}
	where $\mpm$ is a  rotation matrix defined as
	 \begin{align*}
		\mpm = \begin{bmatrix}
			\cos\theta & \sin\theta &0\\
			-\sin\theta & \cos\theta &0\\
			0          &0           &1
		\end{bmatrix}.
	\end{align*}
	Finally, to compute the surface integral in \eqref{eq:hds}, we take  another  polar transformation that by setting  $x = \cos \phi_4, y = \sin \phi_4\cos\phi_5, z = \sin \phi_4\sin \phi_5$ for \(\phi_4\in [0, \pi), \phi_5\in [0, 2\pi)\), which reveals that \begin{align*}
		h(\theta) = \frac{1}{4\pi} \int_{0}^{2\pi}\dd \phi_5 \int_{0}^{\pi} \sin\phi_4 \abs{\cos\phi_4 + \cos\theta} \cdot \dd \phi_4 = \frac{3+\cos 2\theta}{4}.
	\end{align*}
This completes the proof. % of the claim \eqref{cla:htheta}.
\end{proof}

