\section{Appendix B: Proof of Lemma \ref{le:ortho:l - em:p=1}}\label{pf:ortho:l - em:p=1}
Setting $\vx = (\cos \theta \ \sin \theta)^\T$ and $\vy = (\cos \psi \ \sin \psi)^\T$ with $0 \le \theta, \psi \le 2\pi$, a little algebra reveals
\begin{align*}
	\mem\vx =& \begin{pmatrix}
		\cos \xkh{0-\theta} \ 
		\cos \xkh{\frac{\pi}{m}-\theta} \ 
		\cdots \ 
		\cos \xkh{\frac{(m-1)\pi}{m}-\theta} 
	\end{pmatrix}^\T, \\
	\mem\vy =& \begin{pmatrix}
		\cos \xkh{0-\psi} \ 
		\cos \xkh{\frac{\pi}{m}-\psi} \ 
		\cdots \ 
		\cos \xkh{\frac{(m-1)\pi}{m}-\psi} 
	\end{pmatrix}^\T, 
\end{align*}
for $\mem = (\va_1,\va_2,\cdots,\va_m)^\T$ defined in \eqref{def:mem}. It gives  
\[\sum_{j=1}^m \ucabs{\vy^\T\va_j \va_j^\T\vx} = \sum_{j=1}^{m} \ucabs{\cos(\frac{j\pi}{m} - \theta) \cos(\frac{j\pi}{m} - \psi)} =: G(\theta,\psi).\]
Note that \(G(\theta,\psi) = G(\psi,\theta)\), \(G(\theta, \psi) = G(\theta-\pi, \psi) = G(\theta+\pi, \psi)\), and \(G(\theta, \psi) = G(\theta+\frac{\pi}{m}, \psi+\frac{\pi}{m})\). 
Without loss of generality, one assumes \(0 \le \theta \le \psi \le \pi\). 
We next claim that \begin{equation}\label{claim:em:1} 
	\minm{0\le \theta, \psi \le \pi} G(\theta, \psi)  =  \minm{\substack{\theta\in[0, \pim] \\ \phi \in [\theta, \theta+\pim]}} G(\theta, \phi+\pitwo). 
\end{equation}
To calculate \(G(\theta, \phi+\pitwo)\), we divide the interval \([\pitwo, \pi]\) into segments of length \(\pim\) and separately discuss the scenario \(\psi\) within each subinterval.  
For \(\theta\in[0, \pim]\) and \(m\ge 3\), take \(\phi \in [0, \pim]\) and denote \begin{equation*}
	G_k(\theta, \phi) := G(\theta, \phi+\pitwo+k\pim) = \sum_{j=1}^{m} \ucabs{\cos(\frac{j\pi}{m} - \theta) \sin(\frac{j\pi}{m} - \phi - k\pim)}
\end{equation*}
where \(k\) is an integer with \(0\le k \le \hat{k}\) and \begin{equation}\label{eq:khat}
	\hat{k} = \left\{\begin{aligned}
		\frac{m-2}{2},    &\quad \mbox{if}\ m\ \mbox{is even},\\ 
		\frac{m-1}{2},    &\quad \mbox{if}\ m\ \mbox{is odd and } \phi \in [0, \pimtwo],\\ 
		\frac{m-3}{2},    &\quad \mbox{if}\ m\ \mbox{is odd and } \phi \in [\pimtwo, \pim].\\ 
	\end{aligned}\right.
\end{equation}
Then one claims that \begin{equation}\label{eq:gl}
	G_k(\theta, \phi) = \left\{\begin{aligned}
		&\frac{\cos\kpim \cos(\pim - \theta - \phi)}{\sin\pim} + k\sin(\phi-\theta+\kpim) \hspace{6em}  \mbox{ if}\ m\ \mbox{is even},\\ 
		&\frac{\cos(\pimtwo + \kpim) \cos(\frac{\pi}{2m} - \theta - \phi)}{\sin\pim} + \frac{2k+1}{2}\sin(\phi-\theta+\kpim) \mbox{ if}\ m\ \mbox{is odd and } \theta \in [0, \pimtwo],\\ 
		&\frac{\cos(\pimtwo - \kpim) \cos(\frac{3\pi}{2m} - \theta - \phi)}{\sin\pim} + \frac{2k-1}{2}\sin(\phi-\theta+\kpim) \mbox{ if}\ m\ \mbox{is odd and } \theta \in [\pimtwo, \pim].\\ 
	\end{aligned}\right.
\end{equation}

Below, we provide a proof for the conclusion (b) of Lemma \ref{le:ortho:l - em:p=1}. 
To establish the minimum of  \(G(\theta, \phi+\pitwo)\) for \(\theta\in[0, \pim]\) and $\phi \in [\theta, \theta+\pim]$, we divide \(\phi\in[\theta, \theta+\pim]\) into the two cases \([\theta, \pim]\) and \([\pim, \theta+\pim]\) for discussion. 
\begin{itemize}
	\item When \(\phi\in[\theta, \pim]\), we consider \(G_0(\theta, \phi)\). 
	If $m$ is even, \begin{equation*}
		G_0(\theta, \phi) = \frac{\cos(\pim - \theta - \phi)}{\sin\pim} \ge \frac{\cos\pim}{\sin\pim}
	\end{equation*}
	where the inequality holds if and only if \(\theta + \phi = 0\) or \(\frac{2\pi}{m}\), i.e., \(\theta = \phi = 0\) or \(\theta = \phi = \pim\). If $m$ is odd, one has \begin{equation*}
		G_0(\theta, \phi) = \left\{\begin{aligned}
			&\frac{\cos\theta \cos(\frac{\pi}{2m} - \phi) + \sin(\pimtwo - \theta) \sin\phi}{2\sin\pimtwo},  \ \hspace{5.5em} \mbox{ if}\  \theta \in [0, \pimtwo],\\
			&\frac{\cos(\theta-\pim) \cos(\phi - \frac{\pi}{2m}) + \sin(\theta - \pimtwo) \sin(\pim - \phi)}{2\sin\pimtwo},  \ \mbox{ if}\  \theta \in [\pimtwo, \pim].\\
		\end{aligned}\right.
	\end{equation*}
	For any $\phi \in [0, \pim]$, one sees $\cos\theta$ and $\sin(\pimtwo - \theta)$ are monotonically decreasing on $[0, \pimtwo]$, while $\cos(\theta-\pim)$ and $\sin(\theta - \pimtwo)$ are monotonically increasing on $[\pimtwo, \pim]$. As a result, \begin{equation*}
		G_0(\theta, \phi) \ge G_0(\pimtwo, \phi) = \frac{\cos\pimtwo \cos(\frac{\pi}{2m} - \phi)}{2\sin\pimtwo} \ge \frac{\cos^2\pimtwo}{2\sin\pimtwo} = G_0(\pimtwo, \pim)
	\end{equation*}
	for an odd $m\ge 3$. 



	\item When \(\phi\in[\pim, \theta+\pim]\), we consider \(G_1(\theta, \phi-\pim)\). It is easy to check that \begin{align*}
		G_1(\theta, \phi-\pim) = \frac{\cos\theta \cos(\phi - \pim) + \sin(\frac{2\pi}{m} - \theta) \sin(\phi - \pim)}{\sin\pim} \\
		\ge G_1(\pim, \phi-\pim) = \frac{\cos(\frac{2\pi}{m} - \phi)}{\sin\pim} \ge G_1(\pim, \pim) = \frac{\cos\pim}{\sin\pim} 
	\end{align*}
	with an even \(m\). Similarly, if \(m\) is odd and \(\theta \in [0, \pimtwo]\), one has \begin{align*}
		G_1(\theta, \phi-\pim) = \frac{2\sin(\frac{2\pi}{m}-\theta) \sin(\phi-\pim) + 2\cos(\theta+\pimtwo) \cos(\phi-\pimtwo) + \sin\pim \sin(\phi - \theta)}{2\sin\pim}  \\
		\ge G_1(\pimtwo, \phi-\pim) = \frac{2\cos\pimtwo \cos(\frac{2\pi}{m} - \phi) + \sin\pim \sin(\phi - \pimtwo)}{2\sin\pim} 
		\ge G_1(\pimtwo, 0) = \frac{\cos^2\pimtwo}{2\sin\pimtwo}.
	\end{align*}
	In addition, if \(m\) is odd and \(\theta \in [\pimtwo, \pim]\), we have \begin{align*}
		G_1(\theta, \phi-\pim) = \frac{\cos(\pim-\theta) \cos(\frac{3\pi}{2m} - \phi) + \sin(\frac{3\pi}{2m} - \theta) \sin(\phi-\pim)}{2\sin\pimtwo}  \\
		\ge G_1(\theta, 0) = \frac{\cos(\pim-\theta) \cos\pimtwo}{2\sin\pimtwo} 
		\ge G_1(\pimtwo, 0) = \frac{\cos^2\pimtwo}{2\sin\pimtwo}.
	\end{align*}
\end{itemize}
In short, one has \begin{equation}\label{claim:em:2} 
	\minm{\substack{\theta\in[0, \pim] \\ \phi \in [\theta, \theta+\pim]}} G(\theta, \phi+\pitwo) = \left\{\begin{aligned}
		&\ \frac{\cos\pim}{\sin\pim},     \hspace{1.6em} \mbox{ if}\ m\ \mbox{is even},\\
		&\frac{\cos^2\pimtwo}{2\sin\pimtwo},  \quad \mbox{ if}\ m\ \mbox{is odd}.\\
	\end{aligned}\right.
\end{equation}
Substituting \eqref{claim:em:2} into \eqref{claim:em:1} gives the conclusion \eqref{eq:ortho:2}. 

Next, we consider the conclusion \eqref{eq:ortho:1} of Lemma \ref{le:ortho:l - em:p=1}. 
Without loss of generality, the condition \(\vu \perp \vv\) implies \(\theta = \phi\), i.e., \(\sumjm \ucabs{\vu^\T\va_j \va_j^\T\vv} = G(\theta, \theta+\pitwo)\). 
Therefore, from \eqref{claim:em:1}, it is easy to see that \begin{equation}\label{claim:em:3}
	\minm{0\le \theta \le \pi} G(\theta, \theta+\pitwo)  =  \minm{\theta\in[0, \pim]} G(\theta, \theta+\pitwo) = \minm{\theta\in[0, \pim]} G_0(\theta, \theta). 
\end{equation}
For an even \(m\), take \(\phi = \theta\) into \eqref{eq:gl} to obtain \begin{equation}\label{claim:em:4}
	G_0(\theta, \theta) = \frac{\cos(\pim - 2\theta)}{\sin\pim} \ge \frac{\cos\pim}{\sin\pim}
\end{equation}
with the proviso that \(\theta \in [0, \pim]\). For an odd \(m\), one has \begin{equation*}
	G_0(\theta, \theta) = \left\{\begin{aligned}
		&\frac{\cos(\frac{ \pi}{2m} - 2\theta)}{2\sin\pimtwo},   \quad \mbox{ if}\  \theta \in [0, \pimtwo],\\
		&\frac{\cos(\frac{3\pi}{2m} - 2\theta)}{2\sin\pimtwo},   \quad \mbox{ if}\  \theta \in [\pimtwo, \pim],\\
	\end{aligned}\right.
\end{equation*}
which leads to \begin{equation}\label{claim:em:5}
	G_0(\theta, \theta) \ge \frac{\cos\pimtwo}{2\sin\pimtwo}.
\end{equation}
Clearly, \eqref{claim:em:3}-\eqref{claim:em:5} constitute the conclusion \eqref{eq:ortho:1} of Lemma \ref{le:ortho:l - em:p=1}. \\
{\bf Proof of Claim \eqref{eq:gl}.}  
% Therefore, the sequence \(\{G_k(\theta,\phi)\}_{k=1}^{\hat{k}}\) covers the intervals \([a, b]\).  
Recall that \begin{equation*}
	G_k(\theta, \phi) = \sum_{j=1}^{m} \ucabs{\cos(\frac{j\pi}{m} - \theta) \sin(\frac{j\pi}{m} - \phi - k\pim)}. 
\end{equation*}
Here and below, for convenience, we denote \[\tau_j^k := \cos(\frac{j\pi}{m} - \theta) \sin(\frac{j\pi}{m} - \phi - k\pim) = \frac 12 \zkh{\sin(\frac{2j\pi}{m}-\theta-\phi-\kpim)-\sin(\phi + \kpim-\theta)}.\] 
To check \(G_k(\theta, \phi)\), we divide our proof into the following two cases:

\begin{itemize}
	\item $m$ is even with $m\ge 4$. It is easy to examine \begin{align*}
		\cos(\frac{j\pi}{m}-\theta) &\ge 0 \quad \mbox{ for } 1 \le j\le \frac{m}{2}, \\
		\cos(\frac{j\pi}{m}-\theta) &\le 0 \quad \mbox{ for } \frac{m}{2} + 1 \le j \le m, \\
		\sin(\frac{j\pi}{m} - \phi - \kpim) &\ge 0 \quad \mbox{ for } k + 1 \le j\le m, \\
		\sin(\frac{j\pi}{m} - \phi - \kpim) &\le 0 \quad \mbox{ for } 1 \le j\le k .
	\end{align*}
	As a result, \begin{align*}
		G_k(\theta, \phi) =& -\sum_{j=1}^{k} \tjk + \sum_{j=k+1}^{\frac m2} \tjk - \sum_{j=\frac m2 + 1}^{m} \tjk \\
		%=& (-\sum_{j=1}^{m} + 2\sum_{j=k+1}^{\frac m2}) \frac 12 \zkh{\sin(\frac{2j\pi}{m}-\theta-\phi-\kpim)-\sin(\phi + \kpim-\theta)}\\
		=& (-\sum_{j=1}^{m} + 2\sum_{j=k+1}^{\frac m2}) \frac 12 \zkh{\sin(\frac{2j\pi}{m}-\theta-\phi)\cos(\kpim)-\cos(\frac{2j\pi}{m}-\theta-\phi)\sin(\kpim)} \\
		&+ k\sin(\phi-\theta+\kpim) \\
		\stackrel{\mbox{(i)}}{=}& \frac{\cos\kpim \cos(\pim - \theta - \phi)}{\sin\pim} + k\sin(\phi-\theta+\kpim). 
	\end{align*}
	where (i) comes from \eqref{eq:Lind} by the Lagrange's trigonometric identities.  

	\item $m$ is odd with $m\ge 3$. One can see that \begin{align*}
		\cos(\frac{j\pi}{m}-\theta) &\ge 0 \quad \mbox{ for } 1 \le j\le \frac{m-1}{2} \mbox{ if } \theta\in[0, \pimtwo], \\
		\cos(\frac{j\pi}{m}-\theta) &\le 0 \quad \mbox{ for } \frac{m+1}{2} \le j \le m \mbox{ if } \theta\in[0, \pimtwo], \\
		\cos(\frac{j\pi}{m}-\theta) &\ge 0 \quad \mbox{ for } 1 \le j\le \frac{m+1}{2} \mbox{ if } \theta\in[\pimtwo, \pim], \\
		\cos(\frac{j\pi}{m}-\theta) &\le 0 \quad \mbox{ for } \frac{m+3}{2} \le j \le m \mbox{ if } \theta\in[\pimtwo, \pim], \\
		\sin(\frac{j\pi}{m} - \phi - \kpim) &\ge 0 \quad \mbox{ for } k + 1 \le j\le m, \\
		\sin(\frac{j\pi}{m} - \phi - \kpim) &\le 0 \quad \mbox{ for } 1 \le j\le k .
	\end{align*}
	Thus, if \(\theta\in[0, \pimtwo]\), we have \begin{align*}
		G_k(\theta, \phi) =& -\sum_{j=1}^{k} \tjk + \sum_{j=k+1}^{\frac{m-1}{2}} \tjk - \sum_{j=\frac{m+1}{2}}^{m} \tjk \\
		=& \frac{\cos(\pimtwo + \kpim) \cos(\pimtwo - \theta - \phi)}{\sin\pim} + \frac{2k+1}{2}\sin(\phi-\theta+\kpim). 
	\end{align*}
	In addition, if \(\theta\in[\pimtwo, \pim]\), it holds \begin{align*}
		G_k(\theta, \phi) =& -\sum_{j=1}^{k} \tjk + \sum_{j=k+1}^{\frac{m+1}{2}} \tjk - \sum_{j=\frac{m+3}{2}}^{m} \tjk \\
		=& \frac{\cos(\pimtwo - \kpim) \cos(\frac{3\pi}{2m} - \theta - \phi)}{\sin\pim} + \frac{2k-1}{2}\sin(\phi-\theta+\kpim). 
	\end{align*}
\end{itemize}


In summary, from these two cases, we obtain \begin{equation}%\label{eq:gl}
	G_k(\theta, \phi) = \left\{\begin{aligned}
		&\frac{\cos\kpim \cos(\pim - \theta - \phi)}{\sin\pim} + k\sin(\phi-\theta+\kpim) \hspace{6em}  \mbox{ if}\ m\ \mbox{is even},\\ 
		&\frac{\cos(\pimtwo + \kpim) \cos(\frac{\pi}{2m} - \theta - \phi)}{\sin\pim} + \frac{2k+1}{2}\sin(\phi-\theta+\kpim) \mbox{ if}\ m\ \mbox{is odd and } \theta \in [0, \pimtwo],\\ 
		&\frac{\cos(\pimtwo - \kpim) \cos(\frac{3\pi}{2m} - \theta - \phi)}{\sin\pim} + \frac{2k-1}{2}\sin(\phi-\theta+\kpim) \mbox{ if}\ m\ \mbox{is odd and } \theta \in [\pimtwo, \pim].\\ 
	\end{aligned}\right.
\end{equation}
This completes the proof of \eqref{eq:gl}. \\
