{\bf Case 1:} $m$ is even with $m\ge 4$. Recalling \eqref{eq:gl}, it holds \begin{align*}
	G_{k+1}(\theta, \phi) - G_{k}(\theta, \phi) =& 2k\cos(\phi-\theta+\kpim+\pimtwo)\sin\pimtwo + \sin(\phi - \theta + \frac{k+1}{m}\pi) \\
	&-\frac{2\sin(\kpim+\pimtwo)\sin\pimtwo\cos(\pim-\theta-\phi)}{\sin\pim} \\
	\stackrel{\mbox{(i)}}{\ge}& 2k\cos(\kpim+\frac{\pi}{2m})\sin\pimtwo + \sin\kpim - \frac{2\sin(\kpim+\pimtwo)\sin\pimtwo}{\sin\pim}\\
	=& 2k\cos(\kpim+\frac{\pi}{2m})\sin\pimtwo - \frac{2\cos\kpim\sin^2\pimtwo}{\sin\pim}\\
	=& \frac{2\sin^2\pimtwo}{\sin\pim}\zkh{2k \cos(\kpim+\pimtwo)\cos\pimtwo-\cos\kpim} \stackrel{\mbox{(ii)}}{\ge} 0.
\end{align*}
Here, (i) follows from the facts $\cos(\phi-\theta+\kpim+\pimtwo)\ge \cos(\kpim+\frac{\pi}{2m})$, $\sin(\phi - \theta + \frac{l+1}{m}\pi)\ge \sin\kpim$ and $\cos(\pim-\theta-\phi)\le 1$ with \(k \le \hat{k}-1 = \frac m2 -2\). And (ii) holds since 
\[2k \cos(\kpim+\pimtwo)\cos\pimtwo \ge 2\cos(\kpim+\pimtwo)\cos\pimtwo = \cos\kpim + \cos(\kpim+\pim) \ge \cos\kpim\]
with the proviso that \(1 \le k \le \frac m2 -2\). 


{\bf Case 2:} $m$ is odd with \(\theta\in[0, \pimtwo]\) and $\phi\in[0, \theta]$. \eqref{eq:khat} gives \(m \ge 5\) and \(1 \le k \le \frac{m-3}{2}\). Then \eqref{eq:gl} asserts that \begin{align*}
	G_{k+1}(\theta, \phi) - G_{k}&(\theta, \phi) = (2k+1)\cos(\phi-\theta+\kpim+\pimtwo)\sin\pimtwo + \sin(\phi - \theta + \frac{k+1}{m}\pi) \\
	&-\frac{2\sin(\kpim+\pim)\sin\pimtwo\cos(\pimtwo-\theta-\phi)}{\sin\pim} \\
	\ge& (2k+1)\cos(\kpim+\pimtwo)\sin\pimtwo + \sin(\kpim+\pimtwo) - \frac{2\sin(\kpim+\pim)\sin\pimtwo}{\sin\pim}\\
	=& (2k+1)\cos(\kpim+\pimtwo)\sin\pimtwo - \frac{2\cos(\kpim+\pimtwo)\sin^2\pimtwo}{\sin\pim}\\
	=& \frac{2\sin^2\pimtwo\cos(\kpim+\pimtwo)}{\sin\pim}\zkh{ (2k+1) \cos\pimtwo - 1} \stackrel{\mbox{(i)}}{\ge} 0 
\end{align*}
where (i) holds because of \((2k+1) \cos\pimtwo \ge 3 \cos\frac{\pi}{10}  >  1.\)


{\bf Case 3:} $m$ is odd with \(\theta\in[\pimtwo, \pim]\) and $\phi\in[0, \theta]$. We first prove \(G_{2}(\theta, \phi) \ge G_{1}(\theta, \phi)\) with \(m \ge 5\) due to \(\hat{k} \ge 2\). One has 
\begin{align*}
	G_{2}(\theta, \phi&) - G_{1}(\theta, \phi) = 3\cos(\phi-\theta+\pimtwothree)\sin\pimtwo + \sin(\phi - \theta + \pim) - 2\sin\pimtwo\cos(\pimtwothree-\theta-\phi) \\
	=& -4\sin\pimtwo\sin(\pimtwothree-\theta)\sin\phi + \cos\pimtwo\sin(\pimtwothree-\theta)\cos\phi + \cos\pimtwo\cos(\pimtwothree-\theta) \\
	=& \cos\pimtwo\cos(\pimtwothree-\theta)\cos\phi \zkh{-4\tan\pimtwo\tan(\pimtwothree-\theta)\tan\phi + \tan(\pimtwothree-\theta) + \tan\phi}\\
	=& \frac{\cos\pimtwo\cos(\pimtwothree-\theta)\cos\phi}{4\tan\pimtwo} \zkh{1 - \xkh{1-4\tan\pimtwo\tan(\pimtwothree-\theta)}\xkh{1-4\tan\pimtwo\tan\phi} } \stackrel{\mbox{(i)}}{\ge} 0.
\end{align*}
Here, (i) holds since 
\[\tan\pimtwo\tan(\pimtwothree-\theta),\ \tan\pimtwo\tan\phi \le \tan\pimtwo\tan\pim \le \tan\frac{\pi}{10}\tan\frac{\pi}{5} = \sqrt{5}-2 < \frac 14\]
for \(m \ge 5\). Then consider \(G_{k+1}(\theta, \phi) - G_{k}(\theta, \phi)\) with \(k \ge 2\) and \(\hat{k} \ge 3\), i.e. \(m \ge 7\). It is easy to see that \begin{align*}
	G_{k+1}(\theta, \phi) - G_{k}(&\theta, \phi) \ge (2k+1)\cos(\kpim+\pimtwo)\sin\pimtwo + \sin(\kpim-\pim) - \frac{2\sin\kpim \sin\pimtwo}{\sin\pim}\\
	=& (2k+1)\cos(\kpim+\pimtwo)\sin\pimtwo + \frac{2\sin\pimtwo}{\sin\pim} \zkh{\sin(\kpim-\pim)\cos\pimtwo - \sin\kpim}\\
	\ge& (2k+1)\cos(\kpim+\pimtwo)\sin\pimtwo + \frac{2\sin\pimtwo}{\sin\pim} \zkh{\sin(\kpim-\pim)\cos\pim - \sin\kpim}\\
	=& \sin\pimtwo \Big[\underbrace{(2k+1) \cos(\kpim+\pimtwo)-2\cos(\kpim-\pim)}_{:=I_1}\Big] \ge 0. 
\end{align*}
Here,  we consider \(I_1\) for \(3 \le k \le \frac{m-3}{2}\) and \(k = 2\), respectively.
\begin{itemize}
	\item If \(3 \le k \le \frac{m-3}{2}\), we have \begin{align*}
		I_1 =& (2k+1) \cos(\kpim+\pimtwo) - 2\cos(\kpim+\pimtwo)\cos\pimtwothree - 2\sin(\kpim+\pimtwo)\sin\pimtwothree \\
		\stackrel{\mbox{(i)}}{\ge}& (2+4\cos\pimtwothree) \cos(\kpim+\pimtwo) - 2\cos(\kpim+\pimtwo)\cos\pimtwothree - 2\sin(\kpim+\pimtwo)\sin\pimtwothree \\
		=& 2 \cos(\kpim+\pimtwo) + 2 \cos(\kpim+\frac{2\pi}{m}) = 4 \cos(\kpim+\frac{5\pi}{4m}) \cos \pimfourthree \stackrel{\mbox{(ii)}}{\ge} 0
	\end{align*}
	where (i) uses \(2k+1 >  2 + 4\cos\pimtwothree\) for \(k \ge 3\), and (ii) holds since \(3 \le k \le \frac{m-3}{2}\). % and \(m \ge 9\). 
	\item If \(k = 2\), take \(x = \pimtwo\) and see that \[I_1 = 5\cos\frac{5\pi}{2m}-2\cos\pim = 5\cos(5x) - 2\cos(2x).\]
	We denote \(f(x) := 5\cos(5x) - 2\cos(2x)\) with \(x \in (0, \frac{\pi}{14}]\) and obtain  
	\[f'(x) = -25\sin(5x) + 4\sin(2x) < -25\sin(2x) + 4\sin(2x) < 0.\] 
	As a result, one has \(f(x)>0\) for \(x \in (0, \frac{\pi}{14}]\) since \(f(0) = 3\) and 
	\[f(\frac{\pi}{14}) = 5\cos\frac{5\pi}{14}-2\cos\frac{\pi}{7} = 3\cos\frac{5\pi}{14}-4\sin\frac{\pi}{4}\sin\frac{3\pi}{28} > 3\sin\frac{4\pi}{28}-3\sin\frac{3\pi}{28} > 0.\]
\end{itemize}


The above analysis establishes \eqref{eq:gl+1:1}. 
Inequality \eqref{eq:gl+1:0} is similar; for the sake of simplicity, we omit its proof here. 
This completes the proof. % of \eqref{claim:em:1}.  

