\section*{Appendix A ~~Validation of the fast time convolution using synthetic data }\label{APP Synthetic} 
As an additional check on the accuracy of the fast algorithm described in Section \ref{FastHM}, we apply the method to a synthetic example that has an exact analytical representation for the time-convolution integral of \eqref{kernel}, i.e.,
\begin{equation}\label{kernelA}
    \mathcal{K} g(t) = \int_0^t \frac{1}{\sqrt{t-\tau}} k(t,\tau)  g(\tau) \, d\tau,
\end{equation}
where $k(t,\tau)$ is given by (\ref{k(t,tau)}).

 Set
\begin{equation}\label{synpsi0}
    \psi_0(t) = 1-\frac{1}{2t+2},
\end{equation}
so that the solution of \eqref{psiODE} is
\begin{equation}\label{synpsi1psi2}
    \begin{aligned}
        \psi_1(t) = t-\half\log[1+t]\\
        \psi_2(t) = \frac{3}{4}-\frac{3+2t}{4}\exp[-2t].
    \end{aligned}
\end{equation}
Next,  choose $g(\tau)=g_\alpha(\tau)=
  \psi_2'(\tau)\psi_2^\alpha(\tau)$ and substitute $x = \psi_2(\tau)/\psi_2(t)$ into (\ref{kernelA}) to obtain
\begin{equation}\label{synanalytic}
\begin{aligned}
    \frac{1}{\sqrt{\pi}}\exp[-\psi_1(t)]\int_{0}^{t}\frac{\psi_2'(\tau)\psi_2^\alpha(\tau)}{\sqrt{\psi_2(t)-\psi_2(\tau)}} d\tau &= \frac{1}{\sqrt{\pi}}\exp[-\psi_1(t)]\int_{0}^{1}\frac{\psi_2'(t)x^\alpha \psi_2^\alpha(t)\psi_2(t)}{\psi_2'(t)\sqrt{\psi_2(t)-x\psi_2(t)}}  \ dx, \\
    &= \frac{1}{\sqrt{\pi}}\exp[-\psi_1(t)]\psi_2^{\alpha+1/2}(t)B(\half,1+\alpha),
\end{aligned}
\end{equation}
where $B$ is the Euler beta function.

To test the convergence of the quadrature method, we consider values of $\alpha$  that  lead to the following asymptotic expansions of $g_\alpha(\tau)$ near $\tau=0$:

\begin{align*}
\alpha= -\half\quad &\Rightarrow\quad g_{-\half}(\tau) = \frac{1}{\sqrt{\tau}} -
                 \frac{3}{4}\sqrt{\tau} + O(\tau^{3/2}),\\
\alpha= 0\quad &\Rightarrow\quad g_{0}(\tau) = 1 - \tau + O(\tau^3), \\
\alpha= \half\quad &\Rightarrow\quad g_{\half}(\tau) = \sqrt{\tau} + O(\tau^{3/2}),\\
\alpha= 1 \quad &\Rightarrow\quad g_{1}(\tau) = \tau + O(\tau^2), \\
\alpha= \frac{3}{2}  \quad &\Rightarrow\quad g_{\frac{3}{2}}(\tau) = \tau^{\frac{3}{2}} + O(\tau^\frac{5}{2}).
\end{align*}
Based on these expansions, we consider the following examples
\begin{align}
  E0:\quad  g(\tau) &= g_{-\half}(\tau) + g_0(\tau), \nonumber \\
  E1:\quad  g(\tau) &= g_0(\tau), \nonumber \\
  E2:\quad  g(\tau) &= g_{\half}(\tau), \label{synalpha}\\
  E3:\quad  g(\tau) &= g_{1}(\tau), \nonumber \\
  E4:\quad  g(\tau) &= g_{\threehalf}(\tau). \nonumber
\end{align}
In all examples, we  use  $\psi_0,~ \psi_1$ and $\psi_2$ as given in (\ref{synpsi0}) and   (\ref{synpsi1psi2}).
The numerical results obtained are shown in
Tables~\ref{tab:fast} and~\ref{tab:slow}. It is seen  that the
complexity of the fast method is consistent with log-linear behavior in $P$,
while the direct method is quadratic. The interpolation order $q$ of the fast 
