\node at (0.8,0) (lami1i) {$1^i$};
\node at (1.5,0) (lami02) {$0^{\lceil \frac{n+1}{2} \rceil}$}; 
\node at (2.2,0) (lami1s) {$1^n$};
\node at (0,-1) (lamip101) {$0^{\lfloor \frac{n+1}{2} \rfloor}$};
\node at (0.8,-1) (lamip11i) {$1^{i+1}$};
\node at (1.7,-1) (lamip102) {$0^{\lceil \frac{n+1}{2} \rceil}$}; 
\node at (2.4,-1) (lamip11s) {$1^n$};

\draw[->,thick]
(lami01) -- (lamip101);
\draw[->,thick]
(lami1i) -- (lamip11i);
\draw[->,thick]
(lami02) -- (lamip102);
\draw[->,thick]
(lami1s) -- (lamip11s);
\end{tikzpicture}
\qedhere
\]
\end{claimproof}

\smallskip
The next claim shows that to achieve a doubling of
the lead, a single $\lam_{(n,n-1)}$ block can be mapped to
two adjacent $\lam_{(n,0)}$ blocks.   

\smallskip
\begin{claim}\label{clm:main.clm6}
Let $f$ be any $C$-quasi-isometric reduction
from $\alpha$ to $\beta$. 
Then, for large enough $n$, $f$ can map the
sequence of positions of a $\lam_{(n,n-1)}$ block 
into the sequence of positions of exactly $k$ 
blocks $\lam_{(n,0)}$ iff $k=2$. 
\end{claim}

\smallskip
\begin{claimproof}
If a $\lam_{(n,n-1)}$ block were mapped to a single 
$\lam_{(n,0)}$ block, then the positions of the 
substrings $0^{\lfloor \frac{n+1}{2} \rfloor}$
and $0^{\lceil \frac{n+1}{2} \rceil}$ must be mapped  
into the sequence of positions of $0^n$. But the 
positions of the substring $1^{n-1}$ would have to be 
mapped into the sequence of positions of $1^n$, and this 
would violate Condition (b) for large enough $n$. 
Furthermore, when $n > C+1$, a $\lam_{(n,n-1)}$ block 
cannot be mapped across more than two $\lam_{(n,0)}$ 
blocks without resulting in an interval of at least
$C+1$ positions of $\zeta_n$ having no preimage, 
contradicting Lemma \ref{lem:image.point.density}.    
A one-to-one mapping of the positions of a single 
$\lam_{(n,n-1)}$ block to the positions of two 
$\lam_{(n,0)}$ blocks is depicted in the next figure.

\[
\begin{tikzpicture}
