\node at (1,0) (lamn1n) {$1^{n-1}$};
\node at (1.9,0) (lamn02) {$0^{\lceil \frac{n+1}{2} \rceil}$}; 
\node at (2.6,0) (lamn1s) {$1^n$};
\node at (0,-1) (lam010s) {$0^{n}$};
\node at (0.8,-1) (lam011s) {$1^{n}$};
\node at (1.7,-1) (lam020s) {$0^{n}$}; 
\node at (2.4,-1) (lam021s) {$1^{n}$};

\draw[->,thick]
(lamn01) -- (lam010s);
\draw[->,thick]
(lamn1n) -- (lam011s);
\draw[->,thick]
(lamn02) -- (lam020s);
\draw[->,thick]
(lamn1s) -- (lam021s);
\end{tikzpicture}
\]
Thus, when $n$ is large enough, a single $\lam_{(n,n-1)}$
block maps to exactly two $\lam_{(n,0)}$ blocks.
\end{claimproof}

\smallskip
We elaborate on why, for large enough $n$, the 
lead of $f$ is quadrupled at the end of the scaling segment. 
Suppose that $f$ has a nonnegative lead
$\ell$ at the start of the scaling segment. When $n$ is large
enough, $\ell \leq nB'_n$. By Claim \ref{clm:main.clm5},
for $1 \leq i \leq n-2$, the first $nB'_n-\ell$ blocks 
$\lam_{(n,i)}$ of the (first part of the) scaling segment of $\theta_n$ 
are mapped to the last $nB'_n-\ell$ blocks $\lam_{(n,i)}$ of the
(first part of the) scaling segment of $\zeta_n$, while the last 
$\ell$ blocks $\lam_{(n,i)}$
are mapped to the first $\ell$ blocks $\lam_{(n,i+1)}$.
Further, the first $nB'_n-\ell$ blocks $\lam_{(n,n-1)}$ are 
mapped to the last $nB'_n-\ell$ blocks $\lam_{(n,n-1)}$.
By Claim \ref{clm:main.clm6}, each of the last $\ell$ 
$\lam_{(n,n-1)}$ blocks must be mapped to two $\lam_{(n,0)}$
blocks, while the first $nB'_n-2\ell$ blocks $\lam_{(n,0)}$
of the (first part of the) scaling segment of $\theta_n$ are 
mapped in a monotonic and one-block-to-one-block fashion to the
remaining $nB'_n-2\ell$ blocks $\lam_{(n,0)}$.      
Thus, if $f$ has a lead of $\ell$ in the inner join segment 
preceding the current scaling segment, then it has a lead of 
$2\ell$ at the end of the first part of the scaling segment; 
after the second part of the scaling segment, a similar argument 
as before shows that the lead is quadrupled to $4\ell$. 
We next consider the branching segment.

\proofsubparagraph{Branching segment.} In this segment, the lead
of a $C$-quasi isometry $f$ is increased by $1$ or decreased 
by up to $C$ when $n$ is large enough. To achieve
this, suppose that, after the join segment of $\theta_n$ 
succeeding the scaling segment, there are altogether
$B$ blocks in $\zeta_1\cdots\zeta_{n-1}$ and the current
prefix of $\zeta_n$. The branching segment of $\theta_n$
is 
\[
(\lam_{(n,0)})^{2Bn+1}
\]
while the branching segment of $\zeta_n$ is
\[
(\lam_{(n,0)})^{2Bn}\lam'_n\,.
\] 

\smallskip
\begin{claim}\label{clm:main.clm7}
Let $f$ be any $C$-quasi-isometric reduction
from $\alpha$ to $\beta$. Suppose that $n$
is large enough so that the lead $\ell$
of $f$ in the sequence of positions of the 
join segment just before the branching segment
is defined and nonnegative. 
Then, for large enough $n$, the lead of $f$ in 
the sequence of positions of the join segment after
the branching segment is at least $\ell-C$ and
at most $\ell+1$. 
\end{claim} 

\smallskip
\begin{claimproof}
When $n > C$, the lead of $f$ in the sequence of 
positions of the join segment just before the branching 
segment is at most $nB$, where $B$ is the number of blocks
in the prefix of $\alpha$ (or $\beta$) built so far.
Thus, there are at most $nB$ blocks $\lam_{(n,0)}$ of the
branching segment of $\zeta_n$ that have preimages before
the start of the branching segment of $\theta_n$. 
Consequently, the first $\lam_{(n,0)}$ block of the branching 
segment of $\theta_n$ is mapped into the sequence of positions 
of the first $nB+1$ blocks $\lam_{(n,0)}$ of the branching 
segment of $\zeta_n$.

By Lemma \ref{lem:collision}, up to $C+1$
blocks $\lam_{(n,0)}$ can be mapped to a single
$\lam'_{n}$ block. Hence, the lead of $f$ from the 
previous inner join segment can be decreased by up 
to $C$ in the subsequent inner join segment.
Further, when $n$ is large enough,
a single $\lam_{(n,0)}$ block can be mapped across 
$\lam_{(n,0)}\lam'_n$. This can be done by mapping
the $0^n$ substring of the $\lam_{(n,0)}$ block in 
the branching segment of $\theta_n$ to the $0^n$ 
substring of the $\lam_{(n,0)}$ block in the branching
segment of $\zeta_n$, and then mapping $1^n$ to
$1^n(01)^n1^n$ by mapping the first third of $1$'s
to the first occurrence of $1^n$, the second third of 
$1$'s to $(01)^n$ and the last third of $1$'s to the 
second occurrence of $1^n$. The mapping is illustrated
as follows.
\[
\begin{tikzpicture}
\node at (0,0) (lamn0s) {$0^{n}$};
\node at (0.5,0) (lamn1s) {$1^{n}$};
\node at (0,-1) (lamn20s) {$0^{n}$}; 
\node at (0.5,-1) (lamn21s) {$1^n$};
\node at (1.2,-1) (lamnp1) {$(01)^{n}$};
\node at (1.9,-1) (lamnp2) {$1^{n}$};
\
\draw[->,thick]
(lamn0s) -- (lamn20s);
\draw[->,thick]
(lamn1s) -- (lamn21s);
\draw[->,thick]
(lamn1s) -- (lamnp1);
\draw[->,thick]
(lamn1s) -- (lamnp2);
\end{tikzpicture}
\]
The proof of Claim \ref{clm:main.clm3} shows that for
large enough $n$, one and only one $\lam_{(n,0)}$ block 
can be mapped to a $\lam_{(n,0)}$ block.
Thus, the remaining $\lam_{(n,0)}$ blocks in the branching
segment of $\theta_n$ are mapped in a monotonic
and one-block-to-one-block fashion to the rest of the 
$\lam_{(n,0)}$ blocks in the branching segment of 
$\zeta_n$.
\end{claimproof}

\smallskip
After appending an $n$-join segment to the branching segment,
the selection segment is the final main segment to be added.

\proofsubparagraph{Selection segment.} This segment filters out 
quasi-isometries whose lead in the previous inner join segment
is not an element of $S_n$. The selection segment for
$\theta_n$ is
\[
\lam_{(n,1)}(\lam_{(n,0)})^{\max(S_n)}
\] 
while the selection segment for $\zeta_n$ is a concatenation
\[
\lam_{(n,0)}\cdots\lam_{(n,1)}\cdots\lam_{(n,0)}\cdots
\lam_{(n,0)}\lam_{(n,1)}
\] 
of $\max(S_n)+1$ $n$-blocks such that the $i$-th block is
$\lam_{(n,0)}$ if $i-1 \notin S_n$ and is $\lam_{(n,1)}$ if
$i-1 \in S_n$. 

\smallskip
\begin{claim}\label{clm:main.clm8}
Let $f$ be any $C$-quasi-isometric reduction
from $\alpha$ to $\beta$. Suppose that $n$
is large enough so that the lead $\ell$
of $f$ in the sequence of positions of the 
join segment just before the selection segment
is defined and nonnegative. 
Then, for large enough $n$, $f$ maps the
sequence of positions of the $\lam_{(n,1)}$ 
block in the selection segment of $\theta_n$
into the sequence of positions of exactly
one of the $\lam_{(n,1)}$ blocks in the 
selection segment of $\zeta_n$. In particular,
$\ell \in S_n$.
\end{claim} 

\smallskip
\begin{claimproof}
By Claim \ref{clm:main.clm2}, for large enough $n$, 
$f$ cannot map the $\lam_{(n,1)}$ block of the 
selection segment of
$\theta_n$ to any position in the first join segment
of $\zeta_{n+1}$. Thus, $\ell \leq \max(S_n)$. By
Claim \ref{clm:main.clm2} again, $f$ must map the
$\lam_{(n,1)}$ block of the selection segment
of $\theta_n$ to some $\lam_{(n,1)}$ block in the
selection segment of $\zeta_n$, say the $c$-th block
of the selection segment of $\zeta_n$, for large 
enough $n$. By Condition (b), if $n > C$, then $f$ 
does not map any $\lam_{(n,0)}$ block of the selection 
segment of $\theta_n$ to a position before the image of the 
$\lam_{(n,1)}$ block under $f$. This implies that
$\ell = c-1 \in S_n$.
\end{claimproof}

% \smallskip
Putting everything together, the structures of $\theta_n$ and 
$\zeta_n$ for $n \geq 2$ look as follows:
\begin{equation}
\begin{aligned}\label{eqn:theta.zeta}
\theta_n 
&= v_{n, 1} \;\, s_{n, 1} \;\, v_{n, 2} \;\, s_{n, 2} \;\, 
v_{n, 3} \;\, t_n \;\, v_{n, 4} \;\, u_n\\
&= (\lam_{(n,0)})^{3nB^n_1} 
&&\leftarrow v_{n, 1}  &&\text{ (Join) }\\
&~~~~ (\lam_{(n,1)})^{nB^n_2}(\lam_{(n,2)})^{nB^n_2}\cdots(\lam_{(n,n-1)})^{nB^n_2}(\lam_{(n,0)})^{2nB^n_2} 
&&\leftarrow s_{n, 1}  &&\text{ (Scaling) }\\
&~~~~ (\lam_{(n,0)})^{3nB^n_3} 
&&\leftarrow v_{n, 2}  &&\text{ (Join) }\\ 
&~~~~ (\lam_{(n,1)})^{nB^n_4}(\lam_{(n,2)})^{nB^n_4}\cdots(\lam_{(n,n-1)})^{nB^n_4}
(\lam_{(n,0)})^{2nB^n_4} 
&&\leftarrow s_{n, 2}  &&\text{ (Scaling) }\\ 
&~~~~ (\lam_{(n,0)})^{3nB^n_5} 
&&\leftarrow v_{n, 3}   &&\text{ (Join) }\\ 
&~~~~ (\lam_{(n,0)})^{2nB^n_6+1} 
&&\leftarrow t_n  &&\text{ (Branching) }\\ 
&~~~~ (\lam_{(n,0)})^{3nB^n_7} 
&&\leftarrow v_{n, 4}  &&\text{ (Join) }\\ 
&~~~~ \lam_{(n,1)}(\lam_{(n,0)})^{\max(S_n)} 
&&\leftarrow u_n   &&\text{ (Selection) } \\ 
\\
\zeta_n 
&= v'_{n, 1} \;\, s'_{n, 1} \;\, v'_{n, 2} \;\, s'_{n, 2} \;\, 
v'_{n, 3} \;\, t'_n \;\, v'_{n, 4} \;\, u'_n\\
&= (\lam_{(n,0)})^{3nB^n_1} 
&&\leftarrow v'_{n, 1}  &&\text{ (Join) }\\
&~~~~ (\lam_{(n,1)})^{nB^n_2}(\lam_{(n,2)})^{nB^n_2}\cdots(\lam_{(n,n-1)})^{nB^n_2}(\lam_{(n,0)})^{2nB^n_2} 
&&\leftarrow s'_{n, 1}  &&\text{ (Scaling) }\\
&~~~~ (\lam_{(n,0)})^{3nB^n_3} 
&&\leftarrow v'_{n, 2}  &&\text{ (Join) }\\ 
&~~~~ (\lam_{(n,1)})^{nB^n_4}(\lam_{(n,2)})^{nB^n_4}\cdots(\lam_{(n,n-1)})^{nB^n_4}
(\lam_{(n,0)})^{2nB^n_4} 
&&\leftarrow s'_{n, 2}  &&\text{ (Scaling) }\\ 
&~~~~ (\lam_{(n,0)})^{3nB^n_5} 
&&\leftarrow v'_{n, 3}  &&\text{ (Join) }\\ 
&~~~~ (\lam_{(n,0)})^{2nB^n_6}\lam'_n 
&&\leftarrow t'_n  &&\text{ (Branching) }\\ 
&~~~~ (\lam_{(n,0)})^{3nB^n_7} 
&&\leftarrow v'_{n, 4}  &&\text{ (Join) }\\ 
&~~~~ \lam_{(n,0)}\cdots\lam_{(n,1)}\cdots\lam_{(n,0)}\cdots
\lam_{(n,0)}\lam_{(n,1)} 
&&\leftarrow u'_n   &&\text{ (Selection) } 
\end{aligned}
\end{equation}
where $B^n_i$ is the number of blocks in $\alpha$ 
(or $\beta$) preceding the segment where the 
parameter $B^n_i$ is first used.

Suppose that $f$ is a $C$-quasi-isometry from $\alpha$
to $\beta$. As explained earlier, if $n$ is sufficiently
large, then the lead $\ell$ of $f$ in the first join segment
of $\theta_{n+1}$ is contained in $S_{n}$. The lead is then 
quadrupled after the scaling segment. Further, by Claim 
\ref{clm:main.clm7}, the lead $\ell'$ of $f$ in the final join 
segment of $\theta_{n+1}$ is at least $4\ell-C$, at most $4\ell+1$ 
and is contained in $S_{n+1}$. To establish that 
$\alpha \not\leq_{mqi} \beta$, we prove that there is a 
constant $c$ such that the coefficients of the expressions for 
$\ell$ and $\ell'$ as linear combinations of powers of $4$
agree except on the smallest $c$ powers of $4$. Thus, the
branch on the Kleene tree represented by $\ell$ can be
properly extended by a branch represented by a prefix of
$\ell'$, so by repeatedly calculating the leads of $f$ for 
increasing values of $n$, one may construct an infinite branch 
of the tree. 

\smallskip
\begin{claim}\label{clm:main.clm9}
There exists a nonnegative constant $c$ such that if $n > c$,
$\ell = \sum_{m=1}^n b_m\cdot 4^{n-m} \in S_{n+1}$
and $\ell' = \sum_{m=1}^{n+1} b'_m\cdot 4^{n+1-m} \in S_{n+2}$,
where $b_m \in \{0,1\}$ and $b'_m \in \{0,1\}$, then
for all $m \in \{1,\ldots,n-c\}$, $b_{m} = b'_{m}$. 
\end{claim}

\smallskip
\begin{claimproof}
Let $c$ be a positive constant such that
$C < 4^c$. We show that for all 
$m \in \{1,\ldots,n-c\}$, $b_m = b'_m$.
As shown earlier, $4\ell-C \leq \ell' \leq 4\ell+1$.
Substituting the expressions for $\ell$ and $\ell'$
as linear combinations of powers of $4$ into the  
inequality $4\ell-C \leq \ell'$, 
\[
\begin{aligned}
\sum_{m=1}^{n} b_m4^{n-m+1} - 4^c < \sum_{m=1}^{n} b_m4^{n-m+1} - C
\leq \sum_{m=1}^{n+1} b_m'4^{n-m+1}\,.
\end{aligned}
\] 
Dividing both sides of the inequality by $4^{c+1}$,
\[
\begin{aligned}
\sum_{m=1}^{n} b_m4^{n-m-c} - \frac{1}{4} < \sum_{m=1}^{n+1} b'_m4^{n-m-c}\,.
\end{aligned}
\] 
Splitting the sums on both sides according to whether the powers of $4$
are nonnegative or negative,
\[
\begin{aligned}
\sum_{m=1}^{n-c} b_m4^{n-m-c} + \sum_{m=n-c+1}^{n} b_m4^{n-m-c} - 
\frac{1}{4} < \sum_{m=1}^{n-c} b'_m4^{n-m-c} + \sum_{m=n-c+1}^{n+1} b'_m4^{n-m-c}\,.
\end{aligned}
\] 
Rearranging,
\[
\begin{aligned}
\sum_{m=1}^{n-c} b_m4^{n-m-c} + \sum_{m=n-c+1}^{n} b_m4^{n-m-c} - 
\frac{1}{4} - \sum_{m=n-c+1}^{n+1} b'_m4^{n-m-c} < \sum_{m=1}^{n-c} b'_m4^{n-m-c}\,.
\end{aligned}
\] 
Since 
\[
\begin{aligned}
\sum_{m=n-c+1}^{n} b_m4^{n-m-c} - \frac{1}{4} - \sum_{m=n-c+1}^{n+1} b'_m4^{n-m-c}
\geq -\frac{1}{4} - \sum_{m=1}^{\infty} 4^{-m} = \frac{7}{12}\,,
\end{aligned}
\]
it follows that
\[
\begin{aligned}
\sum_{m=1}^{n-c} b'_m4^{n-m-c} > \sum_{m=1}^{n-c} b_m4^{n-m-c} - \frac{7}{12}\,.
\end{aligned}
\]
Taking the ceiling on both sides,
\begin{align}
\sum_{m=1}^{n-c} b'_m4^{n-m-c} &= \left\lceil \sum_{m=1}^{n-c} b'_m4^{n-m-c} \right\rceil \nonumber\\
&\geq \left\lceil \sum_{m=1}^{n-c} b_m4^{n-m-c} - \frac{7}{12} \right\rceil \nonumber\\ 
&= \sum_{m=1}^{n-c} b_m4^{n-m-c} \label{eqn:constant.sep1}\,. 
\end{align}
From the inequality $\ell' \leq 4\ell+1$, 
\[
\begin{aligned}
\sum_{m=1}^{n-c} b'_m4^{n-m+1} + \sum_{m=n-c+1}^{n+1} b'_m4^{n-m+1}
\leq \sum_{m=1}^{n} b_m4^{n-m+1} + 1\,.
\end{aligned}
\]
Dividing both sides by $4^{c+1}$ and applying the floor function,

\begin{align}
\sum_{m=1}^{n-c} b'_m4^{n-m-c} &= 
\left\lfloor\sum_{m=1}^{n-c} b'_m4^{n-m-c} + \sum_{m=n-c+1}^{n+1} b'_m4^{n-m-c}\right\rfloor \nonumber\\
&\leq \left\lfloor\sum_{m=1}^{n} b_m4^{n-m-c} + \frac{1}{4^{c+1}} \right\rfloor \nonumber\\
&= \sum_{m=1}^{n} b_m4^{n-m-c} \label{eqn:constant.sep2}\,.
\end{align}
Inequalities (\ref{eqn:constant.sep1}) and (\ref{eqn:constant.sep2}) together
give that for each $m \in \{1,\ldots,n-c\}$, $b'_m = b_m$. 
\end{claimproof}

\smallskip
\begin{claim}\label{clm:main.clm10}
$\alpha \not\leq_{mqi} \beta$.
\end{claim}

\smallskip
\begin{claimproof}
Suppose that $f$ is a $C$-quasi-isometry from $\alpha$
to $\beta$. We show that an infinite branch of the 
Kleene tree can be determined recursively in $f$. 
Let $c$ be the constant in the statement
of Claim \ref{clm:main.clm9}. Fix $n_0 > c$ large enough
so that whenever $n \geq n_0$, $f$ has nonnegative lead 
in the last join segment of $\theta_{n}$. 
Then, calculate the sequence $(\ell_n)_{n=n_0}^{\infty}$
of leads of $f$ in the last join segment of $\theta_n$
for $n \geq n_0$, expressing each $\ell_n$ in the shape
$\sum_{m=1}^n b^n_m4^{n-m}$, where $b^n_m \in \{0,1\}$. 
By Claim \ref{clm:main.clm9},
$b^{n}_m = b^{n+1}_m$ for all $m \in \{1,\ldots,n-c\}$,
and so by Claim \ref{clm:main.clm8},
\[
b^{n_0}_1\cdots b^{n_0}_{n_0-c} b^{n_0+1}_{n_0-c+1}
b^{n_0+2}_{n_0-c+2} \cdots b^{n_0+k}_{n_0-c+k} \cdots
\]
is an infinite branch of the Kleene tree. But since the 
tree has no infinite recursive branches, $f$ must be 
nonrecursive.
\end{claimproof}

\smallskip
To finish the proof, we observe that a quasi-isometric
reduction from $\alpha$ to $\beta$ can be obtained from
an infinite branch of the Kleene tree.

\smallskip
\begin{claim}\label{clm:main.clm11}
$\alpha \leq_{qi} \beta$.
\end{claim}

\smallskip
\begin{claimproof}
Fix an infinite branch $\mathcal{B}(1)\mathcal{B}(2)\cdots$ 
of the Kleene tree. For each $n \in \bbbn$, we describe a 
mapping from $\theta_n$ to $\zeta_n$, using the structures
depicted in Equation (\ref{eqn:theta.zeta}) as a reference. 
This will give a quasi-isometric reduction from $\alpha$ to 
$\beta$.
The mappings to be defined are strictly increasing.

First,
since $\theta_1 = \zeta_1 = \lambda_{(n, 0)}$,
we can map $\theta_1$ to $\zeta_1$ in a strictly increasing fashion. 
The lead in the next segment is 0.
For $n \geq 2$, map each join segment $v_{n, i}$ 
of $\theta_n$ to the corresponding join segment $v'_{n, i}$ of 
$\zeta_n$, shifted by the lead at the current step.
That is, suppose the lead is $\ell_1$ and
the number of blocks in $\alpha$ before this segment is $B^n_{2i - 1}$.
Then, for $1 \leq i \leq 3nB^n_{2i - 1} - \ell_1$,
map the $i$-th block of the join segment of $\theta_n$ into
the $(i + \ell_1)$-th block of the corresponding join segment of $\zeta_n$.
Map the last $\ell_1$ blocks $\lambda_{(n, 0)}$ of the join segment into
the first $\ell_1$ blocks of the following segment in $\zeta_n$---which
must be $\lambda_{(n, 0)}$ or $\lambda_{(n, 1)}$ blocks.
Note that a $\lambda_{(n, 0)}$ block can be mapped into
a $\lambda_{(n, 1)}$ block.
\[
\begin{tikzpicture}
\node at (0,0) (lamn0s) {$0^{n}$};
\node at (0.7,0) (lamn1s) {$1^{n}$};
\node at (0,-1) (lamn101) {$0^{\lfloor \frac{n+1}{2} \rfloor}$}; 
\node at (0.7,-1) (lamn11) {$1$};
\node at (1.4,-1) (lamn102) {$0^{\lceil \frac{n+1}{2} \rceil}$};
\node at (2.1,-1) (lamn11s) {$1^{n}$};
\
\draw[->,thick]
(lamn0s) -- (lamn101);
\draw[->,thick]
(lamn0s) -- (lamn102);
\draw[->,thick]
(lamn1s) -- (lamn11s);
\end{tikzpicture}
\]
The lead in the next segment is $\ell_1$.

Next we describe the mapping for scaling part $s_{n, i}$ with lead $\ell_2$.
For each $k \leq n-1$,
map the first $nB^n_{2i}-\ell_2$ blocks $\lam_{(n,k)}$ of $s_{n, i}$
to the corresponding last 
$nB^n_{2i}-\ell_2$ blocks $\lam_{(n,k)}$ of $s'_{n, i}$.
Then, for each $k \leq n-2$, map the last $\ell_2$ 
blocks $\lam_{(n,k)}$ of $s_{n, i}$ to the first $\ell_2$ blocks $\lam_{(n,k+1)}$ of $s'_{n, i}$.
Observe that each block $\lambda_{(n, k)}$ can be mapped to
a block $\lambda_{(n, k + 1)}$ in a strictly increasing manner.
Further, map each of the last $\ell_2$ blocks $\lam_{(n, n - 1)}$
to exactly two blocks $\lam_{(n, 0)}$ of $s'_{n, i}$.
Map the first $2nB^n_{2i} - 2\ell_2$ blocks $\lam_{(n, 0)}$ to
the remaining $2nB^n_{2i} - 2\ell_2$ blocks $\lam_{(n, 0)}$ of $s'_{n, i}$.
Map the last $2\ell_2$ blocks $\lam_{(n, 0)}$ to
the first $2\ell_2$ blocks of the following join segment in $\zeta_n$.
The lead of the next join segment is $2\ell_2$.

For the branching segment, suppose that the current lead is
$\ell_3$. If $\mathcal{B}(n-1) = 1$, 
map the $(2nB^n_6 - \ell_3)$-th $\lam_{(n,0)}$ block to 
the concatenation $\lam_{(n,0)}\lam'_n$ of two blocks in $t'_n v_{n, 4}$.
Otherwise, map the $(2nB^n_6 - \ell_3 + 1)$-st $\lam_{(n,0)}$
block to the $\lam'_n$ block in $t'_n$.
Map the rest of the $\lam_{(n,0)}$ blocks 
such that $f$ is strictly increasing.
Then, the lead of the next join segment is $\ell_3 + \mathcal{B}(n-1)$.

For the selection segment, suppose that the current 
lead is $\ell_4$. Map the $\lam_{(n,1)}$ block to the
$(\ell_4+1)$-st block. By induction, $\ell_4 \in S_n$
and so the $(\ell_4+1)$-st block in the selection segment
of $\zeta_n$ is $\lam_{(n,1)}$.
Recall that a $\lam_{(n,0)}$
block can be mapped in a strictly increasing fashion to a $\lam_{(n,1)}$
block.
Thus, the remaining $\lam_{(n,0)}$
blocks can be mapped to the subsequent $\lam_{(n,0)}$
or $\lam_{(n,1)}$ blocks in a strictly increasing manner.   
\end{claimproof}

From Claims \ref{clm:main.clm10} and \ref{clm:main.clm11}, we conclude that
$\alpha \leq_{qi} \beta$ but $\alpha \not\leq_{mqi} \beta$.
Hence, mqi-reducibility is strictly a stronger notion 
than general quasi-isometric reducibility.
\end{proof}


\section{Automatic Quasi-Isometric Reductions}

Automatic structures were introduced independently 
by Hodgson in 1983~\cite{Hodgson83} and
by Khoussainov and Nerode in 1995~\cite{Khoussainov95}.
Since then, automatic structures have been well studied,
with many surveys written on this
topic~\cite{Gradel20,Khoussainov07,Rubin08,Stephan15}.

The results in the previous section focus mainly on 
quasi-isometric reductions which are recursive.
In this section, we extend the previous results to the area of automata theory
by studying quasi-isometric reductions which are automatic.
We first define formally the notion of automatic quasi-isometric reductions,
by replacing the recursive infinite strings
in Definition~\ref{defn:C.reduction}
with an isomorphic automatic structure.

We let the domain be some regular set $D \subseteq \Sigma^*$
for some finite alphabet $\Sigma$
and let $<_{llex}$ be the length lexicographic ordering.
We define the successor function $succ : D \to D$ such that
$succ(x) = \min_{llex}\{y \in D : x <_{llex} y\}$.
Addition by a constant is then defined using the successor function
such that for any $x \in D$ and $k \in \bbbn_0$, $x \oplus k \coloneq succ^k(x)$.
Similarly, $x \ominus k \coloneq succ^{-k}(x)$ is defined
whenever there are at least $k$ elements of $D$
that are length-lexicographically less than $x$.
Then, given a constant $k \in \bbbn_0$,
the successor function and addition by constant $k$
can be performed automatically.

From the previous paragraph, $(D, <_{llex}, succ)$ is
an automatic structure that is isomorphic to $(\bbbn, <, succ)$,
where $succ$ denotes the successor function in the respective domain.
Then, quasi-isometry results proven earlier for infinite strings
also apply to the corresponding automatic structures
by replacing $(\bbbn, <, succ)$ accordingly with
$(D, <_{llex}, succ)$.
In particular, Proposition~\ref{prop:quasi.iso.alt.def} holds
when we replace $\bbbn, <$ and $succ$ with
$D, <_{llex}$ and $succ$ respectively.
Hence, we can redefine the notion of quasi-isometric reducibility
between two automatic colourings of an automatic domain as follows.

\begin{definition}\label{defn:auto.C.reduction}
Let $C \in \bbbn$, $D \subseteq \Sigma^*$ be regular and
$\alpha, \beta$ be automatic colourings of $D$, that is,
automatic functions from $D$ to some finite sets.
A {\em $C$-quasi-isometric reduction} from $\alpha$ to $\beta$ is
a colour-preserving function
$f : D \to D$ such that for all $x, y \in D$,
\begin{enumerate}[(a)]
\item $f(\min_{llex} D) \leq_{llex} \min_{llex} D \oplus C$ and
$f(x) \ominus C \leq_{llex} f(x \oplus 1) \leq_{llex} f(x) \oplus C$; and
\item $x \oplus C <_{llex} y \Rightarrow f(x) <_{llex} f(y)$.
\end{enumerate}
\end{definition}

Where appropriate, we may drop the constant $C$ and simply call $f$
a quasi-isometric reduction, or a quasi-isometry, from $\alpha$ to $\beta$.
We are particularly interested in the case where $f$ is automatic.

\begin{definition}[Automatic Quasi-Isometric Reducibility]
Let $D \subseteq \Sigma^*$ be a regular set.
An automatic colouring $\alpha$ of $D$ is
{\em automatically quasi-isometrically reducible},
or {\em aqi-reducible}, to another automatic colouring $\beta$ of $D$
iff there exists a quasi-isometric reduction $f$ from $\alpha$ to $\beta$
such that $f$ is automatic.
\end{definition}
% Karen: Do we define many-one, one-one, permutation?

Note that Definition~\ref{defn:auto.C.reduction} uses
the alternate definition of quasi-isometry
given in Definition~\ref{defn:C.reduction},
which is a simpler but equivalent version of
Definition~\ref{defn:quasiisometry}.
The advantage of using this simpler definition is that
it allows automatic quasi-isometry to be defined
for a broader range of domains.
For example, the underlying metric space $(D, d_{llex})$
of the automatic structure $(D, <_{llex}, succ)$
is not always automatic as
subtraction is not automatic for many regular languages.

For our results, we define the following property about domain $D$.

\begin{definition}[\cite{Incitti01}]
Given an infinite regular set $D \subseteq \Sigma^*$,
we define {\em the growth of $D$} as
the function $growth_D : \bbbn_0 \to \bbbn_0$ such that
$growth_D(n) = |\{\sigma \in D : |\sigma| \leq n\}|$.
We say that $D$ has:
\begin{itemize}
\item {\em linear growth} if $growth_D(n) = \Theta(n)$;
\item {\em superlinear growth} if $growth_D(n) = \omega(n)$;
\item {\em polynomial growth} if $growth_D(n) = \Theta(n^c)$
for some $c \in \bbbr$ such that $c \geq 0$;
\item {\em exponential growth} if $growth_D(n) = \Omega(c^n)$
for some $c \in \bbbr$ such that $c > 1$.
\end{itemize}
\end{definition}

Results in automata theory show that if $D$ is regular,
then the growth is either polynomial or exponential, with nothing in between
\cite{Bridson02,Ibarra86,Incitti01,Latteux84,Raz97,Szilard92,Trofimov81}.
Furthermore, if the growth is polynomial, 
then it must be $\Theta(n^c)$ for some $c \in \bbbn$~\cite{Szilard92}.

Besides the growth, which counts the number of strings {\em up to} length $n$,
another useful property of a regular language is
the number of strings at {\em exactly} length $n$.

\begin{lemma}[\protect{\cite[Lemma 1]{Szilard92}}]
\label{lem:growth.lower.bound}
Suppose that $D$ contains $uv_1^*w_1 \ldots v_c^*w_c$ as a subset,
where for each $1 \leq i \leq c$, $v_i$ is a non-empty string and
the first character after $v_i^*$, if it exists, is not the same as
the first character of $v_i$.
If $n = |uw_1 \ldots w_c| + k|v_1|\ldots|v_c|$ for some $k \in \bbbn$,
then the number of strings in $D$ of length $n$ is $\Omega(n^{c-1})$.
\end{lemma}

\begin{lemma}[\protect{\cite[Lemma 4]{Szilard92}}]
\label{lem:growth.upper.bound}
Suppose that a language $D$ is
a finite union of the regular expressions of the form
$uv_1^*w_1 \ldots v_j^*w_j$ where $j \leq c$.
Then, the number of strings in $D$ of length $n$ is $O(n^{c-1})$.
\end{lemma}

We will now present our main results for this section,
which shows that whether automatic quasi-isometric reducibility exists
between two automatic colourings depends on the growth of the domain
(among other factors).

For the next theorem, we define $\beta: D \to \Gamma$ to be
{\em eventually periodic} if and only if
there are $k \in \bbbn$ and $h \in D$ such that for all $x \geq_{llex} h$,
$\beta(x \oplus k) = \beta(x)$.

\begin{theorem}\label{thm:auto.eventually.periodic}
Let $D \subseteq \Sigma^*$ be an infinite regular set,
and let $\alpha, \beta$ be automatic colourings of $D$
such that $\beta$ is eventually periodic.
The following are equivalent:
\begin{enumerate}[(a)]
\item Every colour in $\alpha$ also occurs in $\beta$ and every colour which occurs infinitely often in $\alpha$ also occurs infinitely often in $\beta$;
\item $\alpha$ is aqi-reducible to $\beta$;
\item $\alpha$ is quasi-isometrically reducible to $\beta$.
\end{enumerate}
\end{theorem}

\begin{proof}
$(a) \Rightarrow (b)$: 
We define the quasi-isometric reduction $f$ from $\alpha$ to $\beta$ such that:
\[
f(x) =
\begin{cases}
\min_{llex}\{y \in D: \alpha(x) = \beta(y)\}
& \text{if } \alpha(x) \text{ occurs only finitely often in } \alpha; \\
\min_{llex}\{y \in D: \alpha(x) = \beta(y) \text{ and } x <_{llex} y\}
& \text{if }\alpha(x) \text{ occurs infinitely often in } \alpha. \\
\end{cases}
\]
Note that $f$ is automatic since it is first-order defined
from automatic parameters $D$, $\alpha$, $\beta$ and $<_{llex}$.
Furthermore, $f$ is clearly colour-preserving.
It remains to show that $f$ satisfies Conditions (a) and (b) of
Definition~\ref{defn:auto.C.reduction}.

Let $x_0 = \min_{llex} D$.
Since $\beta$ is eventually periodic, there are $k, h \in \bbbn$ such that
for all $y \geq_{llex} x_0 \oplus h$, $\beta(y \oplus k) = \beta(y)$.
Furthermore, there exists $\ell \geq h$ such that for all $x \geq x_0 \oplus \ell$,
$\alpha(x)$ occurs infinitely often in $\alpha$.
Choose $C' = \max(\{t \in \bbbn_0 : x_0 \oplus t = f(x)$ for some
$x <_{llex} x_0 \oplus \ell\} \cup \{k, \ell\})$.

We first show that for any $x \in D$,
$x \leq_{llex} f(x) \oplus C'$ and $f(x) \leq_{lleq} x \oplus C'$.
If $x <_{llex} x_0 \oplus \ell$, then
$x \leq_{llex} f(x) \oplus C'$ and $f(x) \leq_{lleq} x \oplus C'$ by definition of $C'$.
Otherwise, then $\alpha(x)$ occurs infinitely often and
for all $x' \geq x$, $\beta(x' \oplus k) = \beta(x')$.
Hence, $x <_{llex} f(x) \leq_{llex} x \oplus k$.
Then, $x \leq_{llex} f(x) \oplus C'$ and $f(x) \leq_{llex} x \oplus C'$.

We now show that $f$ is a $C$-quasi-isometric reduction with $C = 2C' + 1$.
The first half of Condition (a) of Definition~\ref{defn:auto.C.reduction}
follows directly from our claim that $f(x) \leq_{llex} x \oplus C'$ for all $x \in D$.
To prove the second half, we have
\[
f(x) \leq_{llex} x \oplus C'
<_{llex} x \oplus 1 \oplus C'
\leq_{llex} f(x \oplus 1) \oplus 2C',
\]
and so $f(x \oplus 1) \geq_{llex} f(x) \ominus C$.
And similarly,
\[
f(x \oplus 1) \leq_{llex} x \oplus 1 \oplus C'
<_{llex} f(x) \oplus 2C' \oplus 1
= f(x) \oplus C.
\]
To prove Condition (b) of Definition~\ref{defn:auto.C.reduction},
suppose that $x \oplus C <_{llex} y$.
Note that
\[
f(x) \oplus C' \leq_{llex} x \oplus 2C' <_{llex} y \leq_{llex} f(y) \oplus C'.
\]
Then, $f(x) <_{llex} f(y)$.

$(b) \Rightarrow (c)$:
This follows from the definition of automatic quasi-isometric reducibility.

$(c) \Rightarrow (a)$:
Let $f$ be a $C$-quasi-isometric reduction from $\alpha$ to $\beta$.
Since $f$ is colour-preserving, then clearly,
every colour in $\alpha$ also occurs in $\beta$.
Furthermore, by Lemma~\ref{lem:collision}, $f$ is finite-to-one.
Hence, every colour which occurs infinitely often in $\alpha$
also occurs infinitely often in $\beta$.
\end{proof}

We next show that eventual periodicity is related to linear growth by the following proposition.

\begin{proposition}
Suppose an infinite regular set $D \subseteq \Sigma^*$ has linear growth.
Then, any automatic colouring $\beta: D \to \Gamma$ is eventually periodic.
\end{proposition}

\begin{proof}
Since $D$ has linear growth, then by Lemmas~\ref{lem:growth.lower.bound} and \ref{lem:growth.upper.bound}, it must be of the form $D = \bigcup_{i=1}^t u_iv_i^*w_i \cup D_{fin}$ where $D_{fin}$ is a finite set, $u_i, w_i \in \Sigma^*$ and $v_i \in \Sigma^+$.
Without loss of generality, we can assume that $|u_1| = \ldots = |u_t|$ and $|v_1| = \ldots = |v_t|$, since $v_i$ can be replaced by $v_i^{|v_1|\ldots|v_{i-1}||v_{i+1}|\ldots|v_t|}$ and rotated as needed so that $|u_1| = \ldots = |u_t|$.

Now consider the set $D_c$ of all the strings $x \in D$ with $\beta(x) = c$.
Since $\beta$ is regular, then so is $D_c$.
Thus, $D_c$ satisfies the pumping lemma for any large enough pumping constant $k$.
We consider the following version of the pumping lemma: for any string $x \in D_c$ of length at least $3k$, there is a representation $x = uvw$ such that $|u|, |w| \geq k$, $0 < |v| \leq k$ and $uv^*w \subseteq D_c$.
We choose a pumping constant $k$ such that $k \geq |u_iv_i|, |v_iw_i|$ for any $1 \leq i \leq t$.
Then, any $x$ of length at least $3k$ must be equal to $u_iv_i^jw_i$ for some $1 \leq i \leq t$ and $j \in \bbbn$.
Furthermore, as $D_c \subseteq D$, the representation $x = uvw$ must satisfy that $u_i$ is a prefix of $u$, $w_i$ is a suffix of $w$ and $v = v_i^{k'}$ for some $k' \leq k$.
Hence, the string $u_iv_i^{j+k!}w_i$ must be a pumped word of $u_iv_i^jw_i$, and so $u_iv_i^{j+k!}w_i \in D_c$ as well.

Next, we claim that there is a constant $m$ depending only on $k$ such that $u_iv_i^{j+k!}w_i = u_iv_i^jw_i \oplus m$ for all $i$ and large enough $j$.
First, observe that if $u_iv_i^jw_i$ is the $h$-th string in $D$ of its length, then $u_iv_i^{j+k!}w_i$ is also the $h$-th string in $D$ of its length.
Furthermore, the number of strings in $D$ of length $|u_iv_i^jw_i|$ to $|u_iv_i^{j+k!}w_i|-1$ is a constant $m$ depending only on $k$.
Hence, it follows that $u_iv_i^{j+k!}w_i = u_iv_i^jw_i \oplus m$ for all $i$ and large enough $j$.

Therefore, we can conclude that for large enough $x$, if $x \in D_c$, then $x \oplus m$ is also in $D_c$.
In other words, if $\beta(x) = c$, then $\beta(x \oplus m) = \beta(x) = c$. Note that this is true for all colours $c \in \Gamma$. Hence, for each colour $c \in \Gamma$, there is a string $x_c \in D$ and a constant $m_c \in \bbbn$ such that for all $x \geq_{llex} x_c$ with $\beta(x) = c$, we have that $\beta(x) = \beta(x \oplus m_c) = c$.
Then, by letting $M = \prod_{c \in \Gamma} m_c$ and $x_0 = \max_{llex} \{x_c : c \in \Gamma\}$, we have that for all $x \geq_{llex} x_0$, $\beta(x) = \beta(x \oplus M)$.
So, $\beta$ is eventually periodic.
\end{proof}

Hence, we have the following results.

\begin{corollary}\label{cor:auto.linear.growth}
Suppose an infinite regular set $D \subseteq \Sigma^*$ has linear growth,
and let $\alpha, \beta$ be automatic colourings of $D$.
The following are equivalent:
\begin{enumerate}[(a)]
\item Every colour in $\alpha$ also occurs in $\beta$ and every colour which occurs infinitely often in $\alpha$ also occurs infinitely often in $\beta$;
\item $\alpha$ is aqi-reducible to $\beta$;
\item $\alpha$ is quasi-isometrically reducible to $\beta$.
\end{enumerate}
\end{corollary}

The above result does not hold if $D$ has superlinear growth.
We first show a counterexample where Condition (a) holds,
but Condition (c) does not hold, and so Condition (b) does not hold.

\begin{theorem}
Suppose an infinite regular set $D \subseteq \Sigma^*$ has superlinear growth.
There exist automatic colourings $\alpha, \beta$ of $D$ such that the following statements are true:
\begin{enumerate}[(a)]
\item Every colour in $\alpha$ also occurs in $\beta$ and every colour which occurs infinitely often in $\alpha$ also occurs infinitely often in $\beta$;
\item $\alpha$ is {\em not} quasi-isometrically reducible to $\beta$.
\end{enumerate}
\end{theorem}

\begin{proof}
We define $\alpha$ and $\beta$ as follows.
Let $\alpha(x) = 1$ if
$x$ is the length-lexicographically minimum string of its length
and $\alpha(x) = 0$ otherwise.
Let $\beta(x) = 1 - \alpha(x)$.
The range of $\alpha$ and $\beta$ is the same, which is $\{0, 1\}$,
and both $0$ and $1$ occur infinitely often in both $\alpha$ and $\beta$.
Hence, $\alpha$ and $\beta$ satisfy statement (a).

We now show that $\alpha$ is not quasi-isometrically reducible to $\beta$
using Corollary~\ref{cor:nary.seq}.
We first claim that there exists $K \in \bbbn$ such that
for any $x \in  D$, there is some $x' \in D$ such that
$x \leq_{llex} x' <_{llex} x \oplus K$ and $\alpha(x') = 0$.
Let $S = \alpha^{-1}(0)$.
Since $\alpha$ is automatic, then $S$ must be regular.
Furthermore, since $D$ has superlinear growth, then by definition of $\alpha$, 
$S$ must be infinite.
So, by the pumping lemma,
$S$ must have a subset of the form $uv^*w$
for some strings $u, w \in \Sigma^*$ and $v \in \Sigma^+$.
Let $K = |uvw| + 2$.
For each $x \in D$, there is an element $x'' \in S$ such that
$|x| < |x''| \leq |x| + |uvw|$.
Then, $x'' \geq_{llex} x$.
If we also have that $x'' <_{llex} x \oplus K$, then we are done.
Otherwise, $x'' \geq_{llex} x \oplus K$ and so $|x| \leq |x \oplus K \ominus 1| \leq |x''| \leq |x| + K - 2$.
Note that for any length $n$,
there is at most one string $y \in D$ of length $n$
such that $\alpha(y) \neq 0$.
Since $S = \alpha^{-1}(0)$,
there are at most $K - 1$ elements of $D \setminus S$
of length $|x|$ to $|x| + K - 2$.
Hence, there are at most $K - 1$ elements of $D \setminus S$
which are length-lexicographically between $x$ and $x \oplus K \ominus 1$ inclusive.
Since there are $K$ elements in $D$ which are
length-lexicographically between $x$ and $x \oplus K \ominus 1$ inclusive,
one of them must be in $S$.
Therefore, for any $x \in  D$, there is some $x' \in S$ such that
$x \leq_{llex} x' <_{llex} x \oplus K$.
Moreover, by definition of $S$, $\alpha(x') = 0$.

Now suppose that there exists a $C$-quasi-isometry $f$ from $\alpha$ to $\beta$
for some $C$.
Since the quasi-isometry defined by
the automatic structure $(D, <_{llex}, succ)$ is isomorphic to
the quasi-isometry between strings defined by $(\bbbn, <, succ)$,
Corollary~\ref{cor:nary.seq} implies that for any $x \in  D$,
there is some $y \leq_{llex} y' < y \oplus KC$ such that $\beta(y') = 0$.
On the other hand, this implies that
there are at most $KC$ strings of each length,
which implies that there are at most $KCn$ strings of length up to $n-1$.
This contradicts the assumption that $D$ has superlinear growth.
Hence, $\alpha$ is not quasi-isometrically reducible to $\beta$.
\end{proof}

Furthermore, if the growth of $D$ is also polynomial (on top of being superlinear),
we can show that 
there exist automatic colourings $\alpha, \beta$ such that
$\alpha$ is quasi-isometrically reducible to $\beta$ but not automatically.
That is, we can separate the notion of
quasi-isometric reducibility from its automatic counterpart.

\begin{theorem}
Suppose an infinite regular set $D \subseteq \Sigma^*$ has superlinear but polynomial growth.
There exist automatic colourings $\alpha, \beta$ of $D$ such that the following statements are true:
\begin{enumerate}[(a)]
\item $\alpha$ is {\em not} aqi-reducible to $\beta$;
\item $\alpha$ is quasi-isometrically reducible to $\beta$.
\end{enumerate}
\end{theorem}

\begin{proof}
Suppose that $D$ has polynomial growth with degree $c \geq 2$.
Then, by Lemmas~\ref{lem:growth.lower.bound} and \ref{lem:growth.upper.bound},
$D$ must have a subset of the form
$u v_1^* w_1 v_2^* w_2 \ldots v_c^* w_c$
where for each $1 \leq i \leq c$,
$v_i$ is a non-empty string
and the first character after $v_i^*$, if it exists,
is not the same as the first character of $v_i$.

Define $t = v_1^{|v_2| \cdot \ldots \cdot |v_c|}$.
Then, $u t^* w_1 \ldots w_c$ is a subset of $D$
and $|t| = |v_1| \cdot \ldots \cdot |v_c| > 0$.
Let $w = w_1 \ldots w_c$ and
$\alpha, \beta : D \to \{0, 1\}$ be defined such that:
\begin{itemize}
\item $\alpha(x) = 1$ if and only if $x \in u (t^2)^* w$;
\item $\beta(x) = 1$ if and only if $x \in u (t^4)^* w$.
\end{itemize}
We first prove statement (a) and show that
$\alpha$ is not aqi-reducible to $\beta$.
Suppose that $f$ is an automatic $C$-quasi-isometry from $\alpha$ to $\beta$.
By Lemma~\ref{lem:growth.lower.bound},
there are $\Omega(n^{c-1})$ strings in $D$ of length $n = |uw| + (2i+1)|t|$
for any $i \in \bbbn_0$.
Since $|ut^{2i}w| < n < |ut^{2(i+1)}w|$,
there are $\Omega(n^{c-1})$ strings in $D$ which are
length-lexicographically between $ut^{2i}w$ and $ut^{2(i+1)}w$.
Note that $c \geq 2$, and so there exists some $i_0$ such that
for all $i \geq i_0$, $u t^{2i} w \oplus C <_{llex} u t^{2(i+1)} w$.
Then, $f(u t^{2i} w) <_{llex} f(u t^{2(i+1)} w)$.

Define $g : \bbbn_0 \to \bbbn_0$ such that
$f(u t^{2i} w) = u t^{4g(i)} w$ for any $i \in \bbbn_0$.
Such $g$ is well-defined by the definitions of $\alpha$ and $\beta$,
as well as the colour-preserving property of $f$.
Furthermore, since $f$ is automatic, then so is $g$.
From the previous paragraph,
we know that for all $i \geq i_0$, $g(i+1) \geq g(i) + 1$.
Then, for any $i \in \bbbn_0$, $g(i_0+i) \geq g(i_0) + i$.
Therefore, for any $x \in \bbbn_0$,
\[
f(u t^{2(i_0+i)} w) = u t^{4(g(i_0+i))} w \geq_{llex} u t^{4(g(i_0)+i)} w.
\]
This contradicts the assumption that $f$ is automatic.
Hence, an automatic quasi-isometry from $\alpha$ to $\beta$ cannot exist.

We now prove statement (b) and show that
$\alpha$ is quasi-isometrically reducible to $\beta$.

As shown earlier, Lemma~\ref{lem:growth.lower.bound} implies that
there are $\Omega(i^{c-1})$ strings in $D$ which are length-lexicographically
between $ut^{2i}w$ and $ut^{2(i+1)}w$ for any $i \in \bbbn_0$.
Furthermore, by Lemma~\ref{lem:growth.upper.bound},
there are at most $(2|t|+1)O(i^{c-1}) = O(i^{c-1})$ strings in $D$
which are length-lexicographically between $ut^{2i}w$ and $ut^{2(i+1)}w$.
Hence, there exist some $d_1, d_2 \in \bbbr^+$ such that
for all large enough $i$, we have
\begin{equation}\label{eqn:auto.poly.alpha.distribution}
d_1 i^{c-1} \leq |\{x \in D: ut^{2i}w <_{llex} x <_{llex} ut^{2(i+1)}w\}|
\leq d_2 i^{c-1}.
\end{equation}
By a similar argument, there exist some $d_3, d_4 \in \bbbr$ such that
for all large enough $i$, we have
\begin{equation}\label{eqn:auto.poly.beta.distribution}
d_3 i^{c-1} \leq |\{y \in D: ut^{4i}w <_{llex} y <_{llex} ut^{4(i+1)}w\}|
\leq d_4 i^{c-1}.
\end{equation}
Then, there is some $i_0 \in \bbbn$ such that
$(\ref{eqn:auto.poly.alpha.distribution})$ and
$(\ref{eqn:auto.poly.beta.distribution})$ are both true
for all $i \geq i_0$.

We define $f: D \to D$ as follows. For any $i \geq i_0$:
\begin{itemize}
\item $f(ut^{2i}w) = ut^{4i}w$;
\item $f(ut^{2i}w \oplus 1), f(ut^{2i}w \oplus 2), \ldots, f(ut^{2(i+1)}w \ominus 1)$
are distributed evenly between $ut^{4i}w$ and $ut^{4(i+1)}w$
in a non-decreasing manner.
\end{itemize}
Furthermore, for any $x <_{llex} ut^{2i_0}w$,
$f(x)$ is the length-lexicographically minimum string in $D$
such that $\beta(x) = \alpha(x)$.

Let $C = \max\{\lceil d_4/d_1 \rceil, \lceil d_2/d_3 \rceil, j_0\}$
where $ut^{4i_0}w = \min_{llex} D \oplus j_0$.
We show that $f$ is a $C$-quasi-isometry.
First, we show that for any $x <_{llex} ut^{2i_0}w$, $f(x) <_{llex} ut^{4i_0}w$.
Note that $i_0 \geq 1$.
Then, $uw <_{llex} ut^{3i_0}w <_{llex} ut^{4i_0}w$.
Moreover, $\beta(uw) = 1$ and $\beta(ut^{3i_0}w) = 0$.
So, for any $x <_{llex} ut^{2i_0}w$,
the length-lexicographically minimum $z \in D$ such that $\beta(z) = \alpha(x)$
satisfies $z <_{llex} ut^{4i_0}w$.
Hence, $f(x) = z <_{llex} ut^{4i_0}w$.

Then, by definition of $C$,
$f(\min_{llex} D) <_{llex} ut^{4i_0}w \leq_{llex} \min_{llex} D \oplus C$
since $\min_{llex} D <_{llex} ut^{2i_0}w$.
Similarly, if $x <_{llex} ut^{2i_0}w$, then by definition of $C$,
$f(x) \ominus C \leq_{llex} f(x \oplus 1) \leq_{llex} f(x) \oplus C$.
Now suppose that $x \geq_{llex} ut^{2i_0}w$.
Clearly, $f(x \oplus 1) \geq_{llex} f(x) \geq_{llex} f(x) \ominus C$.
Let $i$ be the largest $i'$ such that $ut^{2i'}w \leq_{llex} x$.
Note that $i \geq i_0$.
So, from (\ref{eqn:auto.poly.alpha.distribution}) and
(\ref{eqn:auto.poly.beta.distribution}), the ratio
\[
\frac{|\{y \in D: ut^{4i}w <_{llex} y <_{llex} ut^{4(i+1)}w\}|}
{|\{x \in D: ut^{2i}w <_{llex} x <_{llex} ut^{2(i+1)}w\}|} \leq \frac{d_4}{d_1}.
\]
Hence, by definition of $f$,
$f(x \oplus 1) \leq_{llex} f(x) \oplus \lceil d_4/d_1 \rceil
\leq_{llex} f(x) \oplus C$.
Therefore, $f$ satisfies Condition (a) of
Definition~\ref{defn:auto.C.reduction}.

We now show that $f$ satisfies Condition (b) of
Definition~\ref{defn:auto.C.reduction}.
Suppose that $x \oplus C <_{llex} y$.
By definition of $C$, $y \geq_{llex} ut^{2i_0}w$.
First, consider the case where $x <_{llex} ut^{2i_0}w$,
so that $f(x) <_{llex} ut^{4i_0}w$.
Observe that $f$ is non-decreasing from $ut^{2i_0}w$ onwards,
and so $f(y) \geq_{llex} f(ut^{2i_0}w) = ut^{4i_0}w$.
Then, we have $f(x) <_{llex} ut^{4i_0}w \leq_{llex} f(y)$.

Now we consider the case that $x \geq_{llex} ut^{2i_0}w$.
Let $i$ be the largest $i'$ such that $ut^{2i'}w \leq_{llex} x$.
Clearly, $i \geq i_0$.
If $x = ut^{2i}w$ or $ut^{2(i+1)}w \leq_{llex} y$,
then clearly, $f(x) <_{llex} y$.
So, we can assume that $ut^{2i}w <_{llex} x <_{llex} y <_{llex} ut^{2(i+1)}w$.
By (\ref{eqn:auto.poly.alpha.distribution}) and
(\ref{eqn:auto.poly.beta.distribution}), the ratio
\[
\frac{|\{x \in D: ut^{2i}w <_{llex} x <_{llex} ut^{2(i+1)}w\}|}
{|\{y \in D: ut^{4i}w <_{llex} y <_{llex} ut^{4(i+1)}w\}|} \leq \frac{d_2}{d_3}.
\]
Hence, there are at most $\lceil d_2/d_3 \rceil \leq C$ consecutive strings
$x', x' \oplus 1, \ldots, x' \oplus j$ between $ut^{2i}w$ and $ut^{2(i+1)}w$
which are mapped to the same $y'$ between $ut^{4i}w$ and $ut^{4(i+1)}w$.
So, since $y >_{llex} x \oplus C$, then $f(y) >_{llex} f(x)$.
\end{proof}

On the other hand, if the growth of $D$ is not polynomial, then it must be exponential.
We can separate the notions of quasi-isometric reducibility
from its automatic counterparts for some domains $D$ with exponential growth.

\begin{example}
Let $D \subseteq \{0, 1\}^*$ be defined as follows:
$D$ contains all $\sigma \in \{0, 1\}^*$ of even length,
and all $\tau \in 0^*1^*$ of odd length.
There exist automatic colourings $\alpha, \beta$ of $D$ such that the following statements are true:
\begin{enumerate}[(a)]
\item $\alpha$ is {\em not} aqi-reducible to $\beta$;
\item $\alpha$ is quasi-isometrically reducible to $\beta$.
\end{enumerate}

We define $\alpha, \beta : D \to \{0, 1\}$ as follows:
\begin{itemize}
\item $\alpha(\sigma) = 1$ if and only if $\sigma \in 1^*$ and
$|\sigma|$ is odd.
\item $\beta(\sigma) = 1$ if and only if $\sigma \in 0^*$ and
$|\sigma|$ is odd.
\end{itemize}
We first prove that $\alpha$ is not aqi-reducible to $\beta$.
Suppose, for the sake of contradiction, that
$f$ is a $C$-quasi-isometric reduction from $\alpha$ to $\beta$
which is automatic.
Since $f$ is colour-preserving,
then for any $n \in \bbbn_0$,
$f(1^{2n+1}) = 0^{2m+1}$ for some $m \in \bbbn_0$.
In particular, observe that $f(1^{2n+1}) = 0^{\Theta(n)}$.
Now consider $f(0^{2n+1})$ for large enough $n \in \bbbn_0$.
Note that $0^{2n+1} \oplus (2n+1) = 1^{2n+1}$.
By Condition (b) of Definition~\ref{defn:auto.C.reduction},
$f(0^{2n+1}) \oplus \lfloor (2n+1)/(C+1) \rfloor \leq f(1^{2n+1})$.
On the other hand, by Condition (a) of Definition~\ref{defn:auto.C.reduction},
$f(1^{2n+1}) \leq_{llex} f(0^{2n+1}) \oplus (2n+1)C$.
Hence, $f(0^{2n+1}) = f(1^{2n+1}) \ominus \Theta(n)
= 0^{\Theta(n)} \ominus \Theta(n)$.
In other words, $f(0^{2n+1}) = 1^m 0 \sigma$ for some $\sigma \in \{0, 1\}^*$
such that $|\sigma| = \Theta(\log n)$ and $m + |\sigma| = \Theta(n)$.

Now consider the set $S = f(\{0^{2n+1}:n \in \bbbn_0\})$.
Since $f$ is automatic, then the set $S$ is regular,
and thus satisfies the pumping lemma.
Take some $f(0^{2n'+1})$ for some large enough $n'$.
As shown earlier, $f(0^{2n'+1}) = 1^{m'} 0 \sigma'$
for some  $m' \in \bbbn_0$ and $\sigma' \in \{0, 1\}^*$ such that $|\sigma'| = \Theta(\log n')$.
So, by the pumping lemma,
there are some $u,w \in \{0, 1\}^*$ and $v \in \{0, 1\}^+$
such that $\sigma' = uvw$ and $1^{m'} 0 uv^*w \subseteq S$.
On the other hand, for all large enough $n$,
$f(0^{2n+1})$ has the form $1^m 0 \sigma$
where $|\sigma| = \Theta(\log n)$ and $m + |\sigma| = \Theta(n)$.
This contradicts that $S$ contains all words $1^{m'} 0 uv^iw$
where $i \in \bbbn_0$.
Hence, $\alpha$ is not aqi-reducible to $\beta$.

It remains to show that $\alpha$ is quasi-isometrically reducible to $\beta$.
Let $f: D \to D$ be defined as follows.
Firstly, $f(\epsilon) = f(0) = \epsilon$.
For any $n \in \bbbn_0$:
\begin{itemize}
  \item $f(1^{2n+1}) = 0^{2n+1}$;
  \item $f(1^{2n+1} \oplus 1), f(1^{2n+1} \oplus 2), \ldots,
  f(1^{2(n+1)+1} \ominus 1)$
  are distributed evenly between $0^{2n+1}$ and $0^{2(n+1)+1}$
  in a non-decreasing manner.
\end{itemize}
We shall show that
$f$ is a $1$-quasi-isometric reduction from $\alpha$ to $\beta$.

Note that $\min_{llex} D = \epsilon$.
Clearly, $f(\epsilon) = \epsilon \leq_{llex} \epsilon \oplus 1$.
Furthermore, $f$ is non-decreasing and so
for any $x \in D$, $f(x) \ominus 1 \leq_{llex} f(x) \leq_{llex} f(x \oplus 1)$.
To prove the remaining inequality
in Condition (a) of Definition~\ref{defn:auto.C.reduction},
note that for any $n \in \bbbn_0$,
$0^{2(n+1)+1} = 0^{2n+1} \oplus (2n+2+2^{2n+2})$ and
$1^{2(n+1)+1} = 1^{2n+1} \oplus (2n+4+2^{2n+2})$.
Hence, there are $2n+1+2^{2n+2}$ strings length-lexicographically
between $0^{2n+1}$ and $0^{2(n+1)+1}$,
and $2n+3+2^{2n+2}$ strings between $1^{2n+1}$ and $1^{2(n+1)+1}$.
Since there are fewer strings between $0^{2n+1}$ and $0^{2(n+1)+1}$
than between $1^{2n+1}$ and $1^{2(n+1)+1}$,
by definition of $f$, for any $x \geq_{llex} 1$,
$f(x \oplus 1) = f(x)$ or $f(x) \oplus 1$.
So, $f(x \oplus 1) \leq f(x) \oplus 1$ for all $x \in D$.
Therefore, $f$ satisfies Condition (a) of
Definition~\ref{defn:auto.C.reduction} with $C = 1$.

To prove that $f$ satisfies Condition (b) of
Definition~\ref{defn:auto.C.reduction},
note that for any $n \in \bbbn_0$, $2n+1+2^{2n+2} \geq 5$
and so the number of strings between $1^{2n+1}$ and $1^{2(n+1)+1}$ is less than
two times the number of strings between $0^{2n+1}$ and $0^{2(n+1)+1}$.
Hence, each $y \in D$ is the image of at most $2$ strings $x \in D$.
Since $f$ is non-decreasing, then
$f(x) <_{llex} f(y)$ whenever $x \oplus 1 <_{llex} y$.

Hence, $f$ satisfies Conditions (a) and (b) of
Definition~\ref{defn:auto.C.reduction},
and is a $1$-quasi-isometric reduction from $\alpha$ to $\beta$.
\end{example}


\section{Conclusions and Future Investigations}

The present paper introduced finer-grained notions of 
quasi-isometries between infinite strings, in particular 
requiring the reductions to be recursive. We showed that
permutation quasi-isometric reductions are provably more
restrictive than one-one quasi-isometric reductions,
which are in turn provably more restrictive than 
many-one quasi-isometric reductions.
One result was that general many-one quasi-isometries
are strictly more powerful than recursive many-one 
quasi-isometries, which answers
Khoussainov and Takisaka's open problem.

This work also presented some results on the structures of the
permutation, one-one and many-one quasi-isometric degrees.
It was shown, for example, that there are two infinite strings
whose many-one quasi-isometric degrees have a unique common
upper bound. It was also proven that the partial order
$\Sigma^{\omega}_{mqi}$ is non-dense with respect to 
pairs of mqi-degrees. We conclude with the simple observation
that the class of mqi-degrees does not form a lattice; in 
particular, the mqi-degrees $[0^{\omega}]_{mqi}$ and
$[1^{\omega}]_{mqi}$ do not have a common lower bound.  

Furthermore, this paper also studied quasi-isometries which are automatic.
The main results show that automatic quasi-isometry can be separated from
general quasi-isometry depending on the growth of the domain.

