void task matmul::inner( in    float A[M][P]
                       , in    float B[P][N]
                       , inout float C[M][N] ){
  // tunable parameters specify the 
  // size of subblocks of A, B, C
  tunable int U, X, V;

  // Partition matries into sets of blocks
  blkset Ablks = rchop(A, U, X);
  blkset Bblks = rchop(B, X, V);
  blkset Cblks = rchop(C, U, V);

  // Compute all blocks of C in parallel
  mappar(int i=0 to M/U, int j = 0 to N/V) {
    mapreduce (int k=0 to P/X) {
        matmul( Ablks[i][k]    // recursive
              , Bblks[k][j]    // invocation
              , Cblks[i][j] ); // on subblocks
    }
  }
}

void task matmul::leaf( in    float A[M][P]
                      , in    float B[P][N]
                      , inout float C[M][N] ){
  for (int i=0; i<M; i++)
    for (int j=0; j<N; j++)
      for (int k=0; k<P; k++)
        C[i][j] += A[i][k] * B[k][j];
}
