\section{Equation Discovery in Multi-object Hybrid Systems}
% Multi-object multi-dynamics time series
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% While to date hybrid systems have been researched with single-objects, the more general case of systems with multiple objects whose dynamics and modes affect one another is clearly a more natural setting.
% % Multiple objects may exist and interact with each other. 
% As with a single-object setting, the motion dynamics in hybrid dynamical systems of each object are not only influenced by its own evolving nature but also by external influences of potentially interacting objects.
% In this section, we extend our method to multi-object scenarios with multiple motion modes. 

While equation discovery in hybrid dynamical systems has been researched in single-object scenarios, the more general setting of systems with multiple potentially interacting objects 
is an unexplored yet natural setting.
In this section, we elaborate on how our model can be extended for multi-object scenarios, and present AMORtized Equation discovery in MultI-Object hybrid systems, a.k.a. AMORE-MIO. We first introduce how our method models interactions and then introduce the whole framework of AMORE-MIO.

% When the systems are multi-object scenarios, the observations $\mathbf{y}$ are $\mathbf{y}:= \mathbf{y}_{1:T}^{1:N}$ for $T$ time steps and $N$ objects. Besides, mode variables are defined as $\mathbf{z} := \mathbf{z}_{1:T}^{1:N}=\{z_t^1, \dots, z_t^N\}_{t=1}^T$,  where $ z_t^n \in \{1, \dots, K\}$ denotes the mode for each time step $ t \in (1, \dots, T)$ and each object $ n \in (1, \dots, N)$. Count variables are $\mathbf{c}:= \mathbf{c}_{1:T}^{1:N} = \{c_t^1, \dots, c_t^N\}_{t=1}^T$, where each $c_t^n \in (1, \dots, M)$ models the run-length of the current active mode for each object $n$ and each time step $t$.

\vspace{-5pt}
\paragraph{Edge variables.} Assume that $N$ objects and $K$ motion modes exist in multi-object hybrid systems. Inspired by~\citet{kipf2018neural,liu2023graph}, we model interactions between objects by latent edge variables $\mathbf{e}=\mathbf{e}_{1:T}^{1:N^2}=\{e_t^1, \cdots, e_t^{N^2}\}_{t=1}^T$ including self-loop, thus totally $N^2$ for $N$ objects.
For each pair of objects, interactions $e_t^{m\rightarrow n}$ model whether object $m$ interacts with object $n$ at time $t$.
The edge variables are modeled in a latent temporal graph $\mathcal{G}_t=(\mathcal{V}_t, \mathcal{E}_t)$, where edges $e_t^{m\rightarrow n} \in \mathcal{E}_t$ and nodes $\mathcal{V}_t$ summarize states of objects. For instance, $\mathbf{v}^m_t=\{z^m_t, c^m_t, \mathbf{y}^m_t\}$ for $\mathbf{v}^m_t \in \mathcal{V}_t$ defines one graph node summarizing states of object $m$ at time $t$ which includes observation $\{\mathbf{y}^m_t\}$ and latent states $\{z^m_t, c^m_t\}$.
Edge $e_t^{m\rightarrow n}$ signals interaction relationships between node $\mathbf{v}_t^m$ and node $\mathbf{v}_t^n$ in graph $\mathcal{G}_t$. 

\vspace{-5pt}
\paragraph{Object-shared and mode-specific equation discovery.} We set the number of all possible motion modes as $K$ in multi-object hybrid dynamical systems. The $K$ motion modes are shared across $N$ objects, which are implemented by $K$ sets of candidate basis functions $\Theta(\mathbf{y}_t) = (\Theta_1(\mathbf{y}_t), \cdots, \Theta_K(\mathbf{y}_t))$ and learnable coefficient weights $\mathbf{w} = (\mathbf{w}_1, \cdots, \mathbf{w}_K)$. Each mode $k \in [K]$ has its own $\Theta_k(\mathbf{y}_t)$ and $\mathbf{w}_k$ as in Sec.~\ref{sec: Equation Discovery in Hybrid Systems}.
\cameraR{Thus there are K sets of learnable weights for learning dynamics of K modes across N objects. Both the time and space complexity of AMORE-MIO regarding learnable weights of basis functions is $\mathcal{O}(K)$.}
% When training, the model learns to categorize the motion dynamics of each object by all or a portion of $K$ motion modes. 
For instance, the mode variable $z_t^n=k$ of the object $n$ at time $t$ indexes $\Theta_k(\mathbf{y}_t)$ and $\mathbf{w}_k$ which together form equations to represent the dynamics of mode $k$.
Different from single-object scenarios, the mode-switching behaviors of each object are not only influenced by their own evolving nature but also by external influences of potentially interacting objects. 
% We will detail how interactions modeled by edge variables drive the mode transition behaviors in the generative model.
We model the influences of interactions on the mode-switching behaviors between objects, which are detailed in the following generative model of AMORE-MIO.
% Next, we will detail how to model interactions and how interactions drive the mode transition behaviors.

% \vspace{-5pt}
\paragraph{Generative model for amortized equation discovery in multi-object settings.} Assuming Markovian dynamics, the joint generative probability of multi-object hybrid systems in AMORE-MIO is calculated as
\begin{align}
&p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c})=\underbrace{p(\mathbf{y}_{1}^{1:N}|\mathbf{z}_{1}^{1:N})p(\mathbf{z}_{1}^{1:N})}_{\rm{Initial\,\,States}}\cdot \notag \\
% &=p(\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2},\mathbf{z}_{1:T}^{1:N},\mathbf{c}_{1:T}^{1:N}) 
&\prod_{t=2}^{T} \!\bigg[p(\mathbf{y}_{t}^{1:N}|\mathbf{y}_{t-1}^{1:N},\mathbf{z}_{t}^{1:N})p(\mathbf{z}_{t}^{1:N}|\mathbf{z}_{t-1}^{1:N},\mathbf{y}_{t-1}^{1:N},\mathbf{c}_{t}^{1:N}\!,\mathbf{e}_{t}^{1:N^2})\!\! \notag\\ 
    & p(\mathbf{c}_{t}^{1:N}|\mathbf{c}_{t-1}^{1:N},\mathbf{z}_{t-1}^{1:N})p(\mathbf{e}_{t}^{1:N^2}|\mathbf{e}_{t-1}^{1:N^2},\mathbf{c}_{t-1}^{1:N},\mathbf{z}_{t-1}^{1:N},\mathbf{y}_{t-1}^{1:N})\!\bigg]
\label{eq:joint-full-multiple-object}
\end{align}
where the initial states and count transition probability are defined as in Eq.~\ref{eq:joint-full-single-object} of single-object scenarios but with $n$ objects. For later time steps $t\geq 2$, the edge transition probability $p(\mathbf{e}_{t}^{1:N^2}|\mathbf{e}_{t-1}^{1:N^2},\mathbf{c}_{t-1}^{1:N},\mathbf{z}_{t-1}^{1:N},\mathbf{y}_{t-1}^{1:N})$ models how the edge variables evolve depending on all the states at the previous time step. We model the influences of interactions on the mode transition probability $p(\mathbf{z}_{t}^{1:N}|\mathbf{z}_{t-1}^{1:N},\mathbf{y}_{t-1}^{1:N},\mathbf{c}_{t}^{1:N},\mathbf{e}_{t}^{1:N^2})$, which characterizes the mode-switching behaviors of multi-object hybrid dynamical systems. Based on the updated modes of each object, the observation transition probability $p(\mathbf{y}_{t}^{1:N}|\mathbf{y}_{t-1}^{1:N},\mathbf{z}_{t}^{1:N})$ can be factorized over objects $\prod_{n=1}^{N}p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n})$ where equations of each mode are amortized and learned by all segments from all objects belonging to the same mode.
The further expansion over objects of the joint generative probability is in Appendix~\ref{app: Expansion of Generative Model over Objects of AMORE-MIO}.
For inference of latent mode, count, and edge variables, we conduct posterior approximate inference for edge variables $q_{\phi_e}(\mathbf{e}|\mathbf{y})$ conditioned on observations $\mathbf{y}$, and then conduct exact inference of mode and count variables $p_\theta(\mathbf{z},\mathbf{c}|\mathbf{y},\tilde{\mathbf{e}})$ conditioned on observations $\mathbf{y}$ and the approximate edge variables $\tilde{\mathbf{e}} \sim q_{\phi_e}(\mathbf{e}|\mathbf{y})$.
The generative and inference models of AMORE-MIO are illustrated in Fig.~\ref{AMORE-MIO}.
Learnable parameters of AMORE-MIO are optimized by maximizing the evidence lower bound with sparse regularization on the learnable coefficient weights
\begin{align}
&\mathcal{L}_\textrm{ AMORE-MIO} = -{\rm log}\,p_\theta(\mathbf{y}) + \notag \\
&\;\;\;\;\;\;\;\;D_{K\!L}\left[q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\,\|\,p_\theta(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\right] + ||\mathbf{w}||_{1}
% &= 
% - \mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}\left[{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})\right]-H(q_\phi(\mathbf{e}|\mathbf{y})) + ||\mathbf{w}||_{1}.
\end{align}
