\section{More Details of AMORE}
\subsection{Neural Network Implementation}
\label{app: Neural Network Implementation of AMORE}
We use neural networks to model the joint generative probabilities of hybrid systems in our model, i.e. Eq.~\eqref{eq:joint-full-single-object}. For the initial states, we model the initial prior distributions as:
\begin{align*}
p(z_1) &= \rm{Cat}(z_1; \bm{\pi}), \\
p(\mathbf{y}_1|z_1) &= \mathcal{N}(\mathbf{y}_1;\bm{\mu}_{z_1};\bm{\Sigma}_{z_1}),
% \label{eq:initial-states-implm}
\end{align*}
where $\rm{Cat}$ and $\mathcal{N}$ denote categorical and multivariate Gaussian distributions, respectively. We set the prior distribution of $p(z_1)$ as uniform to encourage diversity.

\paragraph{Count variables and count transition probability.} To implement the count variables, we set a categorical distribution over $\{d_{\rm min}, \cdots, d_{\rm max}\}$ for each mode, where $d_{\rm min}$ and $d_{\rm max}$ are the minimal and maximal numbers of time steps before making a mode switch. The count transition probability $p(c_t|c_{t-1},z_{t-1})$ is modeled as a learnable matrix $\mathbf{P} \in \mathbb{R}^{K\times (d_{\rm max}-d_{\rm min}+1)}$, which is fixed across all time steps. Each term $\rho_k(c)$ in $\mathbf{P}$ represents the probability of the $k$-th mode switching to another mode when its current count is $c$. The probability of a count increment at count $c$ for mode $k$ can be calculated as
\begin{align*}
\mu_k(c) = 1 - \frac{\rho_k(c)}{\sum_{d=c}^{d_{\rm max}}\rho_k(d)}.
\end{align*}
The count transition probability is thus defined as
\begin{align*}
\!\! \!  p(c_{t}|c_{t-1}, z_{t-1}\!=\!k)\!=\!\!
\begin{cases}\!
\mu_k(c_{t-1})    &  \!\!\!\! {\rm if}\;c_{t}\!=\!c_{t-1}\!+ 1\!\\
1\!-\!\mu_k(c_{t-1})  & \!\!\!\!{\rm if}\;c_{t} = 1
\! \end{cases}.
\end{align*}

\paragraph{Mode variables and mode transition probability.} Since the mode variables $z_t$ take one out of $K$ possible values, we model them as categorical variables, parameterized by mode transition matrix $\mathbf{T}_t$ at timestep $t$. The mode transition probability is modeled as
\begin{align*}
\!\! \!  p(z_{t}|z_{t-1}, c_{t}, \mathbf{y}_{t-1}\!)\!=\!
\begin{cases}
\delta_{z_{t}=z_{t-1}}    &  \!\!\!\! {\rm if}\;c_{t} > 1 \\
{\rm Cat}(z_{t};  \mathbf{T}_t )  & \!\!\!\!{\rm if}\;c_{t} = 1
\end{cases},
% \label{eq:mode-transition-single-object}
\end{align*}
where we resample the modes or preserve them depending on whether count variables are reset to 1 or not. We model the parameters $\mathbf{T}_t$ of the categorical distributions with a neural network, i.e. a simple MLP, $\mathbf{T}_t = f_z(\mathbf{y}_{t-1})$ that takes as input the observations. The network returns a $K \times K$ transition matrix per time step $t$, where rows correspond to past modes $z_{t-1}$ and columns current modes $z_t$. Each term $\tau_t^{j,k}$ in $\mathbf{T}_t$ represents the probability of mode $j$ switching to mode $k$ at timestep $t$. To satisfy the positivity $\tau_t^{j,k} > 0, \; \forall j,k=1,\cdots,K$ and $\ell_1$ constraints $\sum_{k} \tau_t^{j,k}=1, \; \forall j=1,..., K$, we apply a tempered softmax after $f_z$, i.e. $\mathcal{S}_{\tau_z} \circ f_z(\cdot)$.

\subsection{Inference Model of AMORE}
\label{app: Inference Model of AMORE}
We perform conditionally exact inference for the two discrete latent variables, i.e. modes $\mathbf{z}_{1:T}$ and counts $\mathbf{c}_{1:T}$, similar to the forward-backward procedure for HMM~\citep{eddy1996hidden}.
Conditioned on observations $\mathbf{y}_{1:T}$, the posterior joint distribution $p_\theta(\mathbf{z}_{1:T},\mathbf{c}_{1:T}|\mathbf{y}_{1:T})$ is calculated by modifying the forward-backward recursions to handle the joint hierarchical latent variables. Specifically, the forward $\alpha_t$ and backward $\beta_t$ parts are defined as
\begin{align*}
\alpha_t(z_t,c_t) &= p(z_t,c_t,\mathbf{y}_{1:t}), \\
\beta_t(z_t,c_t) &= p(\mathbf{y}_{t+1:T}|\mathbf{y}_{t},z_t,c_t).
\end{align*}
Specifically, the posterior joint probability of mode and count variables $\mathbf{z}$, $\mathbf{c}$ conditioned on observations $\mathbf{y}$ is calculated as
\begin{align*}
    p(z_t,c_t|\mathbf{y}_{1:T}) & \propto p(z_t, c_t,\mathbf{y}_{1:T}) \\
    &= \underbrace{p(z_t,c_t,\mathbf{y}_{1:t})}_{Forward}\underbrace{p(\mathbf{y}_{t+1:T}|\mathbf{y}_{t},z_t,c_t)}_{Backward} \\
    &= \alpha_t(z_t,c_t)\cdot\beta_t(z_t,c_t).
\end{align*}
The derivatives of the forward section $\alpha_t(z_t,c_t)$ are
\begin{align*}
    \alpha_1(z_1,c_1) 
    &= p(z_1, c_1, \mathbf{y}_1) \\
    &= \delta_{c_1=1} p(z_1)p(\mathbf{y}_1|z_1), \\
    \underline{\alpha_t(z_t, c_t)} &= p(z_t,c_t,\mathbf{y}_{1:t}) \\
    &= \sum_{z_{t-1},c_{t-1}}p(z_t,c_t,\mathbf{y}_{1:t},z_{t-1},c_{t-1}) \\
    &= \sum_{z_{t-1},c_{t-1}}p(z_{t-1},c_{t-1},\mathbf{y}_{1:t-1})p(c_{t}|c_{t-1},z_{t-1})p(z_{t}|z_{t-1},c_{t},\mathbf{y}_{t-1})p(\mathbf{y}_{t}|\mathbf{y}_{t-1},z_{t}) \\
    &= p(\mathbf{y}_{t}|\mathbf{y}_{t-1},z_{t})\sum_{z_{t-1},c_{t-1}}\underline{\alpha_{t-1}(z_{t-1},c_{t-1})}p(c_{t}|c_{t-1},z_{t-1})p(z_{t}|z_{t-1},c_t,\mathbf{y}_{t-1})\\
    &= p(\mathbf{y}_{t}|\mathbf{y}_{t-1},z_{t})\Bigg[\delta_{c_t=1}\sum_{z_{t-1}}p(z_t|z_{t-1},c_t,\mathbf{y}_{t-1})\sum_{c_{t-1}}(1-\mu_{z_{t-1}(c_{t-1})})\alpha_{t-1}(z_{t-1},c_{t-1}) \\
    & + \delta_{\substack{z_{t-1} = z_{t} \\ c_t>1 \\ c_{t-1} = c_{t} - 1}}\mu_{z_{t-1}}(c_{t-1})\alpha_{t-1}(z_{t-1},c_{t-1}) \Bigg],
\end{align*}
where $\alpha_t(z_t,c_t)$ can be expressed by $\alpha_{t-1}(z_{t-1},c_{t-1})$ recursively with states transitions.

The derivatives of the backward section $\beta_t(z_t,c_{t})$ are
\begin{align*}
    \beta_T(z_T,c_T) &= 1 \\
    \underline{\beta_t(z_t,c_t)} &= p(\mathbf{y}_{t+1:T}|\mathbf{y}_{t},z_t,c_t) \\
    &= \sum_{z_{t+1},c_{t+1}}p(\mathbf{y}_{t+1:T},z_{t+1},c_{t+1} |\mathbf{y}_{t}, z_{t}, c_{t})\\
    &= \sum_{z_{t+1},c_{t+1}} p(c_{t+1}|c_{t},z_{t})p(z_{t+1}|z_{t},c_{t},\mathbf{y}_{t})p(\mathbf{y}_{t+1}|\mathbf{y}_{t},z_{t+1})p(\mathbf{y}_{t+2:T}|\mathbf{y}_{t+1}, z_{t+1}, c_{t+1}) \\
    &= \sum_{z_{t+1},c_{t+1}} p(c_{t+1}|c_{t},z_{t})p(z_{t+1}|z_{t},c_{t+1},\mathbf{y}_{t})p(\mathbf{y}_{t+1}|\mathbf{y}_{t},z_{t+1})\underline{\beta_{t+1}(z_{t+1},c_{t+1})} \\
    &= \delta_{\substack{c_{t+1}=1 \\ c_t \geq d_{\rm min}}}(1-\mu_{z_t}(c_t))\sum_{z_{t+1}}p(z_{t+1}|z_{t},c_{t+1},\mathbf{y}_{t})p(\mathbf{y}_{t+1}|\mathbf{y}_{t},z_{t+1})\beta_{t+1}(z_{t+1},c_{t+1}) \\
    &+ \delta_{\substack{c_{t+1} = c_t +1 \\ z_{t+1}=z_t}}\mu_{z_t}(c_t)p(\mathbf{y}_{t+1}|\mathbf{y}_{t},z_{t+1})\beta_{t+1}(z_{t+1},c_{t+1}),
\end{align*}
where $\beta_t(z_t,c_t)$ can be computed via $\beta_{t+1}(z_{t+1},c_{t+1})$ recursively with states transitions.

\subsection{Derivation of Optimization Objective}
\label{app: Derivation of Training Objective of AMORE}
The optimization objective of our model is to maximize the observation likelihood ${\rm log}\,p(\mathbf{y})$ with sparse regularization on coefficients of candidate basis functions, where the observation likelihood ${\rm log}\,p(\mathbf{y})$ can be calculated as
\begin{align*}
\rm log\,p(\mathbf{y}) 
% &= \nabla{\rm log}\,p(\mathbf{x},\mathbf{y})
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[ {\rm log}\,p(\mathbf{y})\right] \\
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[ {\rm log}\,p(\mathbf{y},\mathbf{z},\mathbf{c})\right] - \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[ {\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y})\right] \\
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[ {\rm log}\,p(\mathbf{y},\mathbf{z},\mathbf{c})\right],
\end{align*}
where $\mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[ {\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y})\right]$ is calculated as 
\begin{align*}
\mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[ {\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y})\right] = \int p(\mathbf{z},\mathbf{c}|\mathbf{y})\frac{ {\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y})}{p(\mathbf{z},\mathbf{c}|\mathbf{y})}d(\mathbf{z},\mathbf{c}) =  \int{\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y})d(\mathbf{z},\mathbf{c}) =   1 = 0.
\end{align*}
Following Markovian property, we expand $ {\rm log}\,p(\mathbf{y},\mathbf{z},\mathbf{c})$ over time and calculate it as
\begin{align*}
     {\rm log}\,p(\mathbf{y},\mathbf{z},\mathbf{c}) &=  \,{\rm log}\,p(\mathbf{y}_{1:T},\mathbf{z}_{1:T},\mathbf{c}_{1:T}) \\
    &=  \,{\rm log}\!\left[p(\mathbf{y}_{1}|z_{1})p(z_{1})\right] + \sum_{t=2}^{T} \,{\rm log}\!\left[p(\mathbf{y}_{t}|\mathbf{y}_{t-1},z_{t})p(z_{t}|z_{t-1},c_{t},\mathbf{y}_{t-1})p(c_{t}|c_{t-1},z_{t-1})\right].
\end{align*}
Finally, combined with expectations, ${\rm log}\,p(\mathbf{y})$ can be calculated as
\begin{align*}
      {\rm log}\,p(\mathbf{y})&=\mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y})}\left[  {\rm log}\,p(\mathbf{y},\mathbf{z},\mathbf{c})\right],\\
    &= \mathbb{E}_{p(\mathbf{z}_{1:T},\mathbf{c}_{1:T}|\mathbf{y}_{1:T})}\left[  {\rm log}\,p(\mathbf{y}_{1:T},\mathbf{z}_{1:T},\mathbf{c}_{1:T})\right] \\
    &= \sum_{k}p(z_1=k|\mathbf{y}_{1:T})   \,{\rm log}\left[p(\mathbf{y}_{1}|z_{1})p(z_{1}=k)\right] \\
    &\,\,\,\,\,\,\,+ \sum_{t=2}^{T}\sum_{k,j,u,v}\!\! \xi(k,j,u,v)\,  \,{\rm log}\!\left[p(\mathbf{y}_{t}|\mathbf{y}_{t-1},z_{t}=k)p(z_{t}\!=\!k|z_{t-1}\!=\!j, c_{t}\!=\!v,\mathbf{y}_{t-1})p(c_{t}\!=\!v|c_{t-1}\!=\!u,z_{t-1}\!=\!j)\right]\\
    &= \sum_{k}\gamma(k)\,   \,{\rm log}\!\left[B_1(k)\cdot \pi(k)\right] \\
    &\,\,\,\,\,\,\,+\sum_{t=2}^{T}\sum_{k,j,u,v}\!\!\xi(k,j,u,v)\,  \,{\rm log}\!\left[B_t(k)\cdot 
    A_t(k,j,v) \cdot C_t(j,u,v)\right]
    % &\,\,\,\,\,\,\,+ \sum_{t=2}^{T}\sum_{\mathbf{k},\mathbf{j},\mathbf{q},\mathbf{p},\mathbf{s}}\xi(\mathbf{k},\mathbf{j},\mathbf{q},\mathbf{p},\mathbf{s})\,\,\nabla\,{\rm log}\!\left[B_t(\mathbf{k})\cdot C_t(\mathbf{q},\mathbf{p},\mathbf{j})\cdot A_t(\mathbf{k},\mathbf{j},\mathbf{q},\mathbf{s})\right]
\end{align*}
where $\pi(k)$, $\gamma(k)$, $\xi(k,j,u,v)$, $B_t(k)$, $A_t(k,j,v)$, and $C_t(j,u,v)$ are defined as
\begin{align*}
\pi(k) &= p(z_{1}=k),\\
\gamma(k) &= p(z_1=k|\mathbf{y}_{1:T}),\\
\xi(k,j,u,v) &= p(z_t\!\!=\!k,z_{t-1}\!\!=\!j,c_t\!=\!v,c_{t-1}\!=\!u|\mathbf{y}_{1:T}), \\
B_t(k) &= p(\mathbf{y}_{t}|\mathbf{y}_{t-1},z_{t}=k),\\
A_t(k,j,v) &= p(z_{t}\!=\!k|z_{t-1}\!=\!j, c_{t}\!=\!v,\mathbf{y}_{t-1}),\\
C_t(j,u,v) &= p(c_{t}\!=\!v|c_{t-1}\!=\!u,z_{t-1}\!=\!j).
\end{align*}
$\pi(\mathbf{k})$ is the initial discrete mode probability. $B_t(k)$ is the continuous state transition probability conditioned on different types of discrete modes $k$. $A_t(k,j,v)$ is the discrete mode transition probability. $C_t(j,u,v)$ is the mode duration count transition probability. Besides, $\gamma(k) = p(z_1=k|\mathbf{y}_{1:T})$ and $\xi(k,j,u,v) = p(z_t\!\!=\!k,z_{t-1}\!\!=\!j,c_t\!=\!v,c_{t-1}\!=\!u|\mathbf{y}_{1:T})$ can be calculated similarly to the forward and backward algorithm in HMMs~\citep{eddy1996hidden} which is detailed in Appendix~\ref{app: Inference Model of AMORE}.


\section{More Details of AMORE-MIO}
\subsection{Expansion of Generative Model over Objects}
\label{app: Expansion of Generative Model over Objects of AMORE-MIO}
The joint generative probability of AMORE-MIO for multi-object hybrid systems is expanded over objects as
\begin{align*}
p(\mathbf{y}, \mathbf{z}, \mathbf{c}, \mathbf{e}) &=
\underbrace{\prod_{n=1}^N \!p(\mathbf{y}_1^n|z_1^{n}) \cdot \prod_{n=1}^N \!p(z_1^n) \cdot \prod_{n=1}^{N}\prod_{m=1}^{N}\!p(e_1^{m\rightarrow n})}_{\rm{Initial\,\,states}} \cdot \prod_{t=2}^{T} \Bigg[ \prod_{n=1}^{N} p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n}) \cdot \prod_{n=1}^{N} p(c_{t}^{n}|c_{t-1}^{n},z_{t-1}^{n}) \cdot \\
&\;\;\;\;\;\;\prod_{n=1}^{N}\!\sum_{m=1}^{N}p(z_{t}^{n}|z_{t-1}^{m}, c_{t}^{n}, e_{t}^{m\rightarrow n}, \mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n}) \cdot
\prod_{n=1}^{N}\!\sum_{m=1}^{N}p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, \mathbf{v}_{t-1}^m, \mathbf{v}_{t-1}^n)\Bigg],
% \label{eq:joint-full-multiple-object-expansion}
\end{align*}
where in the initial states, we model for each object $n$ an initial mode and observation distributions, i.e. $p(z_1^n)$ and $p(\mathbf{y}_1^n|z_1^{n})$. For each pair of interactions, $p(e_1^{m\rightarrow n})$ models the initial edge distribution. For later time steps $t \geq 2$, $p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, \mathbf{v}_{t-1}^m, \mathbf{v}_{t-1}^n)$ models the edge variable transition probability conditioned on node states $\{\mathbf{v}_{t-1}^m, \mathbf{v}_{t-1}^n\}$ in graph $\mathcal{G}_t$. $p(z_{t}^{n}|z_{t-1}^{m}, c_{t}^{n}, e_{t}^{m\rightarrow n}, \mathbf{y}_{t-1}^{m,n})$ models how the modes of objects are affected by the modes of all other objects, conditioned on count variables $c_{t}^{n}$, edge variables $e_{t}^{m\rightarrow n}$, and observations $\{\mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n}\}$. $p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n})$ and $p(c_{t}^{n}|c_{t-1}^{n},z_{t-1}^{n})$ model for each object an observation transition probability and count variable transition probability.

\subsection{Neural Network Implementation}
\label{app: Neural Network Implementation of AMORE-MIO}
Implementations of $p(\mathbf{y}_1^n|z_1^{n})$, $p(z_1^n)$, $p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n})$, and $p(c_{t}^{n}|c_{t-1}^{n},z_{t-1}^{n})$ in multi-object scenarios are the same as those in single-object scenarios. Next, we elaborate on how we implement the other terms, i.e. $p(e_1^{m\rightarrow n})$, $p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, \mathbf{v}_{t-1}^m, \mathbf{v}_{t-1}^n)$, and $p(z_{t}^{n}|z_{t-1}^{m}, c_{t}^{n}, e_{t}^{m\rightarrow n}, \mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n})$.

\paragraph{Edge variables and edge transition probability.} We implement the edge variable $\mathbf{e}$ as a categorical distribution over $\{1, \cdots, L\}$ for $L$ possible interaction types including a \emph{no-interaction} type. We set the prior distribution to be higher for \emph{no-interaction} edges in $p(e_1^{m\rightarrow n})$ to encourage sparse graphs. The edge transition probability is modeled as
\begin{align*}
p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, \mathbf{v}_{t-1}^m, \mathbf{v}_{t-1}^n) = {\rm Cat}(e_t^{m\rightarrow n}; \mathcal{S}_{\tau_e}(f_e(e_{t-1}^{m\rightarrow n}, \mathbf{v}_{t-1}^m, \mathbf{v}_{t-1}^n))),
% \label{eq:edge-transition}
\end{align*}
where The neural network $f_e$ takes $e_{t-1}^{m\rightarrow n}$, $\mathbf{v}_{t-1}^m$, and $\mathbf{v}_{t-1}^n$ as input and outputs the probabilities of all possible edge types at time step $t$, which are further post-processed by a tempered softmax function $\mathcal{S}_{\tau_e}$ with temperature $\tau_e$ to ensure normalization. In practice, the edge transition network $f_e$ is a single hidden layer MLP.

\paragraph{Extension of mode transition probability.} After getting $e_{t}^{m\rightarrow n}$ by the edge transition probability, we show how $e_{t}^{m\rightarrow n}$ affects the mod-switching behaviors. We model the mode transition probability in multi-object hybrid systems as
\begin{align*}
& p(z_{t}^n|z_{t-1}^m, c_{t}^n, e_t^{m \rightarrow n}, \mathbf{y}_{t-1}^m, \mathbf{y}_{t-1}^n\!) =\! \begin{cases}
\delta_{z_{t}^n=z_{t-1}^n}    &  \!\!\!\! {\rm if}\;c_{t}^n \!>\! 1 \\
{\rm Cat}(z_{t}^n; \mathcal{S}_{\tau_z}(\sum_{l} e_{t,l}^{m\rightarrow n} f_l(\mathbf{y}_{t-1}^m, \mathbf{y}_{t-1}^n))  & \!\!\!\!{\rm if}\;c_{t}^n \!=\! 1
\end{cases}\!,
% \label{eq:mode-transition-multiple-object}
\end{align*}
where $\delta$ and $\mathcal{S}_{\tau_z}$ are a Kronecker function and a tempered softmax function. $e_{t,l}^{m\rightarrow n}$ denotes the probability of each edge type $l$. We set a neural network $f_l$ for each edge type $l$ (totally $L$) to model different interaction effects, which are normalized by $e_{t,l}^{m\rightarrow n}$ to aggregate effects from all the interaction types.

\subsection{Inference Model of AMORE-MIO}
\label{app: Inference Model of AMORE-MIO}
\paragraph{Approximate inference of edge variables.}We use a graph neural network $f_{\phi_e}(\mathbf{y})$ to conduct approximate inference of edge variables $\mathbf{e}$, i.e. $q_{\phi_e}(\mathbf{e}|\mathbf{y})$. The node embeddings in the latent graph $\mathcal{G}_t$ are the observations $\mathbf{y}$, and the edge embeddings are calculated by two rounds of message-passing
\begin{align*}
                      &\mathbf{h}_{n}^1 = f_{\phi_e}^{\rm emb}(\mathbf{y}_t^{n}), \\
v\rightarrow e\!: \,\,&\mathbf{h}_{m\rightarrow n}^1 = f_{\phi_z}^{e,1}([\mathbf{h}_{m}^1, \mathbf{h}_{n}^1]), \\
e\rightarrow v\!: \,\,&\mathbf{h}_{n}^2 = f_{\phi_e}^{v,1}(\sum_{m=1}^N \mathbf{h}_{m\rightarrow n}^1), \\
v\rightarrow e\!: \,\,&\mathbf{h}_{m\rightarrow n}^2 = f_{\phi_e}^{e,2}([\mathbf{h}_{m}^2, \mathbf{h}_{n}^2]),
\end{align*}
where $\mathbf{h}_{m\rightarrow n}^2$ is further processed by a tempered Gumbel softmax ${\rm softmax}((\mathbf{h}_{m\rightarrow n}^2 + \mathbf{g})/\tau)$ to achieve $q_{\phi_e}(\mathbf{e}|\mathbf{y})$, to be more specific $q_{\phi_e}(e_t^{m\rightarrow n}|\mathbf{y}_t^m,\mathbf{y}_t^n)$. Here, we use continuous relaxation and reparameterization of discrete distributions for gradient backpropagation~\cite{kipf2018neural}. $\mathbf{g}$ is a vector sampled from a ${\rm Gumbel}(0,1)$ distribution and the softmax temperature $\tau$ controls relaxation smoothness.

\paragraph{Exact inference of mode and count variables.} Given the approximate edge variables $\tilde{\mathbf{e}}\sim q_{\phi_e}\!(\mathbf{e}|\mathbf{y})$, we do exact inference of the mode and count variables $p_\theta(\mathbf{z},\mathbf{c}|\mathbf{y},\tilde{\mathbf{e}})$. Similar to the single-object scenarios, the conditional joint distribution is calculated by modifying the forward-backward algorithm. Specifically, the forward $\alpha_t$ and backward $\beta_t$ are calculated as
\begin{align*}
\!\alpha_t(\mathbf{z}_t^{1:N},\mathbf{c}_t^{1:N})\! &= \!p(\mathbf{z}_t^{1:N},\mathbf{c}_t^{1:N},\mathbf{y}_{1:t}^{1:N},\mathbf{e}_{1:t}^{1:N^2}), \\
\!\beta_t(\mathbf{z}_t^{1:N},\mathbf{c}_t^{1:N})\! &= \!p(\mathbf{y}_{t+1:T}^{1:N}|\mathbf{y}_{t}^{1:N},\mathbf{z}_t^{1:N},\mathbf{c}_t^{1:N},\mathbf{e}_{t}^{1:N^2}).
\end{align*}

Specifically, the joint probability of mode and count variables $\mathbf{z}$, $\mathbf{c}$ conditioned on observations $\mathbf{y}$ and approximate edge variables $\mathbf{e}$ is calculated as
\begin{align*}
    p(\mathbf{z}_t,\mathbf{c}_t|\mathbf{y}_{1:T},\mathbf{e}_{1:T}) & \propto p(\mathbf{z}_t,\mathbf{c}_t,\mathbf{y}_{1:T},\mathbf{e}_{1:T}) \\
    &= \underbrace{p(\mathbf{z}_t,\mathbf{c}_t,\mathbf{y}_{1:t},\mathbf{e}_{1:t})}_{Forward}\underbrace{p(\mathbf{y}_{t+1:T},\mathbf{e}_{t+1:T}|\mathbf{y}_t,\mathbf{z}_t,\mathbf{c}_t}_{Backward}) \\
    &= \alpha_t(\mathbf{z}_t,\mathbf{c}_t)\cdot\beta_t(\mathbf{z}_t,\mathbf{c}_t).
\end{align*}
The derivatives of the forward section $\alpha_t(\mathbf{z}_t,\mathbf{c}_t)$ is calculated as:
\begin{align*}
    \alpha_1(\mathbf{z}_1, \mathbf{c}_1) 
    &= p(\mathbf{z}_1, \mathbf{c}_1, \mathbf{y}_1, \mathbf{e}_1) \\
    &= 
    p(\mathbf{z}_1^{1:N}, \mathbf{c}_1^{1:N}, \mathbf{y}_1^{1:N}, \mathbf{e}_1^{1:N^2})\\
    &= \delta_{\mathbf{c}_1^{1:N}=1} p(\mathbf{z}_1^{1:N})p(\mathbf{e}_1^{1:N^2})p(\mathbf{y}_{1}^{1:N}|\mathbf{z}_1^{1:N}) \\
    &=  \delta_{\mathbf{c}_1^{1:N}=1} p(\mathbf{z}_1^{1:N}) p(\mathbf{e}_1^{1:N^2})\prod_{n=1}^{N}p(\mathbf{y}_{1}^{n}|\mathbf{z}_{1}^{n})\\
    \underline{\alpha_t(\mathbf{z}_t, \mathbf{c}_t)} &= p(\mathbf{z}_t,\mathbf{c}_t,\mathbf{y}_{1:t},\mathbf{e}_{1:t}) \\
    &= p(\mathbf{z}_t^{1:N},\mathbf{c}_t^{1:N},\mathbf{y}_{1:t}^{1:N},\mathbf{e}_{1:t}^{1:N^2})\\
    &= \sum_{\mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t-1}^{1:N}}p(\mathbf{z}_t^{1:N},\mathbf{c}_t^{1:N},\mathbf{y}_{1:t}^{1:N},\mathbf{e}_{1:t}^{1:N^2}, \mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t-1}^{1:N}) \\
    &= \sum_{\mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t-1}^{1:N}}\Bigg[p(\mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t-1}^{1:N},\mathbf{y}_{1:t-1}^{1:N},\mathbf{e}_{1:t-1}^{1:N^2})p(\mathbf{y}_{t}^{1:N}|\mathbf{y}_{t-1}^{1:N},\mathbf{z}_{t}^{1:N})p(\mathbf{z}_{t}^{1:N}|\mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t}^{1:N},\mathbf{y}_{t-1}^{1:N},\mathbf{e}_{t}^{1:N^2}) \\
    & \quad\quad\quad\quad\quad\,\, \cdot p(\mathbf{c}_{t}^{1:N}|\mathbf{c}_{t-1}^{1:N},\mathbf{z}_{t-1}^{1:N})p(\mathbf{e}_{t}^{1:N^2}|\mathbf{e}_{t-1}^{1:N^2},\mathbf{z}_{t-1}^{1:N},\mathbf{y}_{t-1}^{1:N}) \Bigg] \\
    & = \sum_{\mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t-1}^{1:N}}\Bigg[\underline{\alpha_{t-1}(\mathbf{z}_{t-1},\mathbf{c}_{t-1})} \cdot\prod_{n=1}^{N}p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n}) \cdot \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(z_{t}^{n}|z_{t-1}^{m}, c_{t}^{n}, \mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n}, e_{t}^{m\rightarrow n}) \cdot  \\
    & \quad\quad\quad\quad\quad\,\,  \cdot \prod_{n=1}^{N}p(c_{t}^{n}|c_{t-1}^{n},z_{t-1}^{n})\prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, z_{t-1}^{m}, z_{t-1}^{n}, c_{t-1}^{m}, c_{t-1}^{n}, \mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n})\Bigg], 
\end{align*}
where $\alpha_t(\mathbf{z}_t,\mathbf{c}_t)$ are calculated by $\alpha_{t-1}(\mathbf{z}_{t-1},\mathbf{c}_{t-1})$ recursively with states transitions.

The derivatives of the backward section $\beta_t(\mathbf{z}_t,\mathbf{c}_{t})$ is calculated as
\begin{align*}
    \beta_T(\mathbf{z}_T,\mathbf{c}_T) &= 1 \\
    \underline{\beta_t(\mathbf{z}_t,\mathbf{c}_t)} &= p(\mathbf{y}_{t+1:T},\mathbf{e}_{t+1:T}|\mathbf{y}_{t},\mathbf{z}_t,\mathbf{c}_t) \\
    &= p(\mathbf{y}_{t+1:T}^{1:N},\mathbf{e}_{t+1:T}^{1:N^2}|\mathbf{y}_{t}^{1:N}, \mathbf{z}_{t}^{1:N}, \mathbf{c}_{t}^{1:N})\\
    &= \sum_{\mathbf{z}_{t+1}^{1:N},\mathbf{c}_{t+1}^{1:N}}p(\mathbf{y}_{t+1:T}^{1:N},\mathbf{e}_{t+1:T}^{1:N^2},\mathbf{z}_{t+1}^{1:N},\mathbf{c}_{t+1}^{1:N} |\mathbf{y}_{t}^{1:N}, \mathbf{z}_{t}^{1:N}, \mathbf{c}_{t}^{1:N})\\
    &= \sum_{\mathbf{z}_{t+1}^{1:N},\mathbf{c}_{t+1}^{1:N}} \Bigg[p(\mathbf{y}_{t+1}^{1:N}|\mathbf{y}_{t}^{1:N},\mathbf{z}_{t+1}^{1:N})p(\mathbf{z}_{t+1}^{1:N}|\mathbf{z}_{t}^{1:N},\mathbf{c}_{t+1}^{1:N},\mathbf{y}_{t}^{1:N},\mathbf{e}_{t+1}^{1:N^2}) \\
    & \cdot p(\mathbf{c}_{t+1}^{1:N}|\mathbf{c}_{t}^{1:N},\mathbf{z}_{t}^{1:N})p(\mathbf{e}_{t+1}^{1:N^2}|\mathbf{e}_{t}^{1:N^2},\mathbf{z}_{t}^{1:N},\mathbf{y}_{t}^{1:N})p(\mathbf{y}_{t+2:T}^{1:N},\mathbf{e}_{t+2:T}^{1:N^2}|\mathbf{y}_{t+1}^{1:N}, \mathbf{z}_{t+1}^{1:N}, \mathbf{c}_{t+1}^{1:N}) \Bigg]\\
    &= \sum_{\mathbf{z}_{t+1}^{1:N},\mathbf{c}_{t+1}^{1:N}}\Bigg[ \prod_{n=1}^{N}p(\mathbf{y}_{t+1}^{n}|\mathbf{y}_{t}^{n},z_{t+1}^{n}) \cdot \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(z_{t+1}^{n}|z_{t}^{m}, c_{t+1}^{n}, \mathbf{y}_{t}^{m,n}, e_{t+1}^{m\rightarrow n}) \\
    & \cdot \prod_{n=1}^{N}p(c_{t+1}^{n}|c_{t}^{n},z_{t}^{n}) \cdot \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(e_{t+1}^{m\rightarrow n}|e_{t}^{m\rightarrow n}, z_{t}^{m}, z_{t}^{n}, c_{t}^{m}, c_{t}^{n}, \mathbf{y}_{t}^{m},\mathbf{y}_{t}^{n})\,\,\underline{\beta_{t+1}(\mathbf{z}_{t+1},\mathbf{c}_{t+1})}\Bigg],
\end{align*}
where $\beta_t(\mathbf{z}_t,\mathbf{c}_t)$ is computed via $\beta_{t+1}(\mathbf{z}_{t+1},\mathbf{c}_{t+1})$ recursively by state transitions.


\subsection{Derivation of Optimization Objective}
\label{app: Derivation of Optimization Objective of AMORE-MIO}
Learnable parameters of our model are optimized by maximizing the evidence lower bound (ELBO) with sparse regularization on coefficients of candidate basis functions where the derivatives of ELBO are as follows.
For brevity, $\mathbf{y}$, $\mathbf{z}$, $\mathbf{c}$, and $\mathbf{e}$ represents $\mathbf{y}_{1:T}^{1:N}$, $\mathbf{z}_{1:T}^{1:N}$, $\mathbf{c}_{1:T}^{1:N}$, and $\mathbf{e}_{1:T}^{1:N^2}$ respectively. $N$ is the number of objects. $T$ is the number of time steps.
\begin{align*}
ELBO &= {\rm log}\,p_\theta(\mathbf{y})\!-\!D_{K\!L}\left[q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\,\|\,p_\theta(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\right] \\
&= \int q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y}) \, {\rm log}\,p_\theta(\mathbf{y}) \, d(\mathbf{z},\mathbf{c},\mathbf{e}) - \int q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y}) \, {\rm log}\,\frac{q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})}{p_\theta(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})} \, d(\mathbf{z},\mathbf{c},\mathbf{e}) \\
&= \int q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\left[{\rm log}\,p_\theta(\mathbf{z},\mathbf{c},\mathbf{e},\mathbf{y})-{\rm log}\,q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\right] \, d(\mathbf{z},\mathbf{c},\mathbf{e}) \\
&= \mathbb{E}_{q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})}\left[{\rm log}\,p_\theta(\mathbf{z},\mathbf{c},\mathbf{e},\mathbf{y})-{\rm log}\,q_\phi(\mathbf{z},\mathbf{c},\mathbf{e}|\mathbf{y})\right] \\
&= \mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})p_\theta(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}\left[{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})p_\theta(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})-{\rm log}\,q_\phi(\mathbf{e}|\mathbf{y})p_\theta(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})\right] \\
&= \mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}\left[{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})-{\rm log}\,q_\phi(\mathbf{e}|\mathbf{y})\right] \\
&= 
\mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}\left[{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})\right]+H(q_\phi(\mathbf{e}|\mathbf{y})),
\end{align*}
where ${\rm log}\,p_\theta(\mathbf{y},\mathbf{e})$ is a joint likelihood, and $H(q_\phi(\mathbf{e}|\mathbf{y}))$ is a conditional entropy for the approximate posterior of edge variable $\mathbf{e}$.
\subsubsection{Training of ELBO}
We use the mini-batch stochastic gradient descent algorithm for training of ELBO. The gradients with respect to $\theta$ or $\phi$ in ELBO are calculated as
\begin{align*}
 \nabla_\theta ELBO &= \nabla_\theta \left[\mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})\right] = \mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}\nabla_\theta{\rm log}\,p_\theta(\mathbf{y},\mathbf{e}), \\
% \end{align*}
% \begin{align*}
\nabla_\phi ELBO &= \nabla_\phi \left[\mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})+H(q_\phi(\mathbf{e}|\mathbf{y}))\right] \\
& = \nabla_\phi \left[\mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})\right] + \nabla_\phi H(q_\phi(\mathbf{e}|\mathbf{y}))\\
& = \mathbb{E}_{\,\mathbf{\epsilon} \sim \mathcal{N}}\left[\nabla_\phi{\rm log}\,p_\theta(\mathbf{e},\mathbf{y}_\phi(\mathbf{e}, \mathbf{\epsilon}))\right] + \nabla_\phi H(q_\phi(\mathbf{e}|\mathbf{y})),
\end{align*}
where we use the reparameterization trick~\cite{kingma2013auto} to calculate the gradients of $\nabla_\phi \left[\mathbb{E}_{q_\phi(\mathbf{e}|\mathbf{y})}{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})\right]$. 
$\nabla_\phi H(q_\phi(\mathbf{e}|\mathbf{y}))$ is an entropy loss.
Among the derivative terms, the challenging part is the gradients of joint probability $\nabla_\theta{\rm log}\,p_\theta(\mathbf{y},\mathbf{e})$, which is calculated as
\begin{align*}
\nabla{\rm log}\,p(\mathbf{y},\mathbf{e}) 
% &= \nabla{\rm log}\,p(\mathbf{x},\mathbf{y})
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y}, \mathbf{e})}\left[\nabla{\rm log}\,p(\mathbf{y},\mathbf{e})\right] \\
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}\left[\nabla{\rm log}\,p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c})\right] - \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}\left[\nabla{\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})\right] \\
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}\left[\nabla{\rm log}\,p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c})\right] - \int p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})\frac{\nabla{\rm log}\,p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}{p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}d(\mathbf{z},\mathbf{c})\\
&= \mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}\left[\nabla{\rm log}\,p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c})\right],
\end{align*}
Following the Markovian property, we unfold the joint likelihood $p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c})$ over time as:
  \begin{align*}
    &\nabla{\rm log}\,p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c}) \\
    &= \nabla\,{\rm log}\,p(\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2},\mathbf{z}_{1:T}^{1:N},\mathbf{c}_{1:T}^{1:N}) \\
    &= \nabla\,{\rm log}\!\left[p(\mathbf{y}_{1}^{1:N}|\mathbf{z}_{1}^{1:N})p(\mathbf{z}_{1}^{1:N})\right] + \sum_{t=2}^{T}\nabla\,{\rm log}\!\bigg[p(\mathbf{y}_{t}^{1:N}|\mathbf{y}_{t-1}^{1:N},\mathbf{z}_{t}^{1:N})p(\mathbf{z}_{t}^{1:N}|\mathbf{z}_{t-1}^{1:N},\mathbf{c}_{t}^{1:N},\mathbf{y}_{t-1}^{1:N},\mathbf{e}_{t}^{1:N^2})\cdot\\ 
    &\;\;\;\;\;\;\;\;p(\mathbf{c}_{t}^{1:N}|\mathbf{c}_{t-1}^{1:N},\mathbf{z}_{t-1}^{1:N})p(\mathbf{e}_{t}^{1:N^2}|\mathbf{e}_{t-1}^{1:N^2},\mathbf{z}_{t-1}^{1:N},\mathbf{y}_{t-1}^{1:N})\bigg] \\
    &= \nabla\,{\rm log}\!\left[\prod_{n=1}^{N}p(\mathbf{y}_{1}^{n}|z_{1}^{n})\cdot \prod_{n=1}^{N}p(z_{1}^n)\right] + \sum_{t=2}^{T}\nabla\,{\rm log}\!\Bigg[\prod_{n=1}^{N}p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n}) \cdot \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(z_{t}^{n}|z_{t-1}^{m}, c_{t}^{n}, \mathbf{y}_{t-1}^{m},\mathbf{y}_{t-1}^{n}, e_{t}^{m\rightarrow n}) \cdot \\
    &\;\;\;\;\;\;\;\;\prod_{n=1}^{N}p(c_{t}^{n}|c_{t-1}^{n},z_{t-1}^{n}) \cdot \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!
    p(e_{t}^{m \rightarrow n}|e_{t-1}^{m \rightarrow n}, z_{t-1}^{m}, z_{t-1}^{n}, c_{t-1}^{m}, c_{t-1}^{n}, \mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n}) \Bigg],
\end{align*}
where edge variables evolve based on all previous states of both objects. We model the influences of interactions between each pair of objects by $p(z_{t}^{n}|z_{t-1}^{m}, c_{t}^{n}, \mathbf{y}_{t-1}^{m}, \mathbf{y}_{t-1}^{n}, e_t^{m\rightarrow n})$ without instantaneous dependences. Combining with expectation, $\nabla{\rm log}\,p(\mathbf{y},\mathbf{e})$ is finally calculated as
\begin{align*}
    \nabla{\rm log}\,p(\mathbf{y},\mathbf{e})
    &=\mathbb{E}_{p(\mathbf{z},\mathbf{c}|\mathbf{y},\mathbf{e})}\left[\nabla{\rm log}\,p(\mathbf{y},\mathbf{e},\mathbf{z},\mathbf{c})\right]\\
    &= \mathbb{E}_{p(\mathbf{z}_{1:T}^{1:N},\mathbf{c}_{1:T}^{1:N}|\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2})}\left[\nabla{\rm log}\,p(\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2},\mathbf{z}_{1:T}^{1:N},\mathbf{c}_{1:T}^{1:N})\right] \\
    &= \sum_{\mathbf{k}}p(\mathbf{z}_1^{1:N}=\mathbf{k}|\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2}) \nabla\,{\rm log}\left[\prod_{n=1}^{N}p(\mathbf{y}_{1}^{n}|\mathbf{z}_{1}^{n}=k^n)\cdot p(\mathbf{z}_{1}^{1:N}=\mathbf{k})\right] \\
    &\,\,\,\,\,\,\, + \sum_{t=2}^{T}\sum_{\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v}}\!\! \xi(\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v})\,\nabla\,{\rm log}\!\Bigg[\prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, \mathbf{z}_{t}^{m,n}=\mathbf{k}^{m,n}, \mathbf{y}_{t}^{m,n}) \cdot \prod_{n=1}^{N}p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n}=k^n)\\
    &\,\,\,\,\,\,\,\cdot \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!\,p(z_{t}^{n}\!=\!k^n|z_{t-1}^{m}\!=\!j^m, c_{t}^{n}\!=\!v^n, \mathbf{y}_{t-1}^{m,n}, e_{t-1}^{m\rightarrow n})\cdot \prod_{n=1}^{N}p(c_{t}^{n}\!=\!v^n|c_{t-1}^{n}\!=\!u^n,z_{t-1}^{n}\!=\!j^n)\Bigg]\\
    &= \sum_{\mathbf{k}}\gamma(\mathbf{k})\, \nabla\,{\rm log}\!\left[B_1(k^n)\cdot \pi(\mathbf{k})\right] \\
    &\,\,\,\,\,\,\,+\sum_{t=2}^{T}\sum_{\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v}}\!\!\xi(\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v})\,\nabla\,{\rm log}\!\left[B_t(\mathbf{k})\cdot 
    E_t(\mathbf{k}) \cdot
    A_t(\mathbf{k},\mathbf{j},\mathbf{v}) \cdot  C_t(\mathbf{u},\mathbf{v},\mathbf{j})\right],
    % &\,\,\,\,\,\,\,+ \sum_{t=2}^{T}\sum_{\mathbf{k},\mathbf{j},\mathbf{q},\mathbf{p},\mathbf{s}}\xi(\mathbf{k},\mathbf{j},\mathbf{q},\mathbf{p},\mathbf{s})\,\,\nabla\,{\rm log}\!\left[B_t(\mathbf{k})\cdot C_t(\mathbf{q},\mathbf{p},\mathbf{j})\cdot A_t(\mathbf{k},\mathbf{j},\mathbf{q},\mathbf{s})\right]
\end{align*}
where $\pi(\mathbf{k})$, $\gamma(\mathbf{k})$, $\xi(\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v})$, $B_t(\mathbf{k})$, $E_t(\mathbf{k})$, $A_t(\mathbf{k},\mathbf{j},\mathbf{v})$, and $C_t(\mathbf{u},\mathbf{v},\mathbf{j})$ are defined as
\begin{align*}
\pi(\mathbf{k}) &= p(\mathbf{z}_{1}^{1:N}=\mathbf{k}),\\
\gamma(\mathbf{k}) &= p(\mathbf{z}_1^{1:N}=\mathbf{k}|\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2}),\\
\xi(\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v}) &= p(\mathbf{z}_t^{1:N}\!\!=\!\mathbf{k},\mathbf{z}_{t-1}^{1:N}\!\!=\!\mathbf{j},\mathbf{c}_t^{1:N}\!=\!\mathbf{v},\mathbf{c}_{t-1}^{1:N}\!=\!\mathbf{u}|\mathbf{y}_{1:T}^{1:N},\mathbf{e}_{1:T}^{1:N^2}), \\
B_t(\mathbf{k}) &= \prod_{n=1}^{N}p(\mathbf{y}_{t}^{n}|\mathbf{y}_{t-1}^{n},z_{t}^{n}=k^n),\\
E_t(\mathbf{k}) &= \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!p(e_{t}^{m\rightarrow n}|e_{t-1}^{m\rightarrow n}, \mathbf{z}_{t}^{m,n}=\mathbf{k}^{m,n}, \mathbf{y}_{t}^{m,n}),\\
A_t(\mathbf{k},\mathbf{j},\mathbf{v}) &= \prod_{n=1}^{N}\!\prod_{m=1}^{N}\!\,p(z_{t}^{n}\!=\!k^n|z_{t-1}^{m}\!=\!j^m, c_{t}^{n}\!=\!v^n, \mathbf{y}_{t-1}^{m,n}, e_{t-1}^{m\rightarrow n}),\\
C_t(\mathbf{u},\mathbf{v},\mathbf{j}) &= \prod_{n=1}^{N}p(c_{t}^{n}\!=\!v^n|c_{t-1}^{n}\!=\!u^n,z_{t-1}^{n}\!=\!j^n),
\end{align*}
Among these, $\pi(\mathbf{k})$ is the initial joint discrete mode probability. $B_t(\mathbf{k})$ is the observation transition probability conditioned on motion modes $\mathbf{k}$. $E_t(\mathbf{k})$ is the discrete edge transition probability. 
$A_t(\mathbf{k},\mathbf{j},\mathbf{v})$ is the discrete motion mode transition probability. 
$C_t(\mathbf{u},\mathbf{v},\mathbf{j})$ is the mode count transition probability.
Besides, $\gamma(\mathbf{k})$ and $\xi(\mathbf{k},\mathbf{j},\mathbf{u},\mathbf{v})$ are conditional posterior distributions, which can be calculated by the forward-backward algorithm in Appendix~\ref{app: Inference Model of AMORE-MIO}.

