\section{Preliminary} \label{sec:Preliminary}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Problem Statement} \label{sec:Problem Statement}
Maneuver detection is a sub-problem in orbit estimation. An orbit estimation system can be generally modeled as a combination of an orbital state equation and a measurement equation, expressed as
\begin{equation} \label{eq1}
    \left\{ {\begin{array}{*{20}{l}}
        {\boldsymbol{\dot x} = \boldsymbol{f}(t,\boldsymbol{x})}\\
        {\boldsymbol{z} = \boldsymbol{h}(\boldsymbol{x}) + \boldsymbol{\varepsilon }}
    \end{array}} \right. \,,
\end{equation}
where $\boldsymbol{x} = [\boldsymbol{r};\boldsymbol{v}] \in {\mathbb{R}^6}$ is the orbital state vector of a spacecraft at a given epoch $t$, with $\boldsymbol{r} = {[x,y,z]^T} \in {\mathbb{R}^3}$ and $\boldsymbol{v} = {[\dot x,\dot y,z]^T} \in {\mathbb{R}^3}$ being the time-dependent position and velocity vectors, respectively, $\boldsymbol{f}(t,\boldsymbol{x}):{\mathbb{R}^6} \mapsto {\mathbb{R}^6}$ is a collection of ordinary differential equations (ODEs) representing the nonlinear orbit dynamics, $\boldsymbol{z} = \boldsymbol{h}(\boldsymbol{x}) + \boldsymbol{\varepsilon} \in {\mathbb{R}^m}$ denotes the $m$-dimensional measurement vector, $\boldsymbol{h}(\boldsymbol{x}):{\mathbb{R}^6} \mapsto {\mathbb{R}^m}$ is the measurement model (usually nonlinear), and $\boldsymbol{\varepsilon} \in {\mathbb{R}^m}$ is a zero-mean, Gaussian-distributed measurement noise satisfying $\mathbb{E}\{\boldsymbol{\varepsilon }\} = {\mathbf{0}_{m \times 1}}$ and $\mathbb{E}\{\boldsymbol{\varepsilon }{\boldsymbol{\varepsilon }^T}\} = \boldsymbol{R}$ ($\boldsymbol{R} \in {\mathbb{R}^{m \times m}}$ is the covariance matrix of the measurement noise $\boldsymbol{\varepsilon}$, which is a positive definite matrix).

The discrete form of the orbit estimation system in Eq.~\eqref{eq1} can be written as
\begin{equation} \label{eq2}
    \left\{ {\begin{array}{*{20}{l}}
        {{\boldsymbol{x}_k} = \boldsymbol{F}({\boldsymbol{x}_{k - 1}},{t_{k - 1}},{t_k})}\\
        {{\boldsymbol{z}_k} = \boldsymbol{h}({\boldsymbol{x}_k}) + {\boldsymbol{\varepsilon }_k}}
    \end{array}} \right. \,,
\end{equation}
where ${\boldsymbol{x}_k} \in {\mathbb{R}^6}$, ${\boldsymbol{z}_k} \in {\mathbb{R}^m}$, and ${\boldsymbol{\varepsilon }_k} \in {\mathbb{R}^m}$ (satisfying $\mathbb{E} \{ {\boldsymbol{\varepsilon }_k}\boldsymbol{\varepsilon }_k^T\}  = {\boldsymbol{R}_k}$) represent the orbital state, measurement vector, and measurement noise at the epoch ${t_k}$, respectively, and $\boldsymbol{F}({\boldsymbol{x}_{k - 1}},{t_{k - 1}},{t_k}):{\mathbb{R}^6} \mapsto {\mathbb{R}^6}$ is a nonlinear orbit propagation from ${t_{k - 1}}$ to ${t_k}$, formulated as
\begin{equation} \label{eq3}
    \boldsymbol{F}({\boldsymbol{x}_{k - 1}},{t_{k - 1}},{t_k}) = \int\limits_{{t_{k - 1}}}^{{t_k}} {\boldsymbol{f}(\tau ,\boldsymbol{x})d\tau }  + {\boldsymbol{x}_{k - 1}} \,.
\end{equation}

Let ${\boldsymbol{x}_0} = [{\boldsymbol{r}_0};{\boldsymbol{v}_0}] \in {\mathbb{R}^6}$ and ${\boldsymbol{\hat x}_0} = [{\boldsymbol{\hat r}_0};{\boldsymbol{\hat v}_0}] \in {\mathbb{R}^6}$ be the true and estimated orbital state at the initial epoch $t_0$. 
Assume that the estimated orbital state ${\boldsymbol{\hat x}_0}$ is Gaussian-distributed, with ${\boldsymbol{x}_0}$ being the mean and ${\boldsymbol{P}_0} = \mathbb{E} \{ ({\boldsymbol{\hat x}_0} - {\boldsymbol{x}_0}){({\boldsymbol{\hat x}_0} - {\boldsymbol{x}_0})^T}\} $ being the covariance (\emph{i.e.}, ${\boldsymbol{\hat x}_0} \sim {\cal N}({\boldsymbol{\hat x}_0};{\boldsymbol{x}_0},{\boldsymbol{P}_0})$). 
Note that the mean ${\boldsymbol{\hat{x}}_0}$ and covariance ${\boldsymbol{P}_0}$ can be obtained via an OD process based on the data collected in the first UCT.
In addition, we assume that a measurement ${\boldsymbol{z}_k} = \boldsymbol{h}({\boldsymbol{x}_k}) + {\boldsymbol{\varepsilon }_k}$ is available at the epoch $t_k$ (${t_k} > {t_0}$), whose predicted orbital state can be propagated based on the initial estimated orbital state as
\begin{equation} \label{eq4}
    {\boldsymbol{\hat x}_k} = \boldsymbol{F}({\boldsymbol{\hat x}_0},{t_0},{t_k}) \,.
\end{equation}

Based on the above definitions and discussions, the maneuver detection problem investigated in this work can be generalized as follows: given the initial estimation ${\boldsymbol{\hat x}_0}$ and associated covariance matrix ${\boldsymbol{P}_0}$, the measurement ${\boldsymbol{z}_k}$ at the given epochs $t_k$ ($k \in \{ 1,2, \cdots ,N\} $), and its associated noise covariance ${\boldsymbol{R}_k}$, identify whether a spacecraft has executed a maneuver.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Taylor Polynomial Approximation} \label{sec:Taylor Polynomial Approximation}
The Taylor polynomial is an efficient technique to approximate the nonlinear orbit propagation. Let $\delta {\boldsymbol{x}_0} = {\boldsymbol{x}_0} - {\boldsymbol{\hat x}_0} \in {\mathbb{R}^6}$ represents an orbital state deviation at the initial epoch (which defines a neighboring orbit) and ${\boldsymbol{\tilde x}_k} = \boldsymbol{F}({\boldsymbol{\hat x}_0} + \delta {\boldsymbol{x}_0},{t_0},{t_k})$ be a propagated state of the neighboring orbit at the given epoch $t_k$. Then, the propagated state ${\boldsymbol{\tilde x}_k}$ can be approximated using a Taylor polynomial up to the \emph{n}-th order as
\begin{equation} \label{eq5}
    {\boldsymbol{\tilde x}_k} \approx {\cal T}_{{{\boldsymbol{\tilde x}}_k}}^n(\delta {\boldsymbol{x}_0}) = \boldsymbol{F}({\boldsymbol{\hat x}_0},{t_0},{t_k}) + \sum\limits_{k = 1}^n {\frac{1}{{k!}}\frac{{{\partial ^k}\boldsymbol{F}}}{{\partial \boldsymbol{\hat x}_0^k}}{{(\delta {\boldsymbol{x}_0})}^k}}  \,,
\end{equation}
where ${\cal T}_{{{\boldsymbol{\tilde x}}_k}}^n(\delta {\boldsymbol{x}_0})$ is an \emph{n}-th order Taylor polynomial expanded at the point ${\boldsymbol{\hat x}_0}$, and $\boldsymbol{F}({\boldsymbol{\hat x}_0},{t_0},{t_k})$ and $\frac{{\partial \boldsymbol{F}}}{{\partial {{\boldsymbol{\hat x}}_0}}}\delta {\boldsymbol{x}_0}$ are its constant and linear (first-order) terms, respectively.

For nonlinear orbital propagation problems (\emph{e.g.}, Eq.~\eqref{eq5}), high-order Taylor polynomial approximations can be derived using a variational approach, leading to the so-called state transition tensor (STT) \cite{Park2006}, or by leveraging the algebra of Taylor polynomials, as in DA \cite{Armellin2010, Valli2013} and jet transport (JT) \cite{Perez-Palau2015}. The variational approach necessitates computing intricate partial derivatives of the dynamical equations and integrating an expanded system of ODEs. In contrast, DA and JT integrate only the original set of ODEs but require specialized numerical schemes to accommodate the Taylor polynomial data structure effectively. In this work, the DA is employed to generate Taylor polynomials, which will be briefly introduced in the next subsection.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Differential Algebra} \label{sec:Differential Algebra}
The DA technique was originally developed as an algebraic framework for solving analytical problems \cite{Griewank2008}. In this work, DA is utilized to obtain high-order Taylor polynomial expansions of the flow in nonlinear orbital dynamics with respect to the initial state deviation. Unlike conventional numerical methods that evaluate functions at discrete points, DA exploits the richer structural information embedded in functions beyond their numerical values \cite{Armellin2009CMDA, Armellin2010, Armellin2012CMDA, Valli2013, Fu2024Astro, Fossa2024Astro, Liu2024IEEE}. Its fundamental principle lies in manipulating functions and their operations in a manner analogous to the arithmetic of real numbers within a computational environment. 

The Differential Algebra Core Engine (DACE) \footnote{Available at \url{https://github.com/dacelib/dace/}.} is a robust and versatile C++ computational toolbox for DA. Its Python interface, DACEyPy \footnote{Available at \url{https://github.com/giovannipurpura/daceypy/}.}, serves as a wrapper for DACE, providing a user-friendly environment for DA-based computations. In this work, DACEyPy is utilized to implement the DA framework efficiently.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{confidence-Dominance Maneuver Indicator} \label{sec:Polynomial Optimization-Based Indicator}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Definition of Confidence-Constrained Region} \label{sec:Definition of Confidence-Constrained Region}
Two concepts of confidence-constrained regions (CCR) are here proposed: one is the confidence-constrained (initial) state region (CCSR) and the other is the confidence-constrained measurement region (CCMR). According to the problem statement in Sec.~\ref{sec:Problem Statement}, the initial orbital deviation $\delta {\boldsymbol{x}_0}$ satisfies a Gaussian distribution, that is $\delta {\boldsymbol{x}_0} \sim {\cal N}(\delta {\boldsymbol{x}_0};{\mathbf{0}_{6 \times 1}},{\boldsymbol{P}_0})$. In this work, the CCSR is defined by bounding the initial orbital deviation $\delta {\boldsymbol{x}_0}$ with a $\chi^2$ distribution of 6 degrees of freedom (DoF) and a given confidence level $\alpha_x$ as
\begin{equation} \label{eq6}
    \frac{1}{2}\delta \boldsymbol{x}_0^T\boldsymbol{P}_0^{ - 1}\delta {\boldsymbol{x}_0} \le {q_{{\chi ^2}}}({\alpha _x},6) = {{\cal M}_x}  \,,
\end{equation}
where ${{\cal M}_x} = {q_{{\chi ^2}}}({\alpha _x},6)$ refers to the quantile (inverse cumulative distribution function [CDF]) of the $\chi^2$ distribution with 6 DoF. Specifically, it represents the value corresponding to a cumulative probability of the given confidence level $\alpha_x$ for the $\chi^2$ distribution with 6 DoF. In other words, ${q_{{\chi ^2}}}({\alpha _x},6)$ is the value such that:
\begin{equation} \label{eq7}
    P\{ \chi _6^2 \le {q_{{\chi ^2}}}({\alpha _x},6)\}  = {\alpha _x} \,,
\end{equation}
where $\chi _6^2$ is a random variable following the $\chi^2$ distribution with 6 DoF.

Based on the CCSR defined in Eq.~\eqref{eq6}, the corresponding CCMR at an (arbitrary) epoch $t_k$, labeled as ${\cal Z}({\alpha _x},{t_k})$, is then defined as
\begin{equation} \label{eq8}
    {\cal Z}({\alpha _x},{t_k}) = \left\{ {{{\boldsymbol{\tilde z}}_k}\left| {{{\boldsymbol{\tilde z}}_k} = \boldsymbol{h}({{\boldsymbol{\tilde x}}_k}),{\rm{ }}\frac{1}{2}\delta \boldsymbol{x}_0^T\boldsymbol{P}_0^{ - 1}\delta {\boldsymbol{x}_0} \le {{\cal M}_x}} \right.} \right\} \,,
\end{equation}
which is a time-dependent measurement set containing all possible observations that satisfy the confidence constraint of the initial state. With the definitions of two CCRs, the confidence-constrained maximum likelihood maneuver indicator under two conditions is introduced in the following two subsections.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Indicator with Measurement at Single Epoch} \label{sec:Indicator with Measurement at Single Epoch}
The proposed maneuver indicator is based on the maximum likelihood estimation within the CCSR.  
The goal of the maximum likelihood estimation is to find the observation with the highest likelihood without any maneuver (\emph{i.e.}, a ballistic motion), given the confidence level constraint on the state estimate. 
The highest likelihood obtained is called the confidence-constrained maximum likelihood throughout this paper. 
Then, based on this confidence-constrained maximum likelihood, the measurement confidence level can be obtained. 
Finally, we derive the CDMI by comparing the confidence levels associated with the state estimate and the observation, which can assess whether the observed measurement is consistent with the ballistic motion hypothesis, thus enabling effective maneuver detection.

This section details the indicator with measurements collected at a single epoch (\emph{i.e.}, $N=1$ and the corresponding CCMR is written as ${\cal Z}({\alpha _x},{t_1})$). 
Note that more than one measurement may be available at a given epoch. For example, an optical sensor can provide two independent measurements (\emph{i.e.}, right ascension and declination) at one epoch, whereas a radar usually has three (\emph{i.e.}, two angles and one range). 
Given the assumption that the measurement noises satisfy a Gaussian distribution (see Sec.~\ref{sec:Problem Statement}), we maximize logarithmic likelihood, which is equivalent to minimizing the squared Mahalanobis, to find the point with the maximum likelihood in the CCMR ${\cal Z}({\alpha _x},{t_1})$ (this point is also called the closest point as it is closest to the observed measurement $\boldsymbol{z}_1$). Therefore, a nonlinear programming (NLP) optimization problem is formulated as
\begin{equation} \label{eq9}
    \begin{array}{*{20}{l}}
        {\mathop {\min }\limits_{\delta {\boldsymbol{x}_0}} }&{J = \delta \boldsymbol{\tilde z}_1^T\boldsymbol{R}_1^{ - 1}\delta {{\boldsymbol{\tilde z}}_1}}\\
        {{\rm{s}}{\rm{.t}}{\rm{.}}}&{\delta {{\boldsymbol{\tilde z}}_1} = {{\boldsymbol{\tilde z}}_1} - {\boldsymbol{z}_1}}\\
        {}&{{{\boldsymbol{\tilde z}}_1} \in {\cal Z}({\alpha _x},{t_1})}
    \end{array} \,.
\end{equation}

Let $\delta \boldsymbol{x}_0^ * $ be the optimal solution of the NLP optimization problem in Eq.~\eqref{eq9}, and $\delta \boldsymbol{\tilde z}_1^ *  = \boldsymbol{h}[\boldsymbol{F}({\boldsymbol{\hat x}_0} + \delta \boldsymbol{x}_0^ * ,{t_0},{t_1})] - {\boldsymbol{z}_1}$ be the corresponding measurement residual. 
Then, by computing $\mathcal{M}_z = \frac{1}{2} \delta \tilde{\boldsymbol{z}}_1^\top R_1^{-1} \delta \tilde{\boldsymbol{z}}_1={q_{\chi^2}}({\alpha_z}, m)$, one can evaluate the corresponding confidence level $\alpha_z$:
\begin{equation} \label{eq10}
    \begin{aligned}
        \alpha_z &= F{\chi_{m}^2(\mathcal{M}_z)} \\
        &= \int_0^{\mathcal{M}_z} \frac{1}{2^{m/2} \Gamma(m/2)} x^{(m/2)-1} e^{-x/2}dx
    \end{aligned} \,,
\end{equation}
where $F{\chi_m^2}$ represents the CDF of the $\chi_m^2$ distribution. For the $\chi_m^2$ distribution in Eq.~\eqref{eq10}, the DoF equals the measurement dimension $m$. 

Two key situations are considered here. First, if the confidence-constrained maximum likelihood of the observation is low, $\delta \boldsymbol{\tilde z}_1^* \to \infty$, then ${q{_{\chi^2}}}({\alpha_z}, m) = {\mathcal{M}_z} \to +\infty$. In this case, ${\alpha_z} \to 1$. This suggests that the measurement is either an outlier or that an unmodeled maneuver may have occurred.

Second, when the confidence-constrained maximum likelihood is highest (\emph{i.e.}, when ${q_{\chi^2}}({\alpha_z}, m) = {\mathcal{M}_z} \to 0$ and ${\alpha_z} \to 0$), the measurement ${\boldsymbol{z}_1}$ is consistent with the state estimation. This indicates that the measurement aligns with the ballistic hypothesis, and the likelihood that a maneuver has occurred is low. 

These outcomes reveal that larger values of $\alpha_z$ are associated with a higher likelihood of a maneuver. However, since $\alpha_z$ depends on the confidence level of the state estimate—denoted by $\alpha_x$—it cannot be used directly as a maneuver indicator. To address this, we compare $\alpha_z$ against $\alpha_x$ to assess whether the observation is statistically consistent with the estimated state. A maneuver is flagged when the measurement confidence exceeds that of the state estimate, \emph{i.e.}, when $\alpha_z > \alpha_x$, indicating that the observation statistically dominates the estimated state and is inconsistent with the no-maneuver hypothesis.
Therefore, we adopt $(\alpha_z > \alpha_x)$ as the proposed CDMI, where a true outcome indicates the presence of a maneuver.

Three issues are worth noting for the NLP optimization problem in Eq.~\eqref{eq9}. First, when different measurement variables are independent and have the same standard deviations (STDs), weights are no longer required, and the objective function of the NLP in Eq.~\eqref{eq9} can be simplified as
\begin{equation} \label{eq12}
    J = \delta \boldsymbol{\tilde z}_1^T\delta {\boldsymbol{\tilde z}_1} \,.
\end{equation}

Second, when ${\alpha _x} = 0$, one doesn’t need to solve for the NLP optimization problem since the CCMR only contains one point:
\begin{equation} \label{eq13}
    {\cal Z}({\alpha _x} = 0,{t_1}) = \left\{ {{{\boldsymbol{\tilde z}}_1}\left| {{{\boldsymbol{\tilde z}}_1} = \boldsymbol{h}({{\boldsymbol{\hat x}}_1})} \right.} \right\} \,.
\end{equation}

Third, when ${\alpha _x} = 1$, one has ${{\cal M}_x} = {q_{{\chi ^2}}}({\alpha _x} = 1,6) =  + \infty $, which means that the CCSR is a set of real numbers with 6 DoF (\emph{i.e.}, $ \mathrm{CCSR} \equiv {\mathbb{R}^6}$). In this case, the CCMR can be expressed as
\begin{equation} \label{eq14}
    {\cal Z}({\alpha _x} = 1,{t_1}) = \left\{ {{{\boldsymbol{\tilde z}}_1}\left| {{{\boldsymbol{\tilde z}}_1} \in {\mathbb{R}^m}} \right.} \right\} \,,
\end{equation}
and the maneuver indicator can be assigned directly as $(\alpha_z > \alpha_x)=(1>1)=\mathrm{false}$. This extreme case corresponds to a situation where the state estimate is completely untrusted, that is, the estimation uncertainty is infinitely large. Under such conditions, any measurement can be explained by the uncertainty in the state estimate, and thus, no maneuver should be detected. While this scenario is unrealistic in practice, it serves as a theoretical limit illustrating that the CDMI will never falsely indicate a maneuver when the prior information is fully uninformative.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Indicator with Measurement at Multiple Epochs} \label{sec:Indicator with Measurement at Multiple Epochs}
When measurements are available at more than one epoch (\emph{i.e.}, $N > 1$), the NLP optimization problem in Eq.~\eqref{eq9} can be rewritten as
\begin{equation} \label{eq16}
    \begin{array}{*{20}{l}}
        {\mathop {\min }\limits_{\delta {\boldsymbol{x}_0}} }&{J = \delta {{\boldsymbol{\tilde Z}}^T}{{\boldsymbol{\bar R}}^{ - 1}}\delta \boldsymbol{\tilde Z}}\\
        {{\rm{s}}{\rm{.t}}{\rm{.}}}&{\delta \boldsymbol{\tilde Z} = [\delta {{\boldsymbol{\tilde z}}_1};\delta {{\boldsymbol{\tilde z}}_2}; \cdots ;\delta {{\boldsymbol{\tilde z}}_N}] \in {\mathbb{R}^{Nm}}}\\
        {}&{\delta {{\boldsymbol{\tilde z}}_k} = {{\boldsymbol{\tilde z}}_k} - {\boldsymbol{z}_k}{\rm{, } \,}k \in \{ 1, \cdots ,N\} }\\
        {}&{{{\boldsymbol{\tilde z}}_k} \in {\cal Z}({\alpha _x},{t_k}){\rm{, } \, }k \in \{ 1, \cdots ,N\} }
    \end{array} \,,
\end{equation}
where
\begin{equation} \label{eq17}
    \boldsymbol{\bar R} = \left[ {\begin{array}{*{20}{c}}
        {{\boldsymbol{R}_1}}&{{\mathbf{0}_{m \times m}}}& \cdots &{{\mathbf{0}_{m \times m}}}\\
        {{\mathbf{0}_{m \times m}}}&{{\boldsymbol{R}_2}}& \cdots &{{\mathbf{0}_{m \times m}}}\\
         \vdots & \vdots & \ddots & \vdots \\
        {{\mathbf{0}_{m \times m}}}&{{\mathbf{0}_{m \times m}}}& \cdots &{{\boldsymbol{R}_N}}
    \end{array}} \right] \in {\mathbb{R}^{Nm \times Nm}} \,.
\end{equation}

Similar to Eq.~\eqref{eq10}, once the optimal solution $\delta {\boldsymbol{\tilde Z}^ * }$ is solved, the associated confidence level can be computed through
\begin{equation} \label{eq18}
    \alpha_z = F{\chi_{Nm}^2(\mathcal{M}_z)}
    = F{\chi_{Nm}^2 \left [ \frac{1}{2}{(\delta {\boldsymbol{\tilde Z}^ * })^T}{\boldsymbol{\bar R}^{ - 1}}\delta {\boldsymbol{\tilde Z}^ * } \right]}\,,
\end{equation}
which can further yield the proposed CMDI. Additionally, if the STDs of the measurements at different epochs are the same, the objective function in Eq.~\eqref{eq16} can be simplified as
\begin{equation} \label{eq19}
    J = \delta {\boldsymbol{\tilde Z}^T}\delta \boldsymbol{\tilde Z} \,.
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Recursive Polynomial Optimization Method} \label{sec:Recursive Polynomial Optimization Method}
The key to the CMDI proposed above lies in estimating the confidence-constrained maximum likelihood, that is, solving the NLP problems in Eqs.~\eqref{eq9} and \eqref{eq16} to find the closest point within the CCMR (defined by Eq.~\eqref{eq8}). Since the NLP problems contain nonlinear objectives and constraints, it’s inefficient to solve them using conventional numerical optimization methods. Motivated by Ref.~\cite{Pavanello2024IEEE}, a novel RPO approach using both the polynomial approximation and convex optimization is proposed in this work to resolve the NLP problems. It’s worth noting that the RPO approach was first introduced in Ref.~\cite{Pavanello2024IEEE} for solving the collision avoidance optimization problems, and the RPO proposed in this paper is an improved version of the one in Ref.~\cite{Pavanello2024IEEE}. The difference between the two RPOs is pictorially shown in Fig.~\ref{fig1} and will be detailed later in this subsection. Moreover, the advantages of the proposed RPO over the previous one in handling the maneuver detection problem will be shown in Sec.~\ref{sec:Maneuver Detection Results Using Single-Epoch Angle}.

\begin{figure*}[!h]
	\centering
	\includegraphics[width=0.8\textwidth]{figures/Methods/RPO.jpg}
	\caption{A comparison between two RPO approaches (left: Ref.~\cite{Pavanello2024IEEE}, right: this work).}
	\label{fig1}
\end{figure*}

Take the NLP problem in Eq.~\eqref{eq9} as an example to show the process of the proposed RPO approach (\emph{i.e.}, consider measurements at a single epoch $t_1$). First, a new nonlinear function is defined for lighter notation:
\begin{equation} \label{eq20}
    {\boldsymbol{\tilde z}_1} = \boldsymbol{g}(\delta {\boldsymbol{x}_0}) = \boldsymbol{h}({\boldsymbol{\tilde x}_1}) = \boldsymbol{h}[\boldsymbol{F}({\boldsymbol{\hat x}_0} + \delta {\boldsymbol{x}_0},{t_0},{t_1})] \,.
\end{equation}
Like Ref.~\cite{Pavanello2024IEEE}, an \emph{n}-th order Taylor polynomial ($n \in {\mathbb{N}^ +}$ is a user-defined parameter representing the highest order of the polynomial) is derived in the DA framework to approximate the nonlinear function ${\boldsymbol{\tilde z}_1} = \boldsymbol{g}(\delta {\boldsymbol{x}_0})$ as
\begin{equation} \label{eq21}
    {\boldsymbol{\tilde z}_1} \approx {\cal T}_{\boldsymbol{g}(\delta {\boldsymbol{x}_0})}^n(\delta {\boldsymbol{x}_0}) = \boldsymbol{g}(\mathbf{0}) + \sum\limits_{i = 1}^n {{{\cal G}^{(i)}}{{(\delta {\boldsymbol{x}_0})}^i}} \,,
\end{equation}
where $\delta {\boldsymbol{x}_0} = {\mathbf{0}_{6 \times 1}}$ is the reference point on which to base the \emph{n}-th order Taylor polynomial is expanded, $\boldsymbol{g}(\mathbf{0})$ is the constant term of the polynomial, and ${{\cal G}^{(i)}} \in {\mathbb{R}^{m \times 6 \times  \cdots  \times 6}}$ is an (\emph{i}+1)-th order tensor, defined as
\begin{equation} \label{eq22}
    {{\cal G}^{(i)}} = {\left. {\frac{{{\partial ^i}\boldsymbol{g}(\delta {\boldsymbol{x}_0})}}{{\partial \delta {\boldsymbol{x}_0} \cdots \partial \delta {\boldsymbol{x}_0}}}} \right|_{\delta {\boldsymbol{x}_0} = {\mathbf{0}_{6 \times 1}}}} \,.
\end{equation}

The derivation process of Eq.~\eqref{eq21} includes two steps. In the first step, one should derive the high-order Taylor polynomial for ${\boldsymbol{\tilde x}_1}$ with respect to $\delta {\boldsymbol{x}_0}$ as
\begin{equation} \label{eq23}
    {\boldsymbol{\tilde x}_1} = \boldsymbol{F}({\boldsymbol{\hat x}_0} + \delta {\boldsymbol{x}_0},{t_0},{t_1}) \approx {\cal T}_{\boldsymbol{F}(\delta {\boldsymbol{x}_0})}^n(\delta {\boldsymbol{x}_0}) \,,
\end{equation}
which can be obtained by implementing an 8$^{\mathrm{th}}$-order Runge-Kutta (RK78) with a relative tolerance of $10^{-12}$ and an absolute tolerance of $10^{-12}$ in the DA framework. Then, in the second step, one should derive a Taylor polynomial for ${\boldsymbol{\tilde z}_1}$ with respect to ${\boldsymbol{\tilde x}_1}$ as ${\boldsymbol{\tilde z}_1} \approx {\cal T}_{\boldsymbol{h}({{\boldsymbol{\tilde x}}_1})}^n({\boldsymbol{\tilde x}_1})$, which, after replacing ${\boldsymbol{\tilde x}_1}$ with Eq.~\eqref{eq23}, becomes Eq.~\eqref{eq21}.

By substituting the high-order Taylor polynomial approximation in Eq.~\eqref{eq21} into Eq.~\eqref{eq9}, the NLP optimization problem can be rewritten as a polynomial optimization problem (POP):
\begin{equation} \label{eq24}
    \begin{array}{*{20}{l}}
        {\mathop {\min }\limits_{\delta {\boldsymbol{x}_0}} }&{J = \delta \boldsymbol{\tilde z}_1^T\boldsymbol{R}_1^{ - 1}\delta {{\boldsymbol{\tilde z}}_1}}\\
        {{\rm{s}}{\rm{.t}}{\rm{.}}}&{\delta {{\boldsymbol{\tilde z}}_1} = {{\boldsymbol{\tilde z}}_1} - {\boldsymbol{z}_1}}\\
        {}&{{{\boldsymbol{\tilde z}}_1} \approx \boldsymbol{g}(\mathbf{0}) + \sum\limits_{i = 1}^n {{{\cal G}^{(i)}}{{(\delta {\boldsymbol{x}_0})}^i}} }\\
        {}&{\delta \boldsymbol{x}_0^T\boldsymbol{P}_0^{ - 1}\delta {\boldsymbol{x}_0} \le 2{{\cal M}_x}}
    \end{array} \,.
\end{equation}

Recall that both ${\boldsymbol{R}_1}$ and ${\boldsymbol{P}_0}$ are assumed to be positive definite matrices; therefore, the third constraint becomes a second-order cone constraint. Moreover, the nonlinear objective in Eq.~\eqref{eq24} can be easily convexified by adding a slack variable $s$ with a second-order cone constraint \cite{Han2019ASR} as
\begin{equation} \label{eq25}
    \delta \boldsymbol{\tilde z}_1^T\boldsymbol{R}_1^{ - 1}\delta {\boldsymbol{\tilde z}_1} \le s \,,
\end{equation}
and rewriting the objective function as $J = s$. Hence, the second constraint (\emph{i.e.}, ${\boldsymbol{\tilde z}_1} \approx \boldsymbol{g}(\mathbf{0}) + \sum\limits_{i = 1}^n {{{\cal G}^{(i)}}{{(\delta {\boldsymbol{x}_0})}^i}} $) becomes the only challenge in this POP as it is still nonlinear. Note that the POP in Eq.~\eqref{eq22} can be solved using general numerical optimization methods (\emph{e.g.}, sequential least squares programming [SLSQP]). However, these methods suffer from drawbacks related to requiring an initial guess or high computational cost, which will be shown in Sec.~\ref{sec:Maneuver Detection Results Using Single-Epoch Angle} and Sec.~\ref{sec:Maneuver Detection Results Using Multiple-Epoch Angle}.

Both RPOs (in this work and Ref.~\cite{Pavanello2024IEEE}) linearize this constraint. As shown in Fig.~\ref{fig1}, they adopt the same linearization approach in the first iteration; however, they differ in the second and subsequent iterations. In the first iteration, the nonlinear constraint ${\boldsymbol{\tilde z}_k} \approx \boldsymbol{g}(\mathbf{0}) + \sum\limits_{i = 1}^n {{{\cal G}^{(i)}}{{(\delta {\boldsymbol{x}_0})}^i}} $ is linearized as 
\begin{equation} \label{eq26}
    {\boldsymbol{\tilde z}_1} \approx \boldsymbol{g}(\mathbf{0}) + {{\cal G}^{(1)}}\delta {\boldsymbol{x}_0} \,.
\end{equation}
Then, the POP is reformulated as
\begin{equation} \label{eq27}
    \begin{array}{*{20}{l}}
        {\mathop {\min }\limits_{\delta {\boldsymbol{x}_0}} }&{J = s}\\
        {{\rm{s}}{\rm{.t}}{\rm{.}}}&{\delta {{\boldsymbol{\tilde z}}_1} = {{\boldsymbol{\tilde z}}_1} - {\boldsymbol{z}_1}}\\
        {}&{{{\boldsymbol{\tilde z}}_1} \approx \boldsymbol{g}(\mathbf{0}) + {{\cal G}^{(1)}}\delta {\boldsymbol{x}_0}}\\
        {}&{\delta \boldsymbol{\tilde z}_1^T\boldsymbol{R}_1^{ - 1}\delta {{\boldsymbol{\tilde z}}_1} \le s}\\
        {}&{\delta \boldsymbol{x}_0^T\boldsymbol{P}_0^{ - 1}\delta {\boldsymbol{x}_0} \le 2{{\cal M}_x}}
    \end{array} \,,
\end{equation}
becoming a second-order cone problem (SOCP).

In this work, the SOCP in Eq.~\eqref{eq27} (also the SOCPs in the second and subsequent iterations) is solved using an interior-point optimizer, MOSEK \footnote{Available at \url{https://www.mosek.com/}}, to obtain the optimal solution $\delta \boldsymbol{x}_0^{(1)}$. This solution is called the linear solution in Fig.~\ref{fig1} (represented by green markers), as only the linear term of the polynomial ${\cal T}_{\boldsymbol{g}(\delta {\boldsymbol{x}_0})}^n(\delta {\boldsymbol{x}_0})$ is considered. Since only the linear term (\emph{i.e.}, the first-order term) of the polynomial is considered in the first iteration, the accuracy of the solution cannot be guaranteed. Therefore, higher-order terms need to be incorporated in subsequent iterations. 
In this process, the RPO method proposed in this work differs from the one in Ref.~\cite{Pavanello2024IEEE}. The following section first introduces the proposed approach, as illustrated in the right subplot of Fig.~\ref{fig1}.

As shown in Fig.~\ref{fig1}, we directly define $\delta \boldsymbol{x}_0^{(j - 1)}$ as the optimal solution of the (\emph{j}-1)-th iteration. In the \emph{j}-th iteration, the proposed RPO approach linearizes the polynomial up to the highest order (\emph{i.e.}, \emph{n}) based on $\delta \boldsymbol{x}_0^{(j - 1)}$ as
\begin{equation} \label{eq31}
    {\boldsymbol{\tilde z}_1} \approx \boldsymbol{g}[\delta \boldsymbol{x}_0^{(j - 1)}] + \boldsymbol{\cal A}_1^{(j)}\Delta \boldsymbol{x}_0^{(j)} \,,
\end{equation}
where
\begin{equation} \label{eq32}
    \Delta \boldsymbol{x}_0^{(j)} = \delta \boldsymbol{x}_0^{(j)} - \delta \boldsymbol{x}_0^{(j - 1)} \,,
\end{equation}
\begin{equation} \label{eq33}
    \boldsymbol{\cal A}_1^{(j)} = \sum\limits_{i = 1}^n {i{\boldsymbol{\cal G}^{(i)}}{{[\delta \boldsymbol{x}_0^{(j - 1)}]}^{i - 1}}}  \in {\mathbb{R}^{m \times 6}} \,.
\end{equation}
Therefore, the SOCP is rewritten as
\begin{equation} \label{eq34}
    \begin{array}{*{20}{l}}
        {\mathop {\min }\limits_{\Delta \boldsymbol{x}_0^{(j)}} }&{J = s}\\
        {{\rm{s}}{\rm{.t}}{\rm{.}}}&{\delta {{\boldsymbol{\tilde z}}_1} = {{\boldsymbol{\tilde z}}_1} - {\boldsymbol{z}_1}}\\
        {}&{{{\boldsymbol{\tilde z}}_1} \approx \boldsymbol{g}[\delta \boldsymbol{x}_0^{(j - 1)}] + \boldsymbol{\cal A}_1^{(j)}\Delta \boldsymbol{x}_0^{(j)}}\\
        {}&{\delta \boldsymbol{\tilde z}_1^T\boldsymbol{R}_1^{ - 1}\delta {{\boldsymbol{\tilde z}}_1} \le s}\\
        {}&{{{(\delta \boldsymbol{x}_0^{(j - 1)} + \Delta \boldsymbol{x}_0^{(j)})}^T}\boldsymbol{P}_0^{ - 1}(\delta \boldsymbol{x}_0^{(j - 1)} + \Delta \boldsymbol{x}_0^{(j)}) \le 2{{\cal M}_x}}
    \end{array} \,.
\end{equation}

As plotted in Fig.~\ref{fig1}, once the optimal solution $\Delta \boldsymbol{x}_0^{(j)}$ is solved (using MOSEK), the initial state deviation is updated as $\delta \boldsymbol{x}_0^{(j)} = \Delta \boldsymbol{x}_0^{(j)} + \delta \boldsymbol{x}_0^{(j - 1)}$. Similarly, the approach converges when a pre-defined threshold is satisfied as
\begin{equation} \label{eq35}
    \left\| {\delta \boldsymbol{x}_0^{(j - 1)} - \delta \boldsymbol{x}_0^{(j)}} \right\| = \left\| {\Delta \boldsymbol{x}_0^{(j)}} \right\| \le \eta \,.
\end{equation}
According to the above discussions, the main process of the proposed RPO method is presented in Algorithm~\ref{alg:RPO}.

\begin{algorithm}
	\caption{Pseudocode of the proposed RPO for determining the indicator with measurement at a single epoch} \label{alg:RPO}

	\SetKwInOut{Input}{Input}
	\SetKwInOut{Output}{Output}
	\SetKwInOut{Return}{Return}

	\Input{The initial estimation (mean) ${\boldsymbol{\hat x}_0}$ and its associated covariance ${\boldsymbol{P}_0}$, orbital dynamics $\boldsymbol{f}(t,\boldsymbol{x})$, measurement model $\boldsymbol{h}(\boldsymbol{x})$, observed measurement ${\boldsymbol{z}_1} = \boldsymbol{h}({\boldsymbol{x}_1}) + {\boldsymbol{\varepsilon }_1}$ at a given epoch $t_1$, measurement noise covariance ${\boldsymbol{R}_1}$, confidence level ${\alpha _x}$, maximal order of the polynomial \emph{n}, threshold $\eta$.}
	\Output{The optimal solution $\delta \boldsymbol{x}_0^ * $ and the assoicated closest point $\delta \boldsymbol{\tilde z}_1^ * $.}

	Derive the polynomial ${\boldsymbol{\tilde z}_1} \approx {\cal T}_{\boldsymbol{g}(\delta {\boldsymbol{x}_0})}^n(\delta {\boldsymbol{x}_0})$ in the DA scheme\;

    Determine the inverse CDF of the $\chi^2$ distribution to obtain ${{\cal M}_x} = {q_{{\chi ^2}}}({\alpha _x},6)$\;

    Linearize the polynomial ${\cal T}_{\boldsymbol{g}(\delta {\boldsymbol{x}_0})}^n(\delta {\boldsymbol{x}_0})$ at zero point to obtain ${\boldsymbol{\tilde z}_1} \approx \boldsymbol{g}(\mathbf{0}) + {\boldsymbol{\cal G}^{(1)}}\delta {\boldsymbol{x}_0}$\;

    Solve the SOCP in Eq.~\eqref{eq27} to obtain the linear optimal solution $\delta \boldsymbol{x}_0^{(1)}$\;

    Let $j \gets 2$ and  ${\rm{tol}} \gets  + \infty $\;

	\While{$\rm{tol} > \eta $}{
		Linearize the polynomial ${\cal T}_{\boldsymbol{g}(\delta {\boldsymbol{x}_0})}^n(\delta {\boldsymbol{x}_0})$ at $\delta \boldsymbol{x}_0^{(j - 1)}$ to obtain ${\boldsymbol{\tilde z}_1} \approx \boldsymbol{g}[\delta \boldsymbol{x}_0^{(j - 1)}] + \boldsymbol{\cal A}_1^{(j)}\Delta \boldsymbol{x}_0^{(j)}$\;

        Solve the SOCP in Eq.~\eqref{eq34} to obtain the optimal solution $\Delta \boldsymbol{x}_0^{(j)}$\;

        Update the results as $\delta \boldsymbol{x}_0^{(j)} \leftarrow \Delta \boldsymbol{x}_0^{(j)} + \delta \boldsymbol{x}_0^{(j - 1)}$ and ${\rm{tol}} = \left\| {\delta \boldsymbol{x}_0^{(j - 1)} - \delta \boldsymbol{x}_0^{(j)}} \right\| = \left\| {\Delta \boldsymbol{x}_0^{(j)}} \right\|$\;

        $j \leftarrow j + 1$\;
	}

	\Return{$\delta \boldsymbol{x}_0^ *  \leftarrow \delta \boldsymbol{x}_0^{(j)}$ and $\delta \boldsymbol{\tilde z}_1^ *  = \boldsymbol{h}[\boldsymbol{F}({\boldsymbol{\hat x}_0} + \delta \boldsymbol{x}_0^ * ,{t_0},{t_1})] - {\boldsymbol{z}_1}$.}
\end{algorithm}

Compared with the RPO method proposed in Ref.~\cite{Pavanello2024IEEE} (shown by the subplot on the left of Fig.~\ref{fig1}), the main improvements of the proposed RPO method lie in the use of the highest-order polynomial throughout the second and subsequent iterations, without the need to gradually increase the polynomial order step by step. This modification significantly accelerates the convergence (will be illustrated in Fig.~\ref{fig5}), as all higher-order terms are utilized in each iteration based on the solution from the previous step.

When measurements at multiple epochs are available, one can stack the linear matrices in Eq.~\eqref{eq33} at different epochs to obtain
\begin{equation} \label{eq36}
    {\boldsymbol{\cal A}^{(j)}} = [\boldsymbol{\cal A}_1^{(j)};\boldsymbol{\cal A}_2^{(j)}; \cdots ;\boldsymbol{\cal A}_N^{(j)}] \in {\mathbb{R}^{Nm \times 6}} \,.
\end{equation}
Then, the same RPO process in Algorithm~\ref{alg:RPO} can be implemented.

