    \includegraphics[width=\textwidth]{figures/fig3a_deadspace_floorplan.png}
    \caption{Non-optimal floorplan}
    \Description{This is a non-optimal floorplan with three modules. The $p_0$ is on the top of $p_1$ and $p_2$ is on the right side of $p_1$.}
    \label{fig:deadspace_floorplan}
  \end{subfigure}
  \hfill
  \begin{subfigure}[b]{0.23\textwidth}
    \centering
    \includegraphics[width=\textwidth]{figures/fig3b_deadspace_tree.png}
    \caption{Slicing tree for the floorplan}
    \Description{This is a slicing tree for the floorplan. The root node is a vertical slice, and the left and right child nodes are horizontal slices and $p_2$, respectively. The child nodes of the horizontal slice are $p_1$ and $p_0$.}
    \label{fig:deadspace_tree}
  \end{subfigure}
  \hfill
