\section{Proof of \texorpdfstring{\Cref{lemma:direct_nphard_if_lemma}}{Lemma}}
\label{appendix:proof_direct_nphard_if_lemma}

\directnphardiflemma*
\begin{proof}
    First, note that if $\maxsatfull$, then we have that \cref{eq:max2sat_satisfiable} holds:
    \begin{align}
        \minclauses \leq 
        &\max_{\satvals \in \{\valfalse,\valtrue\}^{J}} \sum_{i=1}^{I} \one\{\satliteral_i^1 \lor \satliteral_i^2\}
    \end{align}
    Now, without loss of generality, let a satisfying solution have values $\satvarsatisfiedj$.
    In this case, for each variable $\satvar_j$, we construct token \token{\spacesymbol\satyesvarj\spacesymbol} if $\satvarsatisfiedj$ is true, or
    \token{\spacesymbol\satnotvarj\spacesymbol} if $\satvarsatisfiedj$ is false.
    This gives us a total of $J$ new tokens, so satisfies the $|\vocab| = |\alphabet| + \vocabsize$ condition.
    Now we just need to count the symbols output by this solution to see if \cref{eq:direct_satisfiable} is satisfied, since any given tokenisation $\tokenise(\cdot, \vocab)$ will provide an upper bound on the optimal tokenisation in terms of compression:
    \begin{align}
        %
        \sum_{\characters \in \dataset} |\directtokenfull|
        %
        \geq &\min_{\vocab' \subset \alphabet^*} \sum_{\characters \in \dataset} |\directtoken[\vocab'](\characters)| \\
        & \mathrm{s.t.}\,\,|\vocab'| = |\alphabet| + \vocabsize \nonumber
    \end{align}
    For each pair of strings $\charstring{\spacesymbol\satyesvarj\spacesymbol}$ and $\charstring{\spacesymbol\satnotvarj\spacesymbol}$ in $\dataset_1$, one is compressed into a single subword 
    %
    while the other is kept as originally---using 3 symbols.
    We thus have that the strings in $\dataset_1$ will occupy a total of $(1 + 3)J$ characters, and:
    \begin{align} \label{eq:nphard_if_proof_dataset_1}
        \sum_{\characters \in (\bigcup_{\_ = 1}^{\nrepeatvar} \dataset_1)} |\directtokenfull| = 4 \nrepeatvar J
    \end{align}
    Similarly, for each string in $\dataset_2$ of form $\charstring{\spacesymbol\satyesvarj\spacesymbol\satnotvarj\spacesymbol}$, we have that either token $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ or $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ exists.
    So each of these strings is compressed from 5 into 3 symbols.
    We thus have:
    \begin{align} \label{eq:nphard_if_proof_dataset_2}
        \sum_{\characters \in (\bigcup_{\_ = 1}^{\nrepeatvar'} \dataset_2)} |\directtokenfull| = 3 \nrepeatvar' J
    \end{align}
    Finally, we have strings in $\dataset_3$ of form $\charstring{\spacesymbol\satliteral_i^1\spacesymbol\satliteral_i^2\spacesymbol}$.
    These strings will be compressed into 3 symbols if 
    %
    $\subwordstring{\spacesymbol\satliteral_i^1\spacesymbol}$ or $\subwordstring{\spacesymbol\satliteral_i^2\spacesymbol}$ (or both) exist, and kept with 5 symbols otherwise.
    We thus have:
    \begin{subequations} \label{eq:nphard_if_proof_dataset_3}
    \begin{align}
        \sum_{\characters \in \dataset_3} |\directtokenfull| 
        &= \sum_{\characters \in \dataset_3} \Bigg(5 - 2\, \one\Bigg\{
        \!\!\!
        \begin{array}{c}
            \token{\spacesymbol\satliteral_i^1\spacesymbol} \in \vocab  \\
            \mathrm{or} \\
            \token{\spacesymbol\satliteral_i^2\spacesymbol} \in \vocab
        \end{array}
        \!\!
        \Bigg\} \Bigg) \\
        & = 5I - 2\sum_{\characters \in \dataset_3} \one\Bigg\{
        \!\!\!
        \begin{array}{c}
            \token{\spacesymbol\satliteral_i^1\spacesymbol} \in \vocab  \\
            \mathrm{or} \\
            \token{\spacesymbol\satliteral_i^2\spacesymbol} \in \vocab
        \end{array}
        \!\!
        \Bigg\}  \\
        & = 5I - 2 \sum_{i=1}^{I} 
            \one\{\satliteral_i^1  \lor \satliteral_i^2 \} \\
        & \leq 5I - 2 \minclauses
    \end{align}
    \end{subequations}
    where, by construction, we have that a subword $\subwordstring{\spacesymbol\satliteral_i\spacesymbol} \in \vocab$ if and only if its associated variable ($\satval_j$ or $\neg \satval_j$) is true.
    Summing together the lengths in \cref{eq:nphard_if_proof_dataset_1,eq:nphard_if_proof_dataset_2,eq:nphard_if_proof_dataset_3}, we get that 
    \begin{align}
        \sum_{\characters \in \dataset} |\directtokenfull| \leq \maxsymbols = (4\nrepeatvar + 3\nrepeatvar')\,J + 5\,I - 2\minclauses
    \end{align}
    which concludes the proof.
    %
    %
\end{proof}



\section{Proof of \texorpdfstring{\Cref{lemma:direct_nphard_onlyif_lemma}}{Lemma}}
\label{appendix:proof_direct_nphard_onlyif_lemma}


\directnphardonlyiflemma*
\begin{proof}
    First, note that the dataset $\dataset$ output by \cref{reduction:max2set_to_tokenisation_reduction} has a total of characters:
    \begin{align}
        \sum_{\characters \in \dataset} |\characters| = (6\nrepeatvar + 5\nrepeatvar') \satnvariables + 5\satnclauses
    \end{align}
    Further, let:
    \begin{align}
    	\tokeniselength \defeq \sum_{\characters \in \dataset} |\directtokenfull|,
    	\qquad\qquad
    	\vocabvariables = \bigcup_{j=1}^{J}
        \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}
    \end{align}
    %
    The maximum number of symbols in this dataset after compression is set to $\maxsymbols = (4\nrepeatvar + 3\nrepeatvar')\,\satnvariables + 5\,\satnclauses - 2\minclauses$.
    This means that, to satisfy this objective, there must exist a vocabulary whose tokeniser compresses the text by at least $(2\nrepeatvar + 2\nrepeatvar')\,\satnvariables + 2\minclauses$ symbols.
    We now prove this lemma in three steps: \circled{1} we show that any solution which compresses the text by at least $2\nrepeatvar \satnvariables$ symbols must only have subwords of the form \subwordstring{$\spacesymbol\satyesvarj\spacesymbol$} or \subwordstring{$\spacesymbol\satnotvarj\spacesymbol$};
    \circled{2} we show that any solution which compresses the text by at least $(2\nrepeatvar  + 2\nrepeatvar')\satnvariables$ symbols must only have either subword \subwordstring{$\spacesymbol\satyesvarj\spacesymbol$} or \subwordstring{$\spacesymbol\satnotvarj\spacesymbol$} for any variable $\satvar_j$;
    \circled{3} we show that any solution which compresses the text by at least $(2\nrepeatvar  + 2\nrepeatvar')\satnvariables + 2\minclauses$ symbols must be produced by a \maxsatacron instance which has at least $\minclauses$ clauses that are simultaneously satisfiable.
\end{proof}

\begin{mylemmastep} \textnormal{(Step \circled{1}).}
Any solution which compresses the text by at least $2\nrepeatvar \satnvariables$ symbols must only have subwords of the form \subwordstring{$\spacesymbol\satyesvarj\spacesymbol$} or \subwordstring{$\spacesymbol\satnotvarj\spacesymbol$}, i.e.,: 
\begin{align}
    &\bigg(
    \tokeniselength 
    \leq \underbrace{(4\nrepeatvar + 5\nrepeatvar') \satnvariables + 5\satnclauses}_{\sum_{\characters \in \dataset} |\characters| - 2\nrepeatvar \satnvariables}\bigg) 
    \implies 
    \vocab \subset \vocabvariables
\end{align}
\end{mylemmastep}
\begin{proof}
    First, given a solution with $\vocab \subset \vocabvariables$, each subword $\subword \in \vocab$ will replace at least $\nrepeatvar$ strings in $\dataset_1$---i.e., with form $\charstring{\spacesymbol\satyesvarj\spacesymbol}$ or $\charstring{\spacesymbol\satnotvarj\spacesymbol}$---for a single subword, thus saving $2\nrepeatvar$ characters.
    Since we have $|\vocab| = \vocabsize = \satnvariables$ tokens, we save exactly $2\nrepeatvar \satnvariables$ symbols: 
    %
    \begin{align}
        \vocab \subset \vocabvariables
        %
        \implies
        \bigg(\tokeniselengthfun(\dataset_1, \vocab')
        = \underbrace{4\nrepeatvar \satnvariables}_{\sum_{\characters \in \dataset_1} |\characters| - 2\nrepeatvar \satnvariables}\bigg) 
    \end{align}
    Note now that any solution $\vocab'$ for which $\vocab' \not\subset \vocabvariables$ has at least one subword which is not of the form $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ or $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$; 
    this subword $\subword \notin \vocabvariables$ will thus not compress strings in $\dataset_1$ by $2\nrepeatvar$ symbols, but by at most $\nrepeatvar$:
    \begin{align}
        \vocab' \not\subset \vocabvariables
        \implies
        \bigg(\tokeniselengthfun(\dataset_1, \vocab')
        \geq \underbrace{4\nrepeatvar (\satnvariables - 1) + 5\nrepeatvar}_{\sum_{\characters \in \dataset_1} |\characters| - 2\nrepeatvar \satnvariables + \nrepeatvar}\bigg) 
    \end{align}
    Even if this new subword were able to fully compress strings in $\dataset_2$ and $\dataset_3$ to a single symbol each, it would reach a compression of at most $4\nrepeatvar'\satnvariables + 4\satnclauses$.
    %
    Since by design $\nrepeatvar = 4\nrepeatvar' \satnvariables + 4\satnclauses + 1$,
    we get that:
    \begin{align}
        \vocab' \not\subset \vocabvariables
        \implies
        \bigg(\tokeniselengthfun(\dataset, \vocab')
        \geq 
        %
        %
        4\nrepeatvar \satnvariables + \nrepeatvar + 
         \nrepeatvar' \satnvariables + \satnclauses
         %
         > (4\nrepeatvar + 5\nrepeatvar') \satnvariables + 5\satnclauses
         \bigg) 
    \end{align}
    which concludes this step of the proof.
\end{proof}
\begin{mylemmastep} \textnormal{(Step \circled{2}).}
Any solution which compresses the text by at least $(2\nrepeatvar  + 2\nrepeatvar')\satnvariables$ symbols must only have either subword \subwordstring{$\spacesymbol\satyesvarj\spacesymbol$} or \subwordstring{$\spacesymbol\satnotvarj\spacesymbol$} for any variable $\satvar_j$, i.e.,:
\begin{align}
    &\bigg(
    \tokeniselength 
    \leq \underbrace{(4\nrepeatvar + 3\nrepeatvar') \satnvariables + 5\satnclauses}_{\sum_{\characters \in \dataset} |\characters| - (2\nrepeatvar  + 2\nrepeatvar')\satnvariables}\bigg) 
    %
    \implies 
    \forall_{j \in \{1, ..., J\}}\,\,
    |\vocab \cap 
    \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}| = 1
    %
\end{align}
\end{mylemmastep}
\begin{proof}
    In this step of the proof, we show that satisfying solutions must have one and only one of subwords $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ and  $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ for any variable $\satvar_j$.
    As before, it's easy to see that a solution of the form described achieves at least $(2\nrepeatvar  + 2\nrepeatvar')\satnvariables$ symbol compression.
    Each subword of form $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ or  $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ saves exactly $2\nrepeatvar$ characters in the strings in $\dataset_1$.
    Further, because we always have either subword $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ or  $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ for each value of $j$, we also get $2\nrepeatvar'$ compression in the strings in $\dataset_2$:
    \begin{align} \label{eq:direct_compression_datasets12}
        &\forall_{j \in \{1, ..., J\}}\,\,
        |\vocab \cap 
        \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}| = 1 \\
        &\qquad\qquad\qquad
        \implies 
        \bigg(
        \tokeniselengthfun(\dataset_1, \vocab)
        = \underbrace{4\nrepeatvar\satnvariables}_{\sum_{\characters \in \dataset_1} |\characters| - 2\nrepeatvar\satnvariables}\bigg) 
        \,\mathtt{and}\,
        \bigg(
        \tokeniselengthfun(\dataset_2, \vocab)
        = \underbrace{3\nrepeatvar'\satnvariables}_{\sum_{\characters \in \dataset_2} |\characters| - 2\nrepeatvar'\satnvariables}\bigg) 
        \nonumber
        %
        %
    \end{align}
    %
    Now note that this is not true if both $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ and  $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ exist for a single $j$; in this case, only one of the tokens can be applied to $\subwordstring{\spacesymbol\satyesvarj\spacesymbol\satnotvarj\spacesymbol}$, and thus both tokens together lead to a benefit of $2$ instead of $4$.
    %
    If both $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ and  $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ exist for any token $\satvar_j$, this implies that neither of $\subwordstring{\spacesymbol\satyesvarjprime\spacesymbol}$ and $\subwordstring{\spacesymbol\satnotvarjprime\spacesymbol}$ exists for some other $\satvar_{j'}$, resulting in an uncompressed string.
    Then, we get at most a compression of $2\nrepeatvar \satnvariables  + 2\nrepeatvar'(\satnvariables-1) + 4\satnclauses$:
    \begin{align}
        \exists_{j \in \{1, ..., J\}}\,\,
        |\vocab' \cap 
        \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}| \neq 1
        \implies
        \bigg(\tokeniselengthfun(\dataset, \vocab')
        \geq 
        %
        \underbrace{
        (4\nrepeatvar + 3\nrepeatvar') \satnvariables + \nrepeatvar' + \satnclauses
         }_{\sum_{\characters \in \dataset} |\characters| - (2\nrepeatvar + 2\nrepeatvar)'\satnvariables + \nrepeatvar' - 4\satnclauses}
         %
         \bigg) 
    \end{align}
    By construction 
    %
    $\nrepeatvar' = 4\satnclauses+1$,
    which leads to:
    \begin{align}
        \exists_{j \in \{1, ..., J\}}\,\,
        |\vocab' \cap 
        \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}| \neq 1
        \implies
        \bigg(\tokeniselengthfun(\dataset, \vocab')
        > (4\nrepeatvar + 3\nrepeatvar') \satnvariables + 5\satnclauses
         \bigg) 
    \end{align}
    This concludes the proof.
\end{proof}
\begin{mylemmastep} \textnormal{(Step \circled{3}).}
Any tokenisation problem with a solution which compresses the text by at least $(2\nrepeatvar  + 2\nrepeatvar')\satnvariables + 2\minclauses$ symbols must be produced by a \maxsatacron problem with at least $\minclauses$ satisfied clauses, i.e.,:
\begin{align}
    &\bigg(
    \tokeniselength 
    \leq \underbrace{(4\nrepeatvar + 3\nrepeatvar') \satnvariables + 5\satnclauses - 2\minclauses}_{\sum_{\characters \in \dataset} |\characters| - (2\nrepeatvar  + 2\nrepeatvar')\satnvariables + 2\minclauses}\bigg) 
    %
    \implies 
    \maxsatfull
    %
\end{align}
\end{mylemmastep}
\begin{proof}
    %
    Finally, we now know any solution with this compression must have---for any variable $\satvar_j$---either subword $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ or $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$.
    We can thus create a bijection $\bijectionvocabsat$ between the set of possible vocabularies respecting this condition, and the set of $\valtrue$/$\valfalse$ assignments to SAT variables $\satvals$:
    \begin{align}
        \bijectionvocabsat(\vocab) = \bigg\{
        \begin{array}{lr}
            \valtrue & \mathtt{if}\,\subwordstring{\spacesymbol\satyesvarj\spacesymbol}\in\vocab \\
            \valfalse & \mathtt{if}\,\subwordstring{\spacesymbol\satnotvarj\spacesymbol}\in\vocab
        \end{array}
        \bigg\}_{j=1}^{\satnvariables}
    \end{align}
    Further, note that vocabularies of this form (as shown in \cref{eq:direct_compression_datasets12}) lead to exactly $(2\nrepeatvar  + 2\nrepeatvar')\satnvariables$ symbols being compressed in $\dataset_1$ and $\dataset_2$.
    To achieve the target compression, a solution must thus compress $\dataset_3$ by at least $2\minclauses$ symbols.
    Now note that for any string $\charstring{\spacesymbol\satliteral_i^1\spacesymbol\satliteral_i^2\spacesymbol}$ in $\dataset_3$ we have three compression options: $\charstring{\spacesymbol\satliteral_i^1\spacesymbol}$ will be compressed, saving 2 symbols; 
    $\charstring{\spacesymbol\satliteral_i^2\spacesymbol}$ will be compressed, also saving 2 symbols; or nothing will be compressed.
    More specifically,
    $\charstring{\spacesymbol\satliteral_i^1\spacesymbol}$ can be compressed
    if $\satliteral_i^1$ represents $\satvar_j$ and subword $\subwordstring{\spacesymbol\satyesvarj\spacesymbol}$ exists,
    or if $\satliteral_i^1$ represents $\neg\satvar_j$ and subword $\subwordstring{\spacesymbol\satnotvarj\spacesymbol}$ exists; the same is true for $\charstring{\spacesymbol\satliteral_i^2\spacesymbol}$.
    They cannot both be compressed, however, as there is only one symbol $\charstring{\spacesymbol}$ between the literals.
    We thus get a compression of $2$ symbols for each of these strings if at least one of its literals has an associated subword in $\vocab$.
    Note thus that whenever a string $\charstring{\spacesymbol\satliteral_i^1\spacesymbol}$ is compressed by 2 symbols using vocabulary $\vocab$, the \maxsatacron disjunction $\satliteral_i^1 \lor \satliteral_i^2$ will also be satisfied by assignment $\satvals = \bijectionvocabsat(\vocab)$;
    similarly, whenever this string suffers no compression (i.e., having a compression of zero), the \maxsatacron disjunction will not be satisfied.
    As our condition assumes a compression of at least $2\minclauses$ symbols, we know that we have at least $\minclauses$ strings for which a literal has an associated subword.
    We can thus write:
    \begin{subequations}
    \begin{align}
         2\minclauses \leq
        &\max_{\vocab \subset \alphabet^*} \sum_{\characters \in \dataset_3} |\characters| - |\directtokenfull|  \\
        & \mathrm{s.t.}\,\,
        |\vocab| = \satnvariables \,\,\mathtt{and}\,\, \forall_{j \in \{1, ..., \satnvariables\}}\,\,
        |\vocab \cap 
        \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}| = 1 \nonumber \\
        %
        =
        &\max_{\vocab \subset \alphabet^*} \,\,\,\,\, \sum_{\charstring{\spacesymbol\satliteral_i^1\spacesymbol\satliteral_i^2\spacesymbol} \,\in\, \dataset_3} 2\,
        \one\Bigg\{
        \begin{array}{c}
             \subwordstring{\spacesymbol\satliteral_i^1\spacesymbol} \in \vocab  \\
               \mathrm{or} \\
             \subwordstring{\spacesymbol\satliteral_i^2\spacesymbol} \in \vocab
        \end{array} \Bigg\}  \\
        %
        & \mathrm{s.t.}\,\,
        |\vocab| = \satnvariables \,\,\mathtt{and}\,\, \forall_{j \in \{1, ..., \satnvariables\}}\,\,
        |\vocab \cap 
        \{\subwordstring{\spacesymbol\satyesvarj\spacesymbol}, \subwordstring{\spacesymbol\satnotvarj\spacesymbol}\}| = 1 \nonumber \\
        %
        =&\max_{\satvals \in \{0,1\}^{\satnvariables}} \sum_{i=1}^{\satnclauses} 2\one\{\satliteral_i^1 \lor \satliteral_i^2\} \\
        &\qquad\qquad \implies\,\, \maxsatfull
    \end{align}
    \end{subequations}
    We thus know that, if a satisfying tokenisation solution exists, then the associated \maxsatacron problem will also be satisfiable.
    This concludes the proof.
\end{proof}



\section{Proof of \texorpdfstring{\Cref{lemma:bottomup_nphard_if_lemma}}{Lemma}}
\label{appendix:proof_bottomup_nphard_if_lemma}


\bottomupnphardiflemma*
\begin{proof}
    Our proof starts by first defining the three following lists of merges, which will be included in any satisfying solution to the tokenisation problem:
    %
    \begin{align}
        \merges_1 = \BigCirc_{j=1}^{\satnvariables} \big[\mergestring{\spacesymboltwo}{\satnotvarj}, \mergestring{\satyesvarj}{\spacesymboltwo}\big], \quad
        \merges_3 = \BigCirc_{j=1}^{\satnvariables} \big[\mergestring{\satnotvarj}{\spacesymbol}, \mergestring{\spacesymbol}{\satyesvarj}\big], \quad
        \merges_5 = \BigCirc_{j=1}^{\satnvariables} \big[\mergestring{\spacesymbol}{\satnotvarj}, \mergestring{\satyesvarj}{\spacesymbol}\big]
    \end{align}
    %
    Now, without loss of generality, let a satisfying solution to \maxsatacron have values $\satvarsatisfiedj$.
    We then construct two other lists of merges, which depend on this \maxsatacron solution:
    %
    \begin{align}
        \merges_2 = \BigCirc_{j=1}^{\satnvariables} \left[
        \begin{array}{lr}
            \mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo} & \mathtt{if}\,\,\satvarsatisfiedj=\valtrue \\
            \mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol} & \mathtt{else}
        \end{array}
        \right], \qquad
        \merges_4 = \BigCirc_{j=1}^{\satnvariables} \left[
        \begin{array}{lr}
            \mergestring{\spacesymbol\satyesvarj}{\spacesymbol} & \mathtt{if}\,\,\satvarsatisfiedj=\valtrue \\
            \mergestring{\spacesymbol}{\satnotvarj\spacesymbol} & \mathtt{else}
        \end{array}
        \right] 
    \end{align}
    %
    in words, we create merges $\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}$ and $\mergestring{\spacesymbol\satyesvarj}{\spacesymbol}$ if  $\satvarsatisfiedj$ is true, or
    $\mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}$ and 
$\mergestring{\spacesymbol}{\satnotvarj\spacesymbol}$ if $\satvarsatisfiedj$ is false.
    We then create a merge sequence by concatenating these lists in order:
