\section{Proof of \texorpdfstring{\Cref{lemma:bottomup_nphard_onlyif_lemma}}{Lemma}}
\label{appendix:proof_bottomup_nphard_onlyif_lemma}


\bottomupnphardonlyiflemma*
\begin{proof}
%
%
%
%
    First, note that:
    \begin{align}
        \sum_{\characters \in \dataset} |\characters| = (12\nrepeatvar + 12\nrepeatvar' + 10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\,\satnclauses
    \end{align}
    Further, let:
    %
    %
    \begin{gather}
    	\tokeniselengthmerge \defeq \sum_{\characters \in \dataset} |\bottomuptokenfull|,
    	\qquad\qquad
    	\mergebase = \merges_1 \circ \merges_2 \circ \merges_3 \circ \merges_4 \circ \merges_5 \\
        %
        \merges_1 = \bigcirc_{j=1}^{\satnvariables} [\mergestring{\spacesymboltwo}{\satnotvarj}, \mergestring{\satyesvarj}{\spacesymboltwo}], \qquad
        \merges_3 = \bigcirc_{j=1}^{\satnvariables} [\mergestring{\satnotvarj}{\spacesymbol}, \mergestring{\spacesymbol}{\satyesvarj}], \qquad
        \merges_5 = \bigcirc_{j=1}^{\satnvariables} [\mergestring{\spacesymbol}{\satnotvarj}, \mergestring{\satyesvarj}{\spacesymbol}] \nonumber \\
        \merges_2 = \bigcirc_{j=1}^{\satnvariables} \left[
        \begin{array}{lr}
            \mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo} & \mathtt{if}\,\,\satvarsatisfiedj=\valtrue \\
            \mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol} & \mathtt{else}
        \end{array}
        \right], \qquad
        \merges_4 = \bigcirc_{j=1}^{\satnvariables} \left[
        \begin{array}{lr}
            \mergestring{\spacesymbol\satyesvarj}{\spacesymbol} & \mathtt{if}\,\,\satvarsatisfiedj=\valtrue \\
            \mergestring{\spacesymbol}{\satnotvarj\spacesymbol} & \mathtt{else}
        \end{array}
        \right] \nonumber \\
        \mergesthreecharsone = \bigg\{
\!\!\begin{array}{c}
\mergestring{\spacesymbol\satyesvarj}{\spacesymbol}, \mergestring{\spacesymbol}{\satnotvarj\spacesymbol} \\
\mergestring{\spacesymbol}{\satyesvarj\spacesymbol}, \mergestring{\spacesymbol\satnotvarj}{\spacesymbol}
\end{array}\!\!
        \bigg\},\qquad
        \mergesthreecharstwo = \bigg\{\!\!
\begin{array}{c}
\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}, \mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}\\
\mergestring{\spacesymbol\satyesvarj}{\spacesymboltwo}, \mergestring{\spacesymboltwo}{\satnotvarj\spacesymbol} 
\end{array}\!\!\bigg\} \nonumber \\
        \mergesthreecharstrue = \bigg\{
\!\!\begin{array}{c}
\mergestring{\spacesymbol\satyesvarj}{\spacesymbol}, 
\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}, \\
\mergestring{\spacesymbol}{\satyesvarj\spacesymbol}, 
\mergestring{\spacesymbol\satyesvarj}{\spacesymboltwo}, 
\end{array}\!\!
        \bigg\},\qquad
        \mergesthreecharsfalse = \bigg\{\!\!
\begin{array}{c}
\mergestring{\spacesymbol}{\satnotvarj\spacesymbol},
\mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}, \\
\mergestring{\spacesymbol\satnotvarj}{\spacesymbol},
\mergestring{\spacesymboltwo}{\satnotvarj\spacesymbol},
\end{array}\!\!\bigg\} \nonumber
    \end{gather}
    %
    %
    %
    The maximum number of symbols in this dataset after compression is set to $\maxsymbols = (6\nrepeatvar \!+\! 6\nrepeatvar' \!+\! 4\nrepeatvar'' \!+\! 4\nrepeatvar''')\,\satnvariables \!+\! 3\,\satnclauses \!-\! \minclauses$.
    This means that to satisfy this objective, there must exist a vocabulary whose tokeniser compresses the text by at least $(6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar''')\,\satnvariables + 2\satnclauses + \minclauses$ symbols.
    We now prove this lemma in five steps:
    \circled{1} we show that any solution which compresses the text by at least $6\nrepeatvar\satnvariables$
    %
    symbols must include all merges in $\merges_1$, $\merges_3$, and $\merges_5$;
    \circled{2} we show that any solution which compresses the text by at least $(6\nrepeatvar  + 6\nrepeatvar')\satnvariables$ symbols must only include either merges in $\merges_1$, $\merges_3$, $\merges_5$, or in either $\mergesthreecharsone$ or $\mergesthreecharstwo$;
    \circled{3} we show that any solution which compresses the text by at least $(6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'')\satnvariables$ symbols must include, for each $j \in \{1, \satnvariables\}$, exactly one merge in set $\mergesthreecharsone$ and one in set $\mergesthreecharstwo$;
    \circled{4} we show that any solution which compresses the text by at least $(6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar''')\satnvariables$ symbols must include, for each $j \in \{1, \satnvariables\}$, exactly two merge in either set $\mergesthreecharstrue$ or in set $\mergesthreecharsfalse$;
    \circled{5} we show that any solution which compresses the text by at least $(6\nrepeatvar  + 6\nrepeatvar' + 4\nrepeatvar'' + 4\nrepeatvar''')\satnvariables + 6\nrepeatvar'' + 6\nrepeatvar'')\satnvariables + 2\satnclauses + \minclauses$
    %
    symbols must be produced by a \maxsatacron problem with at least $\minclauses$ satisfied clauses.
\end{proof}

\newcommand{\mathcomment}[1]{\textcolor{gray}{\text{#1}}}

    \begin{mylemmastep} \textnormal{(Step \circled{1}).}
    Any solution which compresses the text by at least $6\nrepeatvar\satnvariables$ symbols must include all merges in $\merges_1$, $\merges_3$, and $\merges_5$, i.e.,:
    \begin{align}
        &\bigg(\tokeniselengthmerge \leq \underbrace{6\nrepeatvar\satnvariables + (12\nrepeatvar' + 10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\,\satnclauses}_{\sum_{\characters \in \dataset} |\characters| - 6\nrepeatvar\satnvariables}\bigg) 
        \\
        %
        %
        &\quad \implies
        \underbrace{\bigcirc_{j=1}^{\satnvariables} [\mergestring{\spacesymboltwo}{\satnotvarj}, \mergestring{\satyesvarj}{\spacesymboltwo}]}_{\merges_1} \subset \merges, 
        \quad
        \underbrace{\bigcirc_{j=1}^{\satnvariables} [\mergestring{\satnotvarj}{\spacesymbol}, \mergestring{\spacesymbol}{\satyesvarj}]}_{\merges_3} \subset \merges, 
        \quad
        \underbrace{\bigcirc_{j=1}^{\satnvariables} [\mergestring{\spacesymbol}{\satnotvarj}, \mergestring{\satyesvarj}{\spacesymbol}]}_{\merges_5} \subset \merges \nonumber
    \end{align}
    \end{mylemmastep}
    \begin{proof}
    We prove this statement by contradiction.
    Assume that one of the subwords above is not present in the tokenisers' merge sequence $\merges$.
    In that case, the strings in $\dataset_1$ which contain this character string will not be compressed, and will thus still be represented with 2 symbols.
    There will thus be at most $6\satnvariables-1$ strings in $\dataset_1$ represented with a single symbol, and at least one represented with two symbols.
    The minimum length achievable would thus be:
    %
    \begin{subequations}
    \begin{align}
        \tokeniselengthmerge 
        &= \underbrace{\sum_{\characters \in \bigcup_{\_ = 1}^{\nrepeatvar} \dataset_0} |\bottomuptokenfull|}_{\geq (6\satnvariables-1)\nrepeatvar + 2\nrepeatvar} + \underbrace{\sum_{\characters \in \dataset\setminus(\bigcup_{\_ = 1}^{\nrepeatvar} \dataset_0)} |\bottomuptokenfull|}_{>0} \\
%
		&> (6 \satnvariables + 1)\nrepeatvar 
        &\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!
        \mathcomment{By construction $\nrepeatvar = (12\nrepeatvar' + 10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\satnclauses$} \\
		&= (6\nrepeatvar + 12\nrepeatvar' + 10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\satnclauses 
        %
    \end{align}
    \end{subequations}
    which contradicts the proofs statement.
    \end{proof}

    \begin{mylemmastep} \textnormal{(Step \circled{2}).}
    Any solution which compresses the text by at least $(6\nrepeatvar  + 6\nrepeatvar')\satnvariables$ symbols must only include either merges in $\merges_1$, $\merges_3$, $\merges_5$, or in either $\mergesthreecharsone$ or $\mergesthreecharstwo$, i.e.,:
    \begin{align}
        &\bigg(\tokeniselength \leq \underbrace{(6\nrepeatvar + 6\nrepeatvar')\satnvariables + (10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\,\satnclauses
        }_{\sum_{\characters \in \dataset} |\characters| - (6\nrepeatvar + 6\nrepeatvar')\satnvariables}\bigg)  
       \\ &\qquad\qquad\qquad\qquad
        \implies 
        \merges \setminus(\merges_1\circ\merges_3\circ\merges_5) \subseteq 
\underbrace{\bigg\{\!\!
\begin{array}{c}
\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}, \mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}, \mergestring{\spacesymbol\satyesvarj}{\spacesymbol}, \mergestring{\spacesymbol}{\satnotvarj\spacesymbol} \\
%
\mergestring{\spacesymbol\satyesvarj}{\spacesymboltwo}, \mergestring{\spacesymboltwo}{\satnotvarj\spacesymbol}, \mergestring{\spacesymbol}{\satyesvarj\spacesymbol}, \mergestring{\spacesymbol\satnotvarj}{\spacesymbol}
\end{array}
\!\!\bigg\}_{j=1}^{\satnvariables}
}_{\bigcup_{j=1}^{\satnvariables} (\mergesthreecharsone \cup \mergesthreecharstwo)}
\nonumber
    \end{align}
    \end{mylemmastep}
    \begin{proof}
    We again prove this statement by contradiction.
    Assume that $\merges$ has all merges $\merges_1, \merges_3, \merges_5$, but one of its other merges is in neither of the sets $\mergesthreecharsone$ and $\mergesthreecharstwo$.
    This means that at least one of the sets $\mergesthreecharsone$ and $\mergesthreecharstwo$ will have no merge in the solution; this is because there are $2\satnvariables$ such sets, which---coupled together with the  $6\satnvariables$ already selected merges in $\merges_1, \merges_3, \merges_5$---would amount to the maximum of $8\satnvariables$ merges.
    In that case, the strings (e.g.,
$\charstring{\spacesymbol\satyesvarj\spacesymbol}$,
$\charstring{\spacesymbol\satnotvarj\spacesymbol}$,
$\charstring{\spacesymbol\satyesvarj\spacesymboltwo}$ and
$\charstring{\spacesymboltwo\satnotvarj\spacesymbol}$) in $\dataset_2$ containing the characters this absent merge represents will not be fully compressed to a single symbol, being represented with 2 symbols instead.
    There will thus be at most $6\satnvariables-1$ strings in $\dataset_2$ represented with a single symbol, and at least one represented with two symbols.
    The minimum length achievable would thus be:
    %
    \begin{subequations}
    \begin{align}
        \tokeniselengthmerge 
        &= \underbrace{\sum_{\characters \in \bigcup_{\_ = 1}^{\nrepeatvar} \dataset_1} |\bottomuptokenfull|}_{= 6\nrepeatvar\satnvariables} + 
        \underbrace{\sum_{\characters \in \bigcup_{\_ = 1}^{\nrepeatvar'} \dataset_2} |\bottomuptokenfull|}_{\geq (6\satnvariables-1)\nrepeatvar' + 2\nrepeatvar'} + 
        \underbrace{\sum_{\characters \in \dataset\setminus( \dataset_1\cup\dataset_2)} |\bottomuptokenfull|}_{>0} 
        \!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\! \\
%
		&> 6\nrepeatvar\satnvariables + (6 \satnvariables + 1)\nrepeatvar' 
        &\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!
        \mathcomment{By construction $\nrepeatvar' = (10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\satnclauses$} \\
		&= (6\nrepeatvar + 6\nrepeatvar' + 10\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\,\satnclauses 
        %
    \end{align}
    \end{subequations}
    which contradicts the proofs statement.
    \end{proof}

    \begin{mylemmastep} \textnormal{(Step \circled{3}).}
    Any solution which compresses the text by at least $(6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'')\satnvariables$ symbols must include all merges in $\merges_1$, $\merges_3$, $\merges_5$, and, for each $j \in \{1, \satnvariables\}$, exactly one merge in set $\mergesthreecharsone$ and one in set $\mergesthreecharstwo$, i.e.,:
    \begin{align}
        &\bigg(\tokeniselengthmerge \leq \underbrace{(6\nrepeatvar + 6\nrepeatvar' + 4\nrepeatvar'')\satnvariables + 10\nrepeatvar''' \,\satnvariables + 5\,\satnclauses 
        }_{\sum_{\characters \in \dataset} |\characters| - (6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'') \satnvariables}\bigg)  
        \\ &\qquad\quad
        \implies 
        \forall_{j \in \{1, ..., \satnvariables\}}\,\,
        \bigg|\merges \cap \underbrace{\bigg\{
\!\!\begin{array}{c}
\mergestring{\spacesymbol\satyesvarj}{\spacesymbol}, \mergestring{\spacesymbol}{\satnotvarj\spacesymbol} \\
%
\mergestring{\spacesymbol}{\satyesvarj\spacesymbol}, \mergestring{\spacesymbol\satnotvarj}{\spacesymbol}
\end{array}\!\!
        \bigg\}}_{\mergesthreecharsone}\bigg| = 1 
        \,\,\mathtt{and}\,\,
        \bigg|\merges \cap \underbrace{\bigg\{\!\!
\begin{array}{c}
\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}, \mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}\\
\mergestring{\spacesymbol\satyesvarj}{\spacesymboltwo}, \mergestring{\spacesymboltwo}{\satnotvarj\spacesymbol} 
\end{array}\!\!\bigg\}}_{\mergesthreecharstwo}\bigg| = 1
        \nonumber
    \end{align}
    \end{mylemmastep}
    \begin{proof}
    We again prove this statement by contradiction.
    First, assume that $\merges$ contains all the merges in $\merges_1, \merges_3, \merges_5$; further, assume all its other merges are contained in sets 
    $\mergesthreecharsone$ and $\mergesthreecharstwo$.
    Note now that, if any merge in $\mergesthreecharstwo$ is in the selected merges $\merges$, the string $\charstring{\spacesymboltwo\satnotvarj\spacesymbol\satyesvarj\spacesymboltwo}$ in $\dataset_3$ will be compressed to 2 symbols (e.g., $\subwordstring{\langle\spacesymboltwo\satnotvarj,\spacesymbol\satyesvarj\spacesymboltwo\rangle}$);
    if none of these merges is present, however, this string will only be compressed to 3 symbols  (e.g., $\subwordstring{\langle\spacesymboltwo\satnotvarj,\spacesymbol,\satyesvarj\spacesymboltwo\rangle}$).
    The same is true for strings $\charstring{\spacesymbol\satyesvarj\spacesymbol\satnotvarj\spacesymbol}$ and merges in $\mergesthreecharsone$.
    Now, assume the contradictory case: for a value of $j \in \{1, \satnvariables\}$, $\merges$ does not satisfy the condition above.
    As, by construction, our solution has $\vocabsize = 8\satnvariables$ merges, and because $|\merges_1 \circ \merges_3 \circ \merges_5| = 6\satnvariables$, we know that we have $2\satnvariables$ merges in sets $\mergesthreecharsone$ and $\mergesthreecharstwo$.
    As there are exactly $2\satnvariables$ such sets, if the condition above does not hold, at least one of these sets must have no merge present in $\merges$.
    In that case, the strings in $\dataset_3$ which contain the character string represented by these absent merges will be compressed to three symbols, while others will be compressed to two symbols.
    There will thus be at most $2\satnvariables-1$ strings in $\dataset_3$ represented with two symbols, and at least one represented with three symbols.
    The minimum length achievable would thus be:
    %
    \begin{subequations}
    \begin{align}
        \tokeniselengthmerge 
        &= \underbrace{\sum_{\characters \in \bigcup\limits_{\_ = 1}^{\nrepeatvar} \dataset_1 \cup \bigcup\limits_{\_ = 1}^{\nrepeatvar'} \dataset_2} \!\!\!\!\!\!\!\!\!\!\!\! 
        |\bottomuptokenfull|}_{= (6\nrepeatvar+6\nrepeatvar')\satnvariables} + 
        \underbrace{\sum_{\characters \in \bigcup\limits_{\_ = 1}^{\nrepeatvar''} \dataset_3} |\bottomuptokenfull|}_{\geq (2\satnvariables-1)2\nrepeatvar'' + 3\nrepeatvar''} + 
        \underbrace{\sum_{\characters \in 
        \bigcup\limits_{\_ = 1}^{\nrepeatvar'''} \dataset_4\cup
        \dataset_5}\!\!\!\!\!\!\!
        |\bottomuptokenfull|}_{>0} 
        %
        \\
%
		&> (6\nrepeatvar+6\nrepeatvar')\satnvariables + (4 \satnvariables + 1)\nrepeatvar'' 
        &\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\! 
        \mathcomment{By construction $\nrepeatvar'' = 10\nrepeatvar'''\,\satnvariables + 5\satnclauses$} \\
		&= (6\nrepeatvar + 6\nrepeatvar' + 4\nrepeatvar'' + 10\nrepeatvar''')\,\satnvariables + 5\,\satnclauses 
        %
    \end{align}
    \end{subequations}
    which contradicts the proof's statement.
    \end{proof}


    \begin{mylemmastep} \textnormal{(Step \circled{4}).}
    Any solution which compresses the text by at least $(6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar''')\satnvariables$ symbols must include all merges in $\merges_1$, $\merges_3$, $\merges_5$, and,
    %
    for each $j \in \{1, \satnvariables\}$, exactly one merge in set $\mergesthreecharsone$ and one in set $\mergesthreecharstwo$, such that either both these merges are in $\mergesthreecharstrue$ or both are in $\mergesthreecharsfalse$, i.e.,:
    \begin{align}
        &\bigg(\tokeniselengthmerge \leq \underbrace{(6\nrepeatvar + 6\nrepeatvar' + 4\nrepeatvar'' + 4\nrepeatvar''')\satnvariables + 5\,\satnclauses 
        }_{\sum_{\characters \in \dataset} |\characters| - (6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar''') \satnvariables}\bigg)  
        \\ &\qquad\quad
        \implies 
        \forall_{j \in \{1, ..., \satnvariables\}}\,\,
        |\merges \cap \underbrace{\bigg\{
\!\!\begin{array}{c}
\mergestring{\spacesymbol\satyesvarj}{\spacesymbol}, 
\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}, \\
\mergestring{\spacesymbol}{\satyesvarj\spacesymbol}, 
\mergestring{\spacesymbol\satyesvarj}{\spacesymboltwo}, 
\end{array}\!\!
        \bigg\}}_{\mergesthreecharstrue}| = 2 
        \,\,\mathtt{or}\,\,
        |\merges \cap \underbrace{\bigg\{\!\!
\begin{array}{c}
\mergestring{\spacesymbol}{\satnotvarj\spacesymbol},
\mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}, \\
\mergestring{\spacesymbol\satnotvarj}{\spacesymbol},
\mergestring{\spacesymboltwo}{\satnotvarj\spacesymbol},
\end{array}\!\!\bigg\}}_{\mergesthreecharsfalse}| = 2 \nonumber \\
        %
        %
    \end{align}
    %
    \end{mylemmastep}
    \begin{proof}
    First, note that the conditions of the step of our proof are stricter than previous ones, so we assume the conditions of steps \circled{1} to \circled{3} hold---i.e., $\merges$ contains all merges in $\merges_1, \merges_3, \merges_5$; further, it has one and only one merge from each set $\mergesthreecharsone$ and $\mergesthreecharstwo$.
    (Note that $\mergesthreecharsone \cup \mergesthreecharstwo = \mergesthreecharstrue \cup \mergesthreecharsfalse$, and that the just-mentioned condition implies $|\merges \cap (\mergesthreecharstrue \cup \mergesthreecharsfalse)| = 2$.)
    We now again prove this statement by contradiction.
    Consider now the case:
    \begin{align}
        \bigg|\merges \cap \underbrace{\bigg\{
\!\!\begin{array}{c}
\mergestring{\spacesymbol\satyesvarj}{\spacesymbol}, 
\mergestring{\spacesymbol}{\satyesvarj\spacesymboltwo}, \\
\mergestring{\spacesymbol}{\satyesvarj\spacesymbol}, 
\mergestring{\spacesymbol\satyesvarj}{\spacesymboltwo}, 
\end{array}\!\!
        \bigg\}}_{\mergesthreecharstrue}\bigg| = 2 
        \,\,\mathtt{or}\,\,
        \bigg|\merges \cap \underbrace{\bigg\{\!\!
\begin{array}{c}
\mergestring{\spacesymbol}{\satnotvarj\spacesymbol},
\mergestring{\spacesymboltwo\satnotvarj}{\spacesymbol}, \\
\mergestring{\spacesymbol\satnotvarj}{\spacesymbol},
\mergestring{\spacesymboltwo}{\satnotvarj\spacesymbol},
\end{array}\!\!\bigg\}}_{\mergesthreecharsfalse}\bigg| = 2 
    \end{align}
    If this is true, then strings $\charstring{\spacesymbol\satnotvarj\spacesymbol\satyesvarj\spacesymboltwo}$ and $\charstring{\spacesymboltwo\satnotvarj\spacesymbol\satyesvarj\spacesymbol}$ in $\dataset_4$ will be compressed to 2 symbols each (e.g., to $\subwordstring{\langle\spacesymbol\satnotvarj,\spacesymbol\satyesvarj\spacesymboltwo\rangle}$ and $\subwordstring{\langle\spacesymboltwo\satnotvarj,\spacesymbol\satyesvarj\spacesymbol\rangle}$ 
    or $\subwordstring{\langle\spacesymbol\satnotvarj\spacesymbol,\satyesvarj\spacesymboltwo\rangle}$ and $\subwordstring{\langle\spacesymboltwo\satnotvarj\spacesymbol,\satyesvarj\spacesymbol\rangle}$ );
    if this condition is false, however, one of these strings will only be compressed to 3 symbols (e.g., to $\subwordstring{\langle\spacesymbol\satnotvarj,\spacesymbol\satyesvarj\spacesymboltwo\rangle}$ and $\subwordstring{\langle\spacesymboltwo\satnotvarj,\spacesymbol,\satyesvarj\spacesymbol\rangle}$).
%
%
%
    %
    Now, assume the contradictory case: for a value of $j \in \{1, \satnvariables\}$, $\merges$ does not satisfy the condition above.
    %
    %
    %
    In that case, the strings in $\dataset_4$ for which the condition does not hold will be compressed to $3+2$  symbols, while others will be compressed to $2+2$ symbols.
    There will thus be at most $2\satnvariables-1$ strings in $\dataset_4$ represented with two symbols, and at least one represented with three symbols.
    The minimum length achievable would thus be:
    %
    \begin{subequations}
    \begin{align}
        \tokeniselengthmerge 
        &= \underbrace{\sum_{\characters \in \bigcup\limits_{\_ = 1}^{\nrepeatvar} \dataset_1 \cup \bigcup\limits_{\_ = 1}^{\nrepeatvar'} \dataset_2\cup \bigcup\limits_{\_ = 1}^{\nrepeatvar''} \dataset_3} \!\!\!\!\!\!\!\!\!\!\!\! 
        |\bottomuptokenfull|}_{= (6\nrepeatvar+6\nrepeatvar'+4\nrepeatvar'')\satnvariables} + 
        \underbrace{\sum_{\characters \in \bigcup\limits_{\_ = 1}^{\nrepeatvar'''} \dataset_4} |\bottomuptokenfull|}_{\geq (2\satnvariables-1)2\nrepeatvar''' + 3\nrepeatvar'''} + 
        \underbrace{\sum_{\characters \in 
        \dataset_5}
        |\bottomuptokenfull|}_{>0} 
        \\
%
		&> (6\nrepeatvar+6\nrepeatvar'+4\nrepeatvar'')\satnvariables + (4 \satnvariables + 1)\nrepeatvar''' 
        &\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\! 
        \mathcomment{By construction $\nrepeatvar''' = 5\satnclauses$\,\,} \\
		&= (6\nrepeatvar + 6\nrepeatvar' + 4\nrepeatvar'' + 4\nrepeatvar''')\,\satnvariables + 5\,\satnclauses 
        %
    \end{align}
    \end{subequations}
    which contradicts the proof's statement.
    \end{proof}


    \begin{mylemmastep} \textnormal{(Step \circled{5}).}
    Any tokenisation problem with a solution which compresses the text by at least $(6\nrepeatvar  + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar'')\satnvariables + 2\satnclauses + \minclauses$ symbols must be produced by a \maxsatacron problem with at least $\minclauses$ satisfied clauses, i.e.,:
    \begin{align}
        &\bigg(\tokeniselength \leq \underbrace{(6\nrepeatvar + 6\nrepeatvar' + 4\nrepeatvar'' + 4\nrepeatvar''')\satnvariables + 3\satnclauses - \minclauses 
        }_{\sum_{\characters \in \dataset} |\characters| - (6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar''') \satnvariables + 2\satnclauses + \minclauses}\bigg)  
        %
        \implies 
        \maxsat(\satvars, \satclauses, \minclauses) \nonumber
    \end{align} 
    \end{mylemmastep}
    \begin{proof}
    Finally, we now know any solution with this compression must have---for any variable $\satvar_j$---either two merges in $\mergesthreecharstrue$ or in $\mergesthreecharsfalse$ (and never both).
    We can thus create a bijection $\bijectionmergesat$ between the set of possible merge sequences respecting this condition, and the set of $\valtrue$/$\valfalse$ assignments to SAT variables $\satvals$:
    \begin{align}
        \bijectionmergesat(\merges) = \bigg\{
        \begin{array}{lr}
            \valtrue & \mathtt{if}\,|\merges \cap \mergesthreecharstrue|=2 \\
            \valfalse & \mathtt{if}\,|\merges \cap \mergesthreecharsfalse|=2
        \end{array}
        \bigg\}_{j=1}^{\satnvariables}
    \end{align}
    Further, note that merge sequences of this form (as shown in \cref{eq:direct_compression_datasets12}) lead to exactly $(6\nrepeatvar + 6\nrepeatvar' + 6\nrepeatvar'' + 6\nrepeatvar''')\satnvariables$ symbols being compressed in datasets $\dataset_1$ to $\dataset_4$.
    To achieve the target compression, a solution must thus compress $\dataset_5$ by at least $2\satnclauses + \minclauses$ symbols.
    Now note that for any string, e.g., $\charstring{\spacesymbol\satliteral_i^1\spacesymbol\satliteral_i^2\spacesymbol}$, 
    in $\dataset_5$ we have three compression options: $\charstring{\spacesymbol\satliteral_i^1\spacesymbol}$ and $\charstring{\satliteral_i^2\spacesymbol}$ will be compressed, saving 3 symbols; 
    $\charstring{\spacesymbol\satliteral_i^1}$ and $\charstring{\spacesymbol\satliteral_i^2\spacesymbol}$  will be compressed, also saving 3 symbols; or only 
    $\charstring{\spacesymbol\satliteral_i^1}$ and $\charstring{\satliteral_i^2\spacesymbol}$ will be compressed saving only 2 symbols.
    %
    More specifically,
    $\charstring{\spacesymbol\satliteral_i^1\spacesymbol}$ will be compressed
    if $\satliteral_i^1$ represents $\satvar_j$ and merge $\mergestring{\spacesymbol}{\satyesvarj\spacesymbol}$ exists,
    or if $\satliteral_i^1$ represents $\neg\satvar_j$ and subword $\mergestring{\spacesymbol\satnotvarj}{\spacesymbol}$ exists; the same is true for $\charstring{\spacesymbol\satliteral_i^2\spacesymbol}$.
    They cannot both be compressed, however, as there is only one symbol $\charstring{\spacesymbol}$ between the literals.
    We thus get a compression of $3$ symbols for each of these strings if at least one of its literals has an associated merge in $\merges$.
    Note thus that whenever a string $\charstring{\spacesymbol\satliteral_i^1\spacesymbol\satliteral_i^2\spacesymbol}$ is compressed by 3 symbols using vocabulary $\vocab$, the \maxsatacron disjunction $\satliteral_i^1 \lor \satliteral_i^2$ will also be satisfied by assignment $\satvals = \bijectionmergesat(\merges)$;
    similarly, whenever this string is only compressed by two symbols, the \maxsatacron disjunction will not be satisfied.
    As our condition assumes a compression of at least $2\satnclauses+\minclauses$ symbols, we know that we have at least $\minclauses$ strings for which a literal has an associated merge.
    We can thus write:
    \begin{subequations}
    \begin{align}
         2\minclauses \leq
        &\max_{\merges \in \mergeset^*} \sum_{\characters \in \dataset_3} |\characters| - |\bottomuptokenfull|  \\
        %
        %
        %
        =
        &\max_{\merges \subset \mergeset^*} \,\,\,\,\, \sum_{\charstring{\spacesymbol\satliteral_i^1\spacesymbol\satliteral_i^2\spacesymbol} \,\in\, \dataset_3} 2\,
        \one\left\{
        \begin{array}{c}
             (\satliteral_i^1 = \satvar_j) \,\,\mathtt{and}\,\, (\mergesthreecharstrue \in \merges)  \\
               \mathtt{or} \\
             (\satliteral_i^1 = \neg\satvar_j) \,\,\mathtt{and}\,\, (\mergesthreecharsfalse \in \merges)  \\
               \mathtt{or} \\
             (\satliteral_i^2 = \satvar_{j'}) \,\,\mathtt{and}\,\, (\mergesthreecharstrueprime \in \merges)  \\
               \mathtt{or} \\
             (\satliteral_i^2 = \neg\satvar_{j'}) \,\,\mathtt{and}\,\, (\mergesthreecharsfalseprime \in \merges)
             %
        \end{array} \right\}  \\
        %
        =&\max_{\satvals \in \{0,1\}^{\satnvariables}} \sum_{i=1}^{\satnclauses} 2\one\{\satliteral_i^1 \lor \satliteral_i^2\} \\
        &\qquad\qquad \implies\,\, \maxsatfull
    \end{align}
    \end{subequations}
    We thus know that, if a satisfying tokenisation solution exists, then the associated \maxsatacron problem will also be satisfiable.
    This concludes the proof.
    \end{proof}



