For a function $v\in \mathcal{U}$, we define the finite difference operators 
\begin{equation}
        \delta^c_kv^n_i:=\sum^{k}_{j=-k}\hat{b}_jv_{i+j},
\end{equation}
where $\hat{b}_j$ is fixed corresponding to center difference scheme when $N,c$ are fixed, and $v^n_i=v(i\Delta x, n\Delta t), i\in \mathbf{X}, n\in\mathbf{T}$. Again, we define compact difference operators of $c$-order derivative
\begin{align}
    \label{compact_operator}
    D^c_N v^n_i:= \sum_{j=-N}^{N}a_j \left( \frac{\partial^c v}{\partial x^c} \right)^{n}_{i+j},\ a_j>0 \ ,\ N \leq i \leq N_x-N.
\end{align}
where $a_j$ represents the weight of the term in compact scheme and notice that the number of points we used is $2N+1 $ by definition \eqref{compact_operator}.
Now the compact difference scheme of $c$-order derivative is able to be expressed in the form of
\begin{equation}
    \label{compactscheme}
    D^c_N v^{n}_i= \frac{1}{\Delta x^c}\sum_{j=1}^{\hat{N}}b_j \delta^c_j v^{n}_i,
\end{equation}
the integer $N, \hat{N}$ is defined to satisfies the consistence
\begin{equation}
    \label{compact_consistence}
     D^c_N v^{n}_i - \frac{1}{\Delta x^c}\sum_{j=1}^{\hat{N}}b_j \delta^c_j v^{n}_i = O(\Delta x^k).
\end{equation}

where $k$ is fixed and \eqref{compactscheme}-\eqref{compact_consistence} mean that we use finite difference scheme to approximate the weighted average of the derivatives of multiple points instead of the derivative of one point. The advantage of this is that a higher order of convergence can be obtained with fewer discrete points, especially in some cases of uniform grid. We use Taylor series to deduce the the integer $N, \hat{N}$ with a fixed appropriate integer $k$. 

For convenience, we also define a operator $\tilde{D}_N^c $:
\begin{equation}
    \tilde{D}_N^c  v_i^n := \sum_{j=-N}^{N}a_j v^{n}_{i+j},\ a_j>0 \ ,\ N \leq i \leq N_x-N.
\end{equation}
where $a_j$ is the coefficient of $D^c_Nv^n_i$ defined by \eqref{compact_operator}. That means we ignore the differential effect when we use the operator $ \tilde{D}_N^c$ which corresponds to operator $D_N^c$.

In this paper, the scheme we used of second derivative with $k=4$ is
\begin{equation}
    \label{D23}
    D^2_1v^{n}_i = \frac{1}{\Delta x^2}\delta^2_1 v^{n}_i,
\end{equation}
here we choose $N=1, \hat{N}=1$ for $k=4$ and expand \eqref{D23} in uniform grid with $b_1 = 1$ and $a_1 = a_{-1} = 1/12, a_0 = 5/6$
\begin{equation}
    \label{parameter}
    \frac{1}{12} \left (\frac{\partial^2 v}{\partial x^2}  \right ) ^n_{i+1}+ \frac{5}{6}\left (\frac{\partial^2 v}{\partial x^2}  \right ) ^n_{i}+\frac{1}{12} \left (\frac{\partial^2 v}{\partial x^2}  \right ) ^n_{i-1}=
    \frac{1}{\Delta x^2}\delta^2_1 v^{n}_i.
\end{equation}

With the scheme above,  we can discrete the equation and solve it.

\subsection{Compact difference scheme separating first and second time derivatives}
First, we replace the variables with the following form and transform the fourth-order equation into a second-order equation system,
\begin{empheq}[left=\empheqlbrace]{equation}
\begin{aligned}
    \phi(x,t) &=  u_t(x,t),\\
    \psi(x,t) &= u_{xx}(x,t).
\end{aligned}
\label{variable_assume}
\end{empheq}
Then equation \eqref{ebe} turns to
\begin{empheq}[left=\empheqlbrace]{align}
    EI\psi_{xx}(x,t) &=  -\rho\phi_t(x,t) - c\phi(x,t) - f(x,t), \label{eq1}\\ 
    \phi_{xx}(x,t) &= \psi_t(x,t). \label{eq2}   
\end{empheq}
In the variable substitution, $\phi(x,t)$ represents the velocity of the beam, and $\psi(x,t)$ represents the bending moment value of the beam. For simplicity in analysis, we rewrite the equation \eqref{eq1}-\eqref{eq2} with operators in the following form:
\begin{equation}
    \label{lu_f}
    \mathcal{L}H=\mathcal{F},
\end{equation}
where $H=H\left(\phi, \psi \right)$ and $\mathcal{F}$ represents the force term. Exactly $\mathcal{L}$ is a vector operator with two components
\begin{align}
    \mathcal{L} = \begin{pmatrix}
        \mathcal{\bar{L}}\\
        \mathcal{\bar{\bar{L}}}
    \end{pmatrix},
\end{align}
where
\begin{align}
    \mathcal{\bar{L}}(\phi ,\psi) &= -EI\psi_{xx} -\rho\phi_t - c\phi,\\
    \mathcal{\bar{\bar{L}}}(\phi ,\psi) &=  \phi_{xx} - \psi_t.
\end{align}
To get an spatial semidiscrete scheme we apply compact difference scheme \eqref{compactscheme} to \eqref{eq1}, notice that here $c = 2$
\begin{align}
    \label{eq1_cs1}
    D^2_1 \psi^{n}_i = \frac{1}{\Delta x^2} \delta^2_1 \psi^{n}_i,
\end{align}
by the definition of compact scheme
\begin{align}
D^2_1 EI\psi^{n}_i = \tilde{D}^2_1\left ( f-\rho\phi_t -c \phi \right ) ^{n}_{i},
    % D^2_1 EI\psi^{n}_i &= \sum_{j=-1}^{1}a_j EI\left (\frac{\partial^2 \psi}{\partial x^2}  \right ) ^n_{i}\\
    % &= \sum_{j=-1}^{1} a_j\left ( f-\rho\phi_t -c \phi \right ) ^{n}_{i+j},
    \label{eq1_cs2}
\end{align}
Where $a_j$ is already given by left terms of equation \eqref{parameter}. And apply the same way to \eqref{eq2} and notice that
\begin{align}
  D^2_1 \phi^{n}_i = \tilde{D}^2_1\left (\psi_t \right ) ^n_{i}.
    %D^2_1 \phi^{n}_i = \sum_{j=-1}^{1} a_j \left (\frac{\partial \psi}{\partial t}  \right ) ^n_{i}.
    \label{eq2_cs1}
\end{align}
We deduce the compact scheme of equation system \eqref{eq1}-\eqref{eq2} by combining \eqref{eq1_cs1}-\eqref{eq1_cs2} and \eqref{eq2_cs1}
\begin{empheq}[left=\empheqlbrace]{align}
\tilde{D}^2_1 ( f-\rho\phi_t - c\phi ) ^{n}_{i} &= \frac{1}{\Delta x^2} \delta^2_1 EI\psi^{n}_i,\label{cs1}\\
        \tilde{D}^2_1 \left (\psi_t  \right )^{n}_i &= \frac{1}{\Delta x^2}\delta^2_1 \phi^{n}_i\label{cs2},
\end{empheq}
rewrite \eqref{cs1} and \eqref{cs2} as systems of ordinary differential equations and implies
\begin{empheq}[left=\empheqlbrace]{align}
    \bm{A}\left(\rho\bm{\Phi}_t + c\bm{\Phi} - \bm{f}\right) &= \bm{B}\bm{\Psi},\label{linearsystem1}\\
    \bm{A}\bm{\Psi}_t &= -\bm{B}\bm{\Phi},\label{linearsystem2}
\end{empheq}
where we define
\begin{align}
    \bm{\Phi} &:= \left( \phi_1,\phi_2,...,\phi_{N_x-1}\right)^T,\bm{\Psi} := \left( \psi_1,\psi_2,...,\psi_{N_x-1} \right)^T,\bm{f} := \left( f_1,f_2,...,f_{N_x-1} \right)^T,\\
    \bm{\Phi}_t &:=\frac{\partial }{\partial t} \bm{\Phi} = \left(\left ( \frac{\partial \phi}{\partial t} \right ) _1,\left ( \frac{\partial \phi}{\partial t} \right ) _2,...,\left ( \frac{\partial \phi}{\partial t} \right ) _{N_x-1} \right)^T,\bm{\Psi}_t := \frac{\partial }{\partial t} \bm{\Psi} =\left( \left ( \frac{\partial \psi}{\partial t} \right ) _1,\left ( \frac{\partial \psi}{\partial t} \right ) _2,...,\left ( \frac{\partial \psi}{\partial t} \right ) _{N_x-1} \right)^T,
\end{align}
where  $\phi_i(t) = \phi(i\Delta x,t)$,  the coefficient matrix $\bm A, \bm B$ is given by the following equation
\begin{align}
    \bm A &:= \mathrm{diag}_{N_x -1}\left( \frac{1}{12},\frac{5}{6},\frac{1}{12} \right),\\
    \bm B &:= \frac{1}{\Delta x^2}\mathrm{diag}_{N_x -1}\left(-1,2,-1  \right).
\end{align}

the $\mathrm{diag}_{N_x -1}(a_{-1},a_0,a_1)$ is redefined here as tridiagonal matrix of $(N_x -1)\times(N_x -1)$ size:
\begin{equation}
    \mathrm{diag}_{N_x -1}\left( a_{-1}, a_0, a_1 \right) := \begin{pmatrix}
        a_0    & a_1  &      &     &  & & &  \\
        a_{-1} & a_0  & a_1  &    &  & & &    \\
          &a_{-1} & a_0 & a_1 &  & & &   \\
                      &   &     & ... & & & &   \\
                & &  & a_{-1}  & a_0& a_1 &  \\
                & & &   & a_{-1}& a_0 &a_1  \\
                & & & &  & a_{-1}  & a_0
    \end{pmatrix}_{(N_x -1)\times(N_x -1)}
\end{equation}
Notice that \eqref{linearsystem1}-\eqref{linearsystem2} can be organized into one linear system by combining $\bm{\Phi}$ and $\bm{\Psi}$ into a new vector,i.e.
\begin{align}
    \label{linearsystem}
    \mathcal{A}\bm{U}_t = \mathcal{B}\bm{U}+\bm{F},
\end{align}
where
\begin{align}
    \bm{U} := \begin{pmatrix}        \bm \Phi \\        \bm \Psi    \end{pmatrix},
    \bm{U}_t := \frac{\partial}{\partial t}\bm{U}
    =\begin{pmatrix}      \bm \Phi_t\\        \bm \Psi_t    \end{pmatrix},
    \bm{F} :=  \begin{pmatrix}\bm {F}_1 \\ \bm{F}_2   \end{pmatrix},
\end{align}
\begin{align}
\label{eq:the definition of matrix A and B}
    \mathcal{A} &:= \begin{pmatrix}
        \rho\bm A & \mathbf{0}\\
        \mathbf{0} & \bm A
    \end{pmatrix},
    \mathcal{B} := \begin{pmatrix}
        -c\bm A & EI\bm B\\
        -\bm B & \mathbf{0}
    \end{pmatrix},
\end{align}
and
\begin{align*}
    \bm{F}_1 &= \left( \alpha + \tilde{D}^2_1f_1,\tilde{D}^2_1f_2,\dots,\tilde{D}^2_1f_{N_x-2},\tilde{D}^2_1f_{N_x-1}+\beta \right)^T,\\
    \bm{F}_2 &= \left( \alpha',0,\dots,0,\beta' \right)^T, \\
\end{align*}
where $\alpha,\beta,\alpha',\beta'$ represents the boundary condition:
\begin{align*}
    \alpha & = - EI \frac{\psi_0(t)}{h^2}  - \rho\frac{\phi_0'(t)}{12}  - c\frac{\phi_0(t)}{12},  \\
    \beta &= -EI\frac{\psi_{N_x}(t)}{h^2}  - \rho\frac{\phi_{N_x}'(t)}{12}  - c\frac{\phi_{N_x}(t)}{12}, \\
    \alpha' &= \frac{\phi_0(t)}{h^2} - \frac{\psi_0'(t)}{12}, \\
    \beta' &= \frac{\phi_{N_x}(t)}{h^2} - \frac{\psi_{N_x}'(t)}{12} .
\end{align*}
In order to maintain the stability in time, we use Crank-Nicolson scheme\cite{sun2006efficient}, which yields
\begin{align}
    \label{The final Scheme}
    \mathcal{A}\left( \frac{\bm{U}^{n+1}-\bm{U}^{n}}{\Delta t} \right) = \mathcal{B}\left( \frac{\bm{U}^{n+1}+\bm{U}^{n}}{2} \right) + 
    \left( \frac{\bm{F}^{n+1}+\bm{F}^{n}}{2} \right).
\end{align}
We can rewrite the difference scheme above the same as \eqref{lu_f} in point-to-point form
\begin{equation}
\mathcal{L}^n_jH^n_j=G^n_j,\label{discrete_lu_f}
\end{equation}
where $H^n_j=H(\phi^n_j, \psi^n_j)$ and $G^n_j$ represents the force term. Notice that $\mathcal{L}_j^n$ is the same as $\mathcal{L}$ and also has two components 

\begin{align}
    \mathcal{L}_j^n = \begin{pmatrix}
        \mathcal{\bar{L}}_j^n\\
        \mathcal{\bar{\bar{L}}}_j^n
    \end{pmatrix},
\end{align}
where
\begin{align*}
        \mathcal{\bar L}^n_jH^n_j &:= \frac{\rho}{\Delta t}\tilde{D}^{2}_1 \left ( \phi_i^{n+1} - \phi_i^n \right )  + \frac{c}{2}\tilde{D}^{2}_1\left ( \phi_i^{n+1} + \phi_i^n \right )  + \frac{EI}{2\Delta x^2}\left ( \delta^2_1\psi^{n+1}_i + \delta^2_1\psi^{n}_i \right ), \\
        \bar{G}^n_j& := \frac{1}{2}\tilde{D}^{2}_1\left ( f^{n+1}_i + f^n_i \right ) .
\end{align*}
and
\begin{align*}
        \mathcal{\bar{ \bar{L}}}^n_jH^n_j &:= \frac{1}{\Delta t}\tilde{D}^{2}_1\left ( \psi_i^{n+1} - \psi_i^n \right )  - \frac{1}{2}\tilde{D}^{2}_1\left ( \phi_i^{n+1} + \phi_i^n \right ) , \\
        \bar{\bar{G}}^n_j& := 0 
       % \bar{\bar{G}}^n_j& := \frac{1}{2}\tilde{D}^{2}_1\left ( f^{n+1}_i + f^n_i \right ) 
\end{align*}
which are the point-by-point form corresponding to \eqref{The final Scheme}.

Since matrix $\mathcal{A}$ is invertible, the equation \eqref{The final Scheme} can be rewritten as
\begin{equation}
    \label{cn_scheme}
    \left( \bm I - \frac{\Delta t}{2}\mathcal{A}^{-1}\mathcal{B} \right)\bm{U}^{n+1} = \left( \bm I + \frac{\Delta t}{2}\mathcal{A}^{-1}\mathcal{B} \right)\bm{U}^n + \frac{\Delta t}{2}\mathcal{A}^{-1}\left(\bm{F}^{n+1}+\bm{F}^{n}\right) .
\end{equation}

Solving the above equation yields vector $\bm U ^n$, noting that vector $\bm \Psi^n \in \bm U ^n$ is the second-order spatial derivative of the original solution from \eqref{variable_assume}, and recall the compact difference scheme with $c=2$

\begin{align}
    D_1^2 u^{n}_i &= \frac{1}{\Delta x^2}\delta^2_1 u^{n}_i,\\
    \label{eq:tanslated U to u}
\end{align}
again, rewrite it as a linear system using the matrix $\bm A$ and $\bm B$
\begin{align}
    \bm A \bm \Psi ^n = -\bm B  {\bm C} ^n.
\end{align}
where ${\bm C} ^n := \left( u^{n}_1,...,u^{n}_{N_x-1} \right)^T$.

\section{Consistency, Stability and Convergence}

In this section, we give analytical proof of the consistency, stability and convergence of the difference scheme  \eqref{The final Scheme}, thereby demonstrating that the difference scheme has excellent properties.

\subsection{Consistency Analysis}
Before proving the consistency of the final scheme and the original equation, we shall prove the consistency of \eqref{discrete_lu_f} first.
\begin{lemma}
The compact scheme \eqref{discrete_lu_f} is pointwise consistent with the partial differential equation \eqref{lu_f} at point $(x,t)$ and 
\begin{equation}
   \left\| \left(\mathcal{L}H-F\right)^n_j-\left(\mathcal{L}^n_j H^n_j-G^n_j\right)\right\|_{\infty}=O(\Delta x^4)+O(\Delta t^2).
\end{equation}
\label{le:consistency of middle shceme}
\begin{proof}
Note that the scheme \eqref{discrete_lu_f}  has two part schemes so we first  expand $\mathcal{\bar L}^n_jH^n_j - \bar{G}^n_j$ into Taylor series at point $(x, t)$,  we have
\begin{align}
    \mathcal{\bar L}^n_jH^n_j - \bar{G}^n_j &=c\phi_j^{n+1}+\rho \left(\frac{\partial \phi}{\partial t}\right)_j^{n+1} +EI \left(\frac{\partial^2 \psi}{\partial x^2}\right)_j^{n+1}-f_j^{n+1} \\
&-\frac{\Delta t}{2}\left [ c\left(\frac{\partial \phi}{\partial t}\right)_j^{n+1}+\rho\left(\frac{\partial^2 \phi}{\partial t^2}\right)_j^{n+1} +EI\left(\frac{\partial^3 \psi}{\partial t\partial x^2}\right)_j^{n+1}-\left(\frac{\partial f}{\partial t}\right)_j^{n+1}  \right ] \\
&+\frac{(\Delta x)^2}{12}\left[c\left(\frac{\partial^2 \phi}{\partial x^2}\right)_j^{n+1} +\rho\left(\frac{\partial^3 \phi}{\partial t\partial x^2}\right)_j^{n+1}+EI\left(\frac{\partial^4 \psi}{\partial x^4}\right)_j^{n+1}-\left(\frac{\partial^2 f}{\partial x^2}\right)_j^{n+1}\right]\\
&-\frac{\Delta t(\Delta x)^2}{24}\left[c\left(\frac{\partial^3 \phi}{\partial t\partial x^2}\right)_j^{n+1}+\rho\left(\frac{\partial^4 \phi}{\partial t^2\partial x^2}\right)_j^{n+1} +EI\left(\frac{\partial^5 \psi}{\partial t\partial x^4}\right)_j^{n+1}-\left(\frac{\partial^3 f}{\partial t\partial x^2}\right)_j^{n+1}\right]\\
&+O(\Delta t^2)+O(\Delta x^4),
\end{align}
and then use the  equation \eqref{eq1} to eliminate the relevant terms to obtain
\begin{equation}
   \mathcal{\bar L}^n_jH^n_j - \bar{G}^n_j = O(\Delta x^4)+O(\Delta t^2).\label{consistence1}
\end{equation}
We can get the following result by similar derivation to the second scheme 
\begin{equation}
       \mathcal{\bar {\bar{L}}}^n_jH^n_j- \bar{\bar{G}}_j^n = O(\Delta x^4)+O(\Delta t^2).\label{consistence2}
\end{equation}
Combining \eqref{consistence1} and \eqref{consistence2} leads to the consistence:
\begin{align}
    \left\| \left(\mathcal{L}H-F\right)^n_j-\left(\mathcal{L}^n_j H^n_j-G^n_j\right)\right\|_{\infty} 
    &=\left\|\begin{pmatrix}
        (\mathcal{ \bar L}H-\bar F)^n_j-(\mathcal{ \bar L}^n_j H^n_j-\bar G^n_j)\\
        (\mathcal{ \bar {\bar L}}H - \bar{\bar{G}})^n_j-(\mathcal{ \bar{\bar L}}^n_j H^n_j - \bar{\bar{G}}_j^n)
    \end{pmatrix}\right\|_{\infty}\\
    &=    \max \{ (\mathcal{ \bar L}H-\bar F)^n_j-(\mathcal{ \bar L}^n_j H^n_j-\bar G^n_j),(\mathcal{ \bar {\bar L}}H - \bar{\bar{G}})^n_j-(\mathcal{ \bar{\bar L}}^n_j H^n_j - \bar{\bar{G}}_j^n)\}\\
    &=\mathcal{O}(\Delta x^4)+\mathcal{O}(\Delta t^2).
\end{align}


