\subsection{Stability Analysis}

Since the right end term matrix of \eqref{cn_scheme} has no effect on the stability of the scheme, we will simplify the equation to the following form when analyzing its stability
\begin{equation}
    \mathcal{Q}_1\bm U ^{n+1} =\mathcal{Q}_2\bm U ^n.
\end{equation}
here we denote
\begin{align}
    \mathcal{Q}_1 &= \left( \bm I - \frac{\Delta t}{2}\mathcal{A}^{-1}\mathcal{B} \right),\label{Q1}\\
    \mathcal{Q}_2 &= \left( \bm I + \frac{\Delta t}{2}\mathcal{A}^{-1}\mathcal{B} \right)\label{Q2},
\end{align}
and the amplification matrix $\mathcal{Q}$ is given by
\begin{equation}
    \mathcal{Q} = \mathcal{Q}_1^{-1} \mathcal{Q}_2.
    \label{Q}
\end{equation}
In order to obtain the stability of the scheme proposed in the previous section, we need to verify whether the spectral radius of the amplification matrix satisfies the von Neumann stability condition, that is, to verify
\begin{equation}
    \left|\rho(\mathcal{Q})\right| = \sup_{\mathcal{Q}\bm x=\lambda \bm x,\bm x\neq \bm 0} \left| \lambda \right| \leq 1.
    \label{eq:Spectral radius of Spectral radius leqslant 1}
\end{equation}
where $\rho(\mathcal{Q})$ represents the spectral radius of $\mathcal{Q}$. 

We now give a general statement and proof of the above discussion. First we will introduce some useful lemmas
\begin{lemma}
    All of the eigenvalues of a real symmetric and strictly diagonally dominant matrix with positive diagonal elements are positive real numbers.
\end{lemma}
\begin{proof}
    Let $\bm \Lambda$ be a real symmetric and strictly diagonally dominant matrix with $n$ rows and $n$ columns, and let $\eta$ be the eigenvalue of $\bm\Lambda$ with eigenvector $\bm x$ i.e. $\bm \Lambda \bm x = \eta \bm x$.\par
    For $n=1,2$ the result is trivial.\par
    Here we consider the situation with $n \geq 3$. First $\eta$ must be a real number since $\bm \Lambda$ is real symmetric. Using the Gershgorin Circle Theorem\cite{weisstein2003gershgorin}, we can deduce the estimate of $\eta$, and notice that $\bm \Lambda$ is strictly diagonally dominant i.e. 
    \begin{equation}
   \sum_{j=1,j\neq i}^{n}\left| \Lambda_{ij} \right| < \left| \Lambda_{ii}\right|  ,   
    \end{equation}
    so
    \begin{align}
        \label{eq_lemma1}
        \left| \Lambda_{ii} - \eta\right| \leq \sum_{j=1,j\neq i}^{n}\left| \Lambda_{ij} \right| < \left| \Lambda_{ii}\right|,
    \end{align}
here $\Lambda_{ij}$ denote the element of $i$th row and $j$th column. since $\Lambda_{ii} > 0$, \eqref{eq_lemma1} holds if only if $\eta > 0$ holds.
\end{proof}
%
%
\begin{lemma}
    The relation \eqref{eq:Spectral radius of Spectral radius leqslant 1} holds if and only if  $\mathfrak{Re}(z) \leq0$, where $z$ is the eigenvalue of  matrix $\mathcal{A}^{-1}\mathcal{B}$.
\begin{proof}
    First, we let $\lambda$, $\lambda_1$, $\lambda_2$, and $z$ be eigenvalues of $\mathcal{Q}$, $\mathcal{Q}_1$, $\mathcal{Q}_2$, and $\mathcal{A}^{-1}\mathcal{B}$, respectively. From the definition of $\mathcal{Q}$ implies
    \begin{align}
        \lambda = \frac{\lambda_2}{\lambda_1},
    \end{align}
since $\left(\hat{\bm A} \pm k\bm I\right)\bm x = \left(\hat{\lambda} \pm k\right)\bm x$, for any complex number $k$, and $\hat{\bm A}\bm{x} = \hat{\lambda}\bm{x}$. We deduce
    \begin{align}
        \lambda_1 &= 1-\frac{\Delta t}{2}z ,\\
        \lambda_2 &= 1+\frac{\Delta t}{2}z ,
    \end{align}
combine the results above implies
    \begin{equation}
        \lambda = \frac{1+\frac{\Delta t}{2}z}{1-\frac{\Delta t}{2}z} .
    \end{equation}
Let's set $z\Delta t = a + bi$ where  $a,b\in \mathbb{R}$. A simple computation yields
\begin{equation}
    \left | \lambda_1 \right | ^2 = (1 + \frac{a}{2} )^2 + \frac{b^2}{4} ,
\end{equation}
and
\begin{equation}
    \left | \lambda_2 \right | ^2 = (1 - \frac{a}{2} )^2 + \frac{b^2}{4} .
\end{equation}
From these calculations, we observe that $\left | \lambda_1 \right | \leq \left | \lambda_2 \right |$ if and only if $a \leq 0$and $\left | \lambda_1 \right | > \left | \lambda_2 \right |$ if and only if $a > 0$. Therefore, the relation \eqref{eq:Spectral radius of Spectral radius leqslant 1} holds if and only if $z$ be in the left-half complex plane, that is $\mathfrak{Re}(z) \leq0$.

\end{proof}
\end{lemma}

    Now we only need to prove that all the eigenvalues of $\mathcal{A}^{-1}\mathcal{B}$ have a negative real part. Before proof it, we should proof a lemma.
\begin{lemma}The matrices $ A = diag_n\left(b,a,b\right)$ and $B = diag_n\left(d,c,d\right)$ are commutative.
\label{le:commutative of three diag matricx}
    \begin{proof}
        We proceed by induction on the size of the matrices $A$ and $B$.

        First, for $n=1$, the conclusion is trivial.

        For $n=2$, through direct computation, we have
        \begin{equation}
            AB = \begin{pmatrix} a & b \\ b & a \end{pmatrix}
            \begin{pmatrix} c & d \\ d & c \end{pmatrix}
            = \begin{pmatrix} ac + bd & ad + bc \\ bc + ad & bd + ac \end{pmatrix} 
            = \begin{pmatrix} c & d \\ d & c \end{pmatrix}
            \begin{pmatrix} a & b \\ b & a \end{pmatrix}
            = BA.
        \end{equation}

        Assume that the conclusion holds for $n-1$, for the case of $n$,
        \begin{equation}
            A = \begin{pmatrix} A_1 & \alpha \\ \alpha^T & a \end{pmatrix}, 
            B = \begin{pmatrix} B_1 & \beta \\ \beta^T & c \end{pmatrix},
        \end{equation}
        where $\alpha = (0, \dots, b)^T \in \mathbb{C}^{n-1}$, $\beta = (0, \dots, d)^T \in \mathbb{C}^{n-1}$, $A_1 = \operatorname{diag}\{b, a, b\}_{n-1}$, and $B_1 = \operatorname{diag}\{d, c, d\}_{n-1}$. Computing the products, we obtain
        \begin{equation}
            AB = \begin{pmatrix} A_1 & \alpha \\ \alpha^T & a \end{pmatrix}
            \begin{pmatrix} B_1 & \beta \\ \beta^T & c \end{pmatrix}
            = \begin{pmatrix} A_1B_1 + \alpha\beta^T & A_1\beta + c\alpha \\ \alpha^TB_1 + a\alpha^T & \alpha^T\beta + ac \end{pmatrix},
        \end{equation}
        and
        \begin{equation}
            BA = \begin{pmatrix} B_1 & \beta \\ \beta^T & c \end{pmatrix}
            \begin{pmatrix} A_1 & \alpha \\ \alpha^T & a \end{pmatrix}
            = \begin{pmatrix} B_1A_1 + \beta\alpha^T & B_1\alpha + a\beta \\ \beta^TA_1 + c\alpha^T & \beta^T\alpha + ca \end{pmatrix}.
        \end{equation}

        Since both $\alpha$ and $\beta$ are vectors, it follows that $\alpha\beta^T = \beta\alpha^T$ and $\alpha^T\beta = \beta^T\alpha$. By the induction hypothesis, we know that $A_1B_1 = B_1A_1$. Thus, we have
        \begin{align}
            A_1B_1 + \alpha\beta^T &= B_1A_1 + \beta\alpha^T, \\
            \alpha^T\beta + ac &= \beta^T\alpha + ca.
        \end{align}

        Moreover, direct computation yields
        \begin{align}
            A_1\beta + c\alpha &= B_1\alpha + a\beta = (0, \dots, bd, ad + bc)^T, \\
            \alpha^TB_1 + a\alpha^T &= \beta^TA_1 + c\alpha^T = (0, \dots, bd, ad + bc).
        \end{align}

        Therefore, it follows that $AB = BA$. By the principle of induction, the lemma is proved.
    \end{proof}

\end{lemma}

\begin{remark}
    \label{remark:the commmutative of A^{-1} and B}
    From the above lemma, we know that the matrices $\bm A$ and $\bm B$, as defined in the finite difference method, are commutative, i.e., $\bm A \bm B = \bm B \bm A$. Since $\bm A$ is invertible, we multiply both sides of the equation $\bm A \bm B = \bm B \bm A$ on the left by $\bm A^{-1}$ and on the right by $\bm A^{-1}$, yielding $\bm A^{-1} \bm B = \bm B \bm A^{-1}$.
\end{remark}

\begin{lemma}
If $EI, \rho $ and $c$ are all positive numbers, then all the eigenvalues of $\mathcal{A}^{-1}\mathcal{B}$ have negative real part.
\end{lemma}
\begin{proof}
        Let $\eta = x + iy$ be an eigenvalue of the matrix $\mathcal{C} := \mathcal{A}^{-1}\mathcal{B}$ and $\zeta = \begin{pmatrix}
            \zeta_1\\ \zeta_2
        \end{pmatrix}$ be the corresponding non-zero eigenvector, where $\zeta \in \mathbb{C}^{2(N_x-1)},\zeta_1,\zeta_2\in \mathbb{C}^{N_x-1}$, i.e.
			\begin{equation}
             \mathcal{C}\zeta = 
				\mathcal{A}^{-1}\mathcal{B}\zeta = 
                \begin{pmatrix}
			      \frac{1}{\rho}\bm A^{-1}& \bm 0  \\  \bm 0& \bm A^{-1}    \end{pmatrix} 
			    \begin{pmatrix}
			      -c\bm A& EI \bm B  \\  -\bm B & \bm 0   \end{pmatrix} 
			    \mathbb{\zeta} = 
                \begin{pmatrix}
			      -\frac{c}{\rho}\bm I& \frac{EI}{\rho}\bm A^{-1} \bm B \\  -\bm A^{-1} \bm B & \mathbf{0}    \end{pmatrix} 
			    \mathbb{\zeta} =    
			    \eta \mathbb{\zeta}.
			    \label{eq:proof_C_long}
			\end{equation}
So we have two equation of  $\zeta_1$ and $\zeta_2$
\begin{equation*}
		    \left\{
		    \begin{aligned}
		    -\frac{c}{\rho}\zeta_1 + \frac{EI}{\rho}\bm{A}^{-1}\bm{B}\zeta_2 &= \eta \zeta_1,\\
		    -\bm{A}^{-1}\bm{B}\zeta_1  & = \eta \zeta_2.\\
		    \end{aligned}
		    \right.
		\end{equation*}
Then the relation between $\zeta_1$ and $\zeta_2$ is 
\begin{equation}
 \bm{A^{-1}B}\zeta_2 = \frac{\rho \eta + c}{EI}\zeta_1.
 \label{eq:the relation of zeta1 and zeta2}
\end{equation}
        Take the conjugate transpose on both sides of the equation \eqref{eq:proof_C_long} gives $\zeta^*\mathcal{C}^*  = \overline{\eta}\zeta^*$. Right multiply vector $\zeta$, we have 
			\begin{equation}
			    \zeta^*\mathcal{C}^*\zeta  = \overline{\eta}\zeta^*\zeta.
			    \label{eq:proof_B_1}
			\end{equation}
		Left multiply equation (\ref{eq:proof_C_long}) with vector $\zeta^*$, we have
			\begin{equation}
				\zeta^*\mathcal{C}\zeta  = 
				\eta\zeta^*\zeta.
				\label{eq:proof_B_2}
			\end{equation}		
	Note that $\bm A^{-1} ,\bm B$ are both symmetric matrices.We also know $\bm A^{-1} \bm B = \bm B \bm A^{-1}$from remark \ref{remark:the commmutative of A^{-1} and B}, so we have
		\begin{equation}
		    \mathcal{C}^* = 
		     \begin{pmatrix} -\frac{c}{\rho}\bm I
             & -\bm A^{-1} \bm B  \\  
		     \frac{EI}{\rho}\bm A^{-1} \bm B  & \mathbf{0}.		     			 
		     \end{pmatrix} 
		\end{equation}
		So add equation (\ref{eq:proof_B_1}) and (\ref{eq:proof_B_2}) side by side,  and  use  the relation \eqref{eq:the relation of zeta1 and zeta2} , we can perform the following calculation
		\begin{align*}
	    \zeta^*(\bm C^* + \bm C)\zeta  &=
	    \begin{pmatrix}
	        \zeta_1^* & \zeta_2^*
	    \end{pmatrix}
	    \begin{pmatrix}
	        -\frac{2c}{\rho}\bm I & (\frac{EI}{\rho} - 1)\bm A^{-1} \bm B  \\ 
	        (\frac{EI}{\rho} - 1)\bm A^{-1} \bm B & \bm 0
	    \end{pmatrix}
	    \begin{pmatrix}	        \zeta_1 \\	        \zeta_2	    \end{pmatrix} \\ 
	    &= -\frac{2c}{\rho}\zeta_1^*\zeta_1 
	    + \left(\frac{EI}{\rho} - 1\right)\zeta_1^*\bm A^{-1} \bm B\zeta_2  
	    + \left(\frac{EI}{\rho} - 1\right)\zeta_2^*\bm A^{-1} \bm B\zeta_1\\
	    &= -\frac{2c}{\rho}\zeta_1^* \zeta_1 
	    + 2\mathfrak{Re} \left[\left(\frac{EI}{\rho} - 1\right)\zeta_1^*\bm A^{-1} \bm B\zeta_2\right]\\
	    &= -\frac{2c}{\rho}\zeta_1^*\zeta_1 
	    + 2\left(\frac{EI}{\rho} - 1\right)\mathfrak{Re} \left[\zeta_1^*\bm A^{-1} \bm B\zeta_2\right]\\
	    &= -\frac{2}{\rho} \left\{c\zeta_1^*\zeta_1 
	    + (\rho - EI)\mathfrak{Re} \left[\zeta_1^*\bm A^{-1} \bm B\zeta_2\right]\right\}\\
	    &= -\frac{2}{\rho} \left[c +\left (\frac{\rho}{EI} - 1\right)\mathfrak{Re}(\rho\eta+c)\right]\zeta_1^*\zeta_1\\
	    &= -2\left[\left(\frac{\rho}{EI} - 1\right)\mathfrak{Re}(\eta) + \frac{c}{EI}\right]\zeta_1^*\zeta_1\\
        &= (\eta + \overline{\eta})\zeta^*\zeta \\
	    &= 2\mathfrak{Re}(\eta)\zeta^*\zeta ,
	\end{align*}
	Taking the last formula and the third to last formula of calculation above, we have
    \begin{equation*}
        \left[\left(1 - \frac{\rho}{EI}\right)\mathfrak{Re}(\eta) - \frac{c}{EI}\right]\zeta_1^*\zeta_1 = \mathfrak{Re}(\eta)\zeta^*\zeta ,
    \end{equation*}

    Note that  $\zeta^*\zeta = \zeta_1^*\zeta_1 + \zeta_2^*\zeta_2$, then  we have
    \begin{equation*}
        -\left(\frac{\rho}{EI}\zeta^*_1\zeta_1 + \zeta^*_2\zeta_2\right) \mathfrak{Re}(\eta) =         \frac{c}{EI}\zeta_1^*\zeta_1.
    \end{equation*}
     It's easy to note that $\zeta_1^*\zeta_1 \ge 0$ and $\zeta^*_2\zeta_2 \ge 0$. And by assumption, so we must have $\mathfrak{Re}(\eta) \le 0$.
\end{proof}

\begin{remark}
    The conditions in the theorem are that $EI$,$\rho$,$c$ are all positive numbers, and in the actual physical background, these values are all positive numbers. Therefore, we have proved the stability of this method in general engineering calculations.
\end{remark}


\begin{remark}
    Note that if only the real part of the eigenvalue of $\mathcal{B}$ is less than or equal to 0, it cannot be obtained that the real part of the eigenvalue of $\mathcal{A}^{-1}\mathcal{B}$ is less than or equal to 0, where $\mathcal{A}$ is defined by \eqref{eq:the definition of matrix A and B}. For example, let $EI = \rho = c = 1$, and $\mathcal{A},\mathcal{B} $ are both  fourth-order matrices, where 
    \begin{equation*}
        \mathcal{B} = \begin{bmatrix}
        -3 & -4 & 3 & -2 \\
        5 & 0 & 0 & 2 \\
        4 & -1 & -1 & 5 \\
        -2 & 5 & -4 & -2
        \end{bmatrix}
    \end{equation*}
then we can compute that the eigenvalues of  $\mathcal{B}$  and $\mathcal{A}^{-1}\mathcal{B}$ are
\begin{table}[h!]
