\hline
\textbf{Eigenvalues of $\mathcal{B}$}& \textbf{Eigenvalues of $\mathcal{A}^{-1}\mathcal{B}$}\\ \hline
$-4.2503 + 0.0000i$ & $-6.4027 + 0.0000i$ \\ \hline
$-1.3154 + 0.0000i$ & $-1.2627 + 0.0000i$ \\ \hline
