            \ALIRLet{$T(x, y)$}
                \ALIRFor{$x \in A.x$}
                    \ALIRFor{$y \in A.y \cap \{ y \mid x^2 + y^2 = r^2 \}$}
                        \State $(x, y).$
                    \EndALIRFor
                \EndALIRFor
            \ALIRIn
                \ALIRFor{$y \in T.y \cap B.y$}
                    \ALIRFor{$z \in B.z$}
                        \ALIRFor{$x \in T.x$}
