\subsection{Random Permutations}
As described earlier, for a given $t$, the base parity-check matrix $\textbf{H}_{\text{base}-(t,1)}$ consists of column groups of sizes $2t-1, 2t-3, \cdots, 5, 3, 1$. 
For a given \(t\), blocklength \(N \leq t^2\), number of permutations \texttt{num\_per}, and a given $base$, we construct a parity-check matrix $\mathbf{H}$ for an FDPC\((N, N - 2t \times (\texttt{num\_per}+1))\) code, as described in Algorithm \ref{alg:1}.
The matrix \(\mathbf{H}\) has \(\texttt{m\_size} = 2t \times (\texttt{num\_per}+1)\) rows, and the first \texttt{m\_size} columns exhibit a bidiagonal structure, allowing the FDPC code to be encoded using the encoder shown in Fig. \ref{fig: encoder_base1}, as described in lines 12 to 17 of Algorithm \ref{alg:1}.
For the columns starting from the $(\texttt{m\_size}+1)$-th column of the base matrix, which we refer to as submatrix \(\mathbf{C}\), we perform \texttt{num\_per} random column permutations and append them below submatrix \(\mathbf{C}\), as described in lines 4 to 11. Additionally, in lines 19 to 21, we remove columns from the resulting parity-check matrix \(\mathbf{H}\), starting from column \(\texttt{m\_size} + 1\), until the matrix \(\mathbf{H}\) contains exactly \(N\) columns.
The obtained parity check matrix $\mathbf{H}$ has a format demonstrated as follows:
\begin{equation*}
\scriptsize
    \mathbf{H} = 
    \left[
    \begin{array}{ccccc|c}
    \R{1} & 0 & 0 & 0 & 0 & \multirow{2}{*}{\(\mathbf{C}\)} \\
    \R{1} & \R{1} & 0 & 0 & 0 &  \\
    0 & \R{1} & \R{1} & 0 & 0 & \raisebox{0.1cm}{\(\pi_1(\mathbf{C})\)} \\
    0 & 0 & \textcolor{red}{\ddots} & \textcolor{red}{\ddots} & 0 & \raisebox{0.1cm}{\vdots} \\
    0 & 0 & 0 & \R{1} & \R{1} & \raisebox{0.1cm}{\(\pi_{\texttt{num\_per}}(\mathbf{C})\)} \\
    \end{array}
    \right].
\end{equation*}






\begin{algorithm}[t] 
\footnotesize
\caption{FDPC Code Construction}\label{alg:1}
\begin{algorithmic}[1]
\Statex \hspace*{-\algorithmicindent} \textbf{Input:} $t$, $num\_per$, $N$, \text{base}
\Statex \hspace*{-\algorithmicindent} \textbf{Output:} $\mathbf{H}$ 

\State $m\_base \gets 2t$

\State $m\_size \gets m\_base + num\_per \times m\_base$

\State $\mathbf{H}, n \gets \text{generate\_base\_matrix}(t, base)$ % base=1--> n = 2^2, base=2 --> n=t(t+1)/2


\State $\mathbf{C} \gets \mathbf{H}[:, m\_size+1:\text{end}]$

\For {$i = 1 \textbf{ to } num\_per$}
    \State $col\_permutation \gets \text{randperm}(\text{size}(\mathbf{C}, 2))$
    \State $\mathbf{C}\_permuted \gets \mathbf{C}[:, col\_permutation]$ 
    \State $\mathbf{H}\_permuted \gets zeros(m\_base, n)$
    \State $\mathbf{H}\_permuted[:, m\_size+1:\text{end}] \gets \mathbf{C}\_permuted$
    \State $\mathbf{H} \gets [\mathbf{H}; \mathbf{H}\_permuted]$
\EndFor

\State \Comment{For the encoder}
\State $\mathbf{H}[1:m\_size, 1:m\_size] \gets \mathbf{0}$
\For {$i = 1 \textbf{ to } m\_size-1$}
    \State $\mathbf{H}[i,i] \gets 1$
    \State $\mathbf{H}[i+1,i] \gets 1$
\EndFor
\State $\mathbf{H}[m\_size, m\_size] \gets 1$

\If {$N \neq n$}
    \State Remove columns \( m\_size+1 \) to \( m\_size + (n - N) \) from \(\mathbf{H}\)
\EndIf

\end{algorithmic}
\end{algorithm}





