For a given $t$ and $base$, Algorithm \ref{alg:2} generates a base parity-check matrix.
The variable \texttt{gap} is initialized to $0$ in line 3 of Algorithm~\ref{alg:2}. This variable determines the gap between the two ones in each column, as described in lines 9 and 10 of the algorithm. The gap increases by 2 for each group of columns in line 13. Additionally, this variable determines the size of each group of columns, which is used to run the iterations over the diagonals of the group submatrices in line 5. 

The variable \texttt{col} tracks the current column of the base matrix and increments until it reaches $t^2$. Lines 4 to 13 construct the \( \mathbf{H}_{\text{base}-(t,1)} \) matrix. 

For $base = 2$, we remove the columns that have 2, 6, 10, $\cdots$ zeros between the ones from the constructed \( \mathbf{H}_{\text{base}-(t,1)} \) matrix in lines 15 to 28. The variable \texttt{current\_gap} determines the number of zeros between the ones corresponding to the columns that need to be removed. It is initialized to $0$ and increases by $4$ in each iteration. The variable \texttt{valid\_columns} stores the indices of the columns that need to be kept, initially containing all indices from 1 to $t^2$. We remove the invalid columns at line 22; these are the columns where the distance between the ones is $\texttt{current\_gap} + 1$. 
For example, when $\texttt{current\_gap} = 2$, the distance between the ones is 3, and these columns are removed.


\begin{algorithm}
\footnotesize
\caption{Base Matrix}\label{alg:2}
\begin{algorithmic}[1]
\Statex \hspace*{-\algorithmicindent} \textbf{Input:} $t$, $base$
\Statex \hspace*{-\algorithmicindent} \textbf{Output:} $\mathbf{H}$, $\text{size}(\mathbf{H}, 2)$ 

\State $\mathbf{H} \gets \mathbf{0}$ \Comment{Initialize $\mathbf{H}$ of size $2t$ by $t^2$.}
\State $col \gets 1$ \Comment{Initialize the column index}
\State $gap \gets 0$ \Comment{No gap between ones at the start}

\While {$col \leq t^2$}
    \For {$row = 1$ \textbf{to} $2t - gap - 1$}
        \If {$col > t^2$}
            \State \textbf{break} \Comment{Break if the column index exceeds $t^2$}
        \EndIf
        \State $\mathbf{H}[row, col] \gets 1$ \Comment{Place 1 in the current row and column}
        \State $\mathbf{H}[row + gap + 1, col] \gets 1$ \Comment{Place 1 with a gap in the same column}
        \State $col \gets col + 1$ \Comment{Move to the next column}
    \EndFor
    \State $gap \gets gap + 2$ \Comment{Increase the gap by 2 for the next group of columns}
\EndWhile

\If {$base == 2$} 
    \State \Comment{Step 1: Remove columns where the gap is 2, 6, etc.}
    \State $valid\_columns \gets \mathbf{true}(1, \text{size}(\mathbf{H}, 2))$ \Comment{All col initially valid}
    \State $current\_gap \gets 2$ \Comment{Start from a gap of 2 zeros between ones}

    \While {$current\_gap < \text{size}(\mathbf{H}, 1) - 1$}
        \For {$col = 1$ \textbf{to} $\text{size}(\mathbf{H}, 2)$}
            \If {\text{any(diff(find(H(:, col) == 1)) == current\_gap + 1)}}
                \State $valid\_columns[col] \gets \mathbf{false}$ \Comment{Mark column for removal}
            \EndIf
        \EndFor
        \State $current\_gap \gets current\_gap + 4$ \Comment{2, 6, etc.}
    \EndWhile

    \State $\mathbf{H} \gets \mathbf{H}(:, valid\_columns)$ \Comment{Keep only the valid columns}
\EndIf

\end{algorithmic}
\end{algorithm}


\begin{remark}
    For an odd $ t = 2k + 1 $, the base matrix $ \mathbf{H}_{\text{base-(t,2)}} $ is a regular matrix with row weights of $ \frac{t+1}{2} $. However, for an even $ t = 2k $, the base matrix has row weights of $ \lceil \frac{t}{2} \rceil $, except for the first and last rows, which have weights of $ \lfloor \frac{t}{2} \rfloor $.
\end{remark}

\section{Numerical results}\label{sec:numerical}
In this section, we demonstrate simulations over the binary-input additive white Gaussian noise (BI-AWGN) channel model with a binary phase-shift keying (BPSK) modulation. For the FDPC and LDPC codes, we employ the normalized min-sum algorithm.
For the polar codes, we employ the scaled min-sum algorithm with a scaling factor of $0.9375$ \cite{yuan2014early}.
The ECP metrics are the frame error rate (FER) and bit error rate (BER).


\subsection{FDPC(256, 192) code}
Starting from base~1 with a single permutation, we construct a parity-check matrix of size $64 \times 256$ with $t = 16$, resulting in an FDPC$(256, 192)$ code. 
Figure~\ref{fig: polarBP_FDPCminsum_N256_K192} shows the FER and BER performance of this code using the normalized min-sum algorithm with both 50 and 5 decoding iterations. 
For comparison, the performance of the polar$(256, 192)$ code—constructed using Gaussian approximation at $E_b/N_0 = 4\,\mathrm{dB}$—is also plotted in the same figure under BP decoding with 50 and 5 iterations. 
Additionally, the performance of the 5G LDPC code is included for reference. 
Notably, the FDPC code with just 5 iterations outperforms the polar code with 50 iterations and achieves approximately a 1~dB coding gain over the polar code with 5 iterations and the 5G LDPC code with 50 iterations at an FER level of $10^{-3}$.\footnote{All of the codes simulated in this paper are available at \href{https://github.com/moradi-coding/}{https://github.com/moradi-coding/}.} 



\begin{figure}[htbp] 
\centering
	\includegraphics [width = \columnwidth]{./figs/polarBP_FDPCminsum_N256_K192.pdf}
	\caption{ECP comparison of $(256,192)$ FDPC, 5G LDPC, and polar codes.} 
	\label{fig: polarBP_FDPCminsum_N256_K192}
\end{figure}



\subsection{FDPC(128, 80) code}
Starting from base 1 with one permutation, we first construct a parity-check matrix of size $48 \times 144$ with $t = 12$. 
Then, we remove columns starting from the $(4t + 1) = 49$-th column through the 65th column, resulting in a parity-check matrix of size $48 \times 128$. 
This produces an FDPC$(128, 80)$ code.
Fig. \ref{fig: polarBP_FDPCminsum_N128_K80} shows the FER and BER performance of this FDPC code using the normalized min-sum algorithm with 5 and 50 iterations. 
For comparison, the performance of a polar$(128, 80)$ code (the codeword length of polar codes is a power of two), constructed using the Gaussian approximation and decoded with the BP algorithm under the same number of iterations, is also plotted.
Additionally, the performance of the 5G LDPC code is included for reference. 
Notably, the FDPC code with just 5 iterations outperforms the polar code with 50 iterations and achieves approximately a $0.5$~dB coding gain over the polar code with 5 iterations and a $1.5$~dB coding gain over the 5G LDPC code with 50 iterations at a FER level of $10^{-3}$.


\begin{figure}[htbp] 
\centering
	\includegraphics [width = \columnwidth]{./figs/polarBP_FDPCminsum_N128_K80.pdf}
	\caption{ECP comparison of $(128,80)$ FDPC, 5G LDPC, and polar codes.} 
	\label{fig: polarBP_FDPCminsum_N128_K80}
\end{figure}


\subsection{FDPC(256, 164) code}

Using the $\mathbf{H}_{\text{base-(23,2)}}$ with one permutation, we first construct a $92\times 276$ parity-check matrix.  
By removing columns starting from the 93rd column, we obtain an FDPC$(256, 164)$ code.  
The ECP of this code is plotted in Fig. \ref{fig: polarBP_FDPCminsum_N256_K164} using 5 and 50 iterations of the normalized min-sum algorithm.  
For comparison, the figure also includes the performance of a polar$(256, 164)$ code using BP decoding.  
The polar code is constructed using the Gaussian approximation at $E_b/N_0 = 4~$dB and decoded with the same number of iterations.
Additionally, the performance of the 5G LDPC code is included for reference. 
Notably, the FDPC code with just 5 iterations achieves approximately a $0.5$~dB coding gain over the polar code and 5G LDPC code with 50 iterations at an FER level of $10^{-3}$.


\begin{figure}[htbp] 
\centering
	\includegraphics [width = \columnwidth]{./figs/polarBP_FDPCminsum_N256_K164.pdf}
	\caption{ECP comparison of $(256,164)$ FDPC, 5G LDPC, and polar codes.} 
