\section{Preliminaries}
% ================================================== %
% In order to facilitate the integration of the previous research methods with our proposed method, we have modified some of the notations used in the prior works.

% ---------------------------------------- %
\subsection{Mixed-Variable Black-Box Optimization}
% ---------------------------------------- %
We consider the mixed-variable function $f$ which has $\Nco$ continuous variables, $\Nin$ integer variables, and $\Nca$ categorical variables. 
The search space of $f$ is given by $\mathcal{X} \times \mathcal{Z} \times \mathcal{C}$, where $\mathcal{X} = \R^{\Nco}$, $\mathcal{Z} = \mathcal{Z}_1 \times \cdots \times \mathcal{Z}_{\Nin}$, and $\mathcal{C} = \mathcal{C}_1 \times \cdots \times \mathcal{C}_{\Nca}$.
The $n$-th integer domain $\mathcal{Z}_n$ and the $n$-th categorical domain $\mathcal{C}_n$ are defined as
\begin{align}
    \mathcal{Z}_n &= \left\{ z_{n,1}, \ldots, z_{n,L_n} \right\} \enspace, \\
    \mathcal{C}_n &= \left\{ \bc_n \in \{0, 1\}^{K_n} \enspace \middle| \enspace \sum_{k=1}^{K_n} \bc_{n, k} = 1 \right\} \enspace,
\end{align}
where $L_n$ is the number of elements in the $n$-th integer variable and $K_n$ is the number of categories in the $n$-th categorical variable.
We note that $z_{n,l}$ is the $l$-th smallest integer in $\mathcal{Z}_n$, and $\bc_n$ is a $K_n$-dimensional one-hot vector.
% In this study, the elements in $\mathcal{Z}_n$ are not restricted to integers and can include non-integer values such as $0.01$ or $0.1$.
% In this study, the integer domain $\mathcal{Z}_n$ can also include non-integer values such as $0.1$.
In this study, the integer domain $\mathcal{Z}_n$ can include discrete non-integer values, as in $\mathcal{Z}_n = \{0.01, 0.1, 1\}$.

% ---------------------------------------- %
\subsection{CMA-ES with Margin} \label{ssec:cmawm}
% ---------------------------------------- %
The CMA-ES with Margin~(CMA-ESwM)~\cite{CMAwM:2022} is one of the promising methods for mixed-integer black-box optimization based on the CMA-ES.
The CMA-ESwM employs a multivariate Gaussian distribution $\mathcal{N}(\m[t], (\sig[t])^2 \A[t] \C[t] \A[t])$, where $\m[t] \! \in \R^{\Nmi := \Nco + \Nin}$ is the mean vector, $\sig[t] \in \R_{>0}$ is the step-size, $\A[t] \! \in \R^{\Nmi \times \Nmi}$ is a diagonal matrix, and $\C[t] \! \in \R^{\Nmi \times \Nmi}$ is the covariance matrix.
The CMA-ESwM repeats the update of the distribution parameters based on the update rules of the CMA-ES and the margin correction, which is an integer handling for the multivariate Gaussian distribution.

% ........................................ %
\subsubsection{Update Rules Based on the CMA-ES} \label{sssec:update_based_on_cmaes}
% ........................................ %
~ The CMA-ESwM generates $\lambda$ candidate solutions $(\x_1, \z_1), \ldots, (\x_\lambda, \z_\lambda)$ at each iteration according to the multivariate Gaussian distribution.
First, we transform samples $\bxi_1, \ldots, \bxi_\lambda$ generated from the $\Nmi$-dimensional standard normal distribution $\mathcal{N}(\boldsymbol{0}, \mathbf{I}_\Nmi)$.
\begin{align}
    \y_i &= \sqrt{\C[t]} \bxi_i \\
    \bv_i &= \m[t] + \sig[t] \A[t] \y_i
\end{align}
The candidate solutions are obtained by discretizing some dimensions of $\bv_1, \ldots, \bv_\lambda$.
In index set $\{1, \ldots, \Nmi \}$, let $\jco_n$ be the index of the $n$-th continuous variable and let $\jin_n$ be the index of the $n$-th integer variable. Then, we note that $\{ \jco_1, \ldots, \jco_{\Nco} \} \cup \{ \jin_1, \ldots, \jin_{\Nin} \} = \{ 1, \ldots, \Nmi \}$.
The discretization is performed by the encoding function $\Enc$ defined as follows:
\begin{align*}
    [\Enc(\bv)]_{\jco_n} &= [\bv]_{\jco_n} \quad \text{for} \enspace n \in \{1, \ldots, \Nco \} \enspace, \\
    [\Enc(\bv)]_{\jin_n} &= \begin{cases}
        z_{n,1} \!\!\!\!\! &\text{if} \enspace [\bv]_{\jin_n} \leq \ell_{n, 1|2}\\
        z_{n,l} \!\!\!\!\! &\text{if} \enspace \ell_{n, l-1|l} < [\bv]_{\jin_n} \leq \ell_{n, l|l+1}\\
        z_{n,L_n} \!\!\!\!\! &\text{if} \enspace \ell_{n, L_n-1|L_n} < [\bv]_{\jin_n} \quad \text{for} \enspace n \in \{1, \ldots, \Nin \}
    \end{cases}
\end{align*}
We denote the $n$-th element of a vector $\bv$ as $[\bv]_n$ and define the threshold between the two consecutive integers $z_{n, l}$ and $z_{n, l+1}$ as $\ell_{n, l|l+1} = (z_{n, l} + z_{n, l+1})/2$.
Then, each element of the candidate solutions is obtained as follows:
\begin{align}
    [\x_i]_n &= [\Enc(\bv_i)]_{\jco_n} \quad \text{for} \enspace n \in \{1, \ldots, \Nco \} \\
    [\z_i]_n &= [\Enc(\bv_i)]_{\jin_n} \quad \text{for} \enspace n \in \{1, \ldots, \Nin \}
\end{align}
The candidate solutions $(\x_1, \z_1), \ldots, (\x_\lambda, \z_\lambda)$ are evaluated by the objective function $f$ and ranked according to their evaluations.

The mean vector is updated as
\begin{align}
    \m[t+1] = \m[t] + c_m \sig[t] \A[t] \sum_{i=1}^\mu w_i \y_{i:\lambda} \enspace, \label{eq:update_m}
\end{align}
where $c_m$ is the learning rate, $i \! :\! \lambda$ denotes the index of the $i$-th best \linebreak sample, and the weight $w_i$ satisfies $w_1 \! \geq \!\cdots\! \geq \! w_\mu \! > \! 0$ and $\sum_{i=1}^\mu \! w_i \! = \! 1$.

The evolution paths are updated as
\begin{align}
    \ps[t+1] &= (1-c_\sigma) \ps[t] + \sqrt{c_\sigma(2-c_\sigma)\muw} (\C[t])^{\! -\frac12} \! \sum_{i=1}^\mu w_i \y_{i:\lambda} ~, \label{eq:update_ps} \\
    \pc[t+1] &= (1-c_c) \pc[t] + h_\sigma \sqrt{c_c(2-c_c)\muw} \sum_{i=1}^\mu w_i \y_{i:\lambda} ~, \label{eq:update_pc}
\end{align}
where $c_\sigma$ and $c_c$ are cumulative rates and $\muw$ denotes $(\sum_{i=1}^\mu w^2_i)^{-1}$. The Heaviside function $h_\sigma$ takes $1$ if it holds
\begin{align}
    \frac{\| \ps[t+1] \|^2}{\sqrt{1 - (1 - c_\sigma)^{2(t+1)}}} < \left( 1.4 + \frac{2}{\Nmi + 1} \right) \E \left[ \left\| \mathcal{N} \left(\boldsymbol{0}, \mathbf{I}_{\Nmi} \right) \right\| \right] \enspace,
\end{align}
and $h_\sigma$ takes $0$ otherwise.
We note that the expected norm \linebreak $\smash{\E \left[ \left\| \mathcal{N} \left(\boldsymbol{0}, \mathbf{I}_{\Nmi} \right) \right\| \right]}$ is approximated by $\smash{\sqrt{\Nmi}\left( 1 - \frac{1}{4\Nmi} + \frac{1}{21\Nmi^2} \right)}$.

The covariance matrix is updated as
\begin{align}
    \begin{split}
    \C[t+1] &= \left( 1 - c_1 - c_\mu \sum_{i=1}^\lambda w_i \bigl. + (1-h_\sigma) c_1 c_c (2-c_c) \right) \C[t] \\
    &\qquad\qquad + c_1 \pc[t+1](\pc[t+1])^\top+ c_\mu \sum_{i=1}^\lambda w^\circ_i \y_{i:\lambda} \y_{i:\lambda}^\top \enspace,
    \end{split} \label{eq:update_C}
\end{align}
where $c_1$ and $c_\mu$ are learning rates and $w^\circ_i$ is given as follows:
\begin{align}
    w^\circ_i = 
    \begin{cases}
        w_i \quad &\text{if} \enspace w_i \geq 0 \\
        w_i \cdot \frac{\Nmi}{\left\| (\C[t])^{-\frac12} \y_{i:\lambda} \right\|^2} \quad &\text{otherwise}
    \end{cases} \label{eq:negative_weight}
\end{align}

The step-size is updated with cumulative step-size adaptation as
\begin{align}
    \sig[t+1] = \sig[t] \exp \left( \frac{c_\sigma}{d_\sigma} \! \left( \frac{\| \ps[t+1] \|}{\E [\| \mathcal{N} (\boldsymbol{0}, \mathbf{I}_{\Nmi}) \|]} - 1 \right) \right) \enspace, \label{eq:update_sig}
\end{align}
where $d_\sigma$ is the damping factor.


% ........................................ %
\subsubsection{Margin Correction} \label{sssec:margin_correction}
% ........................................ %
~ In a certain integer dimension, when the standard deviation of the multivariate Gaussian distribution becomes small compared to the interval of integers, the generated integer variable is fixed to a single value.
To address this problem, the CMA-ESwM introduces a lower bound on the marginal probabilities associated with the generation of integer variables in the multivariate Gaussian distribution, called margin correction.
For each $n \in \{1, \ldots, \Nin\}$, the margin correction updates $[\m[t+1]]_{\jin_n}$ and $\langle \A[t] \rangle_{\jin_n}$, where $\langle \cdot \rangle_{n}$ denotes the $n$-th diagonal element of a matrix.

% '''''''''''''''''''''''''
\paragraph{Case of $~[\textnormal{\textsc{Enc}}(\m[t+1])]_{\jin_n} \in \{ z_{n,1}, z_{n,L_n} \}$.}
Let $\lnei{t+1}{n}$ be the nearest threshold to $\jin_n$-th element of the mean vector. First, the marginal probability $\pmut{t+1}{n}$ is calculated as follows:
\begin{align}
    \pmut{t+1}{n} = &\min\left\{ \Pr\left( [\bv]_{\jin_n} \leq \lnei{t+1}{n} \right),  \Pr\left( \lnei{t+1}{n} < [\bv]_{\jin_n} \right) \right\}
\end{align}
Next, we restrict $\pmut{t+1}{n}$ as
\begin{align}
    \pmut{t+1}{n} \leftarrow \max \left\{ \alpha, \pmut{t+1}{n} \right\} \enspace, \label{eq:clip_edgecase}
\end{align}
where $\alpha$ is the margin value that controls the strength of the correction.
Finally, we modify the mean vector so that the marginal probability becomes restricted $\pmut{t+1}{n}$ as
\begin{align}
    \begin{split}
        % &[\m[t+1]]_{\jin_n} \leftarrow \llow{t+1}{n} + \sign \left( [\m[t+1]]_{\jin_n} - \llow{t+1}{n} \right) \\
        &[\m[t+1]]_{\jin_n} \leftarrow \rev{\lnei{t+1}{n}} + \sign \left( [\m[t+1]]_{\jin_n} - \rev{\lnei{t+1}{n}} \right) \\
        &\qquad\qquad \cdot \sig[t+1] \langle \A[t] \rangle_{\jin_n} \sqrt{\langle \C[t+1] \rangle_{\jin_n}\Xppf{1-2\pmut{t+1}{n}}} ~,
    \end{split}
\end{align}
where $\Xppf{\gamma}$ is $\gamma$-quantile of $\chi^2$-distribution with $1$ degree of freedom.
We note that if $\pmut{t+1}{n}$ does not change before and after the modification in \eqref{eq:clip_edgecase}, $[\m[t+1]]_{\jin_n}$ also does not change. Additionally, no changes are made to $\langle \A[t] \rangle_{\jin_n}$, namely,
\begin{align}
    \langle \A[t+1] \rangle_{\jin_n} \leftarrow \langle \A[t] \rangle_{\jin_n} \enspace.
\end{align}

\begin{comment}
\begin{figure}[t]
    \centering
    \includegraphics[width=0.95\linewidth]{fig/margin_visu.pdf}
    \vspace{-2mm}
    \caption{Margin Correction.}
    \label{fig:margin_visu}
\end{figure}
\end{comment}


% '''''''''''''''''''''''''
\paragraph{Case of $~[\textnormal{\textsc{Enc}}(\m[t+1])]_{\jin_n} \in \{ z_{n,2}, \ldots, z_{n,L_n-1} \}$.}
Let us denote the nearest two thresholds to $[\m[t+1]]_{\jin_n}$ as follows:
\begin{align*}
    \llow{t+1}{n} &= \max \left\{ \ell_{n, l|l+1} \mid l \in \{1, \ldots, L_n-1\}, \ell_{n, l|l+1} < [\m[t+1]]_{\jin_n} \right\} \\
    \lup{t+1}{n} &= \min \left\{ \ell_{n, l|l+1} \mid l \in \{1, \ldots, L_n-1\}, [\m[t+1]]_{\jin_n} \leq \ell_{n, l|l+1} \right\}
\end{align*}
First, the marginal probabilities are calculated as
\begin{align*}
    %\plow{t+1}{n} &= \Pr\left( [\bv]_{\jin_n} \leq \llow{t+1}{n} \right) \enspace, \\
    %\pup{t+1}{n} &= \Pr\left( \lup{t+1}{n} < [\bv]_{\jin_n} \right) \enspace, \\
    \plow{t+1}{n} &= \Pr\left( [\bv]_{\jin_n} \leq \llow{t+1}{n} \right), \enspace \pup{t+1}{n} = \Pr\left( \lup{t+1}{n} < [\bv]_{\jin_n} \right) , \\
    \pmid{t+1}{n} &= 1 - \plow{t+1}{n} - \pup{t+1}{n} \enspace.
\end{align*}
Next, the marginal probabilities are modified so that $\plow{t+1}{n} \geq \alpha/2$, $\pup{t+1}{n} \geq \alpha/2$, and $\plow{t+1}{n} + \pup{t+1}{n} + \pmid{t+1}{n} = 1$ as follows:
\begin{align}
    %\plow{t+1}{n} &\leftarrow \max\left\{\frac{\alpha}{2}, \plow{t+1}{n}\right\} \label{eq:clip_plow} \\
    %\pup{t+1}{n} &\leftarrow \max\left\{\frac{\alpha}{2}, \pup{t+1}{n}\right\} \label{eq:clip_pup} \\
    \plow{t+1}{n} &\leftarrow \max\left\{\frac{\alpha}{2}, \plow{t+1}{n}\right\}, \quad \pup{t+1}{n} \leftarrow \max\left\{\frac{\alpha}{2}, \pup{t+1}{n}\right\} \label{eq:clip_plow} \\
    \Delt{t+1}{n} &\leftarrow \frac{1 - \plow{t+1}{n} - \pup{t+1}{n} - \pmid{t+1}{n}}{\plow{t+1}{n} + \pup{t+1}{n} + \pmid{t+1}{n} - 3\cdot \alpha/2} \label{eq:calc_Delta} \\
    \plow{t+1}{n} &\leftarrow \plow{t+1}{n} + \Delt{t+1}{n} (\plow{t+1}{n} - \alpha/2) \\
    \pup{t+1}{n} &\leftarrow \pup{t+1}{n} + \Delt{t+1}{n} (\pup{t+1}{n} - \alpha/2) \label{eq:clip_end}
\end{align}
Finally, $[\m[t+1]]_{\jin_n}$ and $\langle\A[t+1]\rangle_{\jin_n}$ are corrected as follows:
{\fontsize{8.5pt}{8.5pt}
\begin{align*}
    \begin{split}
        &[\m[t+1]]_{\jin_n}\\
        &\leftarrow \frac{\llow{t+1}{n} \sqrt{\Xppf{1-2\pup{t+1}{n}}} + \lup{t+1}{n} \sqrt{\Xppf{1-2\plow{t+1}{n}}}}{\sqrt{\Xppf{1-2\pup{t+1}{n}}} + \sqrt{\Xppf{1-2\plow{t+1}{n}}}} 
    \end{split} \\
    \begin{split}
        &\langle\A[t+1]\rangle_{\jin_n}\\
        &\leftarrow \frac{\lup{t+1}{n} - \llow{t+1}{n}}{\sig[t+1]\sqrt{\langle\C[t+1]\rangle_{\jin_n}}\left(\sqrt{\Xppf{1-2\pup{t+1}{n}}} + \sqrt{\Xppf{1-2\plow{t+1}{n}}}\right)} 
    \end{split}
\end{align*}
}
