\section{Proposed Integer Handling} \label{sec:proposed_integer_handling}
% ================================================== %
In this section, we propose the new integer handling suitable for integrating into CatCMA based on the previous section.

% ---------------------------------------- %
\subsection{Modified Margin Correction}
% ---------------------------------------- %
We propose a mechanism to suppress unnecessary fluctuations of the mutation rate.
The proposed mechanism imposes the upper bound of the mutation rate depending on whether a successful integer mutation occurs.
This upper bound is motivated by the analytical derivation of a promising margin and the perspective of adapting the mutation rate for efficient optimization.

% Based on \cite{LB+IC-CMA-ES:2024}, the dimension in which a successful integer mutation occurs is $n \in \{1, \ldots, \Nin\}$ that satisfies the following condition:
Based on \cite{LB+IC-CMA-ES:2024}, we consider that a successful integer mutation occurs in the dimension $n \in \{1, \ldots, \Nin\}$ when the following condition is satisfied:
% \begin{align}
%     \exists i \in \{1\!:\!\lambda, \ldots, \mu\!:\!\lambda\} \enspace \text{s.t.} \enspace [\Enc(\x_i)]_{\jin_n} \neq [\Enc(\m[t])]_{\jin_n}
% \end{align}
\begin{align}
    \exists i \in \{1\!:\!\lambda, \ldots, \mu\!:\!\lambda\} \enspace \text{s.t.} \enspace [\z_i]_{n} \neq [\Enc(\m[t])]_{\jin_n}
\end{align}
% After \eqref{eq:clip_end}, the mutation rate is calculated as
% \begin{align}
%     \pmut{t+1}{n} \leftarrow \plow{t+1}{n} + \pup{t+1}{n} \enspace,
% \end{align}
% which allows us to uniformly refer to the mutation rate in the previous iteration as $\pmut{t}{n}$.
To uniformly refer to the mutation rate in the previous iteration as $\pmut{t}{n}$, we insert the following update after \eqref{eq:clip_end}:
\begin{align}
    \pmut{t+1}{n} \leftarrow \plow{t+1}{n} + \pup{t+1}{n} 
\end{align}
For dimensions where a successful integer mutation occurs, the margin correction in Section~\ref{sssec:margin_correction} is performed, and for other dimensions, the following modified margin correction is performed.

% '''''''''''''''''''''''''
\paragraph{Case of $~[\textnormal{\textsc{Enc}}(\m[t+1])]_{\jin_n} \in \{ z_{n,1}, z_{n,L_n} \}$.}
The update of \eqref{eq:clip_edgecase} is modified to the following:
\begin{align}
    \pmut{t+1}{n} \leftarrow \max\left\{ \alpha, \min\left\{ \pmut{t+1}{n}, \pmut{t}{n} \right\} \right\} \label{eq:clip_pmut_modified}
\end{align}


% '''''''''''''''''''''''''
\paragraph{Case of $~[\textnormal{\textsc{Enc}}(\m[t+1])]_{\jin_n} \in \{ z_{n,2}, \ldots, z_{n,L_n-1} \}$.}
The updates of \eqref{eq:clip_plow} to \eqref{eq:calc_Delta} are modified to the following:
\begin{align}
    %\plow{t+1}{n} &\leftarrow \max\left\{\frac{\alpha}{2}, \plow{t+1}{n}\right\} \label{eq:clip_plow_modified} \\
    %\pup{t+1}{n} &\leftarrow \max\left\{\frac{\alpha}{2}, \pup{t+1}{n}\right\} \label{eq:clip_pup_modified} \\
    \plow{t+1}{n} &\leftarrow \max\left\{\frac{\alpha}{2}, \plow{t+1}{n}\right\}, \quad \pup{t+1}{n} \leftarrow \max\left\{\frac{\alpha}{2}, \pup{t+1}{n}\right\} \label{eq:clip_plow_modified} \\
    \pmid{t+1}{n} &\leftarrow \max\left\{1 - \pmut{t}{n}, \pmid{t+1}{n}\right\} \label{eq:clip_pmid_modified} \\
    \Delt{t+1}{n} &\leftarrow \frac{1 - \plow{t+1}{n} - \pup{t+1}{n} - \pmid{t+1}{n}}{\plow{t+1}{n} + \pup{t+1}{n} + \pmid{t+1}{n} - \alpha - (1 - \pmut{t}{n})} \label{eq:calc_Delta_modified}
\end{align}
The above modification ensures $\plow{t+1}{n} \geq \alpha / 2$, $\pup{t+1}{n} \geq \alpha / 2$, $\plow{t+1}{n} + \pup{t+1}{n} \leq \pmut{t}{n}$, and $\plow{t+1}{n} + \pup{t+1}{n} + \pmid{t+1}{n} = 1$.

