%    \begin{cases}
%        \plow{t+1}{n} \geq \alpha / 2 \\
%        \pup{t+1}{n} \geq \alpha / 2 \\
%        \plow{t+1}{n} + \pup{t+1}{n} \leq \pmut{t}{n} \\
%        \plow{t+1}{n} + \pup{t+1}{n} + \pmid{t+1}{n} = 1
%    \end{cases}
%\end{align}


% ---------------------------------------- %
\subsection{Introduction of Integer Centering} \label{ssec:integer_centering}
% ---------------------------------------- %
\begin{comment}
\begin{figure}[t]
    \centering    \includegraphics[width=0.9\linewidth]{fig/centering.pdf}
    \vspace{-2mm}
    \caption{Integer centering under the different standard deviations of the multivariate Gaussian distribution.}
    \label{fig:centering}
\end{figure}
\end{comment}
To further facilitate the escape of the multivariate Gaussian distribution from a plateau, we introduce integer centering proposed in \cite{LB+IC-CMA-ES:2024}.
Integer centering can be implemented independently of the margin correction, since it corrects $\bv_{1:\lambda}, \ldots, \bv_{\mu:\lambda}$ and $\y_{1:\lambda}, \ldots, \y_{\mu:\lambda}$ after evaluation by the objective function.
However, naively introducing integer centering into the CMA-ESwM can lead to unstable optimization in some cases.
As shown in the top of Figure~\ref{fig:centering}, when the mean vector stays in the region where edge integers are generated, the corresponding standard deviation can remain very small.
This is because only the mean vector is corrected in the case of edge integers.
In such cases, since the movement of the samples by integer centering becomes very large compared to the standard deviation of the multivariate Gaussian distribution, the evolution path $\ps[t]$ rapidly becomes long.
To address this problem, we introduce the following correction to $\langle \A[t+1] \rangle_{\jin_n}$ so that the standard deviation of the multivariate Gaussian distribution does not become too small even in the case of edge integers.
\begin{align}
    \langle \A[t+1] \rangle_{\jin_n} \! \leftarrow \! \max \! \left\{ \! \frac{\left| [\Enc(\m[t+1])]_{\jin_n} - \lnei{t+1}{n} \right|}{\sig[t+1] \!\!\! \sqrt{\langle \C[t+1] \rangle_{\!\jin_n}\Xppf{1\!-\!2\alpha}}},   \langle \A[t] \rangle_{\!\jin_n} \! \right\} \!\label{eq:correction_A_new}
\end{align}
After this correction, $[\m[t+1]]_{\jin_n}$ is corrected using $\pmut{t+1}{n}$ previously calculated in \eqref{eq:clip_pmut_modified} as follows:
\begin{align}
    \begin{split}
        % &[\m[t+1]]_{\jin_n} \leftarrow \llow{t+1}{n} + \sign \left( [\m[t+1]]_{\jin_n} - \llow{t+1}{n} \right) \\
        &[\m[t+1]]_{\jin_n} \leftarrow \rev{\lnei{t+1}{n}} + \sign \left( [\m[t+1]]_{\jin_n} - \rev{\lnei{t+1}{n}} \right) \\
        &\qquad\qquad \!\! \cdot \sig[t+1] \langle \A[t+1] \rangle_{\jin_n} \sqrt{\langle \C[t+1] \rangle_{\jin_n}\Xppf{1-2\pmut{t+1}{n}}}
    \end{split}
\end{align}
% When $\langle \A[t+1] \rangle_{\jin_n}$ is lower bounded by \eqref{eq:correction_A_new}, the standard deviation of the multivariate Gaussian distribution becomes appropriately sized relative to the movement by integer centering, as shown in the bottom of Figure~\ref{fig:centering}.
When $\langle \A[t+1] \rangle_{\jin_n}$ is corrected to the lower bound in \eqref{eq:correction_A_new} and $\pmut{t+1}{n}$ is $\alpha$, $[\m[t+1]]_{\jin_n}$ is corrected to match $\z_{n,1}$ or $\z_{n,L_n}$, as shown in the bottom of Figure~\ref{fig:centering}.
A summary of the modified margin correction is provided in the supplementary material to facilitate following the revised and added update rules.

% ---------------------------------------- %
\subsection{Derivation of Promising Margin Settings} \label{ssec:derivation_margin}
% ---------------------------------------- %
Before the derivation of promising margin settings, we confirm that the modified margin correction can suppress unnecessary fluctuations of the mutation rate.
The last two columns of Figure~\ref{fig:margin_typical} show the results of a typical trial introducing the modified margin correction and the integer centering.
Since no upper bound is imposed on the mutation rate in the case of a successful integer mutation, the impact on integer variable optimization is minimal.
Moreover, when the optimization of integer variables has been sufficiently performed, a successful integer mutation does not occur, and the upper bound prevents the mutation rate from fluctuating.
Therefore, we can reasonably assume the convergence of the mutation rate for deriving promising margin settings.

Then, similar to \cite[Proposition~4.1]{CatCMA:2024}, we can derive the margin $\alpha$ that sufficiently reduces the impact of non-optimal integers caused by the margin on the solution ranking.
\begin{prop}
    \label{prop:int_margin}
    Let $\z^\opt \in \mathcal{Z}$ be an optimal integer variable. Assume that the parameters of the multivariate Gaussian distribution satisfy the following:
    \begin{align}
        [\textnormal{\textsc{Enc}}(\m[t])]_{\jin_n} &= \z^\opt_n \enspace \text{for all} \enspace n \in \{ 1, \ldots, \Nin \} \label{eq:int_prop_cond1} \\
        \pmut{t}{n} &= \alpha \enspace \text{for all} \enspace n \in \{ 1, \ldots, \Nin \} \label{eq:int_prop_cond2}
    \end{align}
    Let $\lambda_\mathrm{non}$ be the random variable that counts the number of samples containing non-optimal integer variables among the $\lambda$ samples in the $t$-th iteration of the CMA-ESwM. If the margin satisfies
    \begin{align}
        \alpha = 1 - 0.73^\frac{1}{\Nin} \enspace, \label{eq:promising_margin_int}
    \end{align}
    it holds, for any $\lambda \geq 6$,
    \begin{align}
        \Pr\left( \lambda_\non \leq \lambda - \left\lfloor \frac{\lambda}{2} \right\rfloor \right) \geq 0.95 \enspace. \label{eq:lambda_non_prob_int}
    \end{align}
\end{prop}
The proof of Proposition~\ref{prop:int_margin} can be found in the supplementary material.
This proposition provides the margin that ensures that the top $\mu = \lfloor \lambda/2 \rfloor$ solutions do not contain non-optimal integers with high probability when the part of the multivariate Gaussian distribution responsible for generating integer variables has converged to the optimal state.
This implies that, in the updates of \eqref{eq:update_m} to \eqref{eq:update_pc}, the solutions containing non-optimal integers are almost ignored.
On the other hand, when using negative weights, the update of the covariance matrix \eqref{eq:update_C} is affected by such samples, which will be investigated in the next subsection. 

