\section{Proposed Method : CatCMA with Margin}
% ================================================== %
In this section, we propose CatCMA with Margin (CatCMAwM), an MV-BBO method that can handle continuous, integer, and categorical variables.
As shown in Algorithm~\ref{alg:CatCMAwM}, CatCMAwM is developed by incorporating the integer handling proposed in the previous section into CatCMA.
% As a refinement, we modify the estimation in \eqref{eq:CatCMA_ngr} to use the $\mu$-best solutions for the following reason: to align the weights used in the estimation of \eqref{eq:CatCMA_ngr} in CatCMA with those used in the update of the mean vector in \eqref{eq:update_m} as in \cite{CatCMA:2024}, and to limit negative weights to active covariance matrix adaptation.
As a refinement, we modify the estimation in \eqref{eq:CatCMA_ngr} to use the $\mu$-best solutions for the following reason: to use negative weights solely for active covariance matrix adaptation, we align the weights in the estimation of \eqref{eq:CatCMA_ngr} in CatCMA with those used in the update of the mean vector in \eqref{eq:update_m}, as in \cite{CatCMA:2024}.
We can derive the promising margin values $\alpha$ and $\qmin_n$ in CatCMAwM similar to Proposition~\ref{prop:int_margin} and \cite[Proposition~4.1]{CatCMA:2024}.

\begin{prop}
    \label{prop:mix_margin}
    Let $\z^\opt \in \mathcal{Z}$ be an optimal integer variable. Assume that the parameters of the multivariate Gaussian distribution satisfy the following:
    \begin{align}
        [\textnormal{\textsc{Enc}}(\m[t])]_{\jin_n} &= \z^\opt_n \enspace \text{for all} \enspace n \in \{ 1, \ldots, \Nin \} \label{eq:mix_prop_cond1} \\
        \pmut{t}{n} &= \alpha \enspace \text{for all} \enspace n \in \{ 1, \ldots, \Nin \} \label{eq:mix_prop_cond2}
    \end{align}
    Without loss of generality, assume that categories of the optimal solution are the first categories in all dimensions and the parameter of the categorical distribution satisfies
    \begin{align}
        \begin{split}
            &\qt[t]_{n,1} = 1 - \qmin_n (K_n - 1) \enspace, \\
            &\qt[t]_{n, k} = \qmin_n \quad \text{for all} \enspace k \in \{2, \ldots, K_n \}
        \end{split} \label{eq:assum_cat}
    \end{align}
    for all $n \in \{ 1, \ldots, \Nca \}$.
    Let $\lambda_\mathrm{non}$ be the random variable that counts the number of samples containing non-optimal integer and/or categorical variables among the $\lambda$ samples in the $t$-th iteration of CatCMAwM. If the margins satisfy
    \begin{align}
        \alpha &= 1 - 0.73^\frac{1}{\Nin+\Nca} \enspace, \label{eq:promising_margin_alpha} \\
        \qmin_n &= \frac{1}{K_n - 1}\left( 1 - 0.73^\frac{1}{\Nin+\Nca} \right) \enspace \text{for all} \enspace n \in \{ 1, \ldots, \Nca \} \enspace, \label{eq:promising_margin_qmin}
    \end{align}
    it holds, for any $\lambda \geq 6$,
    \begin{align}
        \Pr\left( \lambda_\non \leq \lambda - \left\lfloor \frac{\lambda}{2} \right\rfloor \right) \geq 0.95 \enspace. \label{eq:lambda_non_prob_mix}
    \end{align}
\end{prop}
The proof of Proposition~\ref{prop:mix_margin} can be found in the supplementary material.
This proposition focuses on the phase where optimization of both integer and categorical variables has been sufficiently performed.
This margin setting is expected to achieve a balance between avoiding the fixation of discrete variables and efficient continuous variable optimization.

