            \STATE Sample $\bxi_i \sim \mathcal{N}(\boldsymbol{0}, \mathbf{I})$
            \STATE Sample $\bc_i \sim p(\bc \mid \qt[t])$
            \STATE $\y_i \leftarrow \sqrt{\C[t]} \bxi_i$
            \STATE $\bv_i \leftarrow \m[t] + \sig[t] \A[t] \y_i$
            \FOR{$n=1,\ldots,\Nco$}
                \STATE $[\x_i]_n \leftarrow [\Enc(\bv_i)]_{j^{\mathrm{co}}_n}$
            \ENDFOR
            \FOR{$n=1,\ldots,\Nin$}
                \STATE $[\z_i]_n \leftarrow [\Enc(\bv_i)]_{j^{\mathrm{in}}_n}$
            \ENDFOR
        \ENDFOR
        \STATE Evaluate $(\x_1, \z_1, \bc_1), \ldots, (\x_\lambda, \z_\lambda, \bc_\lambda)$ on $f(\x, \z, \bc)$.
        \STATE Modify $\bv_{1:\lambda},\ldots,\bv_{\mu:\lambda}$ and $\y_{1:\lambda},\ldots,\y_{\mu:\lambda}$ by Integer Centering in \cite{LB+IC-CMA-ES:2024}.
        \STATE Update $\m[t]$ using
        (\ref{eq:update_m}).
        \STATE Update $\ps[t]$ and $\pc[t]$ using (\ref{eq:update_ps}) and (\ref{eq:update_pc}).
        \STATE Update $\C[t]$ and $\sig[t]$ using (\ref{eq:update_C}) and (\ref{eq:update_sig}).
        \STATE Update $\qt[t]$ using (\ref{eq:update_q}).
        \STATE Update $\st[t]$ and $\gamt[t]$ using (\ref{eq:update_s}) and (\ref{eq:update_gam}).
        \STATE Update $\delt[t]$ using (\ref{eq:update_del}).
        \STATE Modify $\sig[t+1]$ using (\ref{eq:post-process_sigma}).
        \STATE Modify $\qt[t+1]$ using (\ref{eq:margin_correction_1}) and (\ref{eq:margin_correction_2}).
        \STATE Update $\m[t+1]$, $\A[t]$, $\pmut{t}{1}, \ldots, \pmut{t}{\Nin}$ \linebreak by margin correction in Section~\ref{sssec:margin_correction} and Section~\ref{sec:proposed_integer_handling}.
        \STATE $t \leftarrow t+1$
        \ENDWHILE
    \end{algorithmic}
    \label{alg:CatCMAwM}
\end{algorithm}
\end{comment}


