\includegraphics[width=0.92\columnwidth]{figures/SPF09_ia_coarticulation.eps}
%% Use \caption command for figure caption and label.
\caption{Magnitude spectra of 24 successive pitch periods spanning the co-articulation region involving vowels /i/ and /a/ in a Portuguese word context: `Tiago'.}
\label{fig:coarticulation}
