\section{Equilibrium Analysis for MLMF Stackelberg Game} \label{equilibrium_analysis}

\subsection{Follower-level Equilibrium Analysis}
At the follower level of the Stackelberg game, each AV $v$ obtains the bandwidth it needs based on the information of tasks and RSUs’ bandwidth prices \cite{zhou2022stackelberg}. To analyze the concavity of the utility function for AV $v$, the first-order and second-order derivatives of $U^F_v$ with respect to $b_{rv}$ are expressed as
\begin{equation}
    \frac{\partial U^{F}_{v}}{\partial b_{v}} =\sum_{r \in \mathcal{R}}\big[\alpha_{v} \beta \frac{\frac{1}{p_{r} } }{\sum _{l\in\mathcal{R}}\frac{1}{p_{l} } }(\frac{\frac{\alpha _{v} }{T^{max} _{v} } }{ e+\frac{\alpha_{v} b_{rv} }{T^{max} _{v} }}-p_{r})\big],
\end{equation}

\begin{equation}
    \frac{\partial^2 U^F_{v}}{\partial b^2_{v}}=\sum_{r \in \mathcal{R}}\big[-\alpha_v \beta \frac{\frac{1}{p_r}}{\sum_{l \in \mathcal{R}\frac{1}{p_l}}}\frac{{(\frac{\alpha_v}{T^{max}_v})^2}}{(e+\frac{\alpha_v b_{rv}}{T^{max}_v})^2}\big]< 0.
\end{equation}

Because the second-order derivative of the follower utility function is negative, $U^F_v$ is quasi-concave in $b_{rv}$. Hence, the maximum exists for the first-order derivative to equal zero. Hence, the maximum of the follower’s utility function exists and satisfies the first-order optimality condition $\frac{\partial U^F_v}{\partial b_{rv}}=0$,
\begin{equation} \label{response_follwers}
    \hat{b_{rv}}=\frac{1}{p_r} -\frac{eT^{max}_{v}}{\alpha_v},
\end{equation}
where $\hat{b_{rv}}$ represents AV $v$ unique optimal strategy that is calculated by the first-order derivative. The bandwidth amount $b_{rv}$ follows the constraint $b_{rv} \in [0, b^{max}_{rv}]$. Hence, the optimal strategy for AV $v$ is
\begin{equation}
    b^\star_{rv}=\begin{cases}
    \hat{b_{rv}}, &\mathrm{if} \ \alpha_v\geq ep_rT^{max}_v,\\
    0, &\mathrm{if} \ \alpha_v < ep_rT^{max}_v . 
    \end{cases} 
\end{equation}

\subsection{Leader-level Equilibrium Analysis}
In a Stackelberg game, leaders and followers interact such that the leaders’ optimal strategies are influenced by the followers’ actions. Consequently, analyzing the leaders’ strategies requires incorporating the followers’ best-response strategies, i.e., substituting Eq. (\ref{response_follwers}) into Eq. (\ref{utility_leaders}). 

Consequently, analyzing the leaders' strategies requires incorporating the followers' optimal strategies. Thus, we embed the followers' optimal strategies from Eq. (\ref{response_follwers}) into leaders' strategies. We denoted $y_r=\frac{1}{p_r}$ to simplify the mathematical equation. Hence, the utility function of leader $r$ is 
\begin{equation} \label{utility_leaders}
    \begin{split}
    U^{L}_r &= \sum _{v\in \mathcal{V} }\big(\alpha_v\frac{\frac{1}{p_r} }{\sum _{l\in \mathcal{R}\frac{1}{p_l} }}(b_{rv}p_r-b_{rv}c_r)\big), \\ 
    % &= \sum _{v\in \mathcal{V} }\big(\frac{\frac{1}{p_r} }{\sum _{l\in \mathcal{R}\frac{1}{p_l} }}(\frac{1}{p_r} -\frac{eT^{max}_{v}}{\alpha_v})(p_r-c_r)\big), \\ 
    &= \sum _{v\in \mathcal{V} }\big(\alpha_v\frac{y_r}{\sum _{l\in \mathcal{R}}y_l}(y_r -\frac{eT^{max}_{v}}{\alpha_v})(\frac{1}{y_r}-c_r)\big).
    \end{split}
\end{equation}

% \textbf{Lemma 1}: 
\begin{lemma}
A function $\mathcal{H}_r(\boldsymbol{B})$ is a standard function if and only if it satisfies the following three conditions:
\begin{itemize}
\item Positiveness: $\mathcal{H}_r(\boldsymbol{B})>0$.
\item Monotonicity: $\forall \boldsymbol{B'} > \boldsymbol{B}, \mathcal{H}_r( \boldsymbol{B'})> \mathcal{H}_r(\boldsymbol{B})$.
\item Scalability: $\forall \lambda > 1, \lambda \mathcal{H}_r(\boldsymbol{B})> \mathcal{H}_r(\lambda \boldsymbol{B})$.
\end{itemize}
where $\mathcal{H}_r(\boldsymbol{B})$ denotes the optimal strategy of RSU $r$.
\end{lemma}

% \textbf{Theorem 1}: 
\begin{theorem} \label{theorem1}
The unique SE denoted as $(\boldsymbol{B^\star}, \boldsymbol{P^\star})$ is established in the formulated game when the following condition holds, i.e., $\alpha_v\geq ep_rT^{max}_v$. In this case, AVs’ bandwidth amount strategies and RSUs’ bandwidth pricing strategies are both optimal. In particular, this equilibrium ensures the simultaneous optimization in VEANs.
\end{theorem}
